pub fn set_failure_locus(label: Option<String>) {
    FAILURE_LOCUS.with(|value| *value.borrow_mut() = label);
}

pub fn take_failure_locus() -> Option<String> {
    FAILURE_LOCUS.with(|value| value.borrow_mut().take())
}

