fn render_validate_success_output(
    resolved_path: &Path,
    member: Option<&str>,
    text_path_display: &str,
    advisories: &[ContractAdvisory],
) -> String {
    let mut stdout = format!(
        "{}\n\n{}{}",
        format_command_header("VALIDATE", text_path_display),
        render_valid_status(),
        render_validate_ready_next(resolved_path, member)
    );
    if !advisories.is_empty() {
        let warnings_title = if plain_mode() {
            String::from("Warnings")
        } else {
            paint("Warnings", "1;33")
        };
        stdout.push_str(&format!("\n\n{}", warnings_title));
        for (index, advisory) in advisories.iter().enumerate() {
            if index == 0 {
                stdout.push('\n');
            } else {
                stdout.push_str("\n\n");
            }
            stdout.push_str(&render_validate_warning(advisory));
        }
    }
    stdout
}

fn validate_invalid_contract_next_steps(contract_path: &Path) -> Vec<String> {
    vec![
        format!(
            "repair {}",
            paint_code(&format!("`{}`", compact_contract_path(contract_path)))
        ),
        format!(
            "rerun {}",
            paint_code(&format!(
                "`{}`",
                command_for_repo_contract_target("ota validate", contract_path)
            ))
        ),
    ]
}

fn render_validate_ready_next(contract_path: &Path, member: Option<&str>) -> String {
    let doctor = match member {
        Some(member) => format!(
            "run `{}` to inspect readiness",
            command_for_repo_contract_target(
                &format!("ota doctor --member {member}"),
                contract_path
            )
        ),
        None => format!(
            "run `{}` to inspect readiness",
            command_for_repo_contract_target("ota doctor", contract_path)
        ),
    };
    let tasks = match member {
        Some(member) => format!(
            "run `{}` to inspect runnable task usage",
            command_for_repo_contract_target(
                &format!("ota tasks --member {member} --use"),
                contract_path
            )
        ),
        None => format!(
            "run `{}` to inspect runnable task usage",
            command_for_repo_contract_target("ota tasks --use", contract_path)
        ),
    };

    format_next_timeline(&[doctor, tasks])
}

pub fn execution_plan(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => missing_repo_contract_command_output(
                        "EXECUTION PLAN",
                        "ota execution plan",
                        &error,
                    )
                    .unwrap_or_else(|| CommandOutput::failure(error.to_string())),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=execution-plan")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=execution-plan"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(workflow_name) = workflow_name {
        debug_lines.push(format!("DEBUG workflow={workflow_name}"));
    }
    if let Some(backend) = overrides.backend {
        debug_lines.push(format!(
            "DEBUG backend_override={}",
            format_backend(backend)
        ));
    }
    if let Some(lifecycle) = overrides.lifecycle {
        debug_lines.push(format!(
            "DEBUG lifecycle_override={}",
            format_lifecycle(lifecycle)
        ));
    }
    if overrides.skip_deps {
        debug_lines.push(String::from("DEBUG skip_deps=true"));
    }
    if let Some(host_port) = overrides.host_port {
        debug_lines.push(format!("DEBUG host_port_override={host_port}"));
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let contract_path_display = target.contract_path.display().to_string();
                let contract_identity = repo_contract_identity(&target.contract);
                let declared_execution =
                    ExecutionSummary::from_contract(&target.contract, &target.contract_path);
                let workflow_summary = match resolve_selected_workflow_summary(
                    &target.contract,
                    &target.contract_path,
                    workflow_name,
                ) {
                    Ok(summary) => summary,
                    Err(error) => {
                        return finalize_debug(
                            CommandOutput::failure_with_code(error, 2),
                            debug,
                            debug_lines,
                        );
                    }
                };
                let selected_task =
                    selected_execution_plan_task_name(&target.contract, workflow_name);
                match resolve_execution_plan(
                    &target.contract,
                    &target.contract_path,
                    overrides,
                    workflow_name,
                ) {
                    Ok(resolved_execution) => {
                        let applied_overrides = execution_plan_overrides(overrides);
                        let workflow_env_artifacts =
                            selected_workflow_env_profile_rendered_artifact_entries(
                                &target.contract,
                                &target.contract_path,
                                workflow_name,
                            );

                        match format {
                            OutputFormat::Text => {
                                CommandOutput::success(render_execution_plan_text(
                                    &text_path_display,
                                    &target.contract_path,
                                    &contract_identity,
                                    workflow_summary.as_ref(),
                                    selected_task,
                                    declared_execution.as_ref(),
                                    &workflow_env_artifacts,
                                    &resolved_execution,
                                    applied_overrides.as_ref(),
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::success(to_json(&ExecutionPlanSuccess {
                                    ok: true,
                                    path: &path_display,
                                    contract: &contract_path_display,
                                    member,
                                    workflow: workflow_summary,
                                    task: selected_task,
                                    contract_identity,
                                    declared_execution,
                                    workflow_env_artifacts,
                                    resolved: resolved_execution,
                                    overrides: applied_overrides,
                                }))
                            }
                        }
                    }
                    Err(error) => match format {
                        OutputFormat::Text => {
                            CommandOutput::failure(render_execution_plan_structured_error(
                                &target.contract,
                                &target.contract_path,
                                member,
                                overrides,
                                &error,
                            ))
                        }
                        OutputFormat::Json => {
                            CommandOutput::failure(to_json(&ExecutionPlanFailure {
                                ok: false,
                                path: &path_display,
                                member,
                                errors: Vec::new(),
                                error: Some(execution_plan_error(&error)),
                            }))
                        }
                    },
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "EXECUTION PLAN",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution plan",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionPlanFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "EXECUTION PLAN",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution plan",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionPlanFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn execution_topology(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => missing_repo_contract_command_output(
                        "EXECUTION TOPOLOGY",
                        "ota execution topology",
                        &error,
                    )
                    .unwrap_or_else(|| CommandOutput::failure(error.to_string())),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=execution-topology")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=execution-topology"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => render_execution_topology_output(
                &target.contract,
                &target.contract_path,
                &path_display,
                member,
                &text_path_display,
                format,
            ),
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "EXECUTION TOPOLOGY",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution topology",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionTopologyFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "EXECUTION TOPOLOGY",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution topology",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionTopologyFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn render_execution_topology_output(
    contract: &Contract,
    contract_path: &Path,
    path_display: &str,
    member: Option<&str>,
    text_path_display: &str,
    format: OutputFormat,
) -> CommandOutput {
    let contract_path_display = contract_path.display().to_string();
    let contract_identity = repo_contract_identity(contract);
    let declared_execution = ExecutionSummary::from_contract(contract, contract_path);
    let shared_backends =
        build_execution_topology_shared_backend_summaries(contract.execution.as_ref());
    let readiness_probes = build_execution_topology_readiness_probe_summaries(contract);
    let surfaces = build_execution_topology_surface_summaries(contract);
    let services = contract
        .services
        .iter()
        .map(|(name, service)| ServiceSummary::from_spec(name, service))
        .collect::<Vec<_>>();
    let tasks = contract
        .tasks
        .iter()
        .map(|(name, task)| {
            build_execution_topology_task_summary(name, task, current_os(), contract)
        })
        .collect::<Vec<_>>();

    match format {
        OutputFormat::Text => CommandOutput::success(render_execution_topology_text(
            text_path_display,
            &contract_identity,
            declared_execution.as_ref(),
            &shared_backends,
            &readiness_probes,
            &surfaces,
            &services,
            &tasks,
        )),
        OutputFormat::Json => CommandOutput::success(to_json(&ExecutionTopologySuccess {
            ok: true,
            path: path_display,
            contract: &contract_path_display,
            member,
            contract_identity,
            declared_execution,
            shared_backends,
            readiness_probes,
            surfaces,
            services,
            tasks,
        })),
    }
}

pub fn proof_runtime(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    workflow_name: Option<&str>,
    ready_timeout: Option<&str>,
    overrides: ExecutionOverrides,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    activate_mise_paths_for_current_process();
    let ready_timeout = match ready_timeout {
        Some(value) => match parse_readiness_duration_spec(value) {
            Some(duration) => Some(duration),
            None => {
                return finalize_debug(
                    CommandOutput::failure_with_code(
                        format!(
                            "`--ready-timeout {value}` is invalid; expected values like `90s`, `5m`, or `1h`"
                        ),
                        2,
                    ),
                    debug,
                    vec![String::from("DEBUG command=proof runtime")],
                );
            }
        },
        None => None,
    };
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("PROOF", "ota proof runtime", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                        summary: None,
                        ok: false,
                        path: &unresolved_contract_target_path(path, file_override),
                        errors: Vec::new(),
                        error: Some(error.to_string()),
                        warnings: Vec::new(),
                        warning_details: Vec::new(),
                    })),
                },
                debug,
                vec![String::from("DEBUG command=proof runtime")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=proof runtime"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(workflow_name) = workflow_name {
        debug_lines.push(format!("DEBUG workflow={workflow_name}"));
    }
    if let Some(timeout) = ready_timeout {
        debug_lines.push(format!("DEBUG ready_timeout_secs={}", timeout.as_secs()));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "PROOF",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from(
                        "`ota proof runtime` verifies repo runtime paths from a repo contract such as `ota.yaml`",
                    ),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota proof runtime", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let adjusted_contract = contract_adjusted_for_selected_workflow_env_profile(
                    &target.contract,
                    workflow_name,
                );
                let contract = adjusted_contract.as_ref().unwrap_or(&target.contract);
                let workflow_summary = match resolve_selected_workflow_summary(
                    contract,
                    &target.contract_path,
                    workflow_name,
                ) {
                    Ok(summary) => summary,
                    Err(error) => return CommandOutput::failure_with_code(error, 2),
                };
                let effective_workflow_selector = workflow_summary
                    .as_ref()
                    .map(workflow_selector_from_summary)
                    .or_else(|| workflow_name.map(str::to_string));
                let artifact_dir = proof_runtime_artifact_dir(
                    contract_working_dir(&target.contract_path),
                    member,
                    effective_workflow_selector.as_deref(),
                );
                if let Err(error) = fs::create_dir_all(&artifact_dir) {
                    return CommandOutput::failure(command_message_failure_text(
                        "PROOF",
                        &text_path_display,
                        "Artifact directory could not be created",
                        &format!(
                            "failed to create `{}`: {error}",
                            compact_path(&artifact_dir, ".")
                        ),
                        &[],
                    ));
                }

                let topology_artifact_path = artifact_dir.join("topology.json");
                let doctor_artifact_path = artifact_dir.join("doctor.json");
                let up_log_artifact_path = artifact_dir.join("up.log");
                let topology_artifact_display = compact_path(&topology_artifact_path, ".");
                let doctor_artifact_display = compact_path(&doctor_artifact_path, ".");
                let up_log_artifact_display = compact_path(&up_log_artifact_path, ".");

                let topology_output = render_execution_topology_output(
                    contract,
                    &target.contract_path,
                    &path_display,
                    member,
                    &text_path_display,
                    OutputFormat::Json,
                );
                if let Err(error) =
                    write_proof_artifact(&topology_artifact_path, &topology_output.stdout)
                {
                    return CommandOutput::failure(error);
                }

                let mut up_process = match spawn_proof_runtime_up_process(
                    &target.contract_path,
                    workflow_name,
                    member,
                    file_override,
                    overrides,
                    &up_log_artifact_path,
                ) {
                    Ok(child) => child,
                    Err(error) => return CommandOutput::failure(error),
                };
                let (proof_report, proof_phase, _proof_ok, up_process_failure) =
                    match wait_for_proof_runtime_readiness(
                        contract,
                        &target.contract_path,
                        workflow_name,
                        overrides,
                        &mut up_process,
                        "ota up --stream",
                        &up_log_artifact_path,
                        ready_timeout,
                    ) {
                        Ok(result) => result,
                        Err(error) => {
                            let _ = stop_proof_runtime_up_process(&mut up_process);
                            return CommandOutput::failure(error);
                        }
                    };
                let proof_summary = doctor_summary(
                    &proof_report,
                    crate::workspace::agent_verdict_from_agent(contract.agent.as_ref()),
                );
                let up_process_failure = up_process_failure.as_deref();

                let process_cleanup_error = stop_proof_runtime_up_process(&mut up_process)
                    .err()
                    .map(|error| error.to_string());
                let workload_cleanup_error = cleanup_selected_workflow_native_service_workloads(
                    contract,
                    effective_workflow_selector.as_deref(),
                    overrides,
                )
                .err();
                let repo_cleanup_error = if process_cleanup_error.is_none() {
                    clean_execution_report_for_workflow(
                        contract,
                        &target.contract_path,
                        effective_workflow_selector.as_deref(),
                    )
                    .err()
                } else {
                    None
                };
                let cleanup_failure_detail = repo_cleanup_error
                    .as_ref()
                    .and_then(proof_runtime_cleanup_failure_detail);
                let cleanup_error =
                    process_cleanup_error
                        .or(workload_cleanup_error)
                        .or_else(|| {
                            repo_cleanup_error
                                .as_ref()
                                .and_then(proof_runtime_cleanup_failure_message)
                        });
                let cleanup_next = cleanup_error.as_ref().map(|_| {
                    format!(
                        "run `{}` to remove the remaining runtime state, then rerun proof",
                        command_for_repo_contract_target("ota clean", &target.contract_path)
                    )
                });
                let mut proof_summary_for_output = proof_summary.clone();
                if let Some(overridden_blocker) = proof_runtime_up_exit_primary_blocker(
                    &proof_summary,
                    up_process_failure,
                    &up_log_artifact_display,
                ) {
                    proof_summary_for_output.primary_blocker = Some(overridden_blocker);
                }
                let proof_doctor_mode = up_doctor_mode(contract, overrides, workflow_name);
                let up_process_failure = proof_runtime_effective_up_process_failure(
                    &proof_summary_for_output,
                    up_process_failure,
                );
                let proof_likely_cause = proof_runtime_likely_cause(
                    &proof_summary_for_output,
                    up_process_failure,
                    &up_log_artifact_path,
                );
                proof_summary_for_output = proof_runtime_refined_doctor_summary(
                    &proof_summary_for_output,
                    proof_likely_cause.as_ref(),
                );
                let proof_likely_cause_text = proof_likely_cause.as_ref().and_then(|cause| {
                    (!proof_runtime_likely_cause_redundant_with_primary_blocker(
                        &proof_summary_for_output,
                        cause,
                    ))
                    .then(|| cause.message())
                });
                let proof_likely_cause_evidence = proof_likely_cause
                    .as_ref()
                    .map(ProofRuntimeLikelyCause::json_evidence);
                let primary_blocker =
                    proof_runtime_blocking_primary_blocker(&proof_summary_for_output);
                let primary_blocker_error = primary_blocker
                    .as_ref()
                    .map(|blocker| blocker.summary.clone());
                let primary_blocker_next =
                    primary_blocker.as_ref().map(|blocker| blocker.next.clone());
                let proof_error = cleanup_error
                    .clone()
                    .or(primary_blocker_error)
                    .or_else(|| up_process_failure.map(str::to_string));
                let proof_next = match (&cleanup_next, primary_blocker_next, up_process_failure) {
                    (Some(next), _, _) => Some(next.clone()),
                    (None, Some(next), _) => Some(next),
                    (None, None, Some(failure_message)) => Some(format!(
                        "inspect `{}` and rerun `ota proof runtime` ({failure_message})",
                        up_log_artifact_display
                    )),
                    (None, None, None) => None,
                };
                let timed_out = up_process_failure.is_some_and(|failure| {
                    failure.contains("timed out while waiting for readiness")
                });
                let interrupted = up_process_failure
                    .is_some_and(|failure| failure.contains("runtime proof interrupted by signal"));
                let refined_proof_phase = proof_runtime_refined_phase(
                    &proof_summary_for_output,
                    proof_phase,
                    &up_log_artifact_path,
                );
                let json_phase = if cleanup_error.is_some() {
                    "cleanup"
                } else if interrupted {
                    "interrupted"
                } else if timed_out {
                    "timeout"
                } else {
                    refined_proof_phase.as_str()
                };
                let text_phase = if cleanup_error.is_some() {
                    "cleanup"
                } else if interrupted {
                    "interrupted"
                } else if timed_out {
                    "timeout"
                } else {
                    proof_runtime_phase_label(refined_proof_phase.as_str())
                };
                let ok = proof_runtime_ok(&proof_summary_for_output, proof_error.as_deref());
                let raw_status = proof_runtime_status_word(
                    proof_summary_for_output.verdict,
                    refined_proof_phase.as_str(),
                    timed_out,
                    interrupted,
                    cleanup_error.is_some(),
                );
                let status = if !ok && raw_status == "READY" {
                    "FAILED"
                } else {
                    raw_status
                };
                let proof_failure_class = proof_runtime_failure_class(
                    &proof_summary_for_output,
                    refined_proof_phase.as_str(),
                    cleanup_error.as_deref(),
                    up_process_failure,
                    proof_likely_cause.as_ref(),
                    &up_log_artifact_path,
                );
                let doctor_artifact_json = match proof_runtime_doctor_artifact_json(
                    contract,
                    &target.contract_path,
                    &text_path_display,
                    workflow_name,
                    proof_doctor_mode,
                    overrides,
                    &proof_report,
                    &proof_summary_for_output,
                    proof_likely_cause.as_ref(),
                ) {
                    Ok(body) => body,
                    Err(error) => {
                        let _ = stop_proof_runtime_up_process(&mut up_process);
                        return CommandOutput::failure(error);
                    }
                };
                if let Err(error) =
                    write_proof_artifact(&doctor_artifact_path, &doctor_artifact_json)
                {
                    let _ = stop_proof_runtime_up_process(&mut up_process);
                    return CommandOutput::failure(error);
                }
                let workflow_env_artifacts =
                    selected_workflow_env_profile_rendered_artifact_entries(
                        &target.contract,
                        &target.contract_path,
                        effective_workflow_selector.as_deref(),
                    );

                match format {
                    OutputFormat::Text => CommandOutput {
                        stdout: render_proof_runtime_text(
                            &text_path_display,
                            effective_workflow_selector.as_deref(),
                            &target.contract_path,
                            text_phase,
                            status,
                            &proof_summary_for_output,
                            up_process_failure,
                            &topology_artifact_display,
                            &doctor_artifact_display,
                            &up_log_artifact_display,
                            &workflow_env_artifacts,
                            proof_likely_cause_text.as_deref(),
                            cleanup_error.as_deref(),
                            cleanup_next.as_deref(),
                        ),
                        stderr: None,
                        exit_code: if ok { 0 } else { 1 },
                    },
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&ProofRuntimeStatus {
                            ok,
                            path: &path_display,
                            mode: "runtime-proof",
                            workflow: effective_workflow_selector.as_deref(),
                            phase: json_phase,
                            summary: proof_summary_for_output,
                            artifacts: Some(ProofRuntimeArtifacts {
                                topology: &topology_artifact_display,
                                doctor: &doctor_artifact_display,
                                up_log: &up_log_artifact_display,
                            }),
                            workflow_env_artifacts,
                            failure_class: proof_failure_class,
                            error: proof_error.as_deref(),
                            cleanup_failure: cleanup_failure_detail,
                            likely_cause: proof_likely_cause_text,
                            likely_cause_evidence: proof_likely_cause_evidence,
                            next: proof_next.as_deref(),
                        }),
                        stderr: None,
                        exit_code: if ok { 0 } else { 1 },
                    },
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "PROOF",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota proof runtime",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "PROOF",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota proof runtime",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn build_execution_topology_shared_backend_summaries(
    execution: Option<&crate::schema::Execution>,
) -> Vec<ExecutionTopologySharedBackendSummary> {
    execution
        .map(|execution| {
            execution
                .shared_backends
                .iter()
                .map(
                    |(name, shared_backend)| ExecutionTopologySharedBackendSummary {
                        name: name.clone(),
                        scope: match shared_backend.scope {
                            crate::schema::ExecutionSharedBackendScope::Local => "local",
                            crate::schema::ExecutionSharedBackendScope::Remote => "remote",
                        }
                        .to_string(),
                        backend: format_backend(shared_backend.backend).to_string(),
                        lifecycle: format_lifecycle(shared_backend.lifecycle).to_string(),
                        context: shared_backend.context.clone(),
                        fulfillment: shared_backend.fulfillment.map(|fulfillment| {
                            match fulfillment {
                                crate::schema::ExecutionSharedBackendFulfillment::None => "none",
                                crate::schema::ExecutionSharedBackendFulfillment::Run => "run",
                            }
                            .to_string()
                        }),
                        environment: shared_backend.environment.as_ref().map(|environment| {
                            ExecutionTopologySharedBackendEnvironmentSummary {
                                profile: environment.profile.clone(),
                                image_alias: environment.image_alias.clone(),
                                image: environment.image.clone(),
                                source: environment.source.clone(),
                            }
                        }),
                    },
                )
                .collect()
        })
        .unwrap_or_default()
}

fn build_execution_topology_readiness_probe_summaries(
    contract: &Contract,
) -> BTreeMap<String, ExecutionTopologyProbeSummary> {
    contract
        .readiness
        .probes
        .iter()
        .map(|(name, probe)| {
            (
                name.clone(),
                ExecutionTopologyProbeSummary {
                    kind: match probe.kind {
                        crate::schema::ReadinessProbeKind::Http => "http",
                        crate::schema::ReadinessProbeKind::Tcp => "tcp",
                    }
                    .to_string(),
                    url: probe.url.clone(),
                    target: probe.target.as_ref().map(|target| {
                        let observer_task = target
                            .observer
                            .as_ref()
                            .and_then(|observer| observer.task.as_deref())
                            .map(str::trim)
                            .filter(|name| !name.is_empty());
                        let observer_kind = target
                            .observer
                            .as_ref()
                            .map(|observer| observer.kind)
                            .unwrap_or(crate::schema::ReadinessProbeObserverKind::CommandHost);
                        let observer_backend = observer_task.map(|task_name| {
                            crate::runner::effective_task_execution(
                                contract,
                                task_name,
                                ExecutionOverrides::default(),
                            )
                            .backend
                        });
                        let observer = match target.kind {
                            crate::schema::ReadinessProbeTargetKind::Task => {
                                Some(ExecutionTopologyProbeObserverSummary {
                                    kind: match observer_kind {
                                        crate::schema::ReadinessProbeObserverKind::CommandHost => {
                                            "command_host"
                                        }
                                        crate::schema::ReadinessProbeObserverKind::Task => "task",
                                    }
                                    .to_string(),
                                    task: observer_task.map(str::to_string),
                                    backend: observer_backend.map(|backend| {
                                        match backend {
                                            Backend::Native => "native",
                                            Backend::Container => "container",
                                            Backend::Remote => "remote",
                                        }
                                        .to_string()
                                    }),
                                })
                            }
                            crate::schema::ReadinessProbeTargetKind::Service => None,
                        };
                        ExecutionTopologyProbeTargetSummary {
                            kind: match target.kind {
                                crate::schema::ReadinessProbeTargetKind::Task => "task",
                                crate::schema::ReadinessProbeTargetKind::Service => "service",
                            }
                            .to_string(),
                            name: target.name.clone(),
                            listener: target.listener.clone(),
                            address_view: match target.kind {
                                crate::schema::ReadinessProbeTargetKind::Task => Some(
                                    match target.address_view {
                                        crate::schema::TaskTargetAddressView::Topology => {
                                            "topology"
                                        }
                                        crate::schema::TaskTargetAddressView::Host => "host",
                                        crate::schema::TaskTargetAddressView::Internal => {
                                            "internal"
                                        }
                                    }
                                    .to_string(),
                                ),
                                crate::schema::ReadinessProbeTargetKind::Service => None,
                            },
                            observer,
                            resolution_plane: match target.kind {
                                crate::schema::ReadinessProbeTargetKind::Task => Some(
                                    observer_task
                                        .map(|task_name| format!("task:{task_name}"))
                                        .unwrap_or_else(|| String::from("command_host")),
                                ),
                                crate::schema::ReadinessProbeTargetKind::Service => None,
                            },
                            endpoint: target.endpoint.clone(),
                        }
                    }),
                    method: probe.method.map(|method| method.as_str().to_string()),
                    path: probe.path.clone(),
                    headers: probe.headers.clone(),
                    success: probe
                        .success
                        .as_ref()
                        .map(
                            |success| crate::output::ExecutionTopologyReadinessSuccessSummary {
                                status: success.status.clone(),
                            },
                        )
                        .or_else(|| {
                            probe.expect_status.map(|status| {
                                crate::output::ExecutionTopologyReadinessSuccessSummary {
                                    status: vec![status],
                                }
                            })
                        }),
                    body: probe.body.as_ref().map(|body| {
                        crate::output::ExecutionTopologyReadinessBodySummary {
                            contains: body.contains.clone(),
                        }
                    }),
                    timeout_ms: probe.timeout,
                },
            )
        })
        .collect()
}

fn build_execution_topology_surface_summaries(
    contract: &Contract,
) -> BTreeMap<String, crate::output::ExecutionTopologySurfaceSummary> {
    contract
        .surfaces
        .iter()
        .map(|(name, surface)| {
            (
                name.clone(),
                crate::output::ExecutionTopologySurfaceSummary {
                    kind: surface.kind.as_str().to_string(),
                    port: surface.port,
                    label: surface.label.clone(),
                    purpose: surface.purpose.clone(),
                    visibility: surface
                        .visibility
                        .map(|visibility| visibility.as_str().to_string()),
                    path: surface.effective_path(),
                    readiness: surface.readiness.as_ref().map(|readiness| {
                        ExecutionTopologyReadinessSummary {
                            kind: readiness.kind.as_str().to_string(),
                            probe: None,
                            listener: None,
                            method: readiness.method.map(|method| method.as_str().to_string()),
                            path: readiness.path.clone().or_else(|| {
                                matches!(
                                    readiness.kind,
                                    crate::schema::TaskRuntimeReadinessKind::Http
                                )
                                .then(|| surface.effective_path())
                                .flatten()
                            }),
                            headers: readiness.headers.clone(),
                            success: readiness.success.as_ref().map(|success| {
                                crate::output::ExecutionTopologyReadinessSuccessSummary {
                                    status: success.status.clone(),
                                }
                            }),
                            body: readiness.body.as_ref().map(|body| {
                                crate::output::ExecutionTopologyReadinessBodySummary {
                                    contains: body.contains.clone(),
                                }
                            }),
                            interval: readiness.interval.clone(),
                            timeout: readiness.timeout.clone(),
                            retries: readiness.retries,
                            start_period: readiness.start_period.clone(),
                        }
                    }),
                },
            )
        })
        .collect()
}

fn build_execution_topology_task_summary<'a>(
    name: &'a str,
    task: &'a TaskSpec,
    current_os: &str,
    contract: &'a Contract,
) -> ExecutionTopologyTaskSummary<'a> {
    ExecutionTopologyTaskSummary {
        task: TaskSummary::from_spec(name, task, current_os, contract),
        runtime: task
            .runtime
            .as_ref()
            .map(|runtime| build_execution_topology_runtime_summary(runtime, contract)),
        targets: task
            .targets
            .iter()
            .map(|(target_name, target)| ExecutionTopologyTargetSummary {
                name: target_name.clone(),
                kind: match target.kind() {
                    crate::schema::TaskTargetKind::Service => "service",
                    crate::schema::TaskTargetKind::Url => "url",
                }
                .to_string(),
                override_input: target.override_input.clone(),
                url: target.url.clone(),
                activation_mode: target.activation.mode.as_str().to_string(),
                service: target.service.as_ref().map(|service| {
                    ExecutionTopologyTargetServiceSummary {
                        member: service.member.clone(),
                        task: service.task.clone(),
                        listener: service.listener.clone(),
                        address_view: match service.address_view {
                            crate::schema::TaskTargetAddressView::Topology => "topology",
                            crate::schema::TaskTargetAddressView::Host => "host",
                            crate::schema::TaskTargetAddressView::Internal => "internal",
                        }
                        .to_string(),
                    }
                }),
            })
            .collect(),
    }
}

fn build_execution_topology_runtime_summary(
    runtime: &crate::schema::TaskRuntimeSpec,
    contract: &Contract,
) -> ExecutionTopologyRuntimeSummary {
    ExecutionTopologyRuntimeSummary {
        kind: match runtime.kind {
            crate::schema::TaskRuntimeKind::Service => "service",
        }
        .to_string(),
        backend_binding: runtime.backend_binding.clone(),
        readiness: runtime
            .readiness
            .as_ref()
            .map(|readiness| ExecutionTopologyReadinessSummary {
                kind: readiness
                    .probe
                    .as_deref()
                    .and_then(|probe_name| contract.probe(probe_name))
                    .map(|probe| match probe.kind {
                        crate::schema::ReadinessProbeKind::Http => "http",
                        crate::schema::ReadinessProbeKind::Tcp => "tcp",
                    })
                    .or_else(|| readiness.kind.map(|kind| kind.as_str()))
                    .unwrap_or("unknown")
                    .to_string(),
                probe: readiness.probe.clone(),
                listener: readiness.listener.clone(),
                method: readiness.method.map(|method| method.as_str().to_string()),
                path: readiness.path.clone(),
                headers: readiness.headers.clone(),
                success: readiness.success.as_ref().map(|success| {
                    crate::output::ExecutionTopologyReadinessSuccessSummary {
                        status: success.status.clone(),
                    }
                }),
                body: readiness.body.as_ref().map(|body| {
                    crate::output::ExecutionTopologyReadinessBodySummary {
                        contains: body.contains.clone(),
                    }
                }),
                interval: readiness.interval.clone(),
                timeout: readiness.timeout.clone(),
                retries: readiness.retries,
                start_period: readiness.start_period.clone(),
            }),
        attached_surfaces: runtime.surfaces.names_cloned(),
        surface_attachments: runtime
            .surfaces
            .iter()
            .map(|(surface_name, attachment)| {
                (
                    surface_name.clone(),
                    crate::output::ExecutionTopologySurfaceAttachmentSummary {
                        uses_defaults: attachment.uses_defaults(),
                        bind: attachment.bind.as_ref().map(|bind| {
                            crate::output::ExecutionTopologySurfaceBindOverrideSummary {
                                address: bind.address.clone(),
                                port_mode: bind.port.as_ref().map(|port| match port.mode {
                                    crate::schema::TaskRuntimePortMode::Fixed => "fixed",
                                    crate::schema::TaskRuntimePortMode::Discover => "discover",
                                    crate::schema::TaskRuntimePortMode::Auto => "auto",
                                }
                                .to_string()),
                                port_value: bind.port.as_ref().and_then(|port| port.value),
                            }
                        }),
                        project: attachment.project.as_ref().map(|project| {
                            crate::output::ExecutionTopologySurfaceProjectionOverrideSummary {
                                host: project.host.as_ref().map(|host| {
                                    crate::output::ExecutionTopologySurfaceHostProjectionOverrideSummary {
                                        address: host.address.clone(),
                                        port_mode: host.port.as_ref().map(|port| match port.mode {
                                            crate::schema::TaskRuntimeHostPortMode::Fixed => "fixed",
                                            crate::schema::TaskRuntimeHostPortMode::Auto => "auto",
                                        }
                                        .to_string()),
                                        port_value: host.port.as_ref().and_then(|port| port.value),
                                        primary: host.primary,
                                        path: host.path.clone(),
                                    }
                                }),
                            }
                        }),
                    },
                )
            })
            .collect(),
        listeners: runtime
            .listeners
            .iter()
            .map(|(listener_name, listener)| {
                (
                    listener_name.clone(),
                    ExecutionTopologyListenerSummary {
                        protocol: match listener.protocol {
                            crate::schema::TaskRuntimeProtocol::Http => "http",
                            crate::schema::TaskRuntimeProtocol::Https => "https",
                            crate::schema::TaskRuntimeProtocol::Tcp => "tcp",
                        }
                        .to_string(),
                        bind_address: listener.bind.address.clone(),
                        bind_port_mode: match listener.bind.port.mode {
                            crate::schema::TaskRuntimePortMode::Fixed => "fixed",
                            crate::schema::TaskRuntimePortMode::Discover => "discover",
                            crate::schema::TaskRuntimePortMode::Auto => "auto",
                        }
                        .to_string(),
                        bind_port_value: listener.bind.port.value,
                        host_projection: listener.project.host.as_ref().map(|host| {
                            ExecutionTopologyHostProjectionSummary {
                                address: host.address.clone(),
                                port_mode: match host.port.mode {
                                    crate::schema::TaskRuntimeHostPortMode::Fixed => "fixed",
                                    crate::schema::TaskRuntimeHostPortMode::Auto => "auto",
                                }
                                .to_string(),
                                port_value: host.port.value,
                                primary: host.primary,
                                path: host.path.clone(),
                            }
                        }),
                    },
                )
            })
            .collect(),
    }
}

fn render_execution_topology_text(
    path: &str,
    contract_identity: &ContractIdentity,
    declared_execution: Option<&ExecutionSummary<'_>>,
    shared_backends: &[ExecutionTopologySharedBackendSummary],
    readiness_probes: &BTreeMap<String, ExecutionTopologyProbeSummary>,
    surfaces: &BTreeMap<String, crate::output::ExecutionTopologySurfaceSummary>,
    services: &[ServiceSummary],
    tasks: &[ExecutionTopologyTaskSummary<'_>],
) -> String {
    let mut output = format_command_header("EXECUTION TOPOLOGY", path);

    output.push_str("\n\n");
    output.push_str(&paint_section_title("Overview"));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Project:", "1;38;2;102;217;255"),
            &paint_code(&contract_identity.project.name),
        )
    ));
    if let Some(project_type) = contract_identity.project.project_type.as_deref() {
        output.push_str(&format!(
            "\n{}",
            section_list_row(
                &summary_bullet(),
                &paint("Type:", "1;38;2;102;217;255"),
                &paint_code(project_type),
            )
        ));
    }
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Services:", "1;38;2;102;217;255"),
            &paint(&services.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Tasks:", "1;38;2;102;217;255"),
            &paint(&tasks.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Shared Backends:", "1;38;2;102;217;255"),
            &paint(&shared_backends.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Readiness Probes:", "1;38;2;102;217;255"),
            &paint(&readiness_probes.len().to_string(), "1;38;2;255;255;255"),
        )
    ));
    output.push_str(&format!(
        "\n{}",
        section_list_row(
            &summary_bullet(),
            &paint("Surfaces:", "1;38;2;102;217;255"),
            &paint(&surfaces.len().to_string(), "1;38;2;255;255;255"),
        )
    ));

    if let Some(execution) = declared_execution {
        output.push_str("\n\n");
        output.push_str(&render_execution_summary_text(execution));
    }

    output.push_str(&render_execution_topology_shared_backends_text(
        shared_backends,
    ));
    output.push_str(&render_execution_topology_readiness_probes_text(
        readiness_probes,
    ));
    output.push_str(&render_execution_topology_surfaces_text(surfaces));
    output.push_str(&render_execution_topology_services_text(services));
    output.push_str(&render_execution_topology_tasks_text(tasks));
    output
}

fn render_execution_topology_shared_backends_text(
    shared_backends: &[ExecutionTopologySharedBackendSummary],
) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Shared Backends"));
    if shared_backends.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for shared_backend in shared_backends {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint(&shared_backend.name, "1")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Scope:"),
            shared_backend.scope
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Backend:"),
            shared_backend.backend
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Lifecycle:"),
            shared_backend.lifecycle
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Context:"),
            shared_backend.context.as_deref().unwrap_or("-")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Fulfillment:"),
            shared_backend.fulfillment.as_deref().unwrap_or("-")
        ));
        if let Some(environment) = shared_backend.environment.as_ref() {
            let mut details = Vec::new();
            if let Some(profile) = environment.profile.as_deref() {
                details.push(format!("profile={profile}"));
            }
            if let Some(image_alias) = environment.image_alias.as_deref() {
                details.push(format!("image_alias={image_alias}"));
            }
            if let Some(image) = environment.image.as_deref() {
                details.push(format!("image={image}"));
            }
            if let Some(source) = environment.source.as_deref() {
                details.push(format!("source={source}"));
            }
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Environment:"),
                if details.is_empty() {
                    String::from("-")
                } else {
                    details.join(", ")
                }
            ));
        }
    }

    output
}

fn render_execution_topology_readiness_probes_text(
    readiness_probes: &BTreeMap<String, ExecutionTopologyProbeSummary>,
) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Readiness Probes"));
    if readiness_probes.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for (probe_name, probe) in readiness_probes {
        output.push_str(&format!("\n\n{} {}", list_bullet(), paint(probe_name, "1")));
        output.push_str(&format!("\n  {} {}", paint_key("Kind:"), probe.kind));
        let source = if let Some(url) = probe.url.as_deref() {
            format!("literal URL {url}")
        } else if let Some(target) = probe.target.as_ref() {
            match target.kind.as_str() {
                "task" => format!(
                    "task {}.{} ({}, {})",
                    target.name,
                    target.listener.as_deref().unwrap_or("-"),
                    target.address_view.as_deref().unwrap_or("host"),
                    target.resolution_plane.as_deref().unwrap_or("command_host")
                ),
                "service" => format!(
                    "service {}.{}",
                    target.name,
                    target.endpoint.as_deref().unwrap_or("<auto>")
                ),
                _ => target.kind.clone(),
            }
        } else {
            String::from("-")
        };
        output.push_str(&format!("\n  {} {}", paint_key("Source:"), source));
        if let Some(method) = probe.method.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Method:"), method));
        }
        if let Some(observer) = probe
            .target
            .as_ref()
            .and_then(|target| target.observer.as_ref())
        {
            let observer_value = match observer.kind.as_str() {
                "task" => format!(
                    "{} ({})",
                    observer.task.as_deref().unwrap_or("-"),
                    observer.backend.as_deref().unwrap_or("-")
                ),
                _ => observer.kind.clone(),
            };
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Observer:"),
                observer_value
            ));
        }
        if let Some(path) = probe.path.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Path:"), path));
        }
        if let Some(success) = probe.success.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Success Status:"),
                success
                    .status
                    .iter()
                    .map(u16::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
        if let Some(body) = probe.body.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Body Contains:"),
                body.contains
            ));
        }
        if !probe.headers.is_empty() {
            output.push_str(&format!("\n  {}", paint_key("Headers:")));
            for (header, value) in &probe.headers {
                output.push_str(&format!("\n    {} {}={}", detail_arrow(), header, value));
            }
        }
        if let Some(timeout_ms) = probe.timeout_ms {
            output.push_str(&format!("\n  {} {}ms", paint_key("Timeout:"), timeout_ms));
        }
    }

    output
}

fn render_execution_topology_surfaces_text(
    surfaces: &BTreeMap<String, crate::output::ExecutionTopologySurfaceSummary>,
) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Surfaces"));
    if surfaces.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for (surface_name, surface) in surfaces {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint(surface_name, "1")
        ));
        if let Some(label) = surface.label.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Label:"), label));
        }
        if let Some(purpose) = surface.purpose.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Purpose:"), purpose));
        }
        if let Some(visibility) = surface.visibility.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Visibility:"), visibility));
        }
        output.push_str(&format!("\n  {} {}", paint_key("Kind:"), surface.kind));
        output.push_str(&format!("\n  {} {}", paint_key("Port:"), surface.port));
        if let Some(path) = surface.path.as_deref() {
            output.push_str(&format!("\n  {} {}", paint_key("Path:"), path));
        }
        if let Some(readiness) = surface.readiness.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Readiness:"),
                readiness.kind
            ));
        }
    }

    output
}

fn render_execution_topology_services_text(services: &[ServiceSummary]) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Services"));
    if services.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for service in services {
        output.push_str(&format!(
            "\n\n{} {} [{}]",
            list_bullet(),
            paint(&service.name, "1"),
            if service.required {
                "required"
            } else {
                "optional"
            }
        ));
        let manager = service
            .manager
            .as_ref()
            .map(|manager| manager.kind.as_str())
            .or(service.provider.as_deref())
            .unwrap_or("-");
        output.push_str(&format!("\n  {} {manager}", paint_key("Manager:")));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Depends On:"),
            if service.depends_on.is_empty() {
                String::from("-")
            } else {
                service.depends_on.join(", ")
            }
        ));
        if let Some(readiness) = service.readiness.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Readiness:"),
                format_service_readiness_summary(readiness)
            ));
        }
        if !service.endpoints.is_empty() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Endpoints:"),
                service
                    .endpoints
                    .iter()
                    .map(|(context, endpoint)| {
                        format!("{context}=http://{}:{}", endpoint.address, endpoint.port)
                    })
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
    }

    output
}

fn render_execution_topology_tasks_text(tasks: &[ExecutionTopologyTaskSummary<'_>]) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&paint_section_title("Tasks"));
    if tasks.is_empty() {
        output.push_str(&format!("\n{}", detail_list_item("none")));
        return output;
    }

    for task in tasks {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint(task.task.name, "1")
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Context:"),
            task.task.context.unwrap_or("-")
        ));
        output.push_str(&format!("\n  {} {}", paint_key("Kind:"), task.task.kind));
        if let Some(launch) = task.task.launch.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Launch:"),
                render_task_launch_text(launch)
            ));
        }
        if let Some(runtime) = task.runtime.as_ref() {
            output.push_str(&format!("\n  {} {}", paint_key("Runtime:"), runtime.kind));
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Backend Binding:"),
                runtime.backend_binding.as_deref().unwrap_or("-")
            ));
            if let Some(readiness) = runtime.readiness.as_ref() {
                let mut readiness_detail = readiness
                    .probe
                    .as_deref()
                    .map(|probe| format!("probe:{probe}"))
                    .or_else(|| Some(readiness.kind.clone()))
                    .unwrap_or_else(|| String::from("unknown"));
                if let Some(listener) = readiness.listener.as_deref() {
                    readiness_detail.push_str(&format!(" via {listener}"));
                }
                if let Some(path) = readiness.path.as_deref() {
                    readiness_detail.push_str(&format!(" path={path}"));
                }
                output.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Readiness:"),
                    readiness_detail
                ));
            }
            if !runtime.attached_surfaces.is_empty() {
                output.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Attached Surfaces:"),
                    runtime.attached_surfaces.join(", ")
                ));
                if !runtime.surface_attachments.is_empty() {
                    output.push_str(&format!("\n  {}", paint_key("Surface Attachment Intent:")));
                    for (surface_name, attachment) in &runtime.surface_attachments {
                        let mut details = Vec::new();
                        if attachment.uses_defaults {
                            details.push(String::from("default"));
                        } else {
                            if attachment.bind.is_some() {
                                details.push(String::from("bind override"));
                            }
                            if attachment.project.is_some() {
                                details.push(String::from("project override"));
                            }
                            if attachment
                                .project
                                .as_ref()
                                .and_then(|project| project.host.as_ref())
                                .and_then(|host| host.primary)
                                .is_some_and(|primary| primary)
                            {
                                details.push(String::from("primary"));
                            }
                        }
                        output.push_str(&format!(
                            "\n    {} {} ({})",
                            detail_arrow(),
                            surface_name,
                            if details.is_empty() {
                                String::from("custom")
                            } else {
                                details.join(", ")
                            }
                        ));
                    }
                }
            }
            if !runtime.listeners.is_empty() {
                output.push_str(&format!("\n  {}", paint_key("Listeners:")));
                for (listener_name, listener) in &runtime.listeners {
                    let mut bind_detail =
                        format!("{} {}", listener.bind_address, listener.bind_port_mode);
                    if let Some(value) = listener.bind_port_value {
                        bind_detail.push_str(&format!(":{value}"));
                    }
                    let mut listener_line =
                        format!("{listener_name} ({}, bind={bind_detail}", listener.protocol);
                    if let Some(host_projection) = listener.host_projection.as_ref() {
                        listener_line.push_str(&format!(
                            ", host={} {}",
                            host_projection.address, host_projection.port_mode
                        ));
                        if let Some(value) = host_projection.port_value {
                            listener_line.push_str(&format!(":{value}"));
                        }
                        if host_projection.primary {
                            listener_line.push_str(", primary");
                        }
                        if let Some(path) = host_projection.path.as_deref() {
                            listener_line.push_str(&format!(", path={path}"));
                        }
                    }
                    listener_line.push(')');
                    output.push_str(&format!("\n    {} {listener_line}", detail_arrow()));
                }
            }
        }
        if !task.targets.is_empty() {
            output.push_str(&format!("\n  {}", paint_key("Targets:")));
            for target in &task.targets {
                let target_line = if let Some(service) = target.service.as_ref() {
                    let mut service_ref = String::new();
                    if let Some(member) = service.member.as_deref() {
                        service_ref.push_str(&format!("{member}."));
                    }
                    service_ref.push_str(&service.task);
                    if let Some(listener) = service.listener.as_deref() {
                        service_ref.push_str(&format!(".{listener}"));
                    }
                    format!(
                        "{} ({}, activation={}, view={})",
                        target.name, service_ref, target.activation_mode, service.address_view
                    )
                } else {
                    format!(
                        "{} (url={}, activation={})",
                        target.name,
                        target.url.as_deref().unwrap_or("-"),
                        target.activation_mode
                    )
                };
                output.push_str(&format!("\n    {} {target_line}", detail_arrow()));
            }
        }
    }

    output
}

fn execution_plan_overrides(overrides: ExecutionOverrides) -> Option<ExecutionPlanOverrides> {
    let overrides = ExecutionPlanOverrides {
        backend: overrides.backend.map(format_backend).map(str::to_string),
        lifecycle: overrides
            .lifecycle
            .map(format_lifecycle)
            .map(str::to_string),
    };

    if overrides.backend.is_none() && overrides.lifecycle.is_none() {
        None
    } else {
        Some(overrides)
    }
}

fn execution_plan_error(error: &RunError) -> String {
    match error {
        RunError::MissingContainerImage { .. } => String::from(
            "`ota execution plan` requires `execution.backends.container.image` for container execution",
        ),
        RunError::MissingContainerLifecycle { .. } => String::from(
            "`ota execution plan` requires an explicit `execution.lifecycle` for container execution",
        ),
        RunError::MissingContainerBackendCli { engines, .. } => format!(
            "container execution requires one of the supported container backend CLIs on PATH: {engines}"
        ),
        RunError::MissingRemoteProvider { .. } => String::from(
            "`ota execution plan` requires `execution.backends.remote.provider` for remote execution",
        ),
        RunError::MissingRemoteTarget {
            provider,
            example_target,
            ..
        } => format!(
            "remote provider `{provider}` requires `execution.backends.remote.target` (example: `{example_target}`)"
        ),
        RunError::MissingBackendProvider { provider, .. } => format!(
            "remote provider `{provider}` is not declared as a backend provider in ota.yaml"
        ),
        RunError::UnsupportedBackendProviderVersion {
            provider,
            api_version,
            ..
        } => format!(
            "backend provider `{provider}` has unsupported `api_version` `{api_version}`; expected `1`"
        ),
        RunError::UnsupportedTaskModeOverride {
            task,
            requested_mode,
            supported_modes,
        } => format!(
            "task `{task}` was requested with `--mode {requested_mode}`, but it only supports modes: {supported_modes}"
        ),
        other => other.to_string(),
    }
}

fn execution_backend_resolution_lines(
    contract: &Contract,
    overrides: ExecutionOverrides,
    task_name: Option<&str>,
    backend: Backend,
) -> Vec<String> {
    let backend_label = format_backend(backend);
    let backend_flag = format!("--mode {backend_label}");
    if overrides.backend == Some(backend) {
        let subject = task_name
            .map(|task| format!("task `{task}`"))
            .unwrap_or_else(|| String::from("execution inspection"));
        return vec![format!("{subject} was requested with `{backend_flag}`")];
    }

    if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.preferred)
        == Some(backend)
    {
        let subject = task_name
            .map(|task| format!("task `{task}`"))
            .unwrap_or_else(|| String::from("execution inspection"));
        return vec![
            format!("{subject} resolves to {backend_label} execution by default"),
            format!("this contract sets `execution.preferred: {backend_label}`"),
        ];
    }
    if let Some(task_name) = task_name
        && contract
            .tasks
            .get(task_name)
            .and_then(|task| task.mode_default_backend())
            == Some(backend)
    {
        return vec![
            format!("task `{task_name}` resolves to {backend_label} execution by default"),
            format!("this task sets `tasks.{task_name}.execution.default_mode: {backend_label}`"),
        ];
    }

    let subject = task_name
        .map(|task| format!("task `{task}`"))
        .unwrap_or_else(|| String::from("execution inspection"));
    vec![format!("{subject} resolved to {backend_label} execution")]
}

fn render_execution_plan_structured_error(
    contract: &Contract,
    contract_path: &Path,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    error: &RunError,
) -> String {
    let text_path_display = display_contract_target(&compact_contract_path(contract_path), member);
    let (summary, mut why_lines, next_steps) = match error {
        RunError::MissingContainerImage { .. } => (
            "Container execution is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                String::from("add `execution.backends.container.image` to the repo contract"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingContainerLifecycle { .. } => (
            "Container execution lifecycle is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                String::from("add `execution.lifecycle` to the repo contract"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingContainerBackendCli { engines, .. } => (
            "Missing container execution backend CLI",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Container),
            vec![
                format!("install one of the supported container engines: `{engines}`"),
                String::from(
                    "or rerun without container mode if this inspection should stay on the host",
                ),
            ],
        ),
        RunError::MissingRemoteProvider { .. } => (
            "Remote execution is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Remote),
            vec![
                String::from("add `execution.backends.remote.provider` to the repo contract"),
                String::from("or rerun without remote mode if this inspection should stay local"),
            ],
        ),
        RunError::MissingRemoteTarget {
            provider,
            example_target,
            ..
        } => (
            "Remote execution target is not configured",
            execution_backend_resolution_lines(contract, overrides, None, Backend::Remote),
            vec![
                format!(
                    "add `execution.backends.remote.target` for provider `{provider}` (for example `{example_target}`)"
                ),
                String::from("or rerun without remote mode if this inspection should stay local"),
            ],
        ),
        RunError::MissingBackendProvider { provider, .. } => (
            "Backend provider is not configured",
            vec![format!(
                "execution inspection requested backend provider `{provider}`, but the repo does not declare it"
            )],
            vec![format!(
                "declare backend provider `{provider}` in the repo contract or rerun with a supported built-in backend"
            )],
        ),
        RunError::UnsupportedBackendProviderVersion {
            provider,
            api_version,
            ..
        } => (
            "Backend provider version is unsupported",
            vec![format!(
                "backend provider `{provider}` declares unsupported `api_version` `{api_version}`; expected `1`"
            )],
            vec![String::from(
                "update the backend provider declaration to `api_version: 1`, then rerun `ota execution plan`",
            )],
        ),
        RunError::UnsupportedHostPlatform {
            context,
            os,
            arch,
            supported,
            supported_arch,
            ..
        } => (
            "Unsupported host platform",
            vec![format!(
                "the selected execution context `{context}` supports `{supported}` on `{supported_arch}`, but the current host is `{os}/{arch}`"
            )],
            vec![
                if os == "windows" && supported.split(", ").any(|platform| platform == "linux") {
                    String::from(
                        "run this path on a supported host or use WSL, then rerun `ota execution plan`",
                    )
                } else if supported_arch != "all architectures" {
                    String::from(
                        "run this path on a supported host architecture, then rerun `ota execution plan`",
                    )
                } else {
                    String::from(
                        "run this path on a supported host, then rerun `ota execution plan`",
                    )
                },
            ],
        ),
        RunError::UnsupportedTaskModeOverride {
            task,
            requested_mode,
            supported_modes,
        } => (
            "Requested mode is not declared for this task",
            vec![
                format!("task `{task}` was requested with `--mode {requested_mode}`"),
                format!("declared mode branches: {supported_modes}"),
            ],
            vec![
                format!(
                    "run `{}` to inspect declared mode branches for this task",
                    repo_tasks_use_command(member)
                ),
                String::from("rerun without the explicit mode override to use the task default"),
            ],
        ),
        _ => (
            "Execution plan could not be resolved",
            vec![execution_plan_error(error)],
            vec![String::from(
                "repair the declared execution settings, then rerun `ota execution plan`",
            )],
        ),
    };

    if matches!(
        error,
        RunError::MissingContainerImage { .. }
            | RunError::MissingContainerLifecycle { .. }
            | RunError::MissingContainerBackendCli { .. }
    ) {
        why_lines.push(match error {
            RunError::MissingContainerImage { .. } => {
                String::from("this contract does not declare `execution.backends.container.image`")
            }
            RunError::MissingContainerLifecycle { .. } => {
                String::from("this contract does not declare `execution.lifecycle`")
            }
            RunError::MissingContainerBackendCli { engines, .. } => {
                format!("no supported container engine is available on PATH: {engines}")
            }
            _ => unreachable!(),
        });
    } else if matches!(error, RunError::MissingRemoteProvider { .. }) {
        why_lines.push(String::from(
            "this contract does not declare `execution.backends.remote.provider`",
        ));
    } else if matches!(error, RunError::MissingRemoteTarget { .. }) {
        why_lines.push(String::from(
            "this contract does not declare `execution.backends.remote.target`",
        ));
    }

    structured_error_text(
        "EXECUTION PLAN",
        &text_path_display,
        summary,
        &why_lines,
        &next_steps,
    )
}

fn resolve_execution_plan(
    contract: &Contract,
    contract_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> Result<ExecutionPlanResolved, RunError> {
    resolve_execution_plan_for_selected_task(
        contract,
        contract_path,
        overrides,
        selected_execution_plan_task_name(contract, workflow_name)
            .map(|task_name| (task_name, "workflow task")),
    )
}

fn resolve_execution_plan_for_task(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Result<ExecutionPlanResolved, RunError> {
    resolve_execution_plan_for_selected_task(
        contract,
        contract_path,
        overrides,
        Some((task_name, "task")),
    )
}

fn resolve_execution_plan_for_selected_task(
    contract: &Contract,
    contract_path: &Path,
    overrides: ExecutionOverrides,
    selected_task: Option<(&str, &'static str)>,
) -> Result<ExecutionPlanResolved, RunError> {
    let selected_task_name = selected_task.map(|(task_name, _)| task_name);
    let selected_task_source = selected_task.map(|(_, source)| source);
    let task_name = selected_task_name.unwrap_or("execution plan");
    let effective = effective_task_execution(contract, task_name, overrides);
    let backend = effective.backend;
    let lifecycle = effective.lifecycle;
    let execution = contract.execution.as_ref();
    let selected_task_lifecycle = selected_task_name
        .and_then(|selected_task_name| contract.tasks.get(selected_task_name))
        .and_then(|task| task.mode_execution_branch(backend))
        .and_then(|branch| branch.lifecycle)
        .is_some();
    let context_lifecycle = effective
        .context_name
        .and_then(|context_name| {
            execution.and_then(|execution| execution.contexts.get(context_name))
        })
        .is_some_and(|context| context.lifecycle.is_some());
    let backend_source = if overrides.backend.is_some() {
        "override"
    } else if let Some(source) = selected_task_source {
        source
    } else if execution
        .and_then(|execution| execution.default_context.as_deref())
        .is_some_and(|name| effective.context_name == Some(name))
    {
        "default context"
    } else if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.preferred)
        .is_some()
    {
        "contract preferred"
    } else {
        "default"
    };
    let mut lifecycle_source = if overrides.lifecycle.is_some() {
        String::from("override")
    } else if selected_task_lifecycle {
        String::from(selected_task_source.unwrap_or("task"))
    } else if context_lifecycle {
        String::from("context lifecycle")
    } else if contract
        .execution
        .as_ref()
        .and_then(|execution| execution.lifecycle)
        .is_some()
    {
        String::from("contract lifecycle")
    } else {
        String::from("implicit")
    };
    let planned_container_image = if backend == Backend::Container {
        resolve_execution_plan_container_image(
            contract,
            contract_path,
            task_name,
            effective.context_name,
            effective.lifecycle,
            effective
                .container
                .map(|container| container.image.as_str()),
        )?
    } else {
        None
    };
    let resolved_backend = match resolve_execution_backend_with_contract_path(
        contract,
        task_name,
        overrides,
        Some(contract_path),
    ) {
        Ok(resolved_backend) => Ok(resolved_backend),
        Err(RunError::MissingContainerBackendCli { .. }) if backend == Backend::Container => {
            let (container, image, _) = resolve_effective_task_container_backend(
                contract,
                task_name,
                overrides,
                Some(contract_path),
            )?;
            let lifecycle =
                effective
                    .lifecycle
                    .ok_or_else(|| RunError::MissingContainerLifecycle {
                        task: task_name.to_string(),
                    })?;
            let target = match lifecycle {
                Lifecycle::Persistent => {
                    execution_target(contract, contract_path, backend, Some(lifecycle))
                }
                Lifecycle::Ephemeral => ephemeral_container_target(contract, contract_path),
            };
            let target_strategy = match lifecycle {
                Lifecycle::Persistent => String::from("persistent container"),
                Lifecycle::Ephemeral => String::from("ephemeral per-run container"),
            };
            return Ok(ExecutionPlanResolved {
                backend: format_backend(backend).to_string(),
                backend_source: String::from(backend_source),
                lifecycle: Some(format_lifecycle(lifecycle).to_string()),
                lifecycle_source: Some(lifecycle_source),
                image: Some(planned_container_image.unwrap_or(image)),
                engine: selected_container_engine_from_backend(Some(&container)),
                engine_candidates: container_engine_candidates_from_backend(Some(&container)),
                provider: None,
                target,
                target_strategy,
                cwd: None,
            });
        }
        Err(error) => Err(error),
    }?;

    let resolved_lifecycle = match &resolved_backend {
        ResolvedExecutionBackend::Container { lifecycle, .. } => Some(*lifecycle),
        _ => lifecycle,
    };
    if backend == Backend::Container
        && resolved_lifecycle.is_some()
        && overrides.lifecycle.is_none()
        && contract
            .execution
            .as_ref()
            .and_then(|execution| execution.lifecycle)
            .is_none()
    {
        lifecycle_source = String::from("context lifecycle");
    }
    let lifecycle_source = resolved_lifecycle.map(|_| lifecycle_source.clone());

    let (image, engine, engine_candidates, provider, target, target_strategy, cwd) =
        match resolved_backend {
            ResolvedExecutionBackend::Native { .. } => (
                None,
                None,
                Vec::new(),
                None,
                None,
                String::from("host process"),
                None,
            ),
            ResolvedExecutionBackend::Container {
                image,
                engine,
                lifecycle,
                ..
            } => {
                let target = match lifecycle {
                    Lifecycle::Persistent => {
                        execution_target(contract, contract_path, backend, Some(lifecycle))
                    }
                    Lifecycle::Ephemeral => ephemeral_container_target(contract, contract_path),
                };
                let target_strategy = match lifecycle {
                    Lifecycle::Persistent => String::from("persistent container"),
                    Lifecycle::Ephemeral => String::from("ephemeral per-run container"),
                };
                (
                    Some(planned_container_image.unwrap_or(image)),
                    Some(engine),
                    effective
                        .container
                        .map(|container| container_engine_candidates_from_backend(Some(container)))
                        .unwrap_or_else(|| container_engine_candidates(contract)),
                    None,
                    target,
                    target_strategy,
                    None,
                )
            }
            ResolvedExecutionBackend::Remote {
                shared_local_backend: _,
                provider,
                target,
                cwd,
                ..
            } => (
                None,
                None,
                Vec::new(),
                Some(provider),
                Some(target),
                String::from("remote target"),
                cwd,
            ),
            ResolvedExecutionBackend::BackendProvider {
                provider,
                target,
                cwd,
                ..
            } => (
                None,
                None,
                Vec::new(),
                Some(provider),
                Some(target),
                String::from("remote target"),
                cwd,
            ),
        };

    Ok(ExecutionPlanResolved {
        backend: format_backend(backend).to_string(),
        backend_source: backend_source.to_string(),
        lifecycle: resolved_lifecycle.map(format_lifecycle).map(str::to_string),
        lifecycle_source,
        image,
        engine,
        engine_candidates,
        provider,
        target,
        target_strategy,
        cwd,
    })
}

fn resolve_execution_plan_container_image(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    context_name: Option<&str>,
    lifecycle: Option<Lifecycle>,
    fallback_image: Option<&str>,
) -> Result<Option<String>, RunError> {
    let Some(fallback_image) = fallback_image else {
        return Ok(None);
    };
    let Some(context_name) = context_name else {
        return Ok(Some(fallback_image.to_string()));
    };
    let Some(execution) = contract.execution.as_ref() else {
        return Ok(Some(fallback_image.to_string()));
    };

    let matching_backends = execution
        .shared_backends
        .iter()
        .filter(|(binding_name, shared_backend)| {
            if shared_backend.backend != Backend::Container
                || !lifecycle.is_none_or(|selected| shared_backend.lifecycle == selected)
            {
                return false;
            }

            let backend_context_name = shared_backend.context.as_deref().or_else(|| {
                contract.tasks.iter().find_map(|(bound_task_name, task)| {
                    (task.backend_binding_for_backend(Backend::Container)
                        == Some(binding_name.as_str()))
                    .then(|| {
                        selected_task_context_for_backend(
                            contract,
                            bound_task_name,
                            Backend::Container,
                        )
                        .map(|(name, _)| name)
                    })
                    .flatten()
                })
            });

            backend_context_name == Some(context_name)
        })
        .collect::<Vec<(&String, &ExecutionSharedBackend)>>();

    match matching_backends.as_slice() {
        [] => Ok(Some(fallback_image.to_string())),
        [(binding_name, shared_backend)] => {
            let (image, _) = crate::runner::resolve_shared_local_backend_environment(
                Some(contract_path),
                task_name,
                binding_name.as_str(),
                shared_backend.environment.as_ref(),
                fallback_image,
            )?;
            Ok(Some(image))
        }
        _ => Err(RunError::SharedLocalBackendResolutionFailed {
            task: task_name.to_string(),
            binding: String::from("<execution-plan>"),
            details: format!(
                "multiple shared local backends match container context `{context_name}`; add a single deterministic `execution.shared_backends.<name>.context` binding for execution planning"
            ),
        }),
    }
}

struct EnvReport {
    ok: bool,
    workflow: Option<String>,
    profile: Option<String>,
    summary: EnvSummary,
    sources: Vec<EnvSourceEntry>,
    rendered_artifacts: Vec<EnvRenderedArtifactEntry>,
    env: Vec<EnvEntry>,
}

pub fn env(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    workflow_name: Option<&str>,
    task: Option<&str>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("ENV", "ota env", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=env")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=env"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(workflow_name) = workflow_name {
        debug_lines.push(format!("DEBUG workflow={workflow_name}"));
    }
    if let Some(task) = task {
        debug_lines.push(format!("DEBUG task={task}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "ENV",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota env` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota env", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let selected_workflow_name = if task.is_some() || workflow_name.is_some() {
                    workflow_name
                } else {
                    None
                };
                let workflow_summary = match selected_workflow_name {
                    Some(_) => match resolve_selected_workflow_summary(
                        &target.contract,
                        &target.contract_path,
                        selected_workflow_name,
                    ) {
                        Ok(summary) => summary,
                        Err(error) => return CommandOutput::failure_with_code(error, 2),
                    },
                    None => None,
                };
                let effective_workflow_name =
                    workflow_summary.as_ref().map(|workflow| workflow.name);
                match build_env_report(
                    &target.contract,
                    &target.contract_path,
                    selected_workflow_name,
                    task,
                ) {
                    Ok(report) => match format {
                        OutputFormat::Text => CommandOutput {
                            stdout: render_env_text(&text_path_display, task, &report),
                            stderr: None,
                            exit_code: if report.ok { 0 } else { 1 },
                        },
                        OutputFormat::Json => CommandOutput {
                            stdout: to_json(&EnvSuccess {
                                ok: report.ok,
                                path: &path_display,
                                task,
                                workflow: report.workflow.as_deref(),
                                profile: report.profile.as_deref(),
                                summary: report.summary,
                                sources: report.sources,
                                rendered_artifacts: report.rendered_artifacts,
                                env: report.env,
                            }),
                            stderr: None,
                            exit_code: if report.ok { 0 } else { 1 },
                        },
                    },
                    Err(error) => match format {
                        OutputFormat::Text => CommandOutput::failure(error),
                        OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                            ok: false,
                            path: &path_display,
                            task,
                            workflow: effective_workflow_name,
                            error: &error,
                        })),
                    },
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "ENV",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota env", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                    ok: false,
                    path: &path_display,
                    task,
                    workflow: workflow_name,
                    error: &errors.to_string(),
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "ENV",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota env", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&EnvFailure {
                    ok: false,
                    path: &path_display,
                    task,
                    workflow: workflow_name,
                    error: &error.to_string(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

#[derive(Debug, Serialize)]
struct AssistProposalChange<'a> {
    path: &'a str,
    action: &'static str,
    before: YamlValue,
    after: YamlValue,
}

#[derive(Debug, Serialize)]
struct AssistProposalSuccess<'a> {
    ok: bool,
    path: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    member: Option<&'a str>,
    mode: &'static str,
    operation: &'static str,
    subject: BTreeMap<&'static str, &'a str>,
    inputs: BTreeMap<&'static str, String>,
    assumptions: Vec<String>,
    changes: Vec<AssistProposalChange<'a>>,
    diff: String,
    validation: Vec<String>,
    next: String,
}

#[derive(Debug, Serialize)]
struct AssistProposalFailure<'a> {
    ok: bool,
    path: &'a str,
    #[serde(skip_serializing_if = "Option::is_none")]
    member: Option<&'a str>,
    operation: &'static str,
    #[serde(skip_serializing_if = "BTreeMap::is_empty")]
    subject: BTreeMap<&'static str, &'a str>,
    why: String,
    next: String,
}

enum ResolvedAssistReadinessTarget {
    Task {
        name: String,
        listener: String,
        existing: Option<TaskRuntimeReadinessSpec>,
    },
    Service {
        name: String,
        from: Option<String>,
        endpoint: Option<String>,
        compose_managed: bool,
        systemd_managed: bool,
        existing: Option<ServiceReadinessSpec>,
    },
}

pub fn assist_declare_readiness(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    task: Option<&str>,
    service: Option<&str>,
    endpoint: Option<&str>,
    style: Option<AssistReadinessStyleArg>,
    write: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => missing_repo_contract_command_output(
                        "ASSIST DECLARE-READINESS",
                        "ota assist declare-readiness",
                        &error,
                    )
                    .unwrap_or_else(|| CommandOutput::failure(error.to_string())),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=assist declare-readiness")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=assist declare-readiness"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(task) = task {
        debug_lines.push(format!("DEBUG task={task}"));
    }
    if let Some(service) = service {
        debug_lines.push(format!("DEBUG service={service}"));
    }
    if let Some(endpoint) = endpoint {
        debug_lines.push(format!("DEBUG endpoint={endpoint}"));
    }
    if let Some(style) = style {
        debug_lines.push(format!(
            "DEBUG style={}",
            assist_readiness_style_name(style)
        ));
    }
    if write {
        debug_lines.push(String::from("DEBUG mode=write"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "ASSIST DECLARE-READINESS",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from(
                        "`ota assist declare-readiness` reads repo contracts such as `ota.yaml`",
                    ),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command(
                    "ota assist declare-readiness",
                    &resolved_path,
                ),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let source_contents = match fs::read_to_string(&target.contract_path) {
                    Ok(contents) => contents,
                    Err(error) => {
                        let error = format!(
                            "failed to read `{}`: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: assist_subject_map(task, service),
                                    why: error,
                                    next: String::from(
                                        "repair the contract path, then rerun the assist command",
                                    ),
                                }))
                            }
                        };
                    }
                };
                let mut document: YamlValue = match serde_yaml::from_str(&source_contents) {
                    Ok(document) => document,
                    Err(error) => {
                        let why = format!(
                            "failed to parse `{}` for assist preview: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(why.clone()),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: assist_subject_map(task, service),
                                    why,
                                    next: String::from(
                                        "repair the existing contract, then rerun the assist command",
                                    ),
                                }))
                            }
                        };
                    }
                };

                let proposal = match build_assist_readiness_proposal(
                    &target.contract,
                    task,
                    service,
                    endpoint,
                    style,
                ) {
                    Ok(proposal) => proposal,
                    Err((why, next)) => {
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(assist_text_failure(
                                "ota assist declare-readiness",
                                &text_path_display,
                                &why,
                                &next,
                            )),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: assist_subject_map(task, service),
                                    why,
                                    next,
                                }))
                            }
                        };
                    }
                };

                let after_value = proposal.after_value.clone();
                set_yaml_path(
                    &mut document,
                    &proposal
                        .yaml_path
                        .iter()
                        .map(String::as_str)
                        .collect::<Vec<_>>(),
                    after_value.clone(),
                );
                let yaml = match serde_yaml::to_string(&document) {
                    Ok(yaml) => yaml,
                    Err(error) => {
                        let error = format!(
                            "failed to serialize assist proposal for `{}`: {}",
                            compact_contract_path(&target.contract_path),
                            error
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error.clone()),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&AssistProposalFailure {
                                    ok: false,
                                    path: &path_display,
                                    member,
                                    operation: "declare-readiness",
                                    subject: proposal.subject_json(),
                                    why: error,
                                    next: String::from(
                                        "rerun the assist command after fixing the repo contract",
                                    ),
                                }))
                            }
                        };
                    }
                };

                if let Err(error) = validate_assist_contract_update(
                    &resolved_path,
                    member,
                    &target.contract_path,
                    &yaml,
                ) {
                    return match format {
                        OutputFormat::Text => CommandOutput::failure(error.clone()),
                        OutputFormat::Json => {
                            CommandOutput::failure(to_json(&AssistProposalFailure {
                                ok: false,
                                path: &path_display,
                                member,
                                operation: "declare-readiness",
                                subject: proposal.subject_json(),
                                why: error,
                                next: String::from(
                                    "adjust the selector or style, then rerun the assist command",
                                ),
                            }))
                        }
                    };
                }

                let validation =
                    assist_validation_commands(&resolved_path, &target.contract_path, member);

                if write {
                    match fs::write(&target.contract_path, yaml) {
                        Ok(()) => match format {
                            OutputFormat::Text => {
                                CommandOutput::success(render_assist_readiness_text(
                                    &text_path_display,
                                    &proposal,
                                    "write",
                                    &validation,
                                    None,
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::success(to_json(&AssistProposalSuccess {
                                    ok: true,
                                    path: &path_display,
                                    member,
                                    mode: "write",
                                    operation: "declare-readiness",
                                    subject: proposal.subject_json(),
                                    inputs: proposal.inputs_json(),
                                    assumptions: proposal.assumptions.clone(),
                                    changes: vec![AssistProposalChange {
                                        path: &proposal.change_path,
                                        action: "set",
                                        before: proposal.before_value.clone(),
                                        after: after_value,
                                    }],
                                    diff: proposal.diff(),
                                    validation,
                                    next: String::from(
                                        "rerun `ota doctor` to inspect the updated readiness contract",
                                    ),
                                }))
                            }
                        },
                        Err(error) => {
                            let error = format!(
                                "failed to write `{}`: {}",
                                compact_contract_path(&target.contract_path),
                                error
                            );
                            match format {
                                OutputFormat::Text => CommandOutput::failure(error.clone()),
                                OutputFormat::Json => {
                                    CommandOutput::failure(to_json(&AssistProposalFailure {
                                        ok: false,
                                        path: &path_display,
                                        member,
                                        operation: "declare-readiness",
                                        subject: proposal.subject_json(),
                                        why: error,
                                        next: String::from(
                                            "repair the contract path or permissions, then rerun with `--write`",
                                        ),
                                    }))
                                }
                            }
                        }
                    }
                } else {
                    let preview_target_path = if member.is_some() {
                        &resolved_path
                    } else {
                        &target.contract_path
                    };
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_assist_readiness_text(
                            &text_path_display,
                            &proposal,
                            "preview",
                            &validation,
                            Some(&proposal.preview_next_command(member, preview_target_path)),
                        )),
                        OutputFormat::Json => {
                            CommandOutput::success(to_json(&AssistProposalSuccess {
                                ok: true,
                                path: &path_display,
                                member,
                                mode: "preview",
                                operation: "declare-readiness",
                                subject: proposal.subject_json(),
                                inputs: proposal.inputs_json(),
                                assumptions: proposal.assumptions.clone(),
                                changes: vec![AssistProposalChange {
                                    path: &proposal.change_path,
                                    action: "set",
                                    before: proposal.before_value.clone(),
                                    after: after_value,
                                }],
                                diff: proposal.diff(),
                                validation,
                                next: proposal.preview_next_command(member, preview_target_path),
                            }))
                        }
                    }
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "ASSIST DECLARE-READINESS",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota assist declare-readiness",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&AssistProposalFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    operation: "declare-readiness",
                    subject: assist_subject_map(task, service),
                    why: errors.to_string(),
                    next: String::from(
                        "repair the existing contract, then rerun the assist command",
                    ),
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "ASSIST DECLARE-READINESS",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota assist declare-readiness",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&AssistProposalFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    operation: "declare-readiness",
                    subject: assist_subject_map(task, service),
                    why: error.to_string(),
                    next: String::from("repair the contract path, then rerun the assist command"),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

struct AssistReadinessProposal {
    subject_kind: &'static str,
    subject_name: String,
    endpoint: Option<String>,
    style: AssistReadinessStyleArg,
    assumptions: Vec<String>,
    change_path: String,
    yaml_path: Vec<String>,
    before_value: YamlValue,
    after_value: YamlValue,
}

impl AssistReadinessProposal {
    fn subject_json(&self) -> BTreeMap<&'static str, &str> {
        let mut subject = BTreeMap::new();
        subject.insert(self.subject_kind, self.subject_name.as_str());
        subject
    }

    fn inputs_json(&self) -> BTreeMap<&'static str, String> {
        let mut inputs = BTreeMap::new();
        if let Some(endpoint) = &self.endpoint {
            inputs.insert("endpoint", endpoint.clone());
        }
        inputs.insert("style", assist_readiness_style_name(self.style).to_string());
        inputs
    }

    fn diff(&self) -> String {
        format!(
            "{}\n- {}\n+ {}",
            self.change_path,
            compact_yaml_inline(&self.before_value),
            compact_yaml_inline(&self.after_value)
        )
    }

    fn preview_next_command(&self, member: Option<&str>, contract_path: &Path) -> String {
        let mut command = String::from("ota assist declare-readiness");
        if let Some(member) = member {
            command.push_str(&format!(" --member {member}"));
        }
        command.push_str(&format!(" --{} {}", self.subject_kind, self.subject_name));
        if let Some(endpoint) = &self.endpoint {
            command.push_str(&format!(" --endpoint {endpoint}"));
        }
        command.push_str(&format!(
            " --style {} --write",
            assist_readiness_style_name(self.style)
        ));
        let command = command_for_repo_from_contract_path(&command, contract_path);
        format!("rerun with `{command}` to apply this readiness change")
    }
}

struct AssistServiceProposal {
    subject_name: String,
    manager: Option<AssistServiceManagerArg>,
    manager_name: Option<String>,
    compose_file: Option<String>,
    compose_service: Option<String>,
    host_unit: Option<String>,
    host_scope: Option<AssistHostScopeArg>,
    endpoint: Option<String>,
    endpoint_context: Option<String>,
    address: Option<String>,
    port: Option<u16>,
    producer_task: Option<String>,
    producer_repo: Option<String>,
    producer_listener: Option<String>,
    required: bool,
    style: Option<AssistReadinessStyleArg>,
    assumptions: Vec<String>,
    change_path: String,
    yaml_path: Vec<String>,
    before_value: YamlValue,
    after_value: YamlValue,
}

impl AssistServiceProposal {
    fn subject_json(&self) -> BTreeMap<&'static str, &str> {
        let mut subject = BTreeMap::new();
        subject.insert("service", self.subject_name.as_str());
        subject
    }

    fn inputs_json(&self) -> BTreeMap<&'static str, String> {
        let mut inputs = BTreeMap::new();
        inputs.insert("required", self.required.to_string());
        if let Some(manager) = self.manager {
            inputs.insert("manager", assist_service_manager_name(manager).to_string());
        }
        if let Some(endpoint) = &self.endpoint {
            inputs.insert("endpoint", endpoint.clone());
        }
        if let Some(endpoint_context) = &self.endpoint_context {
            inputs.insert("endpoint_context", endpoint_context.clone());
        }
        if let Some(address) = &self.address {
            inputs.insert("address", address.clone());
        }
        if let Some(port) = self.port {
            inputs.insert("port", port.to_string());
        }
        if let Some(style) = self.style {
            inputs.insert("style", assist_readiness_style_name(style).to_string());
        }
        if let Some(name) = &self.manager_name {
            inputs.insert("manager_name", name.clone());
        }
        if let Some(file) = &self.compose_file {
            inputs.insert("compose_file", file.clone());
        }
        if let Some(service) = &self.compose_service {
            inputs.insert("compose_service", service.clone());
        }
        if let Some(unit) = &self.host_unit {
            inputs.insert("host_unit", unit.clone());
        }
        if let Some(scope) = self.host_scope {
            inputs.insert("host_scope", assist_host_scope_name(scope).to_string());
        }
        if let Some(producer) = &self.producer_task {
            let selector = match self.producer_listener.as_deref() {
                Some(listener) => format!("{producer}:{listener}"),
                None => producer.clone(),
            };
            inputs.insert("producer", selector);
        }
        if let Some(repo) = &self.producer_repo {
            inputs.insert("producer_repo", repo.clone());
        }
        inputs
    }

    fn diff(&self) -> String {
        format!(
            "{}\n- {}\n+ {}",
            self.change_path,
            compact_yaml_inline(&self.before_value),
            compact_yaml_inline(&self.after_value)
        )
    }

    fn preview_next_command(&self, member: Option<&str>, contract_path: &Path) -> String {
        let mut command = String::from("ota assist declare-service");
        if let Some(member) = member {
            command.push_str(&format!(" --member {member}"));
        }
        command.push_str(&format!(" --name {}", self.subject_name));
        if let Some(manager) = self.manager {
            command.push_str(&format!(
                " --manager {}",
                assist_service_manager_name(manager)
            ));
        }
        if let Some(endpoint) = &self.endpoint {
            command.push_str(&format!(" --endpoint {}", endpoint));
        }
        if let Some(endpoint_context) = &self.endpoint_context {
            command.push_str(&format!(
                " --endpoint-context {}",
                shell_quote(endpoint_context)
            ));
        }
        if let Some(address) = &self.address {
            command.push_str(&format!(" --address {}", address));
        }
        if let Some(port) = self.port {
            command.push_str(&format!(" --port {}", port));
        }
        if self.required {
            command.push_str(" --required true");
        }
        if let Some(name) = &self.manager_name {
            if !(self.manager == Some(AssistServiceManagerArg::Compose) && name == "local") {
                command.push_str(&format!(" --manager-name {}", shell_quote(name)));
            }
        }
        if let Some(file) = &self.compose_file {
            command.push_str(&format!(" --compose-file {}", shell_quote(file)));
        }
        if let Some(service) = &self.compose_service {
            command.push_str(&format!(" --compose-service {}", shell_quote(service)));
        }
        if let Some(unit) = &self.host_unit {
            command.push_str(&format!(" --host-unit {}", shell_quote(unit)));
        }
        if let Some(scope) = self.host_scope {
            if scope != AssistHostScopeArg::System {
                command.push_str(&format!(" --host-scope {}", assist_host_scope_name(scope)));
            }
        }
        if let Some(style) = self.style {
            command.push_str(&format!(" --style {}", assist_readiness_style_name(style)));
        }
        if let Some(producer) = &self.producer_task {
            let selector = match self.producer_listener.as_deref() {
                Some(listener) => format!("{producer}:{listener}"),
                None => producer.clone(),
            };
            command.push_str(&format!(" --producer {}", shell_quote(&selector)));
        }
        if let Some(repo) = &self.producer_repo {
            command.push_str(&format!(" --producer-repo {}", repo));
        }
        command.push_str(" --write");
        let command = command_for_repo_from_contract_path(&command, contract_path);
        format!("rerun with `{command}` to apply this service change")
    }
}

enum AssistSetupServicesMode {
    Preserve,
    Set(Vec<String>),
    Clear,
}

struct AssistSetupProposal {
    assumptions: Vec<String>,
    before_value: YamlValue,
    after_value: YamlValue,
    write_value: YamlValue,
    body_input_kind: Option<&'static str>,
    body_input: Option<String>,
    copy_from: Option<String>,
    copy_to: Option<String>,
    services_mode: AssistSetupServicesMode,
    internal_input: Option<bool>,
}

impl AssistSetupProposal {
    fn subject_json(&self) -> BTreeMap<&'static str, &str> {
        let mut subject = BTreeMap::new();
        subject.insert("task", "setup");
        subject
    }

    fn inputs_json(&self) -> BTreeMap<&'static str, String> {
        let mut inputs = BTreeMap::new();
        if let (Some(kind), Some(body)) = (self.body_input_kind, self.body_input.as_ref()) {
            inputs.insert(kind, body.clone());
        }
        if let Some(copy_from) = self.copy_from.as_ref() {
            inputs.insert("copy_from", copy_from.clone());
        }
        if let Some(copy_to) = self.copy_to.as_ref() {
            inputs.insert("copy_to", copy_to.clone());
        }
        match &self.services_mode {
            AssistSetupServicesMode::Preserve => {}
            AssistSetupServicesMode::Set(services) => {
                inputs.insert("services", services.join(","));
            }
            AssistSetupServicesMode::Clear => {
                inputs.insert("clear_services", String::from("true"));
            }
        }
        if let Some(internal) = self.internal_input {
            inputs.insert("internal", internal.to_string());
        }
        inputs
    }

    fn diff(&self) -> String {
        format!(
            "tasks.setup\n- {}\n+ {}",
            compact_yaml_inline(&self.before_value),
            compact_yaml_inline(&self.after_value)
        )
    }

    fn preview_next_command(&self, member: Option<&str>, contract_path: &Path) -> String {
        let mut command = String::from("ota assist wire-setup");
        if let Some(member) = member {
            command.push_str(&format!(" --member {member}"));
        }
        if let (Some(kind), Some(body)) = (self.body_input_kind, self.body_input.as_ref()) {
            command.push_str(&format!(" --{kind} {}", shell_quote(body)));
        }
        if let Some(copy_from) = self.copy_from.as_ref() {
            command.push_str(&format!(" --copy-from {}", shell_quote(copy_from)));
        }
        if let Some(copy_to) = self.copy_to.as_ref() {
            command.push_str(&format!(" --copy-to {}", shell_quote(copy_to)));
        }
        match &self.services_mode {
            AssistSetupServicesMode::Preserve => {}
            AssistSetupServicesMode::Set(services) => {
                for service in services {
                    command.push_str(&format!(" --service {service}"));
                }
            }
            AssistSetupServicesMode::Clear => {
                command.push_str(" --clear-services");
            }
        }
        if let Some(internal) = self.internal_input {
            command.push_str(&format!(" --internal {internal}"));
        }
        command.push_str(" --write");
        let command = command_for_repo_from_contract_path(&command, contract_path);
        format!("rerun with `{command}` to apply this setup change")
    }
}

struct AssistBindTaskProposal {
    consumer_task: String,
    target_name: String,
    producer_task: String,
    producer_member: Option<String>,
    listener: String,
    address_view: TaskTargetAddressView,
    activation: TaskTargetActivationMode,
    override_input: Option<String>,
    assumptions: Vec<String>,
    before_value: YamlValue,
    after_value: YamlValue,
    write_value: YamlValue,
}

impl AssistBindTaskProposal {
    fn subject_json(&self) -> BTreeMap<&'static str, &str> {
        let mut subject = BTreeMap::new();
        subject.insert("task", self.consumer_task.as_str());
        subject.insert("target", self.target_name.as_str());
        subject
    }

    fn inputs_json(&self) -> BTreeMap<&'static str, String> {
        let mut inputs = BTreeMap::new();
        let mut to = self.producer_task.clone();
        to.push(':');
        to.push_str(&self.listener);
        inputs.insert("to", to);
        inputs.insert(
            "address_view",
            assist_task_target_address_view_name(self.address_view).to_string(),
        );
        inputs.insert(
            "activation",
            assist_task_target_activation_mode_name(self.activation).to_string(),
        );
        if let Some(member) = &self.producer_member {
            inputs.insert("producer_member", member.clone());
        }
        if let Some(override_input) = &self.override_input {
            inputs.insert("override_input", override_input.clone());
        }
        inputs
    }

    fn diff(&self) -> String {
        format!(
            "tasks.{}.targets.{}\n- {}\n+ {}",
            self.consumer_task,
            self.target_name,
            compact_yaml_inline(&self.before_value),
            compact_yaml_inline(&self.after_value)
        )
    }

    fn preview_next_command(&self, member: Option<&str>, contract_path: &Path) -> String {
        let mut command = String::from("ota assist bind-task");
        if let Some(member) = member {
            command.push_str(&format!(" --member {member}"));
        }
        command.push_str(&format!(" --task {}", self.consumer_task));
        command.push_str(&format!(" --target {}", self.target_name));
        if let Some(producer_member) = &self.producer_member {
            command.push_str(&format!(" --producer-member {producer_member}"));
        }
        command.push_str(&format!(" --to {}:{}", self.producer_task, self.listener));
        command.push_str(&format!(
            " --address-view {}",
            assist_task_target_address_view_name(self.address_view)
        ));
        command.push_str(&format!(
            " --activation {}",
            assist_task_target_activation_mode_name(self.activation)
        ));
        if let Some(override_input) = &self.override_input {
            command.push_str(&format!(
                " --override-input {}",
                shell_quote(override_input)
            ));
        }
        command.push_str(" --write");
        let command = command_for_repo_from_contract_path(&command, contract_path);
        format!("rerun with `{command}` to apply this task binding")
    }
}

