pub fn workspace_receipt(
    path: Option<&Path>,
    file_override: Option<&Path>,
    jobs: usize,
    progress_json: bool,
    format: OutputFormat,
    archive: bool,
    debug: bool,
) -> CommandOutput {
    if jobs == 0 {
        return finalize_debug(
            CommandOutput::failure_with_code(String::from("`--jobs` must be greater than zero"), 2),
            debug,
            vec![
                String::from("DEBUG command=workspace.receipt"),
                String::from("DEBUG jobs=0"),
            ],
        );
    }

    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE RECEIPT",
                        "ota workspace receipt",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.receipt")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.receipt"),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG jobs={jobs}"),
        format!("DEBUG progress_json={progress_json}"),
    ];

    finalize_debug(
        match load_and_run_workspace_receipt(
            &resolved_path,
            jobs,
            if progress_json {
                Some(WorkspaceProgressMode::Json)
            } else {
                None
            },
        ) {
            Ok((workspace_contract, mut report)) => {
                let root = resolved_path.parent().unwrap_or_else(|| Path::new("."));
                let snapshot =
                    match build_contract_snapshot_artifact(root, &workspace_contract, archive) {
                        Ok(snapshot) => snapshot,
                        Err(error) => return CommandOutput::failure(error),
                    };
                let normalized_snapshot =
                    match normalized_contract_snapshot_value(&workspace_contract) {
                        Ok(snapshot) => snapshot,
                        Err(error) => return CommandOutput::failure(error),
                    };
                report.receipt.contract_snapshot_hash = Some(snapshot.hash);
                report.receipt.contract_snapshot_ref = snapshot
                    .archive_path
                    .as_deref()
                    .map(receipt_storage_path_display);
                report.receipt.assumption_set_hash =
                    match assumption_set_hash_from_snapshot(&normalized_snapshot) {
                        Ok(hash) => Some(hash),
                        Err(error) => return CommandOutput::failure(error),
                    };
                let archive_path = if archive {
                    let archive_path = match next_receipt_archive_path(root, "workspace-receipt") {
                        Ok(path) => path,
                        Err(error) => return CommandOutput::failure(error),
                    };
                    let archive_path_display = receipt_storage_path_display(&archive_path);
                    let payload = WorkspaceReceiptSuccess {
                        ok: report.receipt.ok,
                        path: &path_display,
                        mode: "receipt",
                        summary: report.receipt.summary,
                        receipt: report.receipt.clone(),
                        archive_path: Some(archive_path_display.as_str()),
                        repos: &report.repos,
                    };
                    if let Err(error) = write_receipt_archive(&archive_path, &payload) {
                        return CommandOutput::failure(error);
                    }
                    if let Err(error) = prune_receipt_archives(
                        root,
                        "workspace-receipt",
                        RECEIPT_ARCHIVE_LIMIT,
                        None,
                    ) {
                        return CommandOutput::failure(error);
                    }
                    Some(archive_path)
                } else {
                    None
                };

                report.archive_path = archive_path;
                render_workspace_receipt(&compact_path_display, &report, format)
            }
            Err(WorkspaceProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_workspace_contract_output(
                    "WORKSPACE RECEIPT",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    workspace_invalid_contract_next_steps("ota workspace receipt", &resolved_path),
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
            Err(WorkspaceProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE RECEIPT",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps("ota workspace receipt", &resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

