fn render_confirmed_agent_boundary_preview(contract_path: &Path) -> Result<String, String> {
    let contents = fs::read_to_string(contract_path).map_err(|error| {
        format!(
            "failed to read `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })?;
    let review_yaml = confirm_agent_boundary_contract_yaml(contract_path, &contents)?;
    parse_contract_str(contract_path, &review_yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(contract_path))
                .map_err(|error| error.to_string())
        })?;
    Ok(review_yaml)
}

fn write_confirmed_agent_boundary(contract_path: &Path) -> Result<(), String> {
    let contents = fs::read_to_string(contract_path).map_err(|error| {
        format!(
            "failed to read `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })?;
    let review_yaml = confirm_agent_boundary_contract_yaml(contract_path, &contents)?;
    parse_contract_str(contract_path, &review_yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(contract_path))
                .map_err(|error| error.to_string())
        })?;
    fs::write(contract_path, review_yaml).map_err(|error| {
        format!(
            "failed to write `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })
}

fn confirm_agent_boundary_contract_yaml(
    contract_path: &Path,
    contents: &str,
) -> Result<String, String> {
    let mut document: YamlValue = serde_yaml::from_str(contents).map_err(|error| {
        format!(
            "failed to parse `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })?;
    let root = document.as_mapping_mut().ok_or_else(|| {
        format!(
            "`{}` is not a valid mapping contract",
            compact_contract_path(contract_path)
        )
    })?;
    let agent = root
        .get_mut(YamlValue::String(String::from("agent")))
        .and_then(YamlValue::as_mapping_mut)
        .ok_or_else(|| String::from("the repo contract does not declare an `agent` block yet"))?;
    let inferred_boundary = agent
        .get_mut(YamlValue::String(String::from("inferred_boundary")))
        .and_then(YamlValue::as_mapping_mut)
        .ok_or_else(|| String::from("the contract does not mark the agent boundary as inferred"))?;
    let reviewed_key = YamlValue::String(String::from("reviewed"));
    match inferred_boundary.get(&reviewed_key) {
        Some(YamlValue::Bool(true)) => return Ok(contents.to_string()),
        Some(YamlValue::Bool(false)) | None => {}
        Some(_) => {
            return Err(String::from(
                "`agent.inferred_boundary.reviewed` must be a boolean before Ota can confirm it",
            ));
        }
    }
    inferred_boundary.insert(reviewed_key, YamlValue::Bool(true));
    serde_yaml::to_string(&document).map_err(|error| {
        format!(
            "failed to serialize `{}`: {error}",
            compact_contract_path(contract_path)
        )
    })
}

fn render_agents_task_list(output: &mut String, label: &str, tasks: &[String]) {
    output.push_str("- `");
    output.push_str(label);
    output.push_str("`:\n");
    for value in tasks {
        output.push_str("  - `");
        output.push_str(value);
        output.push_str("` (`ota run ");
        output.push_str(value);
        output.push_str("`)\n");
    }
}

const AGENTS_GENERATED_START: &str = "<!-- ota-generated-agent-guidance:start -->";
const AGENTS_GENERATED_END: &str = "<!-- ota-generated-agent-guidance:end -->";

fn merge_agents_markdown(existing: &str, generated: &str) -> String {
    if let Some(start_index) = existing.find(AGENTS_GENERATED_START)
        && let Some(end_index) = existing[start_index..].find(AGENTS_GENERATED_END)
    {
        let end_index = start_index + end_index + AGENTS_GENERATED_END.len();
        let mut merged = String::new();
        merged.push_str(existing[..start_index].trim_end());
        if !merged.is_empty() {
            merged.push_str("\n\n");
        }
        merged.push_str(AGENTS_GENERATED_START);
        merged.push('\n');
        merged.push_str(generated);
        if !generated.ends_with('\n') {
            merged.push('\n');
        }
        merged.push_str(AGENTS_GENERATED_END);
        merged.push_str(&existing[end_index..]);
        return merged;
    }

    let mut merged = existing.trim_end().to_string();
    if !merged.is_empty() {
        merged.push_str("\n\n");
    }
    merged.push_str(AGENTS_GENERATED_START);
    merged.push('\n');
    merged.push_str(generated);
    if !generated.ends_with('\n') {
        merged.push('\n');
    }
    merged.push_str(AGENTS_GENERATED_END);
    merged.push('\n');
    merged
}

fn agents_markdown_already_present(existing: &str, generated: &str) -> bool {
    let existing = existing.replace("\r\n", "\n");
    let generated = generated.replace("\r\n", "\n");
    existing.contains(&generated)
}

fn render_agent_summary_text(agent: &AgentSummary<'_>, include_notes: bool) -> Option<String> {
    let mut lines = Vec::new();
    lines.push(paint_section_title("AGENT"));

    let mut overview = Vec::new();
    overview.push((
        String::from("Posture:"),
        paint_backticked_code(agent.posture),
    ));
    if let Some(entrypoint) = agent.entrypoint {
        overview.push((
            String::from("Entrypoint:"),
            paint_backticked_code(entrypoint),
        ));
    }
    if let Some(default_task) = agent.default_task {
        overview.push((
            String::from("Default task:"),
            paint_backticked_code(default_task),
        ));
    }
    if agent
        .bootstrap
        .as_ref()
        .and_then(|bootstrap| bootstrap.ota.as_ref())
        .is_some()
    {
        overview.push((
            String::from("Bootstrap:"),
            String::from("ota install commands available"),
        ));
    }
    if let Some(reviewed) = agent.inferred_boundary_reviewed {
        let review_status = if reviewed {
            paint("reviewed", "1;38;2;255;255;255")
        } else {
            paint("inferred (needs review)", "1;38;2;255;216;107")
        };
        overview.push((String::from("Boundary review:"), review_status));
    }

    if !overview.is_empty() {
        lines.push(String::new());
        lines.push(paint_section_title("Overview"));
        for (label, value) in overview {
            lines.push(section_list_row(
                &summary_bullet(),
                &paint_key(&label),
                &value,
            ));
        }
    }

    let mut execution = Vec::new();
    if !agent.safe_tasks.is_empty() {
        execution.push(render_agent_counted_code_list_row(
            "Safe tasks",
            &agent.safe_tasks,
        ));
    }
    if !agent.verify_after_changes.is_empty() {
        execution.push(render_agent_counted_code_list_row(
            "Verify after changes",
            &agent.verify_after_changes,
        ));
    }
    if !execution.is_empty() {
        lines.push(String::new());
        lines.push(paint_section_title("Execution"));
        lines.extend(execution);
    }

    let (writable_paths, writable_exceptions) =
        summarize_agent_writable_paths(&agent.writable_paths);
    let mut boundary = Vec::new();
    if !writable_paths.is_empty() {
        boundary.push(render_agent_counted_code_list_row(
            "Writable paths",
            &writable_paths,
        ));
    }
    if !writable_exceptions.is_empty() {
        boundary.push(render_agent_counted_code_list_row(
            "Writable exceptions",
            &writable_exceptions,
        ));
    }
    if !agent.protected_paths.is_empty() {
        boundary.push(render_agent_counted_code_list_row(
            "Protected paths",
            &agent.protected_paths,
        ));
    }
    if !boundary.is_empty() {
        lines.push(String::new());
        lines.push(paint_section_title("Boundary"));
        lines.extend(boundary);
    }

    if include_notes
        && let Some(notes) = agent.notes
        && !notes.trim().is_empty()
    {
        lines.push(String::new());
        lines.push(paint_section_title("Notes"));
        for line in notes.lines() {
            lines.push(format!(" {}  {}", summary_bullet(), line));
        }
    }

    if lines.len() == 1 {
        None
    } else {
        Some(lines.join("\n"))
    }
}

fn render_agent_counted_code_list_row<T: AsRef<str>>(label: &str, items: &[T]) -> String {
    let mut output = String::new();
    let label = format!("{label} ({}):", items.len());
    append_wrapped_labeled_text(
        &mut output,
        &label,
        &render_inline_code_list(items),
        "",
        96,
        true,
        paint_key,
        |value| value.to_string(),
    );
    output.trim_start_matches('\n').to_string()
}

fn summarize_agent_writable_paths<T: AsRef<str>>(paths: &[T]) -> (Vec<String>, Vec<String>) {
    let mut summarized = Vec::new();
    let mut exceptions = Vec::new();
    let mut seen_roots = BTreeSet::new();
    let mut seen_summarized = BTreeSet::new();
    let mut seen_exceptions = BTreeSet::new();

    for path in paths {
        let value = path.as_ref();
        if let Some((root, remainder)) = value.split_once('/') {
            if seen_roots.insert(root.to_string()) {
                let rendered_root = format!("{root}/");
                if seen_summarized.insert(rendered_root.clone()) {
                    summarized.push(rendered_root);
                }
            }
            let final_segment = remainder.rsplit('/').next().unwrap_or(remainder);
            if looks_like_repo_file_path(final_segment) && seen_exceptions.insert(value.to_string())
            {
                exceptions.push(value.to_string());
            }
            continue;
        }

        let rendered = if value.starts_with('.') || looks_like_repo_file_path(value) {
            value.to_string()
        } else {
            format!("{value}/")
        };
        if seen_summarized.insert(rendered.clone()) {
            summarized.push(rendered);
        }
    }

    (summarized, exceptions)
}

fn looks_like_repo_file_path(value: &str) -> bool {
    if Path::new(value).extension().is_some() {
        return true;
    }
    matches!(
        value,
        "Dockerfile"
            | "Containerfile"
            | "Makefile"
            | "GNUmakefile"
            | "Justfile"
            | "Brewfile"
            | "Procfile"
            | "Tiltfile"
            | "Vagrantfile"
            | "Gemfile"
            | "Rakefile"
            | "README"
            | "CHANGELOG"
            | "LICENSE"
            | "NOTICE"
    )
}

fn render_up(
    path: &str,
    member: Option<&str>,
    status: &str,
    phase: &str,
    report: DoctorReport,
    ready: bool,
    service: Option<&str>,
    service_command: Option<&str>,
    task: Option<&str>,
    task_command: Option<&str>,
    stderr: Option<&str>,
    exit_code: Option<i32>,
    receipt: &ExecutionReceipt,
    show_receipt: bool,
    format: OutputFormat,
) -> CommandOutput {
    let cause = primary_up_failure_cause(
        status,
        phase,
        &report.findings,
        receipt.backend.as_deref(),
        stderr,
        service,
        task,
    );
    match format {
        OutputFormat::Text => render_up_text(
            path,
            status,
            phase,
            report,
            ready,
            receipt.backend.as_deref(),
            service,
            service_command,
            task,
            task_command,
            stderr,
            exit_code,
            receipt,
            show_receipt,
        ),
        OutputFormat::Json => render_up_json(
            path,
            member,
            status,
            phase,
            cause.map(up_failure_cause_key),
            report,
            ready,
            stderr.filter(|stderr| !stderr.is_empty()),
            service,
            task,
            exit_code,
            receipt,
        ),
    }
}

fn render_up_result(
    path: &str,
    text_path: &str,
    result: RepoUpResult,
    format: OutputFormat,
    show_receipt: bool,
) -> CommandOutput {
    if let Some(preview) = result.preview.as_ref() {
        return render_up_preview_result(
            path,
            text_path,
            result.status,
            result.phase,
            &preview.summary,
            &preview.contract_identity,
            &preview.execution,
            &preview.plan,
            &preview.blockers,
            result.ok,
            format,
        );
    }

    match format {
        OutputFormat::Text => {
            let member = member_from_display_contract_target(text_path);
            let cause = primary_up_failure_cause(
                result.status,
                result.phase,
                &result.report.findings,
                result.receipt.backend.as_deref(),
                (!result.stderr.is_empty()).then_some(result.stderr.as_str()),
                result.service.as_deref(),
                result.task.as_deref(),
            );
            let receipt = normalized_up_receipt(
                member,
                result.status,
                result.phase,
                &result.report.findings,
                (!result.stderr.is_empty()).then_some(result.stderr.as_str()),
                &result.receipt,
            );
            let mut stdout = render_up_section(text_path, &result);
            if show_receipt {
                stdout.push_str(&render_execution_receipt_text(&receipt));
            }
            stdout.push('\n');
            stdout.push_str(&render_up_summary_block(
                &receipt,
                result.task.as_deref().or(Some(result.phase)),
                "UP SUMMARY",
                cause,
            ));
            append_receipt_next_block(&mut stdout, &receipt);
            CommandOutput {
                stdout,
                stderr: None,
                exit_code: result.exit_code.unwrap_or(if result.ok { 0 } else { 1 }),
            }
        }
        OutputFormat::Json => render_up(
            path,
            member_from_display_contract_target(text_path),
            result.status,
            result.phase,
            result.report,
            result.ok,
            result.service.as_deref(),
            result.service_command.as_deref(),
            result.task.as_deref(),
            result.task_command.as_deref(),
            (!result.stderr.is_empty()).then_some(result.stderr.as_str()),
            result.exit_code,
            &result.receipt,
            false,
            format,
        ),
    }
}

fn render_up_preview_result(
    path: &str,
    text_path: &str,
    status: &str,
    phase: &str,
    summary: &DoctorSummary,
    contract_identity: &ContractIdentity,
    execution: &UpPreviewExecution,
    plan: &UpPreviewPlan,
    blockers: &[Finding],
    ready: bool,
    format: OutputFormat,
) -> CommandOutput {
    match format {
        OutputFormat::Text => CommandOutput {
            stdout: render_up_preview_text(text_path, summary, contract_identity, execution, plan),
            stderr: None,
            exit_code: if ready { 0 } else { 1 },
        },
        OutputFormat::Json => CommandOutput {
            stdout: to_json(&UpPreviewStatus {
                ok: ready,
                path,
                dry_run: true,
                status,
                preview_status: doctor_preview_status_label(summary.verdict),
                phase,
                summary: summary.clone(),
                contract_identity: contract_identity.clone(),
                execution: execution.clone(),
                plan: plan.clone(),
                blockers,
            }),
            stderr: None,
            exit_code: if ready { 0 } else { 1 },
        },
    }
}

fn up_result_json_value(path: &str, result: &RepoUpResult) -> JsonValue {
    if let Some(preview) = result.preview.as_ref() {
        json!({
            "ok": result.ok,
            "path": path,
            "dry_run": true,
            "status": result.status,
            "preview_status": doctor_preview_status_label(preview.summary.verdict),
            "phase": result.phase,
            "summary": preview.summary,
            "contract_identity": preview.contract_identity,
            "execution": preview.execution,
            "plan": preview.plan,
            "blockers": preview.blockers,
        })
    } else {
        let receipt = normalized_up_receipt(
            None,
            result.status,
            result.phase,
            &result.report.findings,
            (!result.stderr.is_empty()).then_some(result.stderr.as_str()),
            &result.receipt,
        );
        let cause = primary_up_failure_cause(
            result.status,
            result.phase,
            &result.report.findings,
            receipt.backend.as_deref(),
            (!result.stderr.is_empty()).then_some(result.stderr.as_str()),
            result.service.as_deref(),
            result.task.as_deref(),
        )
        .map(up_failure_cause_key);
        json!({
            "ok": result.ok,
            "path": path,
            "status": result.status,
            "phase": result.phase,
            "cause": cause,
            "findings": result.report.findings,
            "receipt": receipt,
            "stderr": result.stderr,
            "service": result.service,
            "task": result.task,
            "exit_code": result.exit_code,
        })
    }
}

