    #[test]
    fn proof_runtime_up_exit_primary_blocker_overrides_surface_blocker() {
        let summary = crate::output::DoctorSummary {
            verdict: DoctorVerdict::NotReady,
            agent_verdict: DoctorVerdict::Ready,
            error_count: 1,
            warn_count: 0,
            info_count: 0,
            primary_blocker: Some(crate::output::DoctorPrimaryBlocker {
                code: None,
                severity: FindingSeverity::Error,
                summary: String::from("Surface readiness failed: app"),
                why: String::from("surface app did not become ready"),
                next: String::from("rerun `ota doctor`"),
                provenance: None,
                provenance_key: None,
            }),
        };
        let overridden = super::proof_runtime_up_exit_primary_blocker(
            &summary,
            Some("`ota up --stream` exited while waiting for readiness (exit code 1)"),
            "up.log",
        )
        .expect("surface blocker should be overridden for pre-readiness up exit");
        assert_eq!(overridden.summary, "Run task exited before readiness");
        assert!(overridden.why.contains("exit code 1"));
        assert_eq!(
            overridden.next,
            "inspect up.log and rerun `ota proof runtime`"
        );

        let mut summary = summary;
        summary.primary_blocker = Some(overridden);

        let rendered = strip_ansi_codes(&super::render_proof_runtime_text(
            "./ota.yaml",
            Some("default"),
            Path::new("./ota.yaml"),
            "readiness",
            super::proof_runtime_status_word(summary.verdict, "readiness", false, false, false),
            &summary,
            Some("`ota up --stream` exited while waiting for readiness (exit code 1)"),
            "topology.json",
            "doctor.json",
            "up.log",
            &[],
            None,
            None,
            None,
        ));

        assert!(rendered.contains("Run task exited before readiness"));
        assert!(rendered.contains("inspect up.log and rerun `ota proof runtime`"));
        assert!(!rendered.contains("Surface readiness failed: app"));
    }

    #[test]
    fn proof_runtime_likely_cause_surfaces_loopback_service_drift() {
        let fixture = TempDir::new().unwrap();
        let artifact_dir = fixture.path().join(".ota/proof/docker-build");
        fs::create_dir_all(&artifact_dir).unwrap();
        let up_log = artifact_dir.join("up.log");
        fs::write(&up_log, "timed out while waiting for readiness\n").unwrap();
        fs::write(
            artifact_dir.join("up-detached-run.log"),
            "worker | Error: connect ECONNREFUSED 127.0.0.1:6379\n",
        )
        .unwrap();

        let summary = crate::output::DoctorSummary {
            verdict: DoctorVerdict::NotReady,
            agent_verdict: DoctorVerdict::Ready,
            error_count: 1,
            warn_count: 0,
            info_count: 0,
            primary_blocker: Some(crate::output::DoctorPrimaryBlocker {
                code: None,
                severity: FindingSeverity::Error,
                summary: String::from("Run task exited before readiness"),
                why: String::from("timed out while waiting for readiness"),
                next: String::from("inspect up.log"),
                provenance: None,
                provenance_key: None,
            }),
        };

        let likely = super::proof_runtime_likely_cause(
            &summary,
            Some("timed out while waiting for readiness"),
            &up_log,
        )
        .expect("likely cause should be detected");
        assert_eq!(
            likely,
            super::ProofRuntimeLikelyCause::LoopbackServiceDrift {
                artifact: artifact_dir.join("up-detached-run.log"),
                service: String::from("Redis"),
                host: String::from("127.0.0.1"),
                port: Some(6379),
            }
        );
        let likely_message = likely.message();
        assert!(likely_message.contains("Redis"), "{likely_message}");
        assert!(
            likely_message.contains("task `env_files`"),
            "{likely_message}"
        );
        assert!(
            likely_message.contains("compose `manager.env_file`"),
            "{likely_message}"
        );
    }

