    #[test]
    fn env_outputs_redact_secret_values_loaded_from_declared_sources() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        let contract_contents = r#"
version: 1
project:
  name: ota
env:
  vars:
    APP_TOKEN:
      required: true
      secret: true
  sources:
    - kind: properties
      path: app.properties
tasks:
  test:
    run: echo test
"#;
        fs::write(&contract_path, contract_contents).unwrap();
        fs::write(
            fixture.path().join("app.properties"),
            "app.token=super-secret-token\n",
        )
        .unwrap();
        let original = std::env::var_os("APP_TOKEN");
        unsafe {
            std::env::remove_var("APP_TOKEN");
        }

        let contract = parse_contract_str(&contract_path, contract_contents).unwrap();
        let report = build_env_report(&contract, &contract_path, None, None).unwrap();
        let rendered = strip_ansi_codes(&render_env_text(".", None, &report));
        assert!(rendered.contains("Value: <redacted>"), "{rendered}");
        assert!(!rendered.contains("super-secret-token"), "{rendered}");

        let output = env_command(
            Some(contract_path.as_path()),
            None,
            None,
            None,
            None,
            OutputFormat::Json,
            false,
        );
        let body: serde_json::Value = serde_json::from_str(&output.stdout).unwrap();
        assert_eq!(body["env"][0]["value"], "<redacted>");
        assert_eq!(body["env"][0]["source_kind"], "properties");
        assert!(
            !output.stdout.contains("super-secret-token"),
            "{}",
            output.stdout
        );

        match original {
            Some(value) => unsafe { std::env::set_var("APP_TOKEN", value) },
            None => unsafe { std::env::remove_var("APP_TOKEN") },
        }
    }

    fn make_source_bootstrap_shims(dir: &Path) {
        let bootstrap_log = dir.join("brew-bootstrap.log");
        let brew_log = dir.join("brew.log");
        let node_log = dir.join("node.log");
        let brew_path = dir.join("brew");
        let node_path = dir.join("node");
        let brew_script = format!(
            "#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\n/bin/cat > \"{}\" <<'NODEEOF'\n#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\ncase \"$1\" in\n  --version|-v) echo 'v22.0.0' ;;\n  *) exit 0 ;;\nesac\nNODEEOF\n/bin/chmod +x \"{}\"\nexit 0\n",
            brew_log.display(),
            node_path.display(),
            node_log.display(),
            node_path.display(),
        );
        let bootstrap_script = format!(
            "#!/bin/sh\nprintf '%s\\n' \"$@\" >> \"{}\"\n/bin/cat > \"{}\" <<'BREWEOF'\n{}\nBREWEOF\n/bin/chmod +x \"{}\"\nexit 0\n",
            bootstrap_log.display(),
            brew_path.display(),
            brew_script,
            brew_path.display(),
        );
        write_executable_script(&dir.join("sh"), &bootstrap_script);
    }

