    #[test]
    fn clean_text_reports_single_runtime_projection_load_issue_concisely() {
        let _guard = cwd_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        std::fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  dev:
    context: app
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              port: {}
"#,
        )
        .expect("write contract");

        let cwd = env::current_dir().expect("current dir");
        env::set_current_dir(repo.path()).expect("set current dir");

        let output = strip_ansi_codes(
            super::clean(
                Some(repo.path()),
                None,
                &[],
                false,
                false,
                OutputFormat::Text,
                false,
            )
            .stderr
            .as_deref()
            .expect("stderr"),
        );

        assert!(
            output.contains("Field: tasks.dev.runtime.listeners.http.project.host.port.mode"),
            "{output}"
        );
        assert!(
            output.contains("task `dev` listener `http` host publication port is missing `mode`")
        );
        assert!(output.contains(
            "set `project.host.port.mode` to `auto` if you want Ota to choose the host port"
        ));
        assert!(output.contains("rerun `ota clean .`") || output.contains("rerun `ota clean`"));
        assert!(!output.contains("inspect ./ota.yaml"));
        assert!(!output.contains("rerun `ota validate ./ota.yaml`"));

        env::set_current_dir(cwd).expect("restore current dir");
    }

    #[test]
    fn detect_merge_apply_can_write_generated_task_internal_field() {
        let repo = tempfile::tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: demo
tasks:
  setup:
    run: npm install
"#,
        )
        .expect("write existing contract");

        let mut tasks = BTreeMap::new();
        tasks.insert(
            String::from("setup"),
            DetectTask {
                description: None,
                run: String::from("npm install"),
                command: None,
                action: None,
                prepare: None,
                requirements: crate::schema::TaskRequirementsSpec::default(),
                effects: crate::schema::TaskEffectsSpec::default(),
                depends_on: Vec::new(),
                notes: None,
                internal: true,
                safe_for_agent: false,
            },
        );
        let report = DetectReport {
            root: repo.path().to_path_buf(),
            contract: DetectContract {
                version: 1,
                project: Some(DetectProject {
                    name: String::from("demo"),
                }),
                tasks,
                ..DetectContract::default()
            },
            inferences: vec![
                Inference::new(
                    String::from("tasks.setup.run"),
                    String::from("npm install"),
                    String::from("package.json#scripts.setup"),
                    Confidence::High,
                ),
                Inference::new(
                    String::from("tasks.setup.internal"),
                    String::from("true"),
                    String::from("package.json#scripts.setup"),
                    Confidence::High,
                ),
            ],
        };

        let apply = vec![String::from("tasks.setup.internal")];
        let output = write_detected_merge(report, &apply, false, OutputFormat::Json);

        assert_eq!(output.exit_code, 0, "{}", output.stdout);
        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("parse detect merge json");
        assert_eq!(json["ok"], true, "{}", output.stdout);
        assert_eq!(json["written"], true, "{}", output.stdout);
        assert_eq!(
            json["config"]["tasks"]["setup"]["internal"],
            serde_json::Value::Bool(true),
            "{}",
            output.stdout
        );

        let merged = fs::read_to_string(&contract_path).expect("read merged contract");
        assert!(merged.contains("internal: true"), "{merged}");
    }

