    #[test]
    fn run_dry_run_json_includes_direct_tool_provisioning_request() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let bin_dir = repo.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create fake bin");
        let (
            contract,
            provider_bin,
            expected_source,
            expected_package,
            expected_key,
            expected_value,
        ) = match super::current_os() {
            "macos" => (
                r#"
version: 1
project:
  name: demo
tools:
  helm:
    version: ">=3.8"
    acquisition:
      provider: brew
      package: helm
      source_config:
        tap_name: vendor/tap
        tap_url: https://github.com/vendor/homebrew-tap
tasks:
  render:
    command:
      exe: helm
      args:
        - template
    requirements:
      tools:
        helm: ">=3.8"
"#,
                "brew",
                "brew",
                "helm",
                "tap_name",
                "vendor/tap",
            ),
            "windows" => (
                r#"
version: 1
project:
  name: demo
tools:
  helm:
    version: ">=3.8"
    acquisition:
      provider: winget
      package: Helm.Helm
      source_config:
        source_name: winget
tasks:
  render:
    command:
      exe: helm
      args:
        - template
    requirements:
      tools:
        helm: ">=3.8"
"#,
                "winget",
                "winget",
                "Helm.Helm",
                "source_name",
                "winget",
            ),
            _ => (
                r#"
version: 1
project:
  name: demo
tools:
  helm:
    version: ">=3.8"
    acquisition:
      provider: apt
      package: helm
      source_config:
        sources_list:
          - deb https://packages.example.invalid stable main
tasks:
  render:
    command:
      exe: helm
      args:
        - template
    requirements:
      tools:
        helm: ">=3.8"
"#,
                "apt-get",
                "apt",
                "helm",
                "sources_list",
                "deb https://packages.example.invalid stable main",
            ),
        };
        fs::write(repo.path().join("ota.yaml"), contract).expect("write contract");
        write_executable_script(
            &fake_command_path(&bin_dir, provider_bin),
            if cfg!(windows) {
                "@echo off\r\nexit /b 0\r\n"
            } else {
                "#!/bin/sh\nexit 0\n"
            },
        );

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if cfg!(windows) {
            path_entries.push(PathBuf::from(r"C:\Windows\System32"));
        } else {
            path_entries.push(PathBuf::from("/usr/bin"));
            path_entries.push(PathBuf::from("/bin"));
            path_entries.push(PathBuf::from("/usr/sbin"));
            path_entries.push(PathBuf::from("/sbin"));
        }
        let joined_path = env::join_paths(path_entries).expect("join fake path");
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let output = super::run_command(
            "render",
            Some(repo.path()),
            None,
            OutputFormat::Json,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            true,
            false,
            false,
            false,
            false,
        );

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(output.exit_code, 0);
        assert!(
            !output.stdout.trim().is_empty(),
            "stdout was empty; stderr={:?}",
            output.stderr
        );
        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("dry-run json preview");
        assert_eq!(json["preview_status"], "RUNNABLE WITH WARNINGS");
        assert_eq!(
            json["provisioning_request"]["actions"][0]["source"],
            expected_source
        );
        assert_eq!(
            json["provisioning_request"]["actions"][0]["package"],
            expected_package
        );
        let source_config = &json["provisioning_request"]["actions"][0]["source_config"];
        match expected_key {
            "sources_list" => assert_eq!(source_config[expected_key][0], expected_value),
            _ => assert_eq!(source_config[expected_key], expected_value),
        }
    }

