    #[test]
    fn run_dry_run_json_reports_dependency_backend_provenance() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: demo
execution:
  contexts:
    host:
      backend: native
    app:
      backend: container
      container:
        image: node:24-bookworm
tasks:
  setup:
    context: app
    run: npm ci
  setup:host:
    context: host
    run: npm ci
  typecheck:
    context: app
    command:
      exe: npm
      args: [run, typecheck]
    depends_on:
      - setup
    execution:
      modes:
        native:
          context: host
          depends_on:
            - setup:host
  deploy:
    context: host
    command:
      exe: npm
      args: [run, deploy]
    depends_on:
      - typecheck
"#,
        )
        .expect("parse contract");

        let requested_task = TaskSummary::from_spec_with_overrides(
            "deploy",
            contract.tasks.get("deploy").expect("deploy task"),
            super::current_os(),
            &contract,
            ExecutionOverrides::default(),
        );
        let execution_plan = super::resolve_execution_plan_for_task(
            &contract,
            Path::new("ota.yaml"),
            "deploy",
            ExecutionOverrides::default(),
        )
        .expect("execution plan");
        let preview_plan = super::build_run_preview_plan(
            &contract,
            "deploy",
            ExecutionOverrides::default(),
            &requested_task,
            &execution_plan,
            false,
        );

        let dependency_steps = preview_plan.dependency_steps;
        assert_eq!(dependency_steps.len(), 3);
        assert_eq!(dependency_steps[0].task, "setup:host");
        assert_eq!(dependency_steps[0].parent.as_deref(), Some("typecheck"));
        assert_eq!(dependency_steps[0].backend, "native");
        assert_eq!(dependency_steps[0].backend_selection_source, "task context");
        assert_eq!(dependency_steps[1].task, "typecheck");
        assert_eq!(dependency_steps[1].parent.as_deref(), Some("deploy"));
        assert_eq!(
            dependency_steps[1].backend_selection_source,
            "inherited parent backend"
        );
        assert_eq!(dependency_steps[2].task, "deploy");
        assert_eq!(dependency_steps[2].backend_selection_source, "task context");
    }

    #[test]
    fn effect_policy_closure_uses_selected_mode_specific_dependencies() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: demo
execution:
  contexts:
    host:
      backend: native
    app:
      backend: container
      container:
        image: node:24-bookworm
tasks:
  setup:
    context: app
    run: npm ci
    effects:
      network: true
      network_kind: dependency_hydration
      external_state:
        - registry
  setup:host:
    context: host
    run: npm ci
  typecheck:
    context: app
    command:
      exe: npm
      args: [run, typecheck]
    depends_on:
      - setup
    execution:
      modes:
        native:
          context: host
          depends_on:
            - setup:host
"#,
        )
        .expect("parse contract");

        let native_effects = super::collect_task_closure_effects(
            &contract,
            "typecheck",
            ExecutionOverrides {
                backend: Some(Backend::Native),
                ..ExecutionOverrides::default()
            },
        );
        assert_eq!(native_effects.0, None);
        assert!(native_effects.1.is_empty());
        assert!(native_effects.2.is_empty());

        let container_effects = super::collect_task_closure_effects(
            &contract,
            "typecheck",
            ExecutionOverrides {
                backend: Some(Backend::Container),
                ..ExecutionOverrides::default()
            },
        );
        assert_eq!(
            container_effects.0,
            Some(crate::schema::TaskNetworkEffectKind::DependencyHydration)
        );
        assert!(container_effects.1.is_empty());
        assert!(container_effects.2.contains("registry"));
    }

