    #[test]
    fn clean_workspace_command_json_success_reports_root_and_member_cleanup() {
        let _cwd_guard = cwd_mutex_lock();
        let _env_guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("workspace tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: workspace-root
workspace:
  type: monorepo
  members:
    - api
execution:
  default_context: host
  contexts:
    host:
      backend: native
tasks:
  check:
    run: echo root
"#,
        )
        .expect("write root contract");
        fs::create_dir_all(repo.path().join("api")).expect("member dir");
        fs::write(
            repo.path().join("api").join("ota.yaml"),
            r#"
version: 1
project:
  name: api
execution:
  default_context: host
  contexts:
    host:
      backend: native
tasks:
  check:
    run: echo api
"#,
        )
        .expect("write member contract");

        let cwd = env::current_dir().expect("cwd");
        env::set_current_dir(repo.path()).expect("cd repo");
        let output = super::clean(
            Some(Path::new(".")),
            None,
            &[],
            false,
            false,
            OutputFormat::Json,
            false,
        );
        env::set_current_dir(cwd).expect("restore cwd");

        assert_eq!(output.exit_code, 0);
        let body: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("parse workspace clean json");
        assert_eq!(body.get("ok").and_then(|value| value.as_bool()), Some(true));
        assert_eq!(
            body.get("path").and_then(|value| value.as_str()),
            Some("./ota.yaml")
        );
        let workspace = body.get("workspace").expect("workspace");
        assert_eq!(
            workspace
                .get("root")
                .and_then(|value| value.get("path"))
                .and_then(|value| value.as_str()),
            Some("./ota.yaml")
        );
        let members = workspace
            .get("members")
            .and_then(|value| value.as_array())
            .expect("members array");
        assert_eq!(members.len(), 1);
        assert_eq!(
            members[0].get("member").and_then(|value| value.as_str()),
            Some("api")
        );
        assert_eq!(
            members[0]
                .get("report")
                .and_then(|value| value.get("path"))
                .and_then(|value| value.as_str()),
            Some("./ota.yaml [member api]")
        );
    }

    #[test]
    fn compacts_policy_files_relative_to_contract_repo_root_when_inside_repo() {
        let outer = tempfile::tempdir().expect("outer tempdir");
        let repo = outer.path().join("repo");
        let policy_dir = repo.join(".ota");
        std::fs::create_dir_all(&policy_dir).expect("create policy dir");
        let contract_path = repo.join("ota.yaml");
        let policy_path = policy_dir.join("org-policy.yaml");
        std::fs::write(&contract_path, "version: 1\n").expect("write contract");
        std::fs::write(&policy_path, "policies: {}\n").expect("write policy");

        assert_eq!(
            compact_policy_path_relative_to_contract(&contract_path, &policy_path),
            "./.ota/org-policy.yaml"
        );

        let outside = tempfile::tempdir().expect("outside tempdir");
        let outside_policy = outside.path().join("org-policy.yaml");
        std::fs::write(&outside_policy, "policies: {}\n").expect("write outside policy");

        assert_eq!(
            compact_policy_path_relative_to_contract(&contract_path, &outside_policy),
            format!(
                "../../{}/org-policy.yaml",
                outside
                    .path()
                    .file_name()
                    .and_then(|name| name.to_str())
                    .expect("outside dir name")
            )
        );
    }

