    #[test]
    fn up_preview_plan_lists_provisioning_actions_and_skips() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
runtimes:
  java: "21"
tools:
  node: "22"
tasks:
  setup:
    run: echo setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: false,
            provisioning: Some(crate::doctor::ProvisioningDiagnostics {
                plan: ProvisioningPlan::default(),
                request: ProvisioningBackendRequest {
                    actions: vec![
                        ProvisioningAction {
                            kind: ProvisioningActionKind::SelectSource,
                            target_kind: ProvisioningTargetKind::Runtime,
                            name: String::from("java"),
                            requested_version: String::from("21"),
                            normalized_requirement: None,
                            resolved_version: None,
                            package: None,
                            source: String::from("sdkman"),
                            source_config: None,
                            approved_version: Some(String::from("21")),
                            policy_match: None,
                        },
                        ProvisioningAction {
                            kind: ProvisioningActionKind::SelectSource,
                            target_kind: ProvisioningTargetKind::Tool,
                            name: String::from("node"),
                            requested_version: String::from("22"),
                            normalized_requirement: None,
                            resolved_version: None,
                            package: None,
                            source: String::from("brew"),
                            source_config: None,
                            approved_version: Some(String::from("22")),
                            policy_match: None,
                        },
                    ],
                },
            }),
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: String::from("Missing runtime: java"),
                why: String::from("java is declared in the contract but is not available"),
                next: String::from("install `java` and rerun `ota doctor`"),
            }],
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            None,
            super::UpRunBehaviorPreference::Auto,
            &preflight,
        );

        dbg!(&preview.plan.actions);
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("provision `java` `21` via `sdkman`"))
        );
        assert!(
            preview
                .plan
                .skipped
                .contains(&String::from("skip `node`; already satisfies the contract"))
        );
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("run task `setup`"))
        );
        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("re-check repo readiness"))
        );
    }

    #[test]
    fn up_preview_orders_pre_setup_setup_and_post_setup_service_phases_honestly() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
services:
  postgres:
    required: true
    manager:
      kind: compose
      name: local
      file: compose.yaml
      service: postgres
    endpoints:
      app:
        address: postgres
        port: 5432
    readiness:
      from: app
      kind: tcp
  app:
    required: true
    start: ./bin/start-app
    endpoints:
      host:
        address: 127.0.0.1
        port: 8080
    readiness:
      from: host
      kind: http
      path: /health
tasks:
  setup:
    requires_services:
      - postgres
    run: ./bin/setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: true,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: Vec::new(),
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            None,
            super::UpRunBehaviorPreference::Auto,
            &preflight,
        );

        assert_eq!(
            preview.plan.actions,
            vec![
                String::from("start service `postgres` before `setup`"),
                String::from("verify service `postgres` readiness before `setup`"),
                String::from("run task `setup`"),
                String::from("start service `app` after `setup`"),
                String::from("verify service `app` readiness after `setup`"),
                String::from("re-check repo readiness"),
            ]
        );
    }

