    #[test]
    fn selected_workflow_summary_uses_adjusted_instance_runtime_and_surface_truth() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: workflow-instance-summary-adjustment
surfaces:
  ui:
    kind: https
    port: 3449
    path: /
  ui:http:
    kind: http
    port: 3450
    path: /
tasks:
  devenv:start:
    command:
      exe: docker
      args:
        - compose
        - ps
        - main
    runtime:
      kind: service
      listeners:
        ui:
          protocol: https
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: 3449
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3449
              path: /
              primary: true
        ui:http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: 3450
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3450
              path: /
      surfaces:
        ui: {}
        ui:http: {}
workflows:
  default: devenv
  devenv:
    run:
      task: devenv:start
    exposes:
      - surface: ui
      - surface: ui:http
    instances:
      default: ws0
      ws0: {}
      ci:
        tasks:
          devenv:start:
            runtime:
              listeners:
                ui:
                  bind:
                    port:
                      mode: fixed
                      value: 43449
                  project:
                    host:
                      port:
                        mode: fixed
                        value: 43449
                ui:http:
                  bind:
                    port:
                      mode: fixed
                      value: 43450
                  project:
                    host:
                      port:
                        mode: fixed
                        value: 43450
        surfaces:
          ui:
            port: 43449
          ui:http:
            port: 43450
"#,
        )
        .unwrap();

        let adjusted = super::contract_adjusted_for_selected_workflow_env_profile(
            &contract,
            Some("devenv@ci"),
        )
        .expect("workflow instance should adjust contract");
        let summary = super::resolve_selected_workflow_summary(
            &adjusted,
            Path::new("ota.yaml"),
            Some("devenv@ci"),
        )
        .expect("workflow summary should resolve")
        .expect("workflow summary should exist");

        assert_eq!(summary.instance.as_deref(), Some("ci"));
        assert!(
            summary
                .exposes
                .contains(&String::from("https://127.0.0.1:43449/"))
        );
        assert!(
            summary
                .exposes
                .contains(&String::from("http://127.0.0.1:43450/"))
        );
    }

    #[test]
    fn execute_repo_up_runs_prerequisite_workflow_instances_before_selected_instance() {
        let fixture = tempdir().expect("tempdir");
        let contract_path = fixture.path().join("ota.yaml");
        let log_path = fixture.path().join("instances.log");
        let contents = format!(
            r#"
version: 1
project:
  name: workflow-instance-topology-up
tasks:
  setup:
    env:
      INSTANCE: base
    command:
      exe: sh
      args:
        - -c
        - printf '%s\n' "$INSTANCE" >> instances.log
workflows:
  default: app
  app:
    setup:
      task: setup
    instances:
      default: ws0
      ws0:
        env:
          INSTANCE: ws0
      ws1:
        topology:
          requires_instances:
            - ws0
        env:
          INSTANCE: ws1
"#,
        );
        fs::write(&contract_path, &contents).expect("contract should write");
        let contract =
            parse_contract_str(&contract_path, &contents).expect("contract should parse");

        let result = super::execute_repo_up_with_behavior(
            &contract,
            &contract_path,
            ExecutionOverrides::default(),
            Some("app@ws1"),
            None,
            false,
            RepoExecutionMode::Capture,
            super::UpRunBehaviorPreference::Auto,
            None,
        )
        .expect("up should execute")
        .ok;
        assert!(result);

        let rendered = fs::read_to_string(&log_path).expect("instance log should read");
        assert_eq!(rendered, "ws0\nws1\n");
    }

    #[test]
    fn contract_adjusted_for_selected_workflow_env_profile_binds_rendered_dotenv_to_compose_services()
     {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: env-profile-compose
env:
  profiles:
    compose:
      render:
        dotenv:
          path: .env.compose
services:
  api:
    manager:
      kind: compose
  cache:
    manager:
      kind: compose
tasks:
  dev:
    run: npm run dev
workflows:
  default: compose
  compose:
    env:
      profile: compose
      compose_env_file_services:
        - api
    run:
      task: dev
"#,
        )
        .unwrap();

        let adjusted = super::contract_adjusted_for_selected_workflow_env_profile(&contract, None)
            .expect("workflow env profile should adjust contract");
        assert_eq!(
            adjusted
                .services
                .get("api")
                .and_then(|service| service.manager.as_ref())
                .and_then(|manager| manager.env_file.as_deref()),
            Some(".env.compose")
        );
        assert_eq!(
            adjusted
                .services
                .get("api")
                .and_then(|service| service.manager.as_ref())
                .map(|manager| manager.env_files.clone())
                .unwrap_or_default(),
            vec![String::from(".env.compose")]
        );
        assert_eq!(
            adjusted
                .services
                .get("cache")
                .and_then(|service| service.manager.as_ref())
                .and_then(|manager| manager.env_file.as_deref()),
            None
        );
    }

