    #[test]
    fn contract_adjusted_for_selected_workflow_env_profile_binds_workflow_bake_adapter_inputs() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: workflow-bake-adapter-inputs
workflows:
  default: image
  image:
    adapter_inputs:
      bake:
        cwd: docker
        files:
          - docker-bake.hcl
    run:
      task: image:build
tasks:
  image:build:
    run: docker buildx bake app
"#,
        )
        .unwrap();

        let adjusted = super::contract_adjusted_for_selected_workflow_env_profile(&contract, None)
            .expect("workflow bake adapter inputs should adjust contract");
        let bake = adjusted
            .tasks
            .get("image:build")
            .and_then(|task| task.adapter_inputs.bake.as_ref())
            .expect("bake adapter inputs should exist");
        assert_eq!(bake.cwd.as_deref(), Some("docker"));
        assert_eq!(bake.files, vec![String::from("docker-bake.hcl")]);
        assert!(bake.workflow_overlay_bound);
        assert!(
            !crate::validator::collect_contract_advisories(&adjusted)
                .iter()
                .any(|advisory| matches!(
                    advisory,
                    crate::validator::ContractAdvisory::DuplicateWorkflowAdapterInputOwnership(
                        value
                    ) if value.workflow_name == "image" && value.task_name == "image:build"
                )),
            "workflow-injected bake inputs must not be reclassified as task-authored duplicates"
        );
    }

