    #[test]
    fn finding_targets_provisioning_action_strips_context_suffix() {
        let finding = Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Version mismatch for runtime: java (context remote-app)"),
            why: String::from("java is declared in the contract but is not available"),
            next: String::from("install `java` and rerun `ota doctor`"),
        };
        let action = ProvisioningAction {
            kind: ProvisioningActionKind::SelectSource,
            target_kind: ProvisioningTargetKind::Runtime,
            name: String::from("java"),
            requested_version: String::from("21"),
            normalized_requirement: None,
            resolved_version: None,
            package: None,
            source: String::from("sdkman"),
            source_config: None,
            approved_version: Some(String::from("21")),
            policy_match: None,
        };
        let other_action = ProvisioningAction {
            name: String::from("node"),
            ..action.clone()
        };

        assert_eq!(
            super::provisionable_target_key_for_finding(&finding),
            Some(String::from("runtime:java"))
        );
        assert!(super::finding_targets_provisioning_action(
            &finding, &action
        ));
        assert!(!super::finding_targets_provisioning_action(
            &finding,
            &other_action
        ));
    }

    #[test]
    fn finding_targets_provisioning_action_for_unparseable_tool_version() {
        let finding = Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Unparseable version for tool: npm (context app)"),
            why: String::from(
                "ota probed `/usr/local/bin/npm` with `npm --version`, but the output did not contain a parseable version",
            ),
            next: String::from(
                "run `npm --version` directly, inspect `/usr/local/bin/npm`, and make sure the output contains a parseable version before rerunning `ota doctor`",
            ),
        };
        let action = ProvisioningAction {
            kind: ProvisioningActionKind::SelectSource,
            target_kind: ProvisioningTargetKind::Tool,
            name: String::from("npm"),
            requested_version: String::from("*"),
            normalized_requirement: None,
            resolved_version: None,
            package: None,
            source: String::from("brew"),
            source_config: None,
            approved_version: Some(String::from("*")),
            policy_match: None,
        };

        assert_eq!(
            super::provisionable_target_key_for_finding(&finding),
            Some(String::from("tool:npm"))
        );
        assert!(super::finding_targets_provisioning_action(
            &finding, &action
        ));
    }

    #[test]
    fn up_preview_treats_probe_failures_as_provisionable() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
tools:
  npm: "*"
tasks:
  setup:
    run: echo setup
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: false,
            provisioning: Some(crate::doctor::ProvisioningDiagnostics {
                plan: ProvisioningPlan::default(),
                request: ProvisioningBackendRequest {
                    actions: vec![ProvisioningAction {
                        kind: ProvisioningActionKind::SelectSource,
                        target_kind: ProvisioningTargetKind::Tool,
                        name: String::from("npm"),
                        requested_version: String::from("*"),
                        normalized_requirement: None,
                        resolved_version: None,
                        package: None,
                        source: String::from("choco"),
                        source_config: None,
                        approved_version: Some(String::from("*")),
                        policy_match: None,
                    }],
                },
            }),
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: String::from("Tool probe failed: npm"),
                why: String::from(
                    "ota probed `C:\\node\\npm.cmd` with `npm --version`, but the command exited with code 1 before ota could read a version",
                ),
                next: String::from(
                    "run `npm --version` directly, inspect `C:\\node\\npm.cmd`, and make sure the probe succeeds before rerunning `ota doctor`",
                ),
            }],
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            None,
            super::UpRunBehaviorPreference::Auto,
            &preflight,
        );

        assert!(
            preview
                .plan
                .actions
                .contains(&String::from("provision `npm` `*` via `choco`"))
        );
        assert_eq!(preview.summary.verdict, DoctorVerdict::Risky);
        assert!(
            !preview
                .plan
                .skipped
                .contains(&String::from("skip `npm`; already satisfies the contract"))
        );
    }

    #[test]
    fn execute_repo_up_dry_run_is_ok_when_all_blockers_are_provisionable() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let bin_dir = repo.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create fake bin");
        write_executable_script(
            &fake_command_path(
                &bin_dir,
                if cfg!(windows) {
                    "winget"
                } else if cfg!(target_os = "macos") {
                    "brew"
                } else {
                    "apt-get"
                },
            ),
            if cfg!(windows) {
                "@echo off\r\nexit /b 0\r\n"
            } else {
                "#!/bin/sh\nexit 0\n"
            },
        );
        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if cfg!(windows) {
            path_entries.push(PathBuf::from(r"C:\Windows\System32"));
        } else {
            path_entries.push(PathBuf::from("/usr/bin"));
            path_entries.push(PathBuf::from("/bin"));
            path_entries.push(PathBuf::from("/usr/sbin"));
            path_entries.push(PathBuf::from("/sbin"));
        }
        let joined_path = env::join_paths(path_entries).expect("join fake path");
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let contract = parse_contract_str(
            &repo.path().join("ota.yaml"),
            match super::current_os() {
                "macos" => {
                    r#"
version: 1
project:
  name: preview-up
tools:
  ota-preview-kubectl:
    version: "*"
    acquisition:
      provider: brew
      package: kubernetes-cli
tasks:
  verify:
    command:
      exe: ota-preview-kubectl
      args:
        - version
"#
                }
                "windows" => {
                    r#"
version: 1
project:
  name: preview-up
tools:
  ota-preview-kubectl:
    version: "*"
    acquisition:
      provider: winget
      package: Kubernetes.kubectl
tasks:
  verify:
    command:
      exe: ota-preview-kubectl
      args:
        - version
"#
                }
                _ => {
                    r#"
version: 1
project:
  name: preview-up
tools:
  ota-preview-kubectl:
    version: "*"
    acquisition:
      provider: apt
      package: kubectl
tasks:
  verify:
    command:
      exe: ota-preview-kubectl
      args:
        - version
"#
                }
            },
        )
        .expect("parse contract");

        let result = execute_repo_up(
            &contract,
            &repo.path().join("ota.yaml"),
            ExecutionOverrides::default(),
            None,
            None,
            true,
            RepoExecutionMode::Capture,
        )
        .expect("dry-run up result");

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert!(result.ok);
        let preview = result.preview.expect("preview result");
        assert_eq!(preview.summary.verdict, DoctorVerdict::Risky);
    }

    #[test]
    fn up_activation_actions_are_scoped_to_selected_workflow_requirements() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up
toolchains:
  node:
    provider: corepack
    version: "22"
    package_managers:
      pnpm: "10.22.0"
tasks:
  setup:
    run: pnpm install
    requirements:
      toolchains:
        - node
      tools:
        pnpm: "10.22.0"
  docker:run:
    launch:
      kind: container
      image: ghcr.io/example/app:latest
    requirements:
      tools:
        docker: "*"
workflows:
  default: contributor
  contributor:
    setup:
      task: setup
  docker:
    run:
      task: docker:run
"#,
        )
        .unwrap();

        let preflight = DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![
                Finding {
                    identity: None,
                    severity: FindingSeverity::Error,
                    summary: String::from("Missing tool: pnpm"),
                    why: String::from(
                        "pnpm is declared in the contract but is not available on PATH",
                    ),
                    next: String::from(
                        "run `corepack enable && corepack prepare pnpm@10.22.0 --activate` and rerun `ota doctor`",
                    ),
                },
                Finding {
                    identity: None,
                    severity: FindingSeverity::Error,
                    summary: String::from("Missing tool: docker"),
                    why: String::from(
                        "docker is declared in the contract but is not available on PATH",
                    ),
                    next: String::from("install docker and rerun `ota doctor`"),
                },
            ],
        };

        let contributor_actions = super::selected_up_activation_actions(
            &contract,
            ExecutionOverrides::default(),
            Some("contributor"),
            &preflight,
        );
        assert_eq!(contributor_actions.len(), 1);
        assert_eq!(contributor_actions[0].tool_name, "pnpm");

        let docker_actions = super::selected_up_activation_actions(
            &contract,
            ExecutionOverrides::default(),
            Some("docker"),
            &preflight,
        );
        assert!(docker_actions.is_empty());
    }

