    #[test]
    fn execution_plan_honors_selected_workflow_task() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: execution-plan
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  start:
    run: echo start
  dev:
    context: app
    run: echo dev
workflows:
  default: app
  app:
    run:
      task: start
  backend:
    run:
      task: dev
"#,
        )
        .unwrap();

        let resolved = super::resolve_execution_plan(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            Some("backend"),
        )
        .expect("workflow execution plan should resolve selected task execution");

        assert_eq!(resolved.backend, "container");
        assert_eq!(resolved.backend_source, "workflow task");
        assert_eq!(resolved.lifecycle.as_deref(), Some("ephemeral"));
        assert_eq!(
            resolved.lifecycle_source.as_deref(),
            Some("context lifecycle")
        );
        assert_eq!(resolved.image.as_deref(), Some("ghcr.io/ota/dev:latest"));
    }

    #[test]
    fn execution_plan_for_task_uses_requested_task_instead_of_default_workflow_task() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: execution-plan
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  dev:
    context: app
    run: echo dev
  ci:
    run: echo ci
workflows:
  default: app
  app:
    run:
      task: dev
"#,
        )
        .expect("contract should parse");

        let resolved = super::resolve_execution_plan_for_task(
            &contract,
            Path::new("/tmp/ota.yaml"),
            "ci",
            ExecutionOverrides::default(),
        )
        .expect("requested task execution plan should resolve from the requested task");

        assert_eq!(resolved.backend, "native");
        assert_eq!(resolved.backend_source, "task");
        assert_eq!(resolved.lifecycle_source, None);
        assert_eq!(resolved.image, None);
    }

    #[test]
    fn execution_plan_prefers_workflow_run_task_over_setup_task() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: execution-plan
execution:
  default_context: host
  contexts:
    host:
      backend: native
    prep:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/prep:latest
    app:
      backend: remote
      lifecycle: persistent
      remote:
        provider: ssh
        target: dev@example.com
tasks:
  setup:
    context: prep
    run: echo setup
  start:
    context: app
    run: echo start
workflows:
  default: app
  app:
    setup:
      task: setup
    run:
      task: start
"#,
        )
        .expect("contract should parse");

        let resolved = super::resolve_execution_plan(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            None,
        )
        .expect("workflow execution plan should resolve selected run-task execution");

        assert_eq!(resolved.backend, "remote");
        assert_eq!(resolved.backend_source, "workflow task");
        assert_eq!(resolved.lifecycle.as_deref(), Some("persistent"));
        assert_eq!(resolved.provider.as_deref(), Some("ssh"));
        assert_eq!(resolved.target.as_deref(), Some("dev@example.com"));
    }

