    #[test]
    fn doctor_report_context_keeps_selected_context_target_when_probe_target_differs() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: doctor-context
execution:
  default_context: host
  contexts:
    host:
      backend: native
    a-persistent:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/persistent:latest
    z-ephemeral:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/ephemeral:latest
tasks:
  dev:
    run: echo dev
"#,
        )
        .expect("contract should parse");

        let selected_target = crate::runner::ephemeral_container_name(
            Path::new("/tmp"),
            "ghcr.io/ota/ephemeral:latest",
            "docker",
        );
        let mismatched_probe_target = crate::runner::ephemeral_container_name(
            Path::new("/tmp"),
            "ghcr.io/ota/persistent:latest",
            "docker",
        );
        let report = DoctorReport {
            ok: true,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: Some(mismatched_probe_target),
            findings: Vec::new(),
        };

        let phase = super::doctor_report_execution_context(
            &contract,
            Path::new("/tmp/ota.yaml"),
            DoctorMode::Container,
            None,
            &report,
        );

        assert_eq!(phase.context.as_deref(), Some("z-ephemeral"));
        assert_eq!(phase.image.as_deref(), Some("ghcr.io/ota/ephemeral:latest"));
        assert_eq!(phase.target.as_deref(), Some(selected_target.as_str()));
    }

    #[test]
    fn execution_policy_lines_show_package_aliases_when_policy_maps_packages() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
tools:
  node: "22"
tasks:
  setup:
    run: echo setup
"#,
        )
        .unwrap();
        fs::create_dir_all(fixture.path().join(".ota")).unwrap();
        fs::write(
            fixture.path().join(".ota").join("org-policy.yaml"),
            r#"
policies:
  provisioning:
    node:
      source: apt
      package: nodejs
      approved_versions:
        - "22"
"#,
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let lines = super::execution_policy_lines(&contract, &contract_path, Backend::Native);

        assert_eq!(lines.len(), 1);
        assert!(
            lines[0].contains("tool node (package: nodejs) 22 via apt"),
            "expected package alias in execution policy line, got: {}",
            lines[0]
        );
    }

    #[test]
    fn execution_policy_lines_use_backend_requirement_surface() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    host:
      backend: native
      requirements:
        tools:
          docker: "*"
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
      requirements:
        tools:
          node: "22"
tasks:
  setup:
    context: app
    run: echo setup
"#,
        )
        .unwrap();
        fs::create_dir_all(fixture.path().join(".ota")).unwrap();
        fs::write(
            fixture.path().join(".ota").join("org-policy.yaml"),
            r#"
policies:
  provisioning:
    docker:
      source: apt
      package: docker.io
      approved_versions:
        - "*"
    node:
      source: mise
      approved_versions:
        - "22"
"#,
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let native_lines =
            super::execution_policy_lines(&contract, &contract_path, Backend::Native);
        let container_lines =
            super::execution_policy_lines(&contract, &contract_path, Backend::Container);

        assert_eq!(native_lines.len(), 1);
        assert!(native_lines[0].contains("tool docker (package: docker.io)"));
        assert_eq!(container_lines.len(), 1);
        assert!(container_lines[0].contains("tool node 22 via mise"));
    }

