    #[test]
    fn workspace_run_uses_repo_task_binding_when_declared() {
        let fixture = TempDir::new().unwrap();
        let repo_path = fixture.path().join("sdk");
        fs::create_dir_all(&repo_path).unwrap();
        let contract_path = repo_path.join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: sdk
tasks:
  generate-sdk:
    action:
      kind: ensure_file
      path: generated.txt
      value: generated
"#
            .trim_start(),
        )
        .unwrap();

        let mut task_bindings = BTreeMap::new();
        task_bindings.insert(String::from("prepare-dev"), String::from("generate-sdk"));

        let repo = crate::workspace::WorkspaceRepoRef {
            name: String::from("sdk"),
            path: repo_path.clone(),
            contract_path,
            workflow: None,
            task_bindings,
            required: true,
            depends_on: Vec::new(),
            present: true,
            source_url: None,
            source_ref: None,
            policy_env: BTreeMap::new(),
        };

        let report = super::run_workspace_repo_task(
            repo,
            "prepare-dev",
            &[],
            RepoExecutionMode::Capture,
            fixture.path(),
        );

        assert!(report.ok, "{report:?}");
        assert_eq!(report.task, "prepare-dev");
        assert_eq!(report.repo_task.as_deref(), Some("generate-sdk"));
        assert_eq!(
            fs::read_to_string(repo_path.join("generated.txt")).unwrap(),
            "generated"
        );
    }

    #[test]
    fn workspace_execution_plan_honors_selected_repo_workflow() {
        let fixture = TempDir::new().unwrap();
        let repo_path = fixture.path().join("api");
        fs::create_dir_all(&repo_path).unwrap();
        let contract_path = repo_path.join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: api
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  start:
    run: echo start
  dev:
    context: app
    run: echo dev
workflows:
  default: app
  app:
    run:
      task: start
  backend:
    run:
      task: dev
"#
            .trim_start(),
        )
        .unwrap();

        let repo = crate::workspace::WorkspaceRepoRef {
            name: String::from("api"),
            path: repo_path,
            contract_path,
            workflow: Some(String::from("backend")),
            task_bindings: BTreeMap::new(),
            required: true,
            depends_on: Vec::new(),
            present: true,
            source_url: None,
            source_ref: None,
            policy_env: BTreeMap::new(),
        };

        let report = super::run_workspace_repo_execution_plan(
            repo,
            ExecutionOverrides::default(),
            fixture.path(),
        );

        assert_eq!(report.status, "RESOLVED");
        assert_eq!(report.workflow.as_deref(), Some("backend"));
        assert_eq!(report.task.as_deref(), Some("dev"));
        assert_eq!(
            report
                .resolved
                .as_ref()
                .and_then(|resolved| resolved.image.as_deref()),
            Some("ghcr.io/ota/dev:latest")
        );
    }

