    #[test]
    fn collect_validate_warnings_reports_cross_boundary_depends_on() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: node:24-bookworm
    verify:
      backend: native
tasks:
  setup:
    context: app
    run: npm install
  build:
    context: verify
    run: npm run build
    depends_on:
      - setup
"#,
        )
        .unwrap();

        let warnings = collect_validate_warnings(&contract, None);

        assert!(warnings.iter().any(|warning| {
            warning
                .contains("task `build` depends_on `setup` across different execution boundaries")
                && warning.contains("only durable external side effects survive")
        }));
    }

