    #[test]
    fn up_setup_failed_due_to_container_networking_is_classified_as_backend_startup() {
        let receipt = ExecutionReceipt {
            ok: false,
            path: String::from("./ota.yaml"),
            scope: String::from("repo"),
            contract: String::from("./ota.yaml"),
            contract_identity: None,
            contract_snapshot_hash: None,
            contract_snapshot_ref: None,
            assumption_set_hash: None,
            workspace: None,
            backend: Some(String::from("container")),
            context: Some(String::from("app")),
            lifecycle: Some(String::from("persistent")),
            image: Some(String::from("maven:3.9.14-eclipse-temurin-21-noble")),
            container_memory_bytes: None,
            target: Some(String::from("ota-3ff7e125cddff1a4")),
            provider: None,
            cwd: None,
            acquired: Vec::new(),
            env: BTreeMap::new(),
            env_sources: Vec::new(),
            workflow_env_artifacts: Vec::new(),
            native_prerequisites: Vec::new(),
            toolchains: Vec::new(),
            runtime: None,
            logs: None,
            service_termination: None,
            host_service_cleanup: Vec::new(),
            backend_fulfillment: None,
            workloads: BTreeMap::new(),
            policy: Vec::new(),
            dependency_steps: Vec::new(),
            steps: vec![execution_receipt_step(
                1,
                "setup",
                "SETUP FAILED",
                Some(String::from("task `setup`")),
                Some(125),
            )],
            blocked: Vec::new(),
            status: None,
            failed_task: None,
            failed_dependency: None,
            failure_origin: None,
            summary: ExecutionReceiptSummary::default(),
            next: None,
        };
        let result = RepoUpResult {
            ok: false,
            status: "SETUP FAILED",
            phase: "setup",
            report: DoctorReport {
                ok: false,
                provisioning: None,
                adapter_bootstrap: None,
                execution_target: None,
                findings: Vec::new(),
            },
            preview: None,
            receipt,
            service: None,
            service_command: None,
            task: Some(String::from("setup")),
            task_command: Some(String::from("mvn -q -DskipTests dependency:go-offline")),
            exit_code: Some(125),
            stdout: String::new(),
            stderr: String::from(
                "5f6a5b038e7509106eb6c5f7f05ad0be531e8acc8fe9d7de9827cf885ba922c4\n\
docker: Error response from daemon: failed to set up container networking: network local_default not found\n\
\nRun 'docker run --help' for more information\n",
            ),
        };

        let text = strip_ansi_codes(
            &render_up_result(
                "./ota.yaml",
                "./ota.yaml",
                result,
                OutputFormat::Text,
                false,
            )
            .stdout,
        );

        assert!(text.contains("BACKEND STARTUP FAILED"));
        assert!(text.contains("Phase: setup"));
        assert!(text.contains("Cause:"));
        assert!(text.contains("backend startup"));
        assert!(!text.contains("Cause:       repo setup"));
        assert!(!text.contains("6c0d799bfdb2428e953d80057ba36bacbd14282aca68f5dc5ea3951bdc5053a7"));
        assert!(text.contains(
            "docker: Error response from daemon: failed to set up container networking: network local_default not found"
        ));
        assert!(text.contains("ota execution plan --mode container"));
    }

    #[test]
    fn execution_receipt_redacts_secret_env_values() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
env:
  vars:
    OTA_TEST_SECRET:
      secret: true
tasks:
  test:
    env:
      OTA_TEST_SECRET: task-secret
    run: echo test
"#,
        )
        .unwrap();
        let contract_path = Path::new("/tmp/ota.yaml");
        let receipt = run_execution_receipt(
            &contract,
            contract_path,
            ExecutionOverrides::default(),
            "test",
            None,
            &[ExecutedTaskStep {
                name: String::from("test"),
                exit_code: 0,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: None,
            }],
            &[],
            &[],
            0,
            true,
            None,
            None,
            None,
        );

        assert_eq!(receipt.env["OTA_TEST_SECRET"], "<redacted>");
        let secret_env_source = receipt
            .env_sources
            .iter()
            .find(|entry| entry.name == "OTA_TEST_SECRET")
            .expect("missing env source for OTA_TEST_SECRET");
        assert_eq!(secret_env_source.value, "<redacted>");
        let rendered = render_execution_receipt_text(&receipt);
        assert!(rendered.contains("Env Sources"));
        assert!(rendered.contains("OTA_TEST_SECRET"));
        assert!(rendered.contains("(task)"));
    }

    #[test]
    fn execution_receipt_includes_declared_env_source_metadata() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        let contract = parse_contract_str(
            &contract_path,
            r#"
version: 1
project:
  name: ota
env:
  vars:
    APP_PORT:
      required: true
  sources:
    - kind: properties
      path: app.properties
tasks:
  test:
    run: echo test
"#,
        )
        .unwrap();
        fs::write(fixture.path().join("app.properties"), "app.port=8080\n").unwrap();
        let original = std::env::var_os("APP_PORT");
        unsafe {
            std::env::remove_var("APP_PORT");
        }

        let receipt = run_execution_receipt(
            &contract,
            &contract_path,
            ExecutionOverrides::default(),
            "test",
            None,
            &[ExecutedTaskStep {
                name: String::from("test"),
                exit_code: 0,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: None,
            }],
            &[],
            &[],
            0,
            true,
            None,
            None,
            None,
        );

        assert_eq!(receipt.env_sources[0].source, "properties:app.properties");
        assert_eq!(
            receipt.env_sources[0].source_kind.as_deref(),
            Some("properties")
        );
        assert_eq!(
            receipt.env_sources[0].source_path.as_deref(),
            Some("app.properties")
        );
        assert_eq!(
            receipt.env_sources[0].source_status,
            Some(EnvSourceStatus::Loaded)
        );
        assert_eq!(
            receipt.env_sources[0].source_label.as_deref(),
            Some("properties:app.properties")
        );

        match original {
            Some(value) => unsafe { std::env::set_var("APP_PORT", value) },
            None => unsafe { std::env::remove_var("APP_PORT") },
        }
    }

