    #[test]
    fn run_failure_text_reports_interrupted_non_service_with_cleanup_note() {
        let contract = parse_contract_str(
            Path::new("./ota.yaml"),
            r#"
version: 1
project:
  name: ota
tasks:
  dev:
    run: pnpm dev
"#,
        )
        .expect("contract should parse");
        let receipt = run_execution_receipt(
            &contract,
            Path::new("./ota.yaml"),
            ExecutionOverrides::default(),
            "dev",
            None,
            &[ExecutedTaskStep {
                name: String::from("dev"),
                exit_code: 130,
                relation: TaskExecutionRelation::Requested,
                generation: 0,
                execution_note: Some(String::from(
                    "task interrupted by user; ephemeral container cleanup failed for `ota-ephemeral-deadbeef`: engine unavailable",
                )),
            }],
            &[],
            &[],
            130,
            false,
            Some(String::from("container")),
            None,
            Some(String::from(
                "task interrupted by user; ephemeral container cleanup failed for `ota-ephemeral-deadbeef`: engine unavailable",
            )),
        );
        let summary = render_execution_receipt_summary_block(&receipt, Some("dev"), "RUN SUMMARY");
        let rendered = strip_ansi_codes(&super::render_run_captured_failure_text(
            &contract,
            Path::new("./ota.yaml"),
            "./ota.yaml",
            "dev",
            "dev",
            None,
            ExecutionOverrides::default(),
            130,
            "",
            "",
            None,
            None,
            true,
            None,
            &summary,
        ));

        assert!(rendered.contains("INFO  Task interrupted"), "{rendered}");
        assert!(
            rendered.contains("task `dev` was interrupted by user"),
            "{rendered}"
        );
        assert!(rendered.contains("Status:      interrupted"), "{rendered}");
        assert!(
            rendered.contains("task interrupted by user; ephemeral container cleanup failed"),
            "{rendered}"
        );
    }

    #[test]
    fn interrupted_service_receipt_summary_status_is_interrupted() {
        let mut receipt = ExecutionReceipt {
            ok: false,
            path: String::from("./ota.yaml"),
            scope: String::from("repo"),
            contract: String::from("./ota.yaml"),
            contract_identity: None,
            contract_snapshot_hash: None,
            contract_snapshot_ref: None,
            assumption_set_hash: None,
            workspace: None,
            backend: Some(String::from("container")),
            context: Some(String::from("dev")),
            lifecycle: Some(String::from("ephemeral")),
            image: Some(String::from("node:24")),
            container_memory_bytes: None,
            target: Some(String::from("ota-ephemeral-deadbeef")),
            provider: None,
            cwd: None,
            acquired: Vec::new(),
            env: BTreeMap::new(),
            env_sources: Vec::new(),
            workflow_env_artifacts: Vec::new(),
            native_prerequisites: Vec::new(),
            toolchains: Vec::new(),
            runtime: None,
            logs: None,
            service_termination: Some(ServiceTermination {
                kind: ServiceTerminationKind::ServiceStopped,
                cause: ServiceTerminationCause::Interrupted,
                after_readiness: true,
                target: String::from("container"),
                container: String::from("ota-ephemeral-deadbeef"),
                exit_code: Some(130),
                readiness: None,
            }),
            host_service_cleanup: Vec::new(),
            backend_fulfillment: None,
            workloads: BTreeMap::new(),
            policy: Vec::new(),
            dependency_steps: Vec::new(),
            steps: vec![execution_receipt_step(1, "dev", "FAILED", None, Some(130))],
            blocked: Vec::new(),
            status: None,
            failed_task: None,
            failed_dependency: None,
            failure_origin: None,
            summary: ExecutionReceiptSummary {
                error_count: 1,
                warn_count: 0,
                info_count: 0,
                step_count: 1,
                repo_count: None,
                ready_count: None,
                not_ready_count: None,
            },
            next: None,
        };
        let service_termination = receipt.service_termination.clone();
        super::apply_interrupted_run_classification(
            &mut receipt,
            service_termination.as_ref(),
            false,
        );

        assert_eq!(receipt.steps[0].status, "INTERRUPTED");
        assert_eq!(receipt.summary.error_count, 0);
        assert!(receipt.summary.info_count > 0);

        let rendered = strip_ansi_codes(&render_execution_receipt_summary_block(
            &receipt,
            Some("dev"),
            "RUN SUMMARY",
        ));
        assert!(rendered.contains("Status:      interrupted"), "{rendered}");
        assert!(
            rendered.contains("service interrupted by user"),
            "{rendered}"
        );
        assert!(!rendered.contains("Status:      failed"), "{rendered}");
    }

