    #[test]
    fn up_success_receipt_includes_selected_native_prerequisites() {
        let _env_guard = env_mutex_lock();
        let _cwd_guard = cwd_mutex_lock();
        let fixture = TempDir::new().expect("temp dir");
        let marker = fixture.path().join("ota-native-activated");
        let marker_display = marker.display();
        let marker_pwsh = marker_display.to_string().replace('\'', "''");
        let (platform_name, activation_block, setup_run, required_tool) =
            match super::current_requirement_platform() {
                "windows" => (
                    "windows",
                    format!(
                        "activation:\n          kind: command\n          shell: pwsh\n          run: Set-Content -LiteralPath '{}' -Value '1'",
                        marker_pwsh
                    ),
                    format!(
                        "pwsh -NoProfile -NonInteractive -Command \"if (-not (Test-Path -LiteralPath '{}')) {{ exit 1 }}\"",
                        marker_pwsh
                    ),
                    "cargo",
                ),
                "macos" => (
                    "macos",
                    format!(
                        "activation:\n          kind: command\n          shell: sh\n          run: printf '1' > '{}'",
                        marker_display
                    ),
                    format!("sh -c 'test -f \"{}\"'", marker_display),
                    "cargo",
                ),
                _ => (
                    "linux",
                    format!(
                        "activation:\n          kind: command\n          shell: sh\n          run: printf '1' > '{}'",
                        marker_display
                    ),
                    format!("sh -c 'test -f \"{}\"'", marker_display),
                    "cargo",
                ),
            };

        let contract_source = format!(
            r#"
version: 1
project:
  name: target-test
tools:
  {required_tool}: "*"
native_prerequisites:
  shell-env:
    platforms:
      {platform_name}:
        check: shell-env-check
        requires:
          tools:
            {required_tool}: "*"
        {activation_block}
checks:
  - name: shell-env-check
    kind: precondition
    severity: error
    run: {setup_run}
tasks:
  setup:
    run: {setup_run}
    requirements:
      native: [shell-env]
workflows:
  default: app
  app:
    setup:
      task: setup
"#
        );
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(&contract_path, &contract_source).expect("write contract");
        let contract = parse_contract_str(&contract_path, &contract_source).unwrap();
        let result = super::execute_repo_up(
            &contract,
            &contract_path,
            ExecutionOverrides::default(),
            Some("app"),
            None,
            false,
            RepoExecutionMode::Capture,
        )
        .expect("up should execute");

        assert!(result.ok, "{}", result.status);
        assert_eq!(result.phase, "post-up diagnosis");
        let activation = result.receipt.native_prerequisites[0]
            .activation
            .as_ref()
            .expect("activation");
        assert!(activation.applied);
        let requires = result.receipt.native_prerequisites[0]
            .requires
            .as_ref()
            .expect("native prerequisite requires provenance");
        assert_eq!(
            requires.tools.get(required_tool).map(String::as_str),
            Some("*")
        );
        assert_eq!(requires.source, "native_prerequisite.platform.requires");
    }

