    #[test]
    fn up_selected_workflow_does_not_fail_on_unrelated_global_checks() {
        let _guard = env_mutex_lock();
        let repo = TempDir::new().unwrap();
        let contract_path = repo.path().join("ota.yaml");
        let bin_dir = repo.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        if cfg!(windows) {
            write_executable_script(
                &fake_command_path(&bin_dir, "node"),
                "@echo off\r\necho v19.0.0\r\nexit /b 0\r\n",
            );
        } else {
            write_executable_script(
                &fake_command_path(&bin_dir, "node"),
                "#!/bin/sh\necho v19.0.0\nexit 0\n",
            );
        }
        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        } else if cfg!(unix) {
            path_entries.push(PathBuf::from("/usr/bin"));
            path_entries.push(PathBuf::from("/bin"));
        }
        unsafe {
            env::set_var("PATH", env::join_paths(path_entries).unwrap());
        }
        let contract = parse_contract_str(
            contract_path.as_path(),
            r#"
version: 1
project:
  name: workflow-up
checks:
  - name: workspace-dependencies-installed
    kind: file
    severity: error
    path: node_modules
    expect: directory
tasks:
  quickstart:
    run: echo quickstart
    requirements:
      tools:
        node: "20"
workflows:
  default: instant
  instant:
    run:
      task: quickstart
"#,
        )
        .unwrap();

        let result = execute_repo_up(
            &contract,
            contract_path.as_path(),
            ExecutionOverrides::default(),
            Some("instant"),
            None,
            false,
            RepoExecutionMode::Capture,
        )
        .unwrap();
        match original_path {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        assert!(!result.report.findings.iter().any(
            |finding| finding.summary == "File check failed: workspace-dependencies-installed"
        ));
        assert!(
            result
                .report
                .findings
                .iter()
                .any(|finding| finding.summary == "Version mismatch for tool: node"),
            "status={} phase={} findings={:?} stdout=\n{}\nstderr=\n{}",
            result.status,
            result.phase,
            result
                .report
                .findings
                .iter()
                .map(|finding| finding.summary.as_str())
                .collect::<Vec<_>>(),
            result.stdout,
            result.stderr
        );
    }

