fn build_workspace_init_merge_state(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let contents = fs::read_to_string(workspace_path).map_err(|error| {
        format!(
            "failed to read `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let mut document: YamlValue = serde_yaml::from_str(&contents).map_err(|error| {
        format!(
            "failed to parse existing workspace contract `{}` for merge: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos = document
        .as_mapping()
        .and_then(|root| root.get(YamlValue::String(String::from("repos"))))
        .and_then(YamlValue::as_mapping)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    let mut additions = Vec::new();
    for repo in &draft.included {
        if !repos.contains_key(YamlValue::String(repo.name.clone())) {
            additions.push(repo.clone());
        }
    }

    let root = document.as_mapping_mut().ok_or_else(|| {
        format!(
            "existing workspace contract `{}` must be a mapping for merge",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos_key = YamlValue::String(String::from("repos"));
    if !root.contains_key(&repos_key) {
        root.insert(repos_key.clone(), YamlValue::Mapping(Mapping::new()));
    }
    let repos = root
        .get_mut(&repos_key)
        .and_then(YamlValue::as_mapping_mut)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    for repo in &additions {
        let repo_key = YamlValue::String(repo.name.clone());
        let spec =
            draft.contract.repos.get(&repo.name).ok_or_else(|| {
                format!("internal merge error: missing repo spec `{}`", repo.name)
            })?;
        let mut spec_map = Mapping::new();
        spec_map.insert(
            YamlValue::String(String::from("path")),
            YamlValue::String(spec.path.clone()),
        );
        spec_map.insert(
            YamlValue::String(String::from("required")),
            YamlValue::Bool(spec.required),
        );
        repos.insert(repo_key, YamlValue::Mapping(spec_map));
    }

    let yaml = serde_yaml::to_string(&document).map_err(|error| {
        format!(
            "failed to serialize merged workspace contract `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let contract =
        parse_workspace_contract_str(workspace_path, &yaml).map_err(|error| error.to_string())?;
    validate_workspace_contract(workspace_path, &contract).map_err(|error| error.to_string())?;
    Ok(WorkspaceInitMergeState {
        yaml,
        contract,
        comparison: WorkspaceInitComparison {
            existing_contract: true,
            additions,
        },
    })
}

fn apply_workspace_init_merge(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let state = build_workspace_init_merge_state(workspace_path, draft)?;
    if !state.comparison.additions.is_empty() {
        fs::write(workspace_path, &state.yaml).map_err(|error| {
            format!(
                "failed to write `{}`: {error}",
                compact_workspace_path(workspace_path)
            )
        })?;
    }
    Ok(state)
}

fn resolve_workspace_init_target(path: Option<&Path>) -> Result<(PathBuf, PathBuf), String> {
    match path {
        Some(path)
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name == DEFAULT_WORKSPACE_FILE) =>
        {
            let root = path
                .parent()
                .filter(|parent| !parent.as_os_str().is_empty())
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from("."));
            Ok((root, path.to_path_buf()))
        }
        Some(path) if path.is_dir() => {
            let root = path.to_path_buf();
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
        Some(path) => Err(format!(
            "workspace init path must be a directory or `{DEFAULT_WORKSPACE_FILE}` target path: {}",
            path.display()
        )),
        None => {
            let root = std::env::current_dir()
                .map_err(|error| format!("failed to resolve current directory: {error}"))?;
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
    }
}

fn build_workspace_init_draft(workspace_root: &Path) -> Result<WorkspaceInitDraft, String> {
    let mut candidates = discover_workspace_candidates(workspace_root)?;
    let has_any_candidates = !candidates.is_empty();
    candidates.sort_by(|left, right| left.path.cmp(&right.path));

    let mut included = Vec::new();
    let mut missing_contract = Vec::new();
    for candidate in candidates {
        if candidate.has_contract {
            included.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        } else {
            missing_contract.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        }
    }

    if !has_any_candidates {
        return Err(format!(
            "workspace init could not find any repos to bootstrap; add repo contracts first before writing `ota.workspace.yaml`{}",
            format_next_timeline(&[
                String::from("create repo contracts with `ota init <repo-path>`"),
                String::from("or preview repo contracts with `ota detect --dry-run <repo-path>`"),
                String::from(
                    "then compare `ota workspace detect --dry-run <workspace-root>` with `ota workspace init --dry-run <workspace-root>` before writing a workspace contract"
                ),
            ]),
        ));
    }

    let mut repos = BTreeMap::new();
    for repo in &included {
        repos.insert(
            repo.name.clone(),
            WorkspaceInitRepoSpec {
                path: repo.path.clone(),
                required: true,
            },
        );
    }

    let workspace_name = workspace_root
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or("ota-workspace")
        .to_string();

    Ok(WorkspaceInitDraft {
        contract: WorkspaceInitContract {
            version: 1,
            workspace: WorkspaceInitWorkspace {
                name: workspace_name,
                description: None,
            },
            repos,
        },
        included,
        missing_contract,
    })
}

fn auto_provision_workspace_repo_contracts(
    workspace_root: &Path,
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceAutoProvisionResult {
    let mut result = WorkspaceAutoProvisionResult {
        provisioned: Vec::new(),
        skipped: Vec::new(),
    };

    for repo in missing_contract {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        if contract_path.is_file() {
            result.provisioned.push(repo.clone());
            continue;
        }

        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let Some(candidate) = build_detect_write_candidate(&report) else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => {
                    if let Err(error) = fs::write(&contract_path, yaml) {
                        result
                            .skipped
                            .push((repo.clone(), format!("write failed: {error}")));
                        continue;
                    }
                    result.provisioned.push(repo.clone());
                    continue;
                }
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };
        let candidate_yaml = match serde_yaml::to_string(&candidate) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &candidate_yaml) {
            candidate_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.provisioned.push(repo.clone());
    }

    result
}

fn rewrite_workspace_repo_contracts(
    workspace_root: &Path,
    included: &[WorkspaceInitRepoSummary],
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceRepoRewriteResult {
    let mut result = WorkspaceRepoRewriteResult {
        rewritten: Vec::new(),
        skipped: Vec::new(),
    };
    let repos = included
        .iter()
        .chain(missing_contract.iter())
        .cloned()
        .collect::<Vec<_>>();

    for repo in repos {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let Some(candidate) = build_detect_write_candidate(&report) else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => {
                    if contract_path.is_file()
                        && let Err(error) = create_timestamped_backup(&contract_path)
                    {
                        result
                            .skipped
                            .push((repo.clone(), format!("backup failed: {error}")));
                        continue;
                    }
                    if let Err(error) = fs::write(&contract_path, yaml) {
                        result
                            .skipped
                            .push((repo.clone(), format!("write failed: {error}")));
                        continue;
                    }
                    result.rewritten.push(repo);
                    continue;
                }
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };
        let candidate_yaml = match serde_yaml::to_string(&candidate) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &candidate_yaml) {
            candidate_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if contract_path.is_file()
            && let Err(error) = create_timestamped_backup(&contract_path)
        {
            result
                .skipped
                .push((repo.clone(), format!("backup failed: {error}")));
            continue;
        }

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.rewritten.push(repo);
    }

    result
}

fn contract_yaml_valid(path: &Path, yaml: &str) -> bool {
    parse_contract_str(path, yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(path)).map_err(|error| error.to_string())
        })
        .is_ok()
}

fn minimal_repo_contract_yaml(project_name: &str) -> Result<String, String> {
    let mut root = Mapping::new();
    root.insert(
        YamlValue::String(String::from("version")),
        YamlValue::Number(1u64.into()),
    );
    let mut project = Mapping::new();
    project.insert(
        YamlValue::String(String::from("name")),
        YamlValue::String(project_name.to_string()),
    );
    root.insert(
        YamlValue::String(String::from("project")),
        YamlValue::Mapping(project),
    );
    let yaml = serde_yaml::to_string(&YamlValue::Mapping(root))
        .map_err(|error| format!("failed to build minimal contract: {error}"))?;

    if !contract_yaml_valid(Path::new(DEFAULT_CONTRACT_FILE), &yaml) {
        return Err(String::from(
            "failed to build a valid minimal contract for auto-provision",
        ));
    }

    Ok(yaml)
}

#[derive(Clone)]
struct WorkspaceCandidate {
    name: String,
    path: String,
    has_contract: bool,
}

fn discover_workspace_candidates(workspace_root: &Path) -> Result<Vec<WorkspaceCandidate>, String> {
    let mut rel_paths = BTreeSet::new();
    collect_child_repo_dirs(workspace_root, workspace_root, &mut rel_paths)?;

    for group in ["apps", "services", "repos", "packages"] {
        let container = workspace_root.join(group);
        if container.is_dir() {
            collect_child_repo_dirs(workspace_root, &container, &mut rel_paths)?;
        }
    }

    let mut used_names = BTreeSet::new();
    let mut candidates = Vec::new();
    for rel_path in rel_paths {
        let repo_root = workspace_root.join(&rel_path);
        if !looks_like_repo_candidate(&repo_root) {
            continue;
        }
        let has_contract = repo_root.join(DEFAULT_CONTRACT_FILE).is_file();
        let name = make_workspace_repo_name(&rel_path, &mut used_names);
        candidates.push(WorkspaceCandidate {
            name,
            path: rel_path,
            has_contract,
        });
    }

    Ok(candidates)
}

fn collect_child_repo_dirs(
    workspace_root: &Path,
    parent: &Path,
    rel_paths: &mut BTreeSet<String>,
) -> Result<(), String> {
    let entries = fs::read_dir(parent)
        .map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
    for entry in entries {
        let entry =
            entry.map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if name.starts_with('.') {
            continue;
        }

        let rel = match path.strip_prefix(workspace_root) {
            Ok(rel) => rel,
            Err(_) => continue,
        };
        rel_paths.insert(path_to_contract_style(rel));
    }
    Ok(())
}

fn path_to_contract_style(path: &Path) -> String {
    path.components()
        .map(|component| component.as_os_str().to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join("/")
}

fn make_workspace_repo_name(rel_path: &str, used_names: &mut BTreeSet<String>) -> String {
    let base = rel_path
        .rsplit('/')
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("repo")
        .to_string();
    if used_names.insert(base.clone()) {
        return base;
    }

    let mut normalized = rel_path.replace('/', "-");
    if normalized.is_empty() {
        normalized = String::from("repo");
    }
    if used_names.insert(normalized.clone()) {
        return normalized;
    }

    let mut suffix = 2;
    loop {
        let candidate = format!("{normalized}-{suffix}");
        if used_names.insert(candidate.clone()) {
            return candidate;
        }
        suffix += 1;
    }
}

fn looks_like_repo_candidate(repo_root: &Path) -> bool {
    if repo_root.join(DEFAULT_CONTRACT_FILE).is_file() || repo_root.join(".git").exists() {
        return true;
    }

    const MARKERS: [&str; 12] = [
        "package.json",
        "pyproject.toml",
        "requirements.txt",
        "go.mod",
        "Cargo.toml",
        "pom.xml",
        "build.gradle",
        "build.gradle.kts",
        "composer.json",
        "CMakeLists.txt",
        "mix.exs",
        "Project.toml",
    ];

    MARKERS
        .iter()
        .any(|marker| repo_root.join(marker).is_file())
}

#[derive(Clone, Debug)]
struct RunLogCaptureResult {
    logs: Option<ExecutionReceiptLogs>,
    warning: Option<String>,
}

#[derive(Clone, Debug)]
struct PreparedStreamingRunLogs {
    capture: RunLogCaptureResult,
    live_log: Option<StreamLogTee>,
}

fn capture_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
    enabled: bool,
) -> RunLogCaptureResult {
    if !enabled {
        return RunLogCaptureResult {
            logs: None,
            warning: None,
        };
    }

    match write_durable_run_logs(contract_path, task_name, member, stdout, stderr) {
        Ok(logs) => RunLogCaptureResult {
            logs: Some(logs),
            warning: None,
        },
        Err(error) => RunLogCaptureResult {
            logs: None,
            warning: Some(format!("log capture failed: {error}")),
        },
    }
}

fn prepare_streaming_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> PreparedStreamingRunLogs {
    if !enabled {
        return PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: None,
            },
            live_log: None,
        };
    }

    match create_durable_run_log_paths(contract_path, task_name, member) {
        Ok((logs, stdout_path, stderr_path)) => {
            let stdout = StreamLogFile::create(&stdout_path).map_err(|error| {
                format!(
                    "failed to create stdout log `{}`: {error}",
                    compact_path(&stdout_path, ".")
                )
            });
            let stderr = StreamLogFile::create(&stderr_path).map_err(|error| {
                format!(
                    "failed to create stderr log `{}`: {error}",
                    compact_path(&stderr_path, ".")
                )
            });
            match (stdout, stderr) {
                (Ok(stdout), Ok(stderr)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: Some(logs),
                        warning: None,
                    },
                    live_log: Some(StreamLogTee {
                        stdout: Arc::new(Mutex::new(stdout)),
                        stderr: Arc::new(Mutex::new(stderr)),
                    }),
                },
                (Err(error), _) | (_, Err(error)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: None,
                        warning: Some(format!("log capture failed: {error}")),
                    },
                    live_log: None,
                },
            }
        }
        Err(error) => PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: Some(format!("log capture failed: {error}")),
            },
            live_log: None,
        },
    }
}

fn capture_streaming_structured_error_logs(
    prepared_logs: &PreparedStreamingRunLogs,
    error_detail: &str,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> RunLogCaptureResult {
    if let (Some(logs), Some(live_log)) = (
        prepared_logs.capture.logs.clone(),
        prepared_logs.live_log.as_ref(),
    ) {
        match live_log.stderr.lock() {
            Ok(mut stderr) => match stderr.write_all(error_detail.as_bytes()) {
                Ok(()) => {
                    let _ = stderr.flush();
                    RunLogCaptureResult {
                        logs: Some(logs),
                        warning: prepared_logs.capture.warning.clone(),
                    }
                }
                Err(error) => RunLogCaptureResult {
                    logs: Some(logs),
                    warning: Some(format!("log capture failed: {error}")),
                },
            },
            Err(_) => RunLogCaptureResult {
                logs: Some(logs),
                warning: Some(String::from(
                    "log capture failed: durable log handle lock was poisoned",
                )),
            },
        }
    } else {
        capture_durable_run_logs(contract_path, task_name, member, "", error_detail, enabled)
    }
}

fn create_durable_run_log_paths(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
) -> Result<(ExecutionReceiptLogs, PathBuf, PathBuf), String> {
    let repo_root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let logs_root = repo_root.join(".ota").join("state").join("logs");
    fs::create_dir_all(&logs_root).map_err(|error| {
        format!(
            "failed to create log directory `{}`: {error}",
            compact_path(&logs_root, ".")
        )
    })?;

    let stamp = OffsetDateTime::now_utc()
        .format(&format_description!(
            "[year][month][day]-[hour][minute][second]-[subsecond digits:3]Z"
        ))
        .map_err(|error| format!("failed to format run log timestamp: {error}"))?;
    let task_slug = sanitize_log_component(task_name, "task");
    let member_suffix = member.map(|value| format!("-{}", sanitize_log_component(value, "member")));
    let run_id = format!(
        "{stamp}-{task_slug}{}-{}",
        member_suffix.unwrap_or_default(),
        std::process::id()
    );
    let run_dir = logs_root.join(run_id);
    fs::create_dir_all(&run_dir).map_err(|error| {
        format!(
            "failed to create run log directory `{}`: {error}",
            compact_path(&run_dir, ".")
        )
    })?;

    let stdout_path = run_dir.join("stdout.log");
    let stderr_path = run_dir.join("stderr.log");
    Ok((
        ExecutionReceiptLogs {
            dir: repo_relative_log_path(repo_root, &run_dir),
            stdout: repo_relative_log_path(repo_root, &stdout_path),
            stderr: repo_relative_log_path(repo_root, &stderr_path),
        },
        stdout_path,
        stderr_path,
    ))
}

fn write_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
) -> Result<ExecutionReceiptLogs, String> {
    let (logs, stdout_path, stderr_path) =
        create_durable_run_log_paths(contract_path, task_name, member)?;
    fs::write(&stdout_path, stdout).map_err(|error| {
        format!(
            "failed to write stdout log `{}`: {error}",
            compact_path(&stdout_path, ".")
        )
    })?;
    fs::write(&stderr_path, stderr).map_err(|error| {
        format!(
            "failed to write stderr log `{}`: {error}",
            compact_path(&stderr_path, ".")
        )
    })?;

    Ok(logs)
}

fn sanitize_log_component(value: &str, fallback: &str) -> String {
    let mut output = value
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect::<String>();
    while output.contains("--") {
        output = output.replace("--", "-");
    }
    let output = output.trim_matches('-');
    if output.is_empty() {
        fallback.to_string()
    } else {
        output.to_string()
    }
}

fn repo_relative_log_path(repo_root: &Path, path: &Path) -> String {
    path.strip_prefix(repo_root)
        .map(|relative| relative.to_string_lossy().to_string())
        .unwrap_or_else(|_| compact_path(path, "."))
}

fn run_contract_targets(
    task_name: &str,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    members: &[String],
    task_inputs: &[String],
    show_receipt: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    if members.is_empty() {
        let target = load_and_validate_target(resolved_path, None).map_err(|error| {
            render_run_contract_problem_failure(resolved_path, None, task_name, error)
        })?;
        return run_single_contract_target(
            task_name,
            overrides,
            None,
            target,
            task_inputs,
            show_receipt,
            stream_output,
            persist_logs,
        );
    }

    let mut stderr_sections = Vec::new();
    for member in members {
        let target =
            load_and_validate_target(resolved_path, Some(member.as_str())).map_err(|error| {
                render_run_contract_problem_failure(
                    resolved_path,
                    Some(member.as_str()),
                    task_name,
                    error,
                )
            })?;
        stderr_sections.push(run_single_contract_target(
            task_name,
            overrides,
            Some(member.as_str()),
            target,
            task_inputs,
            show_receipt,
            stream_output,
            persist_logs,
        )?);
    }

    Ok(stderr_sections.join("\n"))
}

fn run_single_contract_target(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    target: LoadedContractTarget,
    task_inputs: &[String],
    show_receipt: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    let details_footer = task_use_details_footer(Some(&target.contract_path), member);
    if let Some(failure) = run_selected_precondition_failure(
        task_name,
        overrides,
        member,
        &target.contract,
        &target.contract_path,
    ) {
        return Err(failure);
    }
    if stream_output || task_requires_interactive_stream(&target.contract, task_name, overrides) {
        return run_single_contract_target_streaming(
            task_name,
            overrides,
            member,
            target,
            task_inputs,
            show_receipt,
            &details_footer,
            persist_logs,
        );
    }

    run_single_contract_target_captured(
        task_name,
        overrides,
        member,
        target,
        task_inputs,
        show_receipt,
        &details_footer,
        persist_logs,
    )
}

fn task_requires_interactive_stream(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> bool {
    let task_name = canonical_declared_task_name(contract, task_name);
    let Some(task) = contract.tasks.get(task_name.as_str()) else {
        return false;
    };
    let backend = effective_task_execution(contract, task_name.as_str(), overrides).backend;
    task.resolved_execution_for_backend(backend, current_os())
        .and_then(|execution| execution.compose())
        .is_some_and(|compose| {
            compose.invocation.kind == crate::schema::TaskComposeExecutionKind::Attach
        })
}

fn run_selected_precondition_failure(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    contract: &Contract,
    contract_path: &Path,
) -> Option<RunCommandFailure> {
    let task_name = canonical_declared_task_name(contract, task_name);
    if resolve_execution_plan_for_task(contract, contract_path, task_name.as_str(), overrides)
        .is_err()
    {
        return None;
    }
    let env_report = build_env_report_with_overrides(
        contract,
        contract_path,
        None,
        Some(task_name.as_str()),
        overrides,
    )
    .ok()?;
    let preconditions_report =
        run_preview_preconditions_report(contract, contract_path, task_name.as_str(), overrides);
    let mut summary = run_preview_summary(
        contract,
        task_name.as_str(),
        member,
        &env_report,
        &preconditions_report,
        overrides,
    );
    if !doctor_verdict_blocks_preview(summary.verdict) {
        return None;
    }
    if has_native_prerequisite_blocker(&preconditions_report) {
        let native_actions = selected_task_native_package_provisioning_actions_for_os(
            contract,
            task_name.as_str(),
            overrides,
            &preconditions_report,
            current_requirement_platform(),
        );
        if !native_actions.is_empty() {
            let request = crate::policy_pack::ProvisioningBackendRequest {
                actions: native_actions,
            };
            if best_effort_apply_provisioning_request_with_adapter_bootstrap(
                contract_path,
                &request,
                &ProvisioningExecutionTarget::Native,
            ) {
                let refreshed_report = run_preview_preconditions_report(
                    contract,
                    contract_path,
                    task_name.as_str(),
                    overrides,
                );
                let refreshed_summary = run_preview_summary(
                    contract,
                    task_name.as_str(),
                    member,
                    &env_report,
                    &refreshed_report,
                    overrides,
                );
                if !doctor_verdict_blocks_preview(refreshed_summary.verdict) {
                    return None;
                }
                summary = refreshed_summary;
            }
        }
    }
    let primary_blocker = summary.primary_blocker?;
    if !run_precondition_blocker_should_stop_execution(&primary_blocker.summary) {
        return None;
    }
    let effective = effective_task_execution(contract, task_name.as_str(), overrides);
    let doctor_mode = doctor_mode_from_backend(Some(format_backend(effective.backend)))
        .unwrap_or(DoctorMode::Native);
    let lifecycle = effective.lifecycle;
    let (display_why, display_next, container_image) = render_container_image_finding_text(
        &primary_blocker.why,
        &primary_blocker.next,
        Some(doctor_mode),
    );
    let why_lines = finding_why_lines(
        &primary_blocker.summary,
        &display_why,
        container_image.as_deref(),
    );
    let rewritten_next = rewrite_doctor_mode_command(&display_next, Some(doctor_mode), lifecycle);
    let next_steps = rewritten_next
        .split("; ")
        .map(str::to_string)
        .collect::<Vec<_>>();
    let text_path_display = display_contract_target(&compact_contract_path(contract_path), member);

    if let Some(message) = render_run_version_mismatch_precondition_text(
        &text_path_display,
        task_name.as_str(),
        member,
        effective.backend,
        &primary_blocker.summary,
        &display_why,
        &rewritten_next,
    ) {
        return Some(RunCommandFailure {
            message,
            summary: None,
            exit_code: 1,
            receipt: None,
        });
    }

    let message = render_field_error_with_tail(
        "RUN",
        &text_path_display,
        &format!("tasks.{task_name}.requirements"),
        &finding_diagnosis_text(
            &primary_blocker.summary,
            &display_why,
            container_image.as_deref(),
        ),
        &why_lines,
        &next_steps,
        None,
        None,
    );

    Some(RunCommandFailure {
        message,
        summary: None,
        exit_code: 1,
        receipt: None,
    })
}

fn render_run_version_mismatch_precondition_text(
    where_value: &str,
    task_name: &str,
    member: Option<&str>,
    backend: Backend,
    summary: &str,
    why: &str,
    next: &str,
) -> Option<String> {
    let (target_kind, subject_name) =
        if let Some(name) = summary.strip_prefix("Version mismatch for runtime: ") {
            ("runtime", strip_finding_context_suffix(name))
        } else if let Some(name) = summary.strip_prefix("Version mismatch for tool: ") {
            ("tool", strip_finding_context_suffix(name))
        } else {
            return None;
        };

    let mismatch_scope = if finding_targets_container_image(why) {
        Some("container")
    } else if finding_targets_remote_backend(why) {
        Some("remote")
    } else {
        None
    };

    let required = extract_backticked_value_after(why, "but the contract requires `");
    let actual = extract_backticked_value_after(why, "resolved to `");
    let probe_path = extract_backticked_value_after(why, "ota probed `");
    let probe_command = extract_backticked_value_after(why, " with `");

    let mut why_lines = Vec::new();
    if let Some(required) = required.as_deref() {
        why_lines.push(format!("task requires `{subject_name}@{required}`"));
    }
    if let Some(actual) = actual.as_deref() {
        let location_suffix = match mismatch_scope {
            Some("container") => " in the configured container image",
            Some("remote") => " through the selected remote backend",
            _ => "",
        };
        why_lines.push(format!(
            "resolved {target_kind} is `{subject_name}@{actual}`{location_suffix}"
        ));
    }
    if let Some(path) = probe_path.as_deref() {
        if let Some(command) = probe_command.as_deref() {
            why_lines.push(format!("detected via `{path}` (`{command}`)"));
        } else {
            why_lines.push(format!("detected via `{path}`"));
        }
    }
    if why_lines.is_empty() {
        why_lines.push(why.to_string());
    }

    let mut next_steps = finding_next_steps(next)
        .into_iter()
        .map(|step| normalize_run_blocker_next_step(&step))
        .collect::<Vec<_>>();
    if !next_steps.iter().any(|step| step.contains("`ota doctor`")) {
        next_steps.push(String::from("run `ota doctor` to confirm readiness"));
    }
    let rerun_command = format!(
        "run `{}`",
        repo_run_command_for_backend(task_name, member, backend)
    );
    if !next_steps.iter().any(|step| step == &rerun_command) {
        next_steps.push(rerun_command);
    }

    let mismatch_summary = if let Some(scope) = mismatch_scope {
        format!("{scope} {target_kind} mismatch: {subject_name}")
    } else {
        format!("{target_kind} mismatch: {subject_name}")
    };

    Some(structured_field_error_text(
        "RUN",
        where_value,
        &format!("tasks.{task_name}.requirements"),
        &format!("task `{task_name}` is blocked ({mismatch_summary})"),
        &why_lines,
        &next_steps,
    ))
}

fn extract_backticked_value_after(value: &str, marker: &str) -> Option<String> {
    let rest = value.split_once(marker)?.1;
    let end = rest.find('`')?;
    let token = rest[..end].trim();
    (!token.is_empty()).then(|| token.to_string())
}

fn normalize_run_blocker_next_step(step: &str) -> String {
    step.strip_prefix("rerun `")
        .map(|rest| format!("run `{rest}"))
        .unwrap_or_else(|| step.to_string())
}

fn is_effect_governance_policy_block_summary(summary: &str) -> bool {
    summary.starts_with("Effect governance policy blocked safe-task effect")
        || summary.starts_with("Effect governance policy blocked task effect")
}

fn run_precondition_blocker_should_stop_execution(summary: &str) -> bool {
    summary.starts_with("Missing tool: ")
        || summary.starts_with("Missing runtime: ")
        || summary.starts_with("Tool probe failed: ")
        || summary.starts_with("Runtime probe failed: ")
        || summary.starts_with("Version mismatch for tool: ")
        || summary.starts_with("Version mismatch for runtime: ")
        || is_effect_governance_policy_block_summary(summary)
}

#[cfg(test)]
#[test]
fn run_precondition_blocker_stops_for_effect_policy_block() {
    assert!(run_precondition_blocker_should_stop_execution(
        "Effect governance policy blocked safe-task effect `external_state:docker`",
    ));
    assert!(run_precondition_blocker_should_stop_execution(
        "Effect governance policy blocked task effect `network:broad`",
    ));
}

#[cfg(test)]
#[test]
fn effect_override_parser_accepts_supported_selectors() {
    let overrides = parse_effect_governance_overrides(&[
        String::from("network=deny"),
        String::from("network:dependency_hydration=allow"),
        String::from("network:integration_test=warn"),
        String::from("network:tool_bootstrap=allow"),
        String::from("adapter_state:compose_volume:bundle_data=deny"),
        String::from("external_state:docker_compose=warn"),
    ])
    .expect("selectors should parse");

    assert_eq!(
        overrides.decisions.get("network:broad"),
        Some(&PolicyEffectDecision::Deny)
    );
    assert_eq!(
        overrides.decisions.get("network:dependency_hydration"),
        Some(&PolicyEffectDecision::Allow)
    );
    assert_eq!(
        overrides.decisions.get("network:integration_test"),
        Some(&PolicyEffectDecision::Warn)
    );
    assert_eq!(
        overrides.decisions.get("network:tool_bootstrap"),
        Some(&PolicyEffectDecision::Allow)
    );
    assert_eq!(
        overrides
            .decisions
            .get("adapter_state:compose_volume:bundle_data"),
        Some(&PolicyEffectDecision::Deny)
    );
    assert_eq!(
        overrides.decisions.get("external_state:docker_compose"),
        Some(&PolicyEffectDecision::Warn)
    );
}

#[cfg(test)]
#[test]
fn effect_override_parser_rejects_invalid_effect_tokens() {
    let error = parse_effect_governance_overrides(&[String::from(
        "adapter_state:ComposeVolume:cache=deny",
    )])
    .expect_err("uppercase adapter token should be rejected");
    assert!(error.contains("effect selector"), "{error}");

    let error = parse_effect_governance_overrides(&[String::from("external_state:Docker=allow")])
        .expect_err("uppercase token should be rejected");
    assert!(error.contains("effect selector"), "{error}");

    let error =
        parse_effect_governance_overrides(&[String::from("external_state:docker--ops=allow")])
            .expect_err("duplicate separator token should be rejected");
    assert!(error.contains("effect selector"), "{error}");
}

fn run_single_contract_target_streaming(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    mut target: LoadedContractTarget,
    task_inputs: &[String],
    show_receipt: bool,
    details_footer: &str,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    if let Err(error) =
        materialize_selected_workflow_env_profile_for_task(&mut target, None, task_name)
    {
        return Err(RunCommandFailure {
            message: stylize_text_failure("ota run", &error),
            summary: None,
            exit_code: 1,
            receipt: None,
        });
    }
    let task_name = canonical_declared_task_name(&target.contract, task_name);
    let prepared_logs = prepare_streaming_durable_run_logs(
        &target.contract_path,
        task_name.as_str(),
        member,
        persist_logs,
    );
    match run_task_with_args_with_overrides_and_stream_capture(
        &target.contract,
        &target.contract_path,
        task_name.as_str(),
        task_inputs,
        overrides,
        true,
        prepared_logs.live_log.clone(),
    ) {
        Ok(outcome) if outcome.exit_code == 0 => {
            let log_capture = if prepared_logs.capture.logs.is_some() {
                prepared_logs.capture.clone()
            } else {
                capture_durable_run_logs(
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    &outcome.stdout,
                    &outcome.stderr,
                    persist_logs,
                )
            };
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &outcome.task_steps,
                &outcome.task_step_target_resolutions,
                &outcome.target_resolutions,
                &outcome.fulfilled_toolchains,
                &outcome.task_step_backend_fulfillments,
                outcome.backend_fulfillment.clone(),
                &outcome.task_step_shared_local_backends,
                outcome.shared_local_backend.clone(),
                outcome.exit_code,
                true,
                outcome.target.clone(),
                outcome.runtime.clone(),
                Some(task_use_details_step(Some(&target.contract_path), member)),
            );
            receipt.service_termination = outcome.service_termination.clone();
            receipt.host_service_cleanup = outcome.host_service_cleanup.clone();
            apply_interrupted_run_classification(
                &mut receipt,
                outcome.service_termination.as_ref(),
                outcome.interrupted,
            );
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            if overrides.skip_deps {
                receipt.next = Some(skip_deps_next(
                    task_name.as_str(),
                    member,
                    overrides,
                    receipt.next.take(),
                ));
            }
            let mut output = String::new();
            if show_receipt {
                let receipt_text = render_execution_receipt_text(&receipt);
                if output.is_empty() {
                    output.push_str(receipt_text.trim_start_matches('\n'));
                } else {
                    output.push_str(&receipt_text);
                }
                output.push('\n');
            }
            output.push_str(&render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            ));
            append_receipt_next_block(&mut output, &receipt);
            Ok(output)
        }
        Ok(outcome) => {
            let log_capture = if prepared_logs.capture.logs.is_some() {
                prepared_logs.capture.clone()
            } else {
                capture_durable_run_logs(
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    &outcome.stdout,
                    &outcome.stderr,
                    persist_logs,
                )
            };
            let failed_task_name = failed_task_name(&outcome.task_steps, task_name.as_str());
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &outcome.task_steps,
                &outcome.task_step_target_resolutions,
                &outcome.target_resolutions,
                &outcome.fulfilled_toolchains,
                &outcome.task_step_backend_fulfillments,
                outcome.backend_fulfillment.clone(),
                &outcome.task_step_shared_local_backends,
                outcome.shared_local_backend.clone(),
                outcome.exit_code,
                false,
                outcome.target.clone(),
                outcome.runtime.clone(),
                Some(format!(
                    "{}; {}",
                    format!(
                        "inspect task `{failed_task_name}` output and rerun `ota run {failed_task_name}`"
                    ),
                    details_footer
                )),
            );
            receipt.service_termination = outcome.service_termination.clone();
            receipt.host_service_cleanup = outcome.host_service_cleanup.clone();
            apply_interrupted_run_classification(
                &mut receipt,
                outcome.service_termination.as_ref(),
                outcome.interrupted,
            );
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            if overrides.skip_deps {
                receipt.next = Some(skip_deps_next(
                    task_name.as_str(),
                    member,
                    overrides,
                    receipt.next.take(),
                ));
            }
            let summary = render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            );
            let receipt_text = show_receipt.then(|| render_execution_receipt_text(&receipt));
            Err(RunCommandFailure {
                message: render_run_captured_failure_text(
                    &target.contract,
                    &target.contract_path,
                    &display_contract_target(&compact_contract_path(&target.contract_path), member),
                    &failed_task_name,
                    task_name.as_str(),
                    member,
                    overrides,
                    outcome.exit_code,
                    &outcome.stdout,
                    &outcome.stderr,
                    outcome.runtime.as_ref(),
                    outcome.service_termination.as_ref(),
                    outcome.interrupted,
                    receipt_text.as_deref(),
                    &summary,
                ),
                summary: None,
                exit_code: outcome.exit_code,
                receipt: None,
            })
        }
        Err(error) => {
            let error_detail = error.to_string();
            let log_capture = capture_streaming_structured_error_logs(
                &prepared_logs,
                &error_detail,
                &target.contract_path,
                task_name.as_str(),
                member,
                persist_logs,
            );
            let next_note = match &error {
                RunError::RuntimeListenerResolutionFailed {
                    task,
                    listener,
                    kind,
                } => runtime_listener_resolution_receipt_note(
                    member, task, listener, kind, overrides,
                ),
                _ => format!(
                    "{}; {}",
                    format!("repair task `{task_name}` and rerun `ota run {task_name}`"),
                    details_footer
                ),
            };
            let error_target = match &error {
                RunError::PersistentContainerListenerBindConflict { container, .. } => {
                    Some(container.clone())
                }
                _ => None,
            };
            let error_backend_fulfillment = match &error {
                RunError::BackendRequirementsMissing { evidence, .. }
                | RunError::BackendFulfillmentFailed { evidence, .. } => Some(evidence.clone()),
                _ => None,
            };
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                overrides,
                task_name.as_str(),
                member,
                &[],
                &[],
                &[],
                &[],
                &[],
                error_backend_fulfillment,
                &[],
                None,
                1,
                false,
                error_target,
                None,
                Some(next_note),
            );
            receipt.blocked = run_error_receipt_blocked_entries(&error);
            refresh_execution_receipt_status(&mut receipt);
            apply_run_log_capture_to_receipt(&mut receipt, log_capture);
            if overrides.skip_deps {
                receipt.next = Some(skip_deps_next(
                    task_name.as_str(),
                    member,
                    overrides,
                    receipt.next.take(),
                ));
            }
            let summary = render_execution_receipt_summary_block(
                &receipt,
                Some(task_name.as_str()),
                "RUN SUMMARY",
            );
            let receipt_text = show_receipt.then(|| render_execution_receipt_text(&receipt));
            Err(RunCommandFailure {
                message: render_run_structured_error_text(
                    &target.contract,
                    &target.contract_path,
                    task_name.as_str(),
                    member,
                    overrides,
                    task_inputs,
                    &error,
                    &summary,
                    receipt_text.as_deref(),
                ),
                summary: None,
                exit_code: 1,
                receipt: None,
            })
        }
    }
}

