fn render_task_runtime_bind_validation_text(
    command: &str,
    resolved_path: &Path,
    member: Option<&str>,
    errors: &ValidationErrors,
    rerun_commands: &[&str],
) -> Option<String> {
    let text_path_display = display_contract_target(&compact_contract_path(resolved_path), member);
    if let Some(issue) = parse_runtime_projection_primary_issue(errors) {
        let field = format!("tasks.{}.runtime.listeners", issue.task_name);
        let listeners = issue
            .listeners
            .iter()
            .map(|listener| format!("`{listener}`"))
            .collect::<Vec<_>>()
            .join(", ");
        let (why_lines, mut next_steps) = match issue.kind {
            RuntimeProjectionPrimaryIssueKind::MissingPrimary => (
                vec![
                    format!(
                        "task `{}` projects multiple listeners ({listeners}) but none is marked primary",
                        issue.task_name
                    ),
                    String::from(
                        "ota needs one primary projected listener to pick `OTA_PUBLIC_URL` and the summary endpoint deterministically",
                    ),
                ],
                vec![
                    String::from(
                        "set `project.host.primary: true` on exactly one projected listener",
                    ),
                    String::from("leave all other projected listeners unset or `false`"),
                ],
            ),
            RuntimeProjectionPrimaryIssueKind::MultiplePrimaries => (
                vec![
                    format!(
                        "task `{}` marks multiple projected listeners as primary ({listeners})",
                        issue.task_name
                    ),
                    String::from(
                        "`OTA_PUBLIC_URL` and primary endpoint rendering require exactly one primary projected listener",
                    ),
                ],
                vec![
                    String::from(
                        "keep `project.host.primary: true` on one projected listener only",
                    ),
                    String::from(
                        "set all other projected listeners to `primary: false` or remove the field",
                    ),
                ],
            ),
        };
        next_steps.extend(rerun_commands.iter().map(|rerun_command| {
            format!(
                "rerun {}",
                paint_code(&format!(
                    "`{}`",
                    command_for_repo_contract_target(rerun_command, resolved_path)
                ))
            )
        }));
        return Some(structured_field_error_text(
            command,
            &text_path_display,
            &field,
            "Invalid contract",
            &why_lines,
            &next_steps,
        ));
    }

    let Some((task_name, listener_name, issue_kind)) = parse_runtime_projection_issue(errors)
    else {
        return None;
    };

    match issue_kind {
        RuntimeProjectionIssueKind::BindPortModeAuto => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.mode");
            let why_lines = vec![
                format!(
                    "task `{task_name}` listener `{listener_name}` with `bind.port.mode: auto` is invalid"
                ),
                String::from("`bind.port.mode` only supports `fixed` or `discover`"),
                String::from("`auto` is only valid on `project.host.port.mode`"),
            ];
            let mut next_steps = vec![String::from("change this field to `fixed` or `discover`")];
            next_steps.extend(rerun_commands.iter().map(|rerun_command| {
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target(rerun_command, resolved_path)
                    ))
                )
            }));
            return Some(structured_field_error_text(
                command,
                &text_path_display,
                &field,
                "Invalid contract",
                &why_lines,
                &next_steps,
            ));
        }
        RuntimeProjectionIssueKind::ContainerProjectionRequiresFixedBind => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.mode");
            let why_lines = vec![
                format!(
                    "task `{task_name}` listener `{listener_name}` must use `bind.port.mode: fixed` when `project.host` is declared in a container context"
                ),
                String::from(
                    "container workloads with `project.host` declared must use a fixed internal bind port",
                ),
                String::from(
                    "`project.host.port.mode: auto` can stay auto so Ota can choose the published host port",
                ),
            ];
            let mut next_steps = vec![
                format!(
                    "change `bind.port.mode` to `fixed` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
                ),
                String::from("set `bind.port.value` to the port the app listens on"),
                String::from(
                    "keep `project.host.port.mode: auto` if you want Ota to choose the host port",
                ),
            ];
            next_steps.extend(rerun_commands.iter().map(|rerun_command| {
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target(rerun_command, resolved_path)
                    ))
                )
            }));
            return Some(structured_field_error_text(
                command,
                &text_path_display,
                &field,
                "Invalid contract",
                &why_lines,
                &next_steps,
            ));
        }
        RuntimeProjectionIssueKind::FixedBindPortValueMissing => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.value");
            let why_lines = vec![format!(
                "task `{task_name}` listener `{listener_name}` with `bind.port.mode: fixed` must declare `bind.port.value`"
            )];
            let mut next_steps = vec![format!(
                "set `bind.port.value` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
            )];
            next_steps.extend(rerun_commands.iter().map(|rerun_command| {
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target(rerun_command, resolved_path)
                    ))
                )
            }));
            return Some(structured_field_error_text(
                command,
                &text_path_display,
                &field,
                "Invalid contract",
                &why_lines,
                &next_steps,
            ));
        }
        RuntimeProjectionIssueKind::FixedHostPortValueMissing => {
            let field = format!(
                "tasks.{task_name}.runtime.listeners.{listener_name}.project.host.port.value"
            );
            let why_lines = vec![String::from(
                "`project.host.port.mode: fixed` requires `project.host.port.value`",
            )];
            let mut next_steps = vec![format!(
                "set `project.host.port.value` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
            )];
            next_steps.push(String::from("or change `project.host.port.mode` to `auto`"));
            next_steps.extend(rerun_commands.iter().map(|rerun_command| {
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target(rerun_command, resolved_path)
                    ))
                )
            }));
            return Some(structured_field_error_text(
                command,
                &text_path_display,
                &field,
                "Invalid contract",
                &why_lines,
                &next_steps,
            ));
        }
    }
}

fn render_run_contract_problem_failure(
    resolved_path: &Path,
    member: Option<&str>,
    task_name: &str,
    error: ContractProblem,
) -> RunCommandFailure {
    let message = match &error {
        ContractProblem::Validation(errors) => {
            render_run_preferred_backend_validation_text(resolved_path, member, task_name, errors)
                .or_else(|| {
                    render_run_runtime_validation_text(resolved_path, member, task_name, errors)
                })
                .unwrap_or_else(|| {
                    invalid_repo_contract_output(
                        "RUN",
                        resolved_path,
                        &errors
                            .errors()
                            .iter()
                            .map(ToString::to_string)
                            .collect::<Vec<_>>(),
                        vec![
                            format!(
                                "repair {}",
                                paint_code(&format!("`{}`", compact_contract_path(resolved_path)))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target("ota validate", resolved_path)
                                ))
                            ),
                            task_use_details_step(Some(resolved_path), member),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    match member {
                                        Some(member) => {
                                            format!("ota run --member {member} {task_name}")
                                        }
                                        None => format!("ota run {task_name}"),
                                    }
                                ))
                            ),
                        ],
                        OutputFormat::Text,
                    )
                    .stdout
                })
        }
        ContractProblem::Load(load_error) => repo_contract_load_text(
            "RUN",
            resolved_path,
            "Contract could not be loaded",
            &load_error.to_string(),
            &[
                format!(
                    "repair {}",
                    paint_code(&format!("`{}`", compact_contract_path(resolved_path)))
                ),
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target("ota validate", resolved_path)
                    ))
                ),
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        match member {
                            Some(member) => format!("ota run --member {member} {task_name}"),
                            None => format!("ota run {task_name}"),
                        }
                    ))
                ),
            ],
        ),
    };

    RunCommandFailure {
        message,
        summary: None,
        exit_code: 1,
        receipt: None,
    }
}

fn validate_declared_monorepo_members(path: &Path) -> Result<(), Vec<String>> {
    let root_contract = match load_contract(path) {
        Ok(contract) => contract,
        Err(LoadContractError::Parse { .. }) => return Ok(()),
        Err(error) => return Err(vec![error.to_string()]),
    };

    let Some(workspace) = root_contract.workspace.as_ref() else {
        return Ok(());
    };

    let mut errors = Vec::new();
    for member in &workspace.members {
        match load_contract_for_member(path, member) {
            Ok((contract, contract_path)) => {
                if let Err(validation_errors) =
                    validate_contract_with_path(&contract, Some(&contract_path))
                {
                    for error in validation_errors.errors() {
                        errors.push(format!("monorepo member `{member}`: {error}"));
                    }
                }
            }
            Err(error) => errors.push(format!("monorepo member `{member}`: {error}")),
        }
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}

fn render_up_text(
    path: &str,
    status: &str,
    phase: &str,
    report: DoctorReport,
    ready: bool,
    backend: Option<&str>,
    service: Option<&str>,
    service_command: Option<&str>,
    task: Option<&str>,
    task_command: Option<&str>,
    stderr: Option<&str>,
    exit_code: Option<i32>,
    receipt: &ExecutionReceipt,
    show_receipt: bool,
) -> CommandOutput {
    let receipt = normalized_up_receipt(
        member_from_display_contract_target(path),
        status,
        phase,
        &report.findings,
        stderr,
        receipt,
    );
    let cause = primary_up_failure_cause(
        status,
        phase,
        &report.findings,
        backend,
        stderr,
        service,
        task,
    );
    let mut stdout = render_up_section_body(
        path,
        Some(Path::new(path)),
        status,
        phase,
        &report,
        backend,
        service,
        service_command,
        task,
        task_command,
        stderr,
        exit_code,
        &receipt,
        cause,
    );
    if show_receipt {
        stdout.push_str(&render_execution_receipt_text(&receipt));
    }
    stdout.push_str("\n\n");
    stdout.push_str(&render_up_summary_block(
        &receipt,
        task.or(Some(phase)),
        "UP SUMMARY",
        cause,
    ));
    append_receipt_next_block(&mut stdout, &receipt);

    CommandOutput {
        stdout,
        stderr: None,
        exit_code: exit_code.unwrap_or(if ready { 0 } else { 1 }),
    }
}

fn render_up_section(path: &str, result: &RepoUpResult) -> String {
    if let Some(preview) = result.preview.as_ref() {
        return render_up_preview_text(
            path,
            &preview.summary,
            &preview.contract_identity,
            &preview.execution,
            &preview.plan,
        );
    }

    render_up_section_body(
        path,
        Some(Path::new(path)),
        result.status,
        result.phase,
        &result.report,
        result.receipt.backend.as_deref(),
        result.service.as_deref(),
        result.service_command.as_deref(),
        result.task.as_deref(),
        result.task_command.as_deref(),
        phase_output_text(&result.stdout, &result.stderr).as_deref(),
        result.exit_code,
        &result.receipt,
        primary_up_failure_cause(
            result.status,
            result.phase,
            &result.report.findings,
            result.receipt.backend.as_deref(),
            phase_output_text(&result.stdout, &result.stderr).as_deref(),
            result.service.as_deref(),
            result.task.as_deref(),
        ),
    )
}

fn render_up_section_body(
    path: &str,
    contract_path: Option<&Path>,
    status: &str,
    phase: &str,
    report: &DoctorReport,
    backend: Option<&str>,
    service: Option<&str>,
    service_command: Option<&str>,
    task: Option<&str>,
    task_command: Option<&str>,
    stderr: Option<&str>,
    exit_code: Option<i32>,
    receipt: &ExecutionReceipt,
    cause: Option<UpFailureCause>,
) -> String {
    if status == "BLOCKED" && phase == "provisioning" {
        return render_up_blocked_provisioning_section(path, contract_path, report, receipt, task);
    }

    if matches!(cause, Some(UpFailureCause::BackendStartup)) {
        return render_up_backend_startup_failure_section(
            path,
            contract_path,
            phase,
            report,
            backend,
            receipt.context.as_deref(),
            stderr,
            exit_code,
            receipt,
        );
    }

    render_up_section_from_parts(
        path,
        contract_path,
        status,
        phase,
        report,
        backend,
        receipt.context.as_deref(),
        service,
        service_command,
        task,
        task_command,
        stderr,
        exit_code,
    )
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum UpFailureCause {
    BackendStartup,
    Provisioning,
    MissingRuntimeTool,
    ServiceReadiness,
    RepoSetup,
    Preconditions,
}

fn up_failure_cause_key(cause: UpFailureCause) -> &'static str {
    match cause {
        UpFailureCause::BackendStartup => "backend_startup",
        UpFailureCause::Provisioning => "provisioning",
        UpFailureCause::MissingRuntimeTool => "missing_runtime_tool",
        UpFailureCause::ServiceReadiness => "service_readiness",
        UpFailureCause::RepoSetup => "repo_setup",
        UpFailureCause::Preconditions => "preconditions",
    }
}

fn up_failure_cause_label(cause: UpFailureCause) -> &'static str {
    match cause {
        UpFailureCause::BackendStartup => "backend startup",
        UpFailureCause::Provisioning => "provisioning",
        UpFailureCause::MissingRuntimeTool => "missing runtime/tool",
        UpFailureCause::ServiceReadiness => "service readiness",
        UpFailureCause::RepoSetup => "repo setup",
        UpFailureCause::Preconditions => "preconditions",
    }
}

fn primary_up_failure_cause(
    status: &str,
    phase: &str,
    findings: &[Finding],
    backend: Option<&str>,
    stderr: Option<&str>,
    service: Option<&str>,
    task: Option<&str>,
) -> Option<UpFailureCause> {
    if backend_output_indicates_backend_startup_issue(backend, stderr) {
        if status == "PROVISION FAILED" && phase == "provisioning" {
            return Some(UpFailureCause::BackendStartup);
        }
        if matches!(phase, "setup" | "task" | "services") || task.is_some() || service.is_some() {
            return Some(UpFailureCause::BackendStartup);
        }
    }

    if status == "PROVISION FAILED" && phase == "provisioning" {
        return Some(UpFailureCause::Provisioning);
    }

    if findings.iter().any(|finding| {
        finding.severity == FindingSeverity::Error
            && is_missing_runtime_or_tool_finding(finding.summary.as_str())
    }) {
        return Some(UpFailureCause::MissingRuntimeTool);
    }

    if findings.iter().any(|finding| {
        finding.severity == FindingSeverity::Error
            && finding.summary.starts_with("Service readiness failed")
    }) {
        return Some(UpFailureCause::ServiceReadiness);
    }

    if matches!(status, "BLOCKED" | "NOT READY") || phase == "preconditions" {
        return Some(UpFailureCause::Preconditions);
    }

    if service.is_some() || task.is_some() || phase == "task" {
        if status != "READY" {
            return Some(UpFailureCause::RepoSetup);
        }
    }

    None
}

fn is_missing_runtime_or_tool_finding(summary: &str) -> bool {
    summary.starts_with("Tool probe failed: ")
        || summary.starts_with("Runtime probe failed: ")
        || summary.starts_with("Version mismatch for runtime: ")
        || summary.starts_with("Version mismatch for tool: ")
}

fn backend_output_indicates_backend_startup_issue(
    backend: Option<&str>,
    stderr: Option<&str>,
) -> bool {
    match backend {
        Some("container") | Some("remote") => {}
        _ => return false,
    }
    let Some(stderr) = stderr else {
        return false;
    };
    let lowered = stderr.to_ascii_lowercase();
    (lowered.contains("failed to set up container networking")
        || lowered.contains("failed to start containers")
        || (lowered.contains("network") && lowered.contains("not found")))
        && (lowered.contains("container")
            || lowered.contains("docker")
            || lowered.contains("network"))
}

fn backend_startup_why_lines(stderr: &str) -> Vec<String> {
    stderr
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .filter(|line| !looks_like_unlabeled_runtime_noise(line))
        .take(4)
        .map(str::to_string)
        .collect()
}

fn looks_like_unlabeled_runtime_noise(line: &str) -> bool {
    if line.starts_with("docker:")
        || line.starts_with("container ")
        || line.starts_with("failed ")
        || line.starts_with("Error response")
        || line.starts_with("Run '")
    {
        return false;
    }

    line.len() >= 32 && line.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn render_up_backend_startup_failure_section(
    path: &str,
    contract_path: Option<&Path>,
    phase: &str,
    report: &DoctorReport,
    backend: Option<&str>,
    context: Option<&str>,
    stderr: Option<&str>,
    exit_code: Option<i32>,
    receipt: &ExecutionReceipt,
) -> String {
    let mut stdout = format!(
        "{}\n\n{}\n{} {}",
        format_command_header("UP", path),
        render_status_line("BACKEND STARTUP FAILED"),
        paint_key("Phase:"),
        phase
    );

    if let Some(backend) = backend {
        stdout.push_str(&format!("\n{} {backend}", paint_key("Backend:")));
    }
    if let Some(context) = context {
        stdout.push_str(&format!("\n{} {context}", paint_key("Context:")));
    }
    if let Some(target) = receipt.target.as_deref() {
        let label = if receipt.backend.as_deref() == Some("container") {
            "Container:"
        } else {
            "Target:"
        };
        stdout.push_str(&format!("\n{} {target}", paint_key(label)));
    }
    if let Some(image) = receipt.image.as_deref() {
        stdout.push_str(&format!("\n{} {image}", paint_key("Image:")));
    }
    if let Some(exit_code) = exit_code {
        stdout.push_str(&format!("\n{} {exit_code}", paint_key("Exit code:")));
    }

    let mut why_lines = Vec::new();
    if let Some(target) = receipt.target.as_deref() {
        why_lines.push(format!(
            "persistent container `{target}` could not start or attach to the required container runtime surface"
        ));
    } else {
        why_lines.push(String::from(
            "the selected execution backend could not start the required runtime surface for `ota up`",
        ));
    }
    if let Some(stderr) = stderr {
        why_lines.extend(backend_startup_why_lines(stderr));
    }
    append_error_detail_section(&mut stdout, "Why:", &why_lines, contract_path);

    let mut next_steps = Vec::new();
    if let Some(contract_path) = contract_path {
        let member = member_from_display_contract_target(path);
        let command = repo_execution_plan_command(
            contract_path,
            member,
            match backend {
                Some("remote") => Backend::Remote,
                _ => Backend::Container,
            },
        );
        next_steps.push(format!(
            "run {} to inspect the selected execution path before changing execution settings",
            paint_code(&format!("`{command}`"))
        ));
    }
    if stderr
        .map(|text| {
            let lowered = text.to_ascii_lowercase();
            lowered.contains("network") && lowered.contains("not found")
        })
        .unwrap_or(false)
    {
        next_steps.push(String::from(
            "repair the missing compose/runtime network attachment, then rerun `ota up`",
        ));
    } else {
        next_steps.push(String::from(
            "repair the container backend startup state, then rerun `ota up`",
        ));
    }
    next_steps.push(String::from(
        "verify the container runtime and required compose attachments are healthy",
    ));
    append_error_detail_section(&mut stdout, "Next:", &next_steps, contract_path);

    let secondary_findings = report
        .findings
        .iter()
        .filter(|finding| {
            !(finding.severity == FindingSeverity::Error
                && finding.summary.starts_with("Service readiness failed"))
        })
        .collect::<Vec<_>>();
    if !secondary_findings.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_key("Also detected:")));
        for finding in secondary_findings {
            stdout.push_str(&format!(
                "\n\n{}  {}",
                render_severity(finding.severity),
                paint(&finding.summary, "1;37")
            ));
            let why_lines = finding_why_lines(&finding.summary, &finding.why, None);
            let next_steps = finding_next_steps(&finding.next);
            append_error_detail_section(&mut stdout, "Why:", &why_lines, contract_path);
            append_error_detail_section(&mut stdout, "Next:", &next_steps, contract_path);
        }
    }

    stdout
}

fn render_up_summary_block(
    receipt: &ExecutionReceipt,
    task: Option<&str>,
    title: &str,
    cause: Option<UpFailureCause>,
) -> String {
    let rendered = render_execution_receipt_summary_block(receipt, task, title);
    let Some(cause) = cause else {
        return rendered;
    };
    let insertion = summary_detail_line("Cause:", up_failure_cause_label(cause));
    if let Some(index) = rendered.find("\nNote:") {
        let mut summary = String::with_capacity(rendered.len() + insertion.len() + 1);
        summary.push_str(&rendered[..index]);
        summary.push('\n');
        summary.push_str(&insertion);
        summary.push_str(&rendered[index..]);
        summary
    } else {
        format!("{rendered}\n{insertion}")
    }
}

fn render_up_blocked_provisioning_section(
    path: &str,
    contract_path: Option<&Path>,
    report: &DoctorReport,
    receipt: &ExecutionReceipt,
    task: Option<&str>,
) -> String {
    let mut stdout = format!(
        "{}\n\n{}\n{} provisioning",
        format_command_header("UP", path),
        render_status_line("BLOCKED"),
        paint_key("Phase:")
    );

    if let Some(backend) = receipt.backend.as_deref() {
        stdout.push_str(&format!("\n{} {backend}", paint_key("Backend:")));
    }
    if let Some(context) = receipt.context.as_deref() {
        stdout.push_str(&format!("\n{} {context}", paint_key("Context:")));
    }
    if let Some(task) = task {
        stdout.push_str(&format!("\n{} {task}", paint_key("Task:")));
    }
    if let Some(image) = receipt.image.as_deref() {
        stdout.push_str(&format!("\n{} {image}", paint_key("Image:")));
    }

    if let Some(primary) = report
        .findings
        .iter()
        .find(|finding| finding.severity == FindingSeverity::Error)
    {
        if primary.summary == "Container execution is not configured" {
            let where_value = contract_path
                .map(compact_contract_path)
                .unwrap_or_else(|| path.to_string());
            let why_lines = vec![
                String::from(
                    "container-backed provisioning requires `execution.backends.container.image` so Ota can provision and run setup inside the execution image instead of on the host",
                ),
                String::from("this contract does not declare `execution.backends.container.image`"),
            ];
            let mut next_steps = Vec::new();
            if let Some(contract_path) = contract_path {
                let member = member_from_display_contract_target(path);
                let command =
                    repo_execution_plan_command(contract_path, member, Backend::Container);
                next_steps.push(format!(
                    "run {} to inspect the selected execution path before changing the contract",
                    paint_code(&format!("`{command}`"))
                ));
            }
            next_steps.extend([
                String::from("set `execution.backends.container.image` in the repo contract"),
                String::from("rerun `ota up`"),
            ]);
            stdout.push_str(&format!(
                "\n\n{}  {}",
                render_severity(FindingSeverity::Error),
                paint("Invalid contract", "1;37")
            ));
            stdout.push_str(&format!(
                "\n{} {}",
                paint_key("Where:"),
                paint_code(&where_value)
            ));
            stdout.push_str(&format!(
                "\n{} {}",
                paint_key("Field:"),
                paint_code("execution.backends.container.image")
            ));
            append_error_detail_section(&mut stdout, "Why:", &why_lines, contract_path);
            append_error_detail_section(&mut stdout, "Next:", &next_steps, contract_path);
        } else {
            let doctor_mode = doctor_mode_from_backend(receipt.backend.as_deref());
            let doctor_lifecycle = lifecycle_from_display_value(receipt.lifecycle.as_deref());
            let (display_why, display_next, container_image) =
                render_container_image_finding_text(&primary.why, &primary.next, doctor_mode);
            let why_lines =
                finding_why_lines(&primary.summary, &display_why, container_image.as_deref());
            let mut next_steps = finding_next_steps(&rewrite_doctor_mode_command(
                &display_next,
                doctor_mode,
                doctor_lifecycle,
            ));
            if let Some(contract_path) = contract_path
                && matches!(receipt.backend.as_deref(), Some("container" | "remote"))
                && !next_steps
                    .iter()
                    .any(|step| step.contains("ota execution plan"))
            {
                let member = member_from_display_contract_target(path);
                let command = repo_execution_plan_command(
                    contract_path,
                    member,
                    if receipt.backend.as_deref() == Some("remote") {
                        Backend::Remote
                    } else {
                        Backend::Container
                    },
                );
                next_steps.insert(
                    0,
                    format!(
                        "run {} to inspect the selected execution path before changing execution settings",
                        paint_code(&format!("`{command}`"))
                    ),
                );
            }
            stdout.push('\n');
            append_error_detail_section(&mut stdout, "Why:", &why_lines, contract_path);
            append_error_detail_section(&mut stdout, "Next:", &next_steps, contract_path);
        }
    }

    let context = blocked_provisioning_context_lines(&report.findings);
    if !context.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_key("Additional context:")));
        for item in context {
            stdout.push_str(&format!(
                "\n  {} {}",
                finding_detail_bullet(FindingSeverity::Info),
                render_backticked_text(&item, contract_path)
            ));
        }
    }

    stdout
}

fn blocked_provisioning_context_lines(findings: &[Finding]) -> Vec<String> {
    let mut lines = Vec::new();

    if findings
        .iter()
        .any(|finding| finding.summary == "Container readiness does not include host-only checks")
    {
        lines.push(String::from(
            "container readiness excludes host-only checks",
        ));
    }

    if findings.iter().any(|finding| {
        matches!(
            finding.summary.as_str(),
            "Policy-backed version rules are declared"
                | "Policy-backed provisioning sources are declared"
                | "Adapter bootstrap sources are declared"
        )
    }) {
        lines.push(String::from(
            "an active policy pack still governs version and provisioning rules",
        ));
    }

    lines
}

fn render_up_section_with_receipt(path: &str, result: &RepoUpResult, show_receipt: bool) -> String {
    if result.preview.is_some() {
        return render_up_section(path, result);
    }

    let mut stdout = render_up_section(path, result);
    if show_receipt {
        stdout.push_str(&render_execution_receipt_text(&result.receipt));
    }
    stdout.push('\n');
    stdout.push_str(&render_execution_receipt_summary_block(
        &result.receipt,
        result.task.as_deref().or(Some(result.phase)),
        "UP SUMMARY",
    ));
    append_receipt_next_block(&mut stdout, &result.receipt);
    stdout
}

fn write_proof_artifact(path: &Path, content: &str) -> Result<(), String> {
    fs::write(path, content).map_err(|error| {
        format!(
            "failed to write proof artifact `{}`: {error}",
            compact_path(path, ".")
        )
    })
}

fn proof_runtime_artifact_dir(
    repo_root: &Path,
    member: Option<&str>,
    workflow: Option<&str>,
) -> PathBuf {
    let mut dir = repo_root.join(".ota").join("proof");
    if let Some(member) = member {
        dir.push(proof_runtime_artifact_segment(member));
    }
    dir.push(proof_runtime_artifact_segment(
        workflow.unwrap_or("default-task-path"),
    ));
    dir
}

fn proof_runtime_artifact_segment(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
            out.push(ch);
        } else {
            out.push('-');
        }
    }
    if out.is_empty() {
        String::from("default")
    } else {
        out
    }
}

fn spawn_proof_runtime_up_process(
    contract_path: &Path,
    workflow_name: Option<&str>,
    member: Option<&str>,
    file_override: Option<&Path>,
    overrides: ExecutionOverrides,
    up_log_artifact_path: &Path,
) -> Result<std::process::Child, String> {
    let exe = env::current_exe().map_err(|error| {
        format!("could not resolve the current ota executable for runtime proof: {error}")
    })?;
    let working_dir = contract_working_dir(contract_path);
    let stdout_log = File::create(up_log_artifact_path)
        .map_err(|error| format!("could not create proof up log artifact: {error}"))?;
    let stderr_log = stdout_log
        .try_clone()
        .map_err(|error| format!("could not prepare proof up log stream: {error}"))?;

    let mut command = Command::new(exe);
    command.current_dir(working_dir).arg("up").arg("--stream");
    command.envs(runtime_proof_child_env());

    if let Some(backend) = overrides.backend {
        command.arg("--mode").arg(match backend {
            Backend::Native => "native",
            Backend::Container => "container",
            Backend::Remote => "remote",
        });
    }
    if let Some(lifecycle) = overrides.lifecycle {
        command.arg("--lifecycle").arg(match lifecycle {
            Lifecycle::Persistent => "persistent",
            Lifecycle::Ephemeral => "ephemeral",
        });
    }
    if let Some(host_port) = overrides.host_port {
        command.arg("--host-port").arg(host_port.to_string());
    }
    if let Some(memory) = overrides.memory {
        command.arg("--memory").arg(memory.to_string());
    }
    if overrides.skip_deps {
        command.arg("--skip-deps");
    }
    if let Some(workflow_name) = workflow_name {
        command.arg("--workflow").arg(workflow_name);
    }
    if let Some(member) = member {
        command.arg("--member").arg(member);
    }
    if let Some(file_override) = file_override {
        command.env("OTA_FILE", file_override);
    }
    command
        .arg(".")
        .stdin(Stdio::null())
        .stdout(Stdio::from(stdout_log))
        .stderr(Stdio::from(stderr_log));

    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;
        command.process_group(0);
    }

    command
        .spawn()
        .map_err(|error| format!("could not start `ota up --stream` for runtime proof: {error}"))
}

fn runtime_proof_child_env() -> BTreeMap<OsString, OsString> {
    let mut selected = BTreeMap::new();
    for key in [
        "PATH",
        "HOME",
        "USERPROFILE",
        "SystemRoot",
        "ComSpec",
        "PATHEXT",
        "LD_LIBRARY_PATH",
        "PKG_CONFIG_PATH",
        "pythonLocation",
        "Python_ROOT_DIR",
        "Python2_ROOT_DIR",
        "Python3_ROOT_DIR",
        "UV_CACHE_DIR",
        "OTA_PYTHON_BIN_DIR",
        "OTA_UV_BIN_DIR",
        "OTA_NODE_BIN_DIR",
        "OTA_NPM_BIN_DIR",
    ] {
        if let Some(value) = env::var_os(key) {
            selected.insert(OsString::from(key), value);
        }
    }
    for (name, value) in env::vars_os() {
        if name
            .to_str()
            .is_some_and(|name| name.starts_with("OTA_") || name.starts_with("NPM_CONFIG_"))
        {
            selected.entry(name).or_insert(value);
        }
    }
    selected
}

fn spawn_up_detached_run_process(
    contract_path: &Path,
    task_name: &str,
    skip_deps: bool,
    overrides: ExecutionOverrides,
    policy_env: Option<&BTreeMap<String, String>>,
    run_log_artifact_path: &Path,
    keep_stdin_open: bool,
) -> Result<std::process::Child, String> {
    let exe = env::current_exe().map_err(|error| {
        format!("could not resolve the current ota executable for detached up run: {error}")
    })?;
    let working_dir = contract_working_dir(contract_path);
    let stdout_log = File::create(run_log_artifact_path)
        .map_err(|error| format!("could not create detached up run log artifact: {error}"))?;
    let stderr_log = stdout_log
        .try_clone()
        .map_err(|error| format!("could not prepare detached up run log stream: {error}"))?;

    let mut command = Command::new(exe);
    command
        .current_dir(working_dir)
        .env("OTA_FILE", contract_path)
        .env(
            "OTA_ACTIVE_EXECUTION_PARENT_PID",
            std::process::id().to_string(),
        )
        .arg("run")
        .arg(task_name)
        .arg("--stream");

    if skip_deps {
        command.arg("--skip-deps");
    }

    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;
        command.process_group(0);
    }

    if let Some(backend) = overrides.backend {
        command.arg("--mode").arg(match backend {
            Backend::Native => "native",
            Backend::Container => "container",
            Backend::Remote => "remote",
        });
    }
    if let Some(lifecycle) = overrides.lifecycle {
        command.arg("--lifecycle").arg(match lifecycle {
            Lifecycle::Persistent => "persistent",
            Lifecycle::Ephemeral => "ephemeral",
        });
    }
    if let Some(host_port) = overrides.host_port {
        command.arg("--host-port").arg(host_port.to_string());
    }
    if let Some(memory) = overrides.memory {
        command.arg("--memory").arg(memory.to_string());
    }
    if let Some(policy_env) = policy_env {
        command.envs(policy_env.iter());
    }

    command.arg(".");
    if keep_stdin_open {
        command.stdin(Stdio::inherit());
    } else {
        command.stdin(Stdio::null());
    }
    command
        .stdout(Stdio::from(stdout_log))
        .stderr(Stdio::from(stderr_log));

    command
        .spawn()
        .map_err(|error| format!("could not start detached `ota run {task_name}`: {error}"))
}

#[derive(Debug, Clone)]
enum ProofRuntimeReadinessStrategy {
    LightweightTargets(Vec<HostRuntimeReadinessProbe>),
    FullDiagnosis,
}

fn proof_runtime_readiness_strategy(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> ProofRuntimeReadinessStrategy {
    match proof_runtime_readiness_targets(contract, contract_path, workflow_name, overrides) {
        Ok(targets) if !targets.is_empty() => {
            ProofRuntimeReadinessStrategy::LightweightTargets(targets)
        }
        Ok(_) | Err(_) => ProofRuntimeReadinessStrategy::FullDiagnosis,
    }
}

fn proof_runtime_readiness_targets(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> Result<Vec<HostRuntimeReadinessProbe>, String> {
    let Some((_, workflow)) = contract.selected_workflow(workflow_name) else {
        return Ok(Vec::new());
    };

    let mut targets = Vec::new();
    if !workflow.readiness.surfaces.is_empty() {
        let run_task_name = workflow
            .run
            .as_ref()
            .map(|run| run.task.as_str())
            .ok_or_else(|| String::from("selected workflow does not declare `run.task`"))?;
        let task = contract
            .tasks
            .get(run_task_name)
            .ok_or_else(|| format!("workflow run task `{run_task_name}` is not declared"))?;
        let backend = match resolve_execution_backend_with_contract_path(
            contract,
            run_task_name,
            overrides,
            Some(contract_path),
        )
        .map_err(|error| error.to_string())?
        {
            ResolvedExecutionBackend::Native { .. } => Backend::Native,
            ResolvedExecutionBackend::Container { .. } => Backend::Container,
            ResolvedExecutionBackend::Remote { .. }
            | ResolvedExecutionBackend::BackendProvider { .. } => Backend::Remote,
        };
        for surface_name in &workflow.readiness.surfaces {
            targets.push(task_surface_host_readiness_probe_for_backend(
                contract,
                task,
                backend,
                surface_name,
            )?);
        }
    }

    for probe_name in &workflow.readiness.probes {
        let target = match resolve_named_readiness_probe(contract, probe_name)? {
            ResolvedNamedReadinessProbe::Http {
                address,
                port,
                request,
                timeout,
                ..
            } => HostRuntimeReadinessProbe {
                listener: probe_name.clone(),
                protocol: TaskRuntimeProtocol::Http,
                address,
                port,
                request: Some(request),
                default_timeout: timeout,
                budget_hint: None,
            },
            ResolvedNamedReadinessProbe::Tcp {
                address,
                port,
                timeout,
                ..
            } => HostRuntimeReadinessProbe {
                listener: probe_name.clone(),
                protocol: TaskRuntimeProtocol::Tcp,
                address,
                port,
                request: None,
                default_timeout: timeout,
                budget_hint: None,
            },
        };
        targets.push(target);
    }

    Ok(targets)
}

fn proof_runtime_readiness_targets_observed(targets: &[HostRuntimeReadinessProbe]) -> bool {
    targets
        .iter()
        .all(|target| host_runtime_readiness_observed(target, None))
}

const PROOF_RUNTIME_READINESS_WAIT_FLOOR_SECS: u64 = 180;
const PROOF_RUNTIME_READINESS_WAIT_CEILING_SECS: u64 = 900;
const PROOF_RUNTIME_READINESS_LOOP_INTERVAL_SECS: u64 = 2;
const PROOF_RUNTIME_READINESS_ATTEMPT_BUDGET: u64 = 30;
const PROOF_RUNTIME_READINESS_EXTRA_GRACE_SECS: u64 = 60;
const PROOF_RUNTIME_EXIT_OBSERVATION_GRACE_MILLIS: u64 = 250;
const PROOF_RUNTIME_FULL_DIAG_STARTUP_GRACE_MILLIS: u64 = 3_000;
static PROOF_RUNTIME_INTERRUPT_FLAG: OnceLock<Arc<AtomicBool>> = OnceLock::new();

fn proof_runtime_interrupt_flag() -> Arc<AtomicBool> {
    PROOF_RUNTIME_INTERRUPT_FLAG
        .get_or_init(|| {
            let interrupted = Arc::new(AtomicBool::new(false));
            #[cfg(unix)]
            {
                use signal_hook::consts::signal::{SIGHUP, SIGINT, SIGQUIT, SIGTERM};
                for signal in [SIGINT, SIGTERM, SIGHUP, SIGQUIT] {
                    let _ = signal_hook::flag::register(signal, Arc::clone(&interrupted));
                }
            }
            #[cfg(windows)]
            {
                use signal_hook::consts::SIGINT;
                let _ = signal_hook::flag::register(SIGINT, Arc::clone(&interrupted));
            }
            interrupted
        })
        .clone()
}

fn proof_runtime_wait_budget(readiness_strategy: &ProofRuntimeReadinessStrategy) -> Duration {
    let floor = Duration::from_secs(PROOF_RUNTIME_READINESS_WAIT_FLOOR_SECS);
    let ceiling = Duration::from_secs(PROOF_RUNTIME_READINESS_WAIT_CEILING_SECS);
    let computed = match readiness_strategy {
        ProofRuntimeReadinessStrategy::LightweightTargets(targets) if !targets.is_empty() => {
            let max_target_budget = targets
                .iter()
                .filter_map(|target| {
                    target.budget_hint.or_else(|| {
                        target.default_timeout.map(|timeout| {
                            let timeout_secs = timeout.as_secs().max(1);
                            Duration::from_secs(
                                timeout_secs
                                    .saturating_mul(PROOF_RUNTIME_READINESS_ATTEMPT_BUDGET)
                                    .saturating_add(
                                        PROOF_RUNTIME_READINESS_LOOP_INTERVAL_SECS
                                            * PROOF_RUNTIME_READINESS_ATTEMPT_BUDGET,
                                    ),
                            )
                        })
                    })
                })
                .max()
                .unwrap_or(Duration::from_millis(200));
            max_target_budget.saturating_add(Duration::from_secs(
                PROOF_RUNTIME_READINESS_EXTRA_GRACE_SECS,
            ))
        }
        _ => floor,
    };
    computed.max(floor).min(ceiling)
}

fn proof_runtime_doctor_report(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    doctor_mode: DoctorMode,
    overrides: ExecutionOverrides,
) -> DoctorReport {
    diagnose_contract_with_mode_and_lifecycle_for_workflow_with_overrides(
        contract,
        contract_path,
        doctor_mode,
        overrides.lifecycle,
        workflow_name,
        overrides,
    )
}

fn proof_runtime_doctor_artifact_json(
    contract: &Contract,
    contract_path: &Path,
    path_display: &str,
    workflow_name: Option<&str>,
    doctor_mode: DoctorMode,
    overrides: ExecutionOverrides,
    report: &DoctorReport,
    summary: &DoctorSummary,
    likely_cause: Option<&ProofRuntimeLikelyCause>,
) -> Result<String, String> {
    let rewritten_findings = rewrite_doctor_findings_for_contract(
        &report.findings,
        contract_path,
        Some(doctor_mode),
        None,
    );
    let refined_findings = proof_runtime_refined_doctor_findings(rewritten_findings, likely_cause);
    let refined_summary = proof_runtime_refined_doctor_summary(summary, likely_cause);
    let workflow_summary =
        resolve_selected_workflow_summary(contract, contract_path, workflow_name)?;
    let agent_summary = contract.agent.as_ref().and_then(AgentSummary::from_config);
    let required_env_names = contract.selected_workflow_required_env_names(workflow_name);
    let execution_summary = ExecutionSummary::from_contract_with_required_env_names(
        contract,
        contract_path,
        (!required_env_names.is_empty()).then_some(&required_env_names),
    );
    let selected_toolchains = selected_workflow_toolchain_summaries(
        contract,
        overrides,
        workflow_name,
        toolchain_summary_backend_for_mode(doctor_mode),
    );

    Ok(to_json(&DoctorSuccess {
        ok: report.ok,
        path: path_display,
        mode: doctor_mode.as_str(),
        summary: refined_summary,
        finding_groups: doctor_finding_group_summaries(&refined_findings, Some(doctor_mode), None),
        workflow: workflow_summary,
        agent: agent_summary,
        execution: execution_summary,
        provisioning: report.provisioning.as_ref().map(|value| &value.plan),
        provisioning_request: report.provisioning.as_ref().map(|value| &value.request),
        adapter_bootstrap: report.adapter_bootstrap.as_ref(),
        extensions: &contract.extensions,
        fix: None,
        toolchains: selected_toolchains,
        findings: &refined_findings,
    }))
}

fn proof_runtime_refined_doctor_summary(
    summary: &DoctorSummary,
    likely_cause: Option<&ProofRuntimeLikelyCause>,
) -> DoctorSummary {
    let mut refined = summary.clone();
    let Some(replacement) = likely_cause.and_then(proof_runtime_refined_run_exit_finding) else {
        return refined;
    };
    if let Some(primary) = refined.primary_blocker.as_mut() {
        primary.summary = replacement.summary.clone();
        primary.why = replacement.why.clone();
        primary.next = replacement.next.clone();
        primary.code = replacement
            .identity
            .as_ref()
            .map(|identity| identity.code.clone());
        primary.provenance = Some(String::from("host"));
        primary.provenance_key = Some(String::from("repo_contract"));
    }
    refined
}

fn proof_runtime_refined_doctor_findings(
    findings: Vec<Finding>,
    likely_cause: Option<&ProofRuntimeLikelyCause>,
) -> Vec<Finding> {
    let Some(replacement) = likely_cause.and_then(proof_runtime_refined_run_exit_finding) else {
        return findings;
    };
    findings
        .into_iter()
        .map(|finding| {
            if finding.summary == "Run task exited before readiness"
                || finding.code() == "OTA_WORKFLOW_SURFACE_READINESS_FAILED"
            {
                replacement.clone()
            } else {
                finding
            }
        })
        .collect()
}

fn proof_runtime_refined_run_exit_finding(
    likely_cause: &ProofRuntimeLikelyCause,
) -> Option<Finding> {
    match likely_cause {
        ProofRuntimeLikelyCause::ContainerEngineUnavailable {
            engine, details, ..
        } => Some(Finding::identified(
            "OTA_CONTAINER_BACKEND_UNAVAILABLE",
            "execution",
            "host",
            FindingSeverity::Error,
            format!("Container engine unavailable: {engine}"),
            format!(
                "the selected proof path could not reach a usable `{engine}` backend: {details}"
            ),
            "start or repair the selected container engine, then rerun `ota proof runtime`",
        )),
        _ => None,
    }
}

fn proof_runtime_likely_cause_redundant_with_primary_blocker(
    summary: &DoctorSummary,
    likely_cause: &ProofRuntimeLikelyCause,
) -> bool {
    let Some(primary) = summary.primary_blocker.as_ref() else {
        return false;
    };
    let Some(replacement) = proof_runtime_refined_run_exit_finding(likely_cause) else {
        return false;
    };
    primary.code.as_deref() == Some(replacement.code())
}

fn wait_for_proof_runtime_readiness(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    up_process: &mut std::process::Child,
    process_label: &str,
    up_log_artifact_path: &Path,
    wait_budget_override: Option<Duration>,
) -> Result<(DoctorReport, &'static str, bool, Option<String>), String> {
    let interrupted = proof_runtime_interrupt_flag();
    interrupted.store(false, Ordering::Relaxed);
    let doctor_mode = up_doctor_mode(contract, overrides, workflow_name);
    let readiness_strategy =
        proof_runtime_readiness_strategy(contract, contract_path, workflow_name, overrides);
    let deadline = Instant::now()
        + wait_budget_override.unwrap_or_else(|| proof_runtime_wait_budget(&readiness_strategy));
    let full_diagnosis_startup_deadline =
        Instant::now() + Duration::from_millis(PROOF_RUNTIME_FULL_DIAG_STARTUP_GRACE_MILLIS);
    let _agent_verdict = crate::workspace::agent_verdict_from_agent(contract.agent.as_ref());
    let mut deferred_service_run_exit_failure = None;
    let mut service_exit_grace_deadline = None;
    loop {
        if deferred_service_run_exit_failure.is_none() {
            match up_process.try_wait() {
                Ok(Some(exit_status)) => {
                    if let Some(terminal_failure) =
                        proof_runtime_terminal_failure_from_up_log(up_log_artifact_path)
                    {
                        return Ok((
                            proof_runtime_terminal_failure_report(
                                up_log_artifact_path,
                                terminal_failure.clone(),
                            ),
                            "run",
                            false,
                            Some(terminal_failure),
                        ));
                    }
                    let latest_report = proof_runtime_doctor_report(
                        contract,
                        contract_path,
                        workflow_name,
                        doctor_mode,
                        overrides.clone(),
                    );
                    let successful_service_run_exit = process_label.starts_with("ota run ")
                        && selected_up_run_task_is_service(contract, workflow_name, overrides)
                        && exit_status.success();
                    if successful_service_run_exit {
                        if latest_report.ok {
                            return Ok((latest_report, "readiness", true, None));
                        }
                        deferred_service_run_exit_failure = Some(
                            proof_runtime_process_exit_failure(process_label, exit_status),
                        );
                        // A successful service-launch command can exit long before the declared
                        // runtime reaches readiness (for example `docker compose up -d`).
                        // Keep probing until the workflow's actual readiness budget is exhausted
                        // instead of collapsing to a shorter post-exit grace window.
                        service_exit_grace_deadline = Some(deadline);
                    } else {
                        if exit_status.success() && latest_report.ok {
                            return Ok((latest_report, "readiness", true, None));
                        }
                        let up_process_failure = Some(proof_runtime_process_exit_failure(
                            process_label,
                            exit_status,
                        ));
                        return Ok((latest_report, "readiness", false, up_process_failure));
                    }
                }
                Ok(None) => {}
                Err(error) => {
                    return Err(format!(
                        "could not observe the runtime-proof `ota up --stream` process: {error}"
                    ));
                }
            }
        }

        if let ProofRuntimeReadinessStrategy::LightweightTargets(targets) = &readiness_strategy
            && proof_runtime_readiness_targets_observed(targets)
        {
            let latest_report = proof_runtime_doctor_report(
                contract,
                contract_path,
                workflow_name,
                doctor_mode,
                overrides.clone(),
            );
            if latest_report.ok {
                match up_process.try_wait() {
                    Ok(Some(exit_status)) => {
                        if exit_status.success() {
                            return Ok((latest_report, "readiness", true, None));
                        }
                        let up_process_failure = Some(proof_runtime_process_exit_failure(
                            process_label,
                            exit_status,
                        ));
                        return Ok((latest_report, "readiness", false, up_process_failure));
                    }
                    Ok(None) => {}
                    Err(error) => {
                        return Err(format!(
                            "could not observe the runtime-proof `ota up --stream` process: {error}"
                        ));
                    }
                }
                let grace_deadline = Instant::now()
                    + Duration::from_millis(PROOF_RUNTIME_EXIT_OBSERVATION_GRACE_MILLIS);
                loop {
                    if Instant::now() >= grace_deadline {
                        break;
                    }
                    match up_process.try_wait() {
                        Ok(Some(exit_status)) => {
                            if exit_status.success() {
                                return Ok((latest_report, "readiness", true, None));
                            }
                            let up_process_failure = Some(proof_runtime_process_exit_failure(
                                process_label,
                                exit_status,
                            ));
                            return Ok((latest_report, "readiness", false, up_process_failure));
                        }
                        Ok(None) => {
                            thread::sleep(Duration::from_millis(25));
                        }
                        Err(error) => {
                            return Err(format!(
                                "could not observe the runtime-proof `ota up --stream` process: {error}"
                            ));
                        }
                    }
                }
                return Ok((latest_report, "readiness", true, None));
            }
            return Ok((latest_report, "readiness", false, None));
        }

        let latest_report = if matches!(
            readiness_strategy,
            ProofRuntimeReadinessStrategy::FullDiagnosis
        ) {
            if let Some(terminal_failure) =
                proof_runtime_terminal_failure_from_up_log(up_log_artifact_path)
            {
                return Ok((
                    proof_runtime_terminal_failure_report(
                        up_log_artifact_path,
                        terminal_failure.clone(),
                    ),
                    "run",
                    false,
                    Some(terminal_failure),
                ));
            }
            if deferred_service_run_exit_failure.is_none()
                && Instant::now() < full_diagnosis_startup_deadline
            {
                thread::sleep(Duration::from_millis(100));
                continue;
            }
            let latest_report = proof_runtime_doctor_report(
                contract,
                contract_path,
                workflow_name,
                doctor_mode,
                overrides.clone(),
            );
            if latest_report.ok {
                match up_process.try_wait() {
                    Ok(Some(exit_status)) => {
                        if exit_status.success() {
                            return Ok((latest_report, "readiness", true, None));
                        }
                        let up_process_failure = Some(proof_runtime_process_exit_failure(
                            process_label,
                            exit_status,
                        ));
                        return Ok((latest_report, "readiness", false, up_process_failure));
                    }
                    Ok(None) => {}
                    Err(error) => {
                        return Err(format!(
                            "could not observe the runtime-proof `ota up --stream` process: {error}"
                        ));
                    }
                }
                return Ok((latest_report, "readiness", true, None));
            }
            Some(latest_report)
        } else {
            None
        };

        let finalize_report = |report: Option<DoctorReport>| {
            report.unwrap_or_else(|| {
                proof_runtime_doctor_report(
                    contract,
                    contract_path,
                    workflow_name,
                    doctor_mode,
                    overrides.clone(),
                )
            })
        };

        let now = Instant::now();
        if interrupted.load(Ordering::Relaxed) {
            return Ok((
                finalize_report(latest_report),
                "interrupted",
                false,
                deferred_service_run_exit_failure
                    .take()
                    .or_else(|| Some(String::from("runtime proof interrupted by signal"))),
            ));
        }
        let timed_out = now >= deadline
            || service_exit_grace_deadline.is_some_and(|grace_deadline| now >= grace_deadline);
        if timed_out {
            return Ok((
                finalize_report(latest_report),
                "readiness",
                false,
                deferred_service_run_exit_failure
                    .take()
                    .or_else(|| Some(String::from("timed out while waiting for readiness"))),
            ));
        }

        thread::sleep(Duration::from_secs(2));
    }
}

fn proof_runtime_process_exit_failure(
    process_label: &str,
    exit_status: std::process::ExitStatus,
) -> String {
    if let Some(code) = exit_status.code() {
        let mut why =
            format!("`{process_label}` exited while waiting for readiness (exit code {code})");
        if let Some(guidance) = windows_exit_code_guidance_line(code) {
            why.push_str("; ");
            why.push_str(guidance.as_str());
        }
        why
    } else {
        String::from(format!(
            "`{process_label}` was terminated before readiness could be observed"
        ))
    }
}

fn proof_runtime_terminal_failure_from_up_log(up_log_artifact_path: &Path) -> Option<String> {
    let log = fs::read_to_string(up_log_artifact_path).ok()?;
    for raw_line in log.lines() {
        let line = strip_ansi_codes(raw_line);
        let trimmed = line.trim();
        let Some(title) = trimmed
            .strip_prefix("◉ ERROR")
            .or_else(|| trimmed.strip_prefix("ERROR"))
        else {
            continue;
        };
        let title = title.trim();
        if title.is_empty() {
            return Some(String::from(
                "`ota up --stream` reported terminal failure before readiness",
            ));
        }
        return Some(format!(
            "`ota up --stream` reported terminal failure before readiness ({title})"
        ));
    }
    None
}

fn proof_runtime_terminal_failure_report(
    up_log_artifact_path: &Path,
    failure: String,
) -> DoctorReport {
    DoctorReport {
        ok: false,
        provisioning: None,
        adapter_bootstrap: None,
        execution_target: None,
        findings: vec![Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Run task exited before readiness"),
            why: failure,
            next: format!(
                "inspect {} and rerun `ota proof runtime`",
                compact_repo_path(up_log_artifact_path)
            ),
        }],
    }
}

fn stop_proof_runtime_up_process(up_process: &mut std::process::Child) -> Result<(), String> {
    #[cfg(unix)]
    let _ = signal_process_group(up_process.id(), "TERM");

    let deadline = Instant::now() + Duration::from_secs(10);
    loop {
        match up_process.try_wait() {
            Ok(Some(_)) => return Ok(()),
            Ok(None) if Instant::now() >= deadline => {
                #[cfg(unix)]
                let _ = signal_process_group(up_process.id(), "KILL");
                up_process.kill().map_err(|error| {
                    format!("could not stop runtime-proof `ota up` process: {error}")
                })?;
            }
            Ok(None) => thread::sleep(Duration::from_millis(100)),
            Err(error) => {
                return Err(format!(
                    "could not observe runtime-proof `ota up` process shutdown: {error}"
                ));
            }
        }
    }
}

#[cfg(unix)]
fn signal_process_group(process_id: u32, signal: &str) -> Result<(), String> {
    let target = proof_runtime_process_group_id(process_id)?.unwrap_or(process_id);
    let output = Command::new("kill")
        .arg(format!("-{signal}"))
        .arg(format!("-{target}"))
        .output()
        .map_err(|error| format!("could not signal runtime-proof process group: {error}"))?;
    if output.status.success() {
        return Ok(());
    }
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    if stderr.contains("No such process") {
        return Ok(());
    }
    if stderr.is_empty() {
        Err(format!(
            "could not signal runtime-proof process group with `kill -{signal} -{target}`"
        ))
    } else {
        Err(format!(
            "could not signal runtime-proof process group with `kill -{signal} -{target}`: {stderr}"
        ))
    }
}

#[cfg(unix)]
fn proof_runtime_process_group_id(process_id: u32) -> Result<Option<u32>, String> {
    let output = Command::new("ps")
        .args(["-o", "pgid=", "-p", &process_id.to_string()])
        .output()
        .map_err(|error| {
            format!("could not inspect runtime-proof process group for pid {process_id}: {error}")
        })?;
    if !output.status.success() {
        return Ok(None);
    }

    Ok(String::from_utf8_lossy(&output.stdout)
        .trim()
        .parse::<u32>()
        .ok())
}

fn proof_runtime_cleanup_failure_message(error: &CleanExecutionError) -> Option<String> {
    match error {
        CleanExecutionError::Cleanup(CleanExecutionFailure {
            reason: CleanExecutionFailureReason::EngineUnavailable,
            ..
        }) => None,
        other => Some(other.to_string()),
    }
}

fn proof_runtime_cleanup_failure_detail(error: &CleanExecutionError) -> Option<JsonValue> {
    if matches!(
        error,
        CleanExecutionError::Cleanup(CleanExecutionFailure {
            reason: CleanExecutionFailureReason::EngineUnavailable,
            ..
        })
    ) {
        return None;
    }
    clean_failure_detail_json_value(error)
}

fn proof_runtime_blocking_primary_blocker(
    summary: &DoctorSummary,
) -> Option<&DoctorPrimaryBlocker> {
    summary
        .primary_blocker
        .as_ref()
        .filter(|blocker| blocker.severity == FindingSeverity::Error)
}

fn proof_runtime_effective_up_process_failure<'a>(
    summary: &DoctorSummary,
    up_process_failure: Option<&'a str>,
) -> Option<&'a str> {
    let failure = up_process_failure?;
    if summary.verdict == DoctorVerdict::Ready
        && proof_runtime_blocking_primary_blocker(summary).is_none()
    {
        None
    } else {
        Some(failure)
    }
}

fn proof_runtime_ok(summary: &DoctorSummary, proof_error: Option<&str>) -> bool {
    summary.error_count == 0 && proof_error.is_none()
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum ProofRuntimeLikelyCause {
    ContainerEngineUnavailable {
        artifact: PathBuf,
        engine: String,
        details: String,
    },
    ReadinessTargetMismatch {
        artifact: PathBuf,
        listener: Option<String>,
        declared_target: String,
        observed_target: String,
        signal: String,
    },
    DnsServiceNameResolutionFailure {
        artifact: PathBuf,
        host: Option<String>,
        signal: String,
    },
    AuthCredentialFailure {
        artifact: PathBuf,
        service: Option<String>,
        host: Option<String>,
        signal: String,
    },
    LoopbackServiceDrift {
        artifact: PathBuf,
        service: String,
        host: String,
        port: Option<u16>,
    },
    MissingEnv {
        artifact: PathBuf,
        variable: Option<String>,
        signal: String,
    },
    InstallOrToolchainFailure {
        artifact: PathBuf,
        signal: String,
    },
    BindConflict {
        artifact: PathBuf,
        port: Option<u16>,
    },
    DetachedRunOutput {
        artifact: PathBuf,
        signal: String,
    },
}

impl ProofRuntimeLikelyCause {
    fn message(&self) -> String {
        match self {
            Self::ContainerEngineUnavailable {
                engine, details, ..
            } => format!(
                "container engine unavailable: ota could not reach a usable {engine} backend for the selected proof path ({details}); start or repair that engine before rerunning proof"
            ),
            Self::ReadinessTargetMismatch {
                declared_target,
                observed_target,
                ..
            } => format!(
                "readiness target mismatch: declared readiness target {declared_target} but runtime advertised {observed_target}; align the declared readiness target or the app's published endpoint before rerunning proof"
            ),
            Self::DnsServiceNameResolutionFailure { host, .. } => match host.as_deref() {
                Some(host) => format!(
                    "dns/service-name resolution failure: the runtime could not resolve {host}; align the selected runtime network, service naming, or workflow-owned adapter/env inputs before rerunning proof"
                ),
                None => String::from(
                    "dns/service-name resolution failure: the runtime could not resolve a required host or service name; align the selected runtime network, service naming, or workflow-owned adapter/env inputs before rerunning proof",
                ),
            },
            Self::AuthCredentialFailure { service, host, .. } => {
                match (service.as_deref(), host.as_deref()) {
                    (Some(service), Some(host)) => format!(
                        "auth/credential failure: the runtime could not authenticate against {service} at {host}; fix the selected credentials, secrets, or workflow-owned auth inputs before rerunning proof"
                    ),
                    (Some(service), None) => format!(
                        "auth/credential failure: the runtime could not authenticate against {service}; fix the selected credentials, secrets, or workflow-owned auth inputs before rerunning proof"
                    ),
                    (None, Some(host)) => format!(
                        "auth/credential failure: the runtime could not authenticate against {host}; fix the selected credentials, secrets, or workflow-owned auth inputs before rerunning proof"
                    ),
                    (None, None) => String::from(
                        "auth/credential failure: the runtime rejected required credentials or authorization; fix the selected credentials, secrets, or workflow-owned auth inputs before rerunning proof",
                    ),
                }
            }
            Self::LoopbackServiceDrift {
                service,
                host,
                port,
                ..
            } => {
                let endpoint = port
                    .map(|port| format!("{host}:{port}"))
                    .unwrap_or_else(|| host.clone());
                format!(
                    "likely config drift: the runtime is still targeting {service} on loopback ({endpoint}) inside a multi-service startup path; move that host binding into a workflow-scoped env overlay, rendered workflow env artifact, task `env_files`, or compose `manager.env_file` instead of `127.0.0.1` / `localhost`"
                )
            }
            Self::MissingEnv { variable, .. } => match variable.as_deref() {
                Some(variable) => format!(
                    "missing environment variable: {variable}; declare or supply that value on the selected proof path before rerunning proof"
                ),
                None => String::from(
                    "missing environment value on the selected proof path; declare or supply the missing config before rerunning proof",
                ),
            },
            Self::InstallOrToolchainFailure { signal, .. } => {
                format!("likely install or toolchain failure: {signal}")
            }
            Self::BindConflict { port, .. } => match port {
                Some(port) => format!(
                    "bind conflict: the runtime could not claim declared port {port}; free that port or change the declared published port before rerunning proof"
                ),
                None => String::from(
                    "bind conflict: the runtime could not claim a declared listener port; free the conflicting port or change the declared published port before rerunning proof",
                ),
            },
            Self::DetachedRunOutput { signal, .. } => {
                format!("detached run output: {signal}")
            }
        }
    }

    fn json_evidence(&self) -> ProofRuntimeLikelyCauseEvidence {
        match self {
            Self::ContainerEngineUnavailable {
                artifact,
                engine,
                details,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("container_engine_unavailable"),
                artifact: compact_repo_path(artifact),
                signal: Some(details.clone()),
                listener: None,
                variable: None,
                service: Some(engine.clone()),
                host: None,
                port: None,
                declared_target: None,
                observed_target: None,
            },
            Self::ReadinessTargetMismatch {
                artifact,
                listener,
                declared_target,
                observed_target,
                signal,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("readiness_target_mismatch"),
                artifact: compact_repo_path(artifact),
                signal: Some(signal.clone()),
                listener: listener.clone(),
                variable: None,
                service: None,
                host: None,
                port: None,
                declared_target: Some(declared_target.clone()),
                observed_target: Some(observed_target.clone()),
            },
            Self::DnsServiceNameResolutionFailure {
                artifact,
                host,
                signal,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("dns_service_name_resolution_failure"),
                artifact: compact_repo_path(artifact),
                signal: Some(signal.clone()),
                listener: None,
                variable: None,
                service: None,
                host: host.clone(),
                port: None,
                declared_target: None,
                observed_target: None,
            },
            Self::AuthCredentialFailure {
                artifact,
                service,
                host,
                signal,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("auth_credential_failure"),
                artifact: compact_repo_path(artifact),
                signal: Some(signal.clone()),
                listener: None,
                variable: None,
                service: service.clone(),
                host: host.clone(),
                port: None,
                declared_target: None,
                observed_target: None,
            },
            Self::LoopbackServiceDrift {
                artifact,
                service,
                host,
                port,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("loopback_service_drift"),
                artifact: compact_repo_path(artifact),
                signal: Some(String::from("connection_refused")),
                listener: None,
                variable: None,
                service: Some(service.clone()),
                host: Some(host.clone()),
                port: *port,
                declared_target: None,
                observed_target: None,
            },
            Self::MissingEnv {
                artifact,
                variable,
                signal,
            } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("missing_env"),
                artifact: compact_repo_path(artifact),
                signal: Some(signal.clone()),
                listener: None,
                variable: variable.clone(),
                service: None,
                host: None,
                port: None,
                declared_target: None,
                observed_target: None,
            },
            Self::InstallOrToolchainFailure { artifact, signal } => {
                ProofRuntimeLikelyCauseEvidence {
                    kind: String::from("install_or_toolchain_failure"),
                    artifact: compact_repo_path(artifact),
                    signal: Some(signal.clone()),
                    listener: None,
                    variable: None,
                    service: None,
                    host: None,
                    port: None,
                    declared_target: None,
                    observed_target: None,
                }
            }
            Self::BindConflict { artifact, port } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("bind_conflict"),
                artifact: compact_repo_path(artifact),
                signal: Some(String::from("address_in_use")),
                listener: None,
                variable: None,
                service: None,
                host: None,
                port: *port,
                declared_target: None,
                observed_target: None,
            },
            Self::DetachedRunOutput { artifact, signal } => ProofRuntimeLikelyCauseEvidence {
                kind: String::from("detached_run_output"),
                artifact: compact_repo_path(artifact),
                signal: Some(signal.clone()),
                listener: None,
                variable: None,
                service: None,
                host: None,
                port: None,
                declared_target: None,
                observed_target: None,
            },
        }
    }

    fn is_readiness_target_mismatch(&self) -> bool {
        matches!(self, Self::ReadinessTargetMismatch { .. })
    }

    fn is_container_engine_unavailable(&self) -> bool {
        matches!(self, Self::ContainerEngineUnavailable { .. })
    }

    fn is_dns_service_name_resolution_failure(&self) -> bool {
        matches!(self, Self::DnsServiceNameResolutionFailure { .. })
    }

    fn is_auth_credential_failure(&self) -> bool {
        matches!(self, Self::AuthCredentialFailure { .. })
    }

    fn implies_config_drift(&self) -> bool {
        matches!(self, Self::LoopbackServiceDrift { .. })
    }

    fn is_missing_env(&self) -> bool {
        matches!(self, Self::MissingEnv { .. })
    }

    fn is_bind_conflict(&self) -> bool {
        matches!(self, Self::BindConflict { .. })
    }

    fn is_install_or_toolchain_failure(&self) -> bool {
        matches!(self, Self::InstallOrToolchainFailure { .. })
    }
}

fn canonical_proof_runtime_phase_key(phase: &str) -> String {
    match phase.trim().to_ascii_lowercase().as_str() {
        "preconditions" | "validation" | "dependencies" | "provisioning" | "activation" => {
            String::from("preconditions")
        }
        "prepare" => String::from("prepare"),
        "setup" | "repo setup" => String::from("setup"),
        "services" | "service readiness" => String::from("services"),
        "task" | "run" => String::from("run"),
        "post-up diagnosis" | "readiness" | "timeout" => String::from("readiness"),
        "cleanup" => String::from("cleanup"),
        "interrupted" => String::from("interrupted"),
        other => other.to_string(),
    }
}

fn proof_runtime_failure_class(
    summary: &DoctorSummary,
    phase: &str,
    cleanup_error: Option<&str>,
    up_process_failure: Option<&str>,
    likely_cause: Option<&ProofRuntimeLikelyCause>,
    up_log_artifact_path: &Path,
) -> Option<String> {
    let likely_install_or_toolchain_failure =
        likely_cause.is_some_and(ProofRuntimeLikelyCause::is_install_or_toolchain_failure);
    if cleanup_error.is_some() {
        return Some(String::from("cleanup_failure"));
    }

    if up_process_failure
        .is_some_and(|failure| failure.contains("runtime proof interrupted by signal"))
    {
        return Some(String::from("interrupted"));
    }

    let canonical_phase = canonical_proof_runtime_phase_key(phase);
    let likely_failure_class = proof_runtime_likely_failure_class(
        likely_cause,
        likely_install_or_toolchain_failure
            || proof_runtime_log_indicates_install_or_toolchain_failure(up_log_artifact_path),
    );

    let Some(primary) = proof_runtime_blocking_primary_blocker(summary) else {
        if up_process_failure
            .is_some_and(|failure| failure.contains("timed out while waiting for readiness"))
        {
            if let Some(class) = likely_failure_class {
                return Some(class);
            }
            return Some(String::from("readiness_timeout"));
        }
        if up_process_failure.is_some() {
            return Some(match canonical_phase.as_str() {
                "preconditions" => String::from("precondition_blocked"),
                "prepare" => String::from("prepare_failed"),
                "setup" => String::from("setup_failed"),
                "services" => String::from("service_readiness_failed"),
                "run" => String::from("run_failed"),
                _ => String::from("up_process_failure"),
            });
        }
        return None;
    };
    if primary.summary == "Run task exited before readiness" {
        if let Some(class) = likely_failure_class {
            return Some(class);
        }
        return Some(String::from("run_task_exit_before_readiness"));
    }

    if primary.summary.starts_with("Surface readiness timed out:")
        || primary
            .summary
            .starts_with("Signal surface readiness timed out:")
    {
        if let Some(class) = likely_failure_class {
            return Some(class);
        }
        return Some(String::from("readiness_timeout"));
    }
    if primary.summary.starts_with("Surface readiness failed:")
        || primary
            .summary
            .starts_with("Signal surface readiness failed:")
    {
        if let Some(class) = likely_failure_class {
            return Some(class);
        }
        return Some(String::from("readiness_check_failed"));
    }
    if primary
        .summary
        .starts_with("Surface readiness could not be evaluated:")
        || primary
            .summary
            .starts_with("Signal surface readiness could not be evaluated:")
    {
        if likely_cause.is_some_and(ProofRuntimeLikelyCause::implies_config_drift) {
            return Some(String::from("config_drift"));
        }
        return Some(String::from("readiness_evaluation_failed"));
    }
    Some(match canonical_phase.as_str() {
        "preconditions" => String::from("precondition_blocked"),
        "prepare" => String::from("prepare_failed"),
        "setup" => String::from("setup_failed"),
        "services" => String::from("service_readiness_failed"),
        "run" => String::from("run_failed"),
        "readiness" => String::from("readiness_blocked"),
        _ => String::from("primary_blocker"),
    })
}

fn proof_runtime_likely_failure_class(
    likely_cause: Option<&ProofRuntimeLikelyCause>,
    install_or_toolchain_hint: bool,
) -> Option<String> {
    let Some(likely_cause) = likely_cause else {
        if install_or_toolchain_hint {
            return Some(String::from("install_or_toolchain_failure"));
        }
        return None;
    };

    if likely_cause.is_readiness_target_mismatch() {
        return Some(String::from("readiness_target_mismatch"));
    }
    if likely_cause.is_container_engine_unavailable() {
        return Some(String::from("container_engine_unavailable"));
    }
    if likely_cause.is_dns_service_name_resolution_failure() {
        return Some(String::from("dns_service_name_resolution_failure"));
    }
    if likely_cause.is_auth_credential_failure() {
        return Some(String::from("auth_credential_failure"));
    }
    if likely_cause.is_missing_env() {
        return Some(String::from("missing_env"));
    }
    if likely_cause.is_bind_conflict() {
        return Some(String::from("bind_conflict"));
    }
    if likely_cause.implies_config_drift() {
        return Some(String::from("config_drift"));
    }
    if likely_cause.is_install_or_toolchain_failure() || install_or_toolchain_hint {
        return Some(String::from("install_or_toolchain_failure"));
    }
    None
}

fn proof_runtime_refined_phase(
    summary: &DoctorSummary,
    fallback_phase: &str,
    up_log_artifact_path: &Path,
) -> String {
    if let Some(phase) = proof_runtime_phase_from_up_log(up_log_artifact_path) {
        return phase;
    }

    let Some(primary) = proof_runtime_blocking_primary_blocker(summary) else {
        return canonical_proof_runtime_phase_key(fallback_phase);
    };

    if primary
        .summary
        .starts_with("Unsupported host platform for context:")
        || primary
            .summary
            .starts_with("Unsupported host architecture for context:")
    {
        return String::from("preconditions");
    }

    if primary.summary == "Run task exited before readiness" {
        return String::from("run");
    }

    if primary.summary.starts_with("Surface readiness failed:")
        || primary.summary.starts_with("Surface readiness timed out:")
        || primary
            .summary
            .starts_with("Surface readiness could not be evaluated:")
        || primary
            .summary
            .starts_with("Signal surface readiness failed:")
        || primary
            .summary
            .starts_with("Signal surface readiness timed out:")
        || primary
            .summary
            .starts_with("Signal surface readiness could not be evaluated:")
        || primary.summary.starts_with("Probe failed:")
        || primary.summary.starts_with("Probe timed out:")
    {
        return String::from("readiness");
    }

    canonical_proof_runtime_phase_key(fallback_phase)
}

fn proof_runtime_phase_from_up_log(up_log_artifact_path: &Path) -> Option<String> {
    let log = fs::read_to_string(up_log_artifact_path).ok()?;
    for raw_line in log.lines() {
        let line = strip_ansi_codes(raw_line);
        let trimmed = line.trim();
        if let Some(phase) = trimmed.strip_prefix("Phase:") {
            return Some(canonical_proof_runtime_phase_key(phase));
        }
        if let Some(phase) = trimmed.strip_prefix("Cause:") {
            return Some(canonical_proof_runtime_phase_key(phase));
        }
    }
    None
}

fn proof_runtime_likely_cause(
    summary: &DoctorSummary,
    up_process_failure: Option<&str>,
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let primary = proof_runtime_blocking_primary_blocker(summary);
    let looks_like_readiness_failure = primary.is_some_and(|primary| {
        primary.summary == "Run task exited before readiness"
            || primary.summary.starts_with("Surface readiness failed:")
            || primary.summary.starts_with("Surface readiness timed out:")
            || primary
                .summary
                .starts_with("Signal surface readiness failed:")
            || primary
                .summary
                .starts_with("Signal surface readiness timed out:")
    }) || up_process_failure
        .is_some_and(|failure| failure.contains("timed out while waiting for readiness"));
    if !looks_like_readiness_failure {
        return None;
    }

    if let Some(cause) =
        proof_runtime_container_engine_unavailable_hint_from_log(up_log_artifact_path)
    {
        return Some(cause);
    }

    if let Some(cause) = proof_runtime_readiness_target_mismatch_hint(up_log_artifact_path) {
        return Some(cause);
    }

    if let Some(cause) = proof_runtime_missing_env_hint_from_log(up_log_artifact_path) {
        return Some(cause);
    }

    if let Some(cause) = proof_runtime_dns_service_name_resolution_hint(up_log_artifact_path) {
        return Some(cause);
    }

    if let Some(cause) = proof_runtime_auth_credential_failure_hint(up_log_artifact_path) {
        return Some(cause);
    }

    if let Some(cause) =
        proof_runtime_install_or_toolchain_failure_hint_from_log(up_log_artifact_path)
    {
        return Some(cause);
    }

    let artifact_dir = up_log_artifact_path.parent()?;
    for candidate in [
        artifact_dir.join("up-detached-run.log"),
        up_log_artifact_path.to_path_buf(),
    ] {
        if let Some(cause) = proof_runtime_container_engine_unavailable_hint_from_log(&candidate) {
            return Some(cause);
        }
        let Some(cause) = runtime_loopback_drift_hint_from_log(candidate.as_path()) else {
            continue;
        };
        return Some(cause);
    }
    detached_run_failure_hint_from_log(&artifact_dir.join("up-detached-run.log"))
}

fn proof_runtime_log_indicates_install_or_toolchain_failure(up_log_artifact_path: &Path) -> bool {
    proof_runtime_install_or_toolchain_failure_hint_from_log(up_log_artifact_path).is_some()
}

fn normalize_container_engine_unavailable_details(details: &str) -> String {
    let mut trimmed = details.trim().trim_start_matches('»').trim().to_string();
    if let Some(rest) = trimmed.strip_prefix("Why:") {
        trimmed = rest.trim().to_string();
    } else if let Some(rest) = trimmed.strip_prefix("why:") {
        trimmed = rest.trim().to_string();
    }
    let prefix = "container engine unavailable:";
    while trimmed.contains(prefix) {
        let Some(start) = trimmed.find('(') else {
            break;
        };
        let end = trimmed
            .rfind("); start or repair")
            .or_else(|| trimmed.rfind(')'));
        let Some(end) = end else {
            break;
        };
        if end <= start {
            break;
        }
        trimmed = trimmed[start + 1..end]
            .trim()
            .trim_start_matches('»')
            .trim()
            .to_string();
    }
    trimmed
}

fn proof_runtime_container_engine_unavailable_hint_from_log(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let log = fs::read_to_string(up_log_artifact_path).ok()?;
    let details = normalize_container_engine_unavailable_details(
        &extract_container_engine_unavailable_details("", &log)?,
    );
    let lowered = log.to_ascii_lowercase();
    let engine = if lowered.contains("podman") {
        "podman"
    } else {
        "docker"
    };
    Some(ProofRuntimeLikelyCause::ContainerEngineUnavailable {
        artifact: up_log_artifact_path.to_path_buf(),
        engine: String::from(engine),
        details,
    })
}

fn proof_runtime_install_or_toolchain_failure_hint_from_log(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let Ok(log) = fs::read_to_string(up_log_artifact_path) else {
        return None;
    };
    let patterns = [
        "node-gyp",
        "gyp err",
        "error c",
        "elifecycle",
        "local package.json exists, but node_modules missing",
        "turbo: not found",
        "not recognized as an internal or external command",
    ];
    for raw_line in log.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty() {
            continue;
        }
        let lowered = line.to_ascii_lowercase();
        if patterns.iter().any(|pattern| lowered.contains(pattern)) {
            return Some(ProofRuntimeLikelyCause::InstallOrToolchainFailure {
                artifact: up_log_artifact_path.to_path_buf(),
                signal: line,
            });
        }
    }
    None
}

fn proof_runtime_missing_env_hint_from_log(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let Ok(log) = fs::read_to_string(up_log_artifact_path) else {
        return None;
    };
    for raw_line in log.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty() {
            continue;
        }
        let lowered = line.to_ascii_lowercase();
        if !(lowered.contains("missing environment variable")
            || lowered.contains("environment variable")
            || lowered.contains("required but not set"))
        {
            continue;
        }
        if let Some(variable) = extract_missing_env_variable_from_line(&line) {
            return Some(ProofRuntimeLikelyCause::MissingEnv {
                artifact: up_log_artifact_path.to_path_buf(),
                variable: Some(variable),
                signal: line,
            });
        }
        if lowered.contains("missing environment variable")
            || lowered.contains("required but not set")
        {
            return Some(ProofRuntimeLikelyCause::MissingEnv {
                artifact: up_log_artifact_path.to_path_buf(),
                variable: None,
                signal: line,
            });
        }
    }
    None
}

fn proof_runtime_dns_service_name_resolution_hint(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let artifact_dir = up_log_artifact_path.parent()?;
    for candidate in [
        artifact_dir.join("up-detached-run.log"),
        up_log_artifact_path.to_path_buf(),
    ] {
        let Some(cause) = dns_service_name_resolution_hint_from_log(candidate.as_path()) else {
            continue;
        };
        return Some(cause);
    }
    None
}

fn proof_runtime_auth_credential_failure_hint(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let artifact_dir = up_log_artifact_path.parent()?;
    for candidate in [
        artifact_dir.join("up-detached-run.log"),
        up_log_artifact_path.to_path_buf(),
    ] {
        let Some(cause) = auth_credential_failure_hint_from_log(candidate.as_path()) else {
            continue;
        };
        return Some(cause);
    }
    None
}

fn auth_credential_failure_hint_from_log(path: &Path) -> Option<ProofRuntimeLikelyCause> {
    let contents = fs::read_to_string(path).ok()?;
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty() {
            continue;
        }
        let lowered = line.to_ascii_lowercase();
        let auth_like = lowered.contains("authentication failed")
            || lowered.contains("invalid credentials")
            || lowered.contains("access denied")
            || lowered.contains("password authentication failed")
            || lowered.contains("login failed")
            || lowered.contains("invalid token")
            || lowered.contains("token expired")
            || lowered.contains("permission denied for user")
            || lowered.contains("unauthorized")
            || lowered.contains("forbidden")
            || lowered.contains("auth failed")
            || lowered.contains("authentication error");
        if !auth_like {
            continue;
        }
        if (lowered.contains("unauthorized") || lowered.contains("forbidden"))
            && !(lowered.contains("token")
                || lowered.contains("auth")
                || lowered.contains("credential")
                || lowered.contains("login")
                || lowered.contains("password")
                || lowered.contains("permission denied for user"))
        {
            continue;
        }
        let host = extract_auth_failure_host(&line);
        return Some(ProofRuntimeLikelyCause::AuthCredentialFailure {
            artifact: path.to_path_buf(),
            service: infer_auth_failure_service(&lowered, host.as_deref()),
            host,
            signal: line,
        });
    }
    None
}

fn infer_auth_failure_service(lowered_line: &str, host: Option<&str>) -> Option<String> {
    if lowered_line.contains("password authentication failed")
        || lowered_line.contains("permission denied for user")
        || lowered_line.contains("postgres")
    {
        return Some(String::from("Postgres"));
    }
    if lowered_line.contains("access denied for user") || lowered_line.contains("mysql") {
        return Some(String::from("MySQL"));
    }
    if lowered_line.contains("redis") || lowered_line.contains("invalid password") {
        return Some(String::from("Redis"));
    }
    if lowered_line.contains("mongodb") || lowered_line.contains("mongo") {
        return Some(String::from("MongoDB"));
    }
    if lowered_line.contains("clickhouse") {
        return Some(String::from("ClickHouse"));
    }
    if lowered_line.contains("jwt") || lowered_line.contains("bearer token") {
        return Some(String::from("HTTP auth"));
    }
    host.and_then(infer_auth_failure_service_from_host)
}

fn infer_auth_failure_service_from_host(host: &str) -> Option<String> {
    let lowered = host.to_ascii_lowercase();
    if lowered.contains("postgres") || lowered.contains("pg") {
        return Some(String::from("Postgres"));
    }
    if lowered.contains("redis") {
        return Some(String::from("Redis"));
    }
    if lowered.contains("mysql") {
        return Some(String::from("MySQL"));
    }
    if lowered.contains("mongo") {
        return Some(String::from("MongoDB"));
    }
    if lowered.contains("clickhouse") {
        return Some(String::from("ClickHouse"));
    }
    None
}

fn extract_auth_failure_host(line: &str) -> Option<String> {
    for token in line.split_whitespace() {
        let candidate = token.trim_matches(|ch: char| {
            matches!(ch, '"' | '\'' | '`' | ',' | ';' | '(' | ')' | '[' | ']')
        });
        if candidate.starts_with("http://")
            || candidate.starts_with("https://")
            || candidate.starts_with("tcp://")
            || candidate.starts_with("postgres://")
            || candidate.starts_with("mysql://")
            || candidate.starts_with("redis://")
            || candidate.starts_with("mongodb://")
        {
            let after_scheme = candidate
                .split_once("://")
                .map(|(_, rest)| rest)
                .unwrap_or(candidate);
            let host = after_scheme
                .split('/')
                .next()
                .unwrap_or(after_scheme)
                .split(':')
                .next()
                .unwrap_or_default()
                .trim();
            if !host.is_empty() {
                return Some(host.to_string());
            }
        }
    }
    if let Some(host) = extract_host_after_prefix(line, "host=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "url=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "uri=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "dsn=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "endpoint=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "server=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "hostname=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "addr=") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "on host ") {
        return Some(host);
    }
    extract_first_host_port_token(line)
}

fn extract_first_host_port_token(line: &str) -> Option<String> {
    for token in line.split_whitespace() {
        let candidate = token.trim_matches(|ch: char| {
            matches!(ch, '"' | '\'' | '`' | ',' | ';' | '(' | ')' | '[' | ']')
        });
        let Some((host, _port)) = candidate.rsplit_once(':') else {
            continue;
        };
        let host = host.rsplit('@').next().unwrap_or(host).trim();
        if let Some(normalized) = normalized_unresolved_host(host) {
            return Some(normalized);
        }
    }
    None
}

fn dns_service_name_resolution_hint_from_log(path: &Path) -> Option<ProofRuntimeLikelyCause> {
    let contents = fs::read_to_string(path).ok()?;
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty() {
            continue;
        }
        let lowered = line.to_ascii_lowercase();
        if !(lowered.contains("enotfound")
            || lowered.contains("eai_again")
            || lowered.contains("could not resolve host")
            || lowered.contains("name or service not known")
            || lowered.contains("temporary failure in name resolution")
            || lowered.contains("no such host")
            || lowered.contains("failed to resolve")
            || lowered.contains("getaddrinfo"))
        {
            continue;
        }
        return Some(ProofRuntimeLikelyCause::DnsServiceNameResolutionFailure {
            artifact: path.to_path_buf(),
            host: extract_unresolved_host_from_line(&line),
            signal: line,
        });
    }
    None
}

fn extract_unresolved_host_from_line(line: &str) -> Option<String> {
    if let Some(host) = extract_host_after_prefix(line, "getaddrinfo enotfound ") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "getaddrinfo eai_again ") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "lookup ") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "could not resolve host: ") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "failed to resolve ") {
        return Some(host);
    }
    if let Some(host) = extract_host_after_prefix(line, "no such host ") {
        return Some(host);
    }
    if let Some(host) = extract_host_before_suffix(line, ": name or service not known") {
        return Some(host);
    }
    if let Some(host) = extract_host_before_suffix(line, ": temporary failure in name resolution") {
        return Some(host);
    }
    if let Some(host) = extract_lookup_host_from_line(line) {
        return Some(host);
    }
    None
}

fn extract_lookup_host_from_line(line: &str) -> Option<String> {
    let lowered = line.to_ascii_lowercase();
    let start = lowered.find("lookup ")? + "lookup ".len();
    let remainder = line.get(start..)?.trim_start();
    let candidate = remainder
        .split(|ch: char| ch.is_whitespace() || ch == ':' || ch == ',' || ch == ';')
        .next()
        .unwrap_or_default()
        .trim_matches(|ch: char| matches!(ch, '"' | '\'' | '`' | '(' | ')' | '[' | ']'));
    normalized_unresolved_host(candidate)
}

fn extract_host_after_prefix(line: &str, prefix: &str) -> Option<String> {
    let lowered = line.to_ascii_lowercase();
    let start = lowered.find(prefix)?;
    let raw = line[start + prefix.len()..]
        .split(|ch: char| ch.is_whitespace() || ch == ',' || ch == ';' || ch == '(' || ch == ')')
        .next()
        .unwrap_or_default()
        .trim_matches('`')
        .trim();
    let value = if let Some((_, remainder)) = raw.split_once("://") {
        remainder
            .split('/')
            .next()
            .unwrap_or(remainder)
            .split(':')
            .next()
            .unwrap_or_default()
            .trim()
    } else {
        raw.split(|ch: char| ch == ':' || ch == '/')
            .next()
            .unwrap_or_default()
            .trim()
    };
    normalized_unresolved_host(value)
}

fn extract_host_before_suffix(line: &str, suffix: &str) -> Option<String> {
    let lowered = line.to_ascii_lowercase();
    let end = lowered.find(suffix)?;
    let value = line[..end]
        .split_whitespace()
        .last()
        .unwrap_or_default()
        .trim_matches('`')
        .trim();
    normalized_unresolved_host(value)
}

fn normalized_unresolved_host(value: &str) -> Option<String> {
    if value.is_empty() {
        return None;
    }
    if value == "localhost" || value == "127.0.0.1" || value == "0.0.0.0" {
        return None;
    }
    Some(value.to_string())
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProofRuntimeDeclaredReadinessTarget {
    listener: Option<String>,
    target: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProofRuntimeObservedTarget {
    target: String,
    signal: String,
}

fn proof_runtime_readiness_target_mismatch_hint(
    up_log_artifact_path: &Path,
) -> Option<ProofRuntimeLikelyCause> {
    let artifact_dir = up_log_artifact_path.parent()?;
    let declared =
        proof_runtime_declared_readiness_target_from_topology(&artifact_dir.join("topology.json"))?;
    for candidate in [
        artifact_dir.join("up-detached-run.log"),
        up_log_artifact_path.to_path_buf(),
    ] {
        let Some(observed) = proof_runtime_observed_runtime_target_from_log(&candidate) else {
            continue;
        };
        if !proof_runtime_targets_materially_differ(
            declared.target.as_str(),
            observed.target.as_str(),
        ) {
            continue;
        }
        return Some(ProofRuntimeLikelyCause::ReadinessTargetMismatch {
            artifact: candidate,
            listener: declared.listener.clone(),
            declared_target: declared.target.clone(),
            observed_target: observed.target,
            signal: observed.signal,
        });
    }
    None
}

fn proof_runtime_declared_readiness_target_from_topology(
    topology_artifact_path: &Path,
) -> Option<ProofRuntimeDeclaredReadinessTarget> {
    let body: JsonValue =
        serde_json::from_str(&fs::read_to_string(topology_artifact_path).ok()?).ok()?;
    let tasks = body.get("tasks")?.as_array()?;
    for task in tasks {
        let runtime = task.get("runtime")?;
        let readiness = runtime.get("readiness")?;
        let listener_name = readiness.get("listener")?.as_str()?.to_string();
        let listener = runtime.get("listeners")?.get(listener_name.as_str())?;
        let protocol = listener.get("protocol")?.as_str()?.to_ascii_lowercase();
        let scheme = match protocol.as_str() {
            "http" => "http",
            "https" => "https",
            "tcp" => "tcp",
            _ => continue,
        };
        let host_projection = listener.get("host_projection");
        let address = host_projection
            .and_then(|projection| projection.get("address"))
            .and_then(JsonValue::as_str)
            .or_else(|| listener.get("bind_address").and_then(JsonValue::as_str))?;
        let port = host_projection
            .and_then(|projection| projection.get("port_value"))
            .and_then(JsonValue::as_u64)
            .or_else(|| listener.get("bind_port_value").and_then(JsonValue::as_u64))?;
        let port = u16::try_from(port).ok()?;
        let base_path = host_projection
            .and_then(|projection| projection.get("path"))
            .and_then(JsonValue::as_str);
        let readiness_path = readiness.get("path").and_then(JsonValue::as_str);
        let path = combine_runtime_target_paths(base_path, readiness_path, scheme != "tcp");
        let target = if scheme == "tcp" {
            format!("tcp://{address}:{port}")
        } else {
            format!("{scheme}://{address}:{port}{path}")
        };
        return Some(ProofRuntimeDeclaredReadinessTarget {
            listener: Some(listener_name),
            target,
        });
    }
    None
}

fn combine_runtime_target_paths(
    base_path: Option<&str>,
    readiness_path: Option<&str>,
    include_default_root: bool,
) -> String {
    match (base_path, readiness_path) {
        (_, Some(readiness_path)) if !readiness_path.is_empty() => {
            if readiness_path.starts_with('/') {
                readiness_path.to_string()
            } else {
                format!("/{readiness_path}")
            }
        }
        (Some(base_path), _) if !base_path.is_empty() => {
            if base_path.starts_with('/') {
                base_path.to_string()
            } else {
                format!("/{base_path}")
            }
        }
        _ if include_default_root => String::from("/"),
        _ => String::new(),
    }
}

fn proof_runtime_observed_runtime_target_from_log(
    path: &Path,
) -> Option<ProofRuntimeObservedTarget> {
    let contents = fs::read_to_string(path).ok()?;
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty() {
            continue;
        }
        let lowered = line.to_ascii_lowercase();
        if !(lowered.contains("local:")
            || lowered.contains("listening")
            || lowered.contains("running")
            || lowered.contains("ready")
            || lowered.contains("started")
            || lowered.contains("available at")
            || lowered.contains("http://")
            || lowered.contains("https://")
            || lowered.contains("tcp://"))
        {
            continue;
        }
        let Some(target) = extract_runtime_target_from_line(&line) else {
            continue;
        };
        return Some(ProofRuntimeObservedTarget {
            target,
            signal: line,
        });
    }
    None
}

fn extract_runtime_target_from_line(line: &str) -> Option<String> {
    for token in line.split_whitespace() {
        let candidate = token.trim_matches(|ch: char| {
            matches!(ch, '"' | '\'' | '`' | ',' | ';' | '(' | ')' | '[' | ']')
        });
        if candidate.starts_with("http://")
            || candidate.starts_with("https://")
            || candidate.starts_with("tcp://")
        {
            return Some(candidate.trim_end_matches('/').to_string());
        }
    }
    None
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ParsedRuntimeTarget {
    scheme: String,
    host: String,
    port: Option<u16>,
    path: String,
}

fn parse_runtime_target(target: &str) -> Option<ParsedRuntimeTarget> {
    let (scheme, remainder) = target.split_once("://")?;
    let (host_port, path) = match remainder.split_once('/') {
        Some((host_port, path)) => (host_port, format!("/{}", path.trim_start_matches('/'))),
        None => (remainder, String::from("/")),
    };
    let (host, port) = match host_port.rsplit_once(':') {
        Some((host, port)) => (host, port.parse::<u16>().ok()),
        None => (host_port, None),
    };
    Some(ParsedRuntimeTarget {
        scheme: scheme.to_string(),
        host: normalize_runtime_target_host(host),
        port,
        path,
    })
}

fn normalize_runtime_target_host(host: &str) -> String {
    match host {
        "127.0.0.1" | "localhost" | "0.0.0.0" => String::from("local"),
        other => other.to_string(),
    }
}

fn proof_runtime_targets_materially_differ(declared: &str, observed: &str) -> bool {
    let Some(declared) = parse_runtime_target(declared) else {
        return false;
    };
    let Some(observed) = parse_runtime_target(observed) else {
        return false;
    };
    if declared.scheme != observed.scheme {
        return true;
    }
    if declared.host != observed.host {
        return true;
    }
    if declared.port != observed.port {
        return true;
    }
    let declared_path = declared.path.trim_end_matches('/');
    let observed_path = observed.path.trim_end_matches('/');
    !observed_path.is_empty() && declared_path != observed_path
}

fn extract_missing_env_variable_from_line(line: &str) -> Option<String> {
    if let Some(value) = line.strip_prefix("Missing environment variable:") {
        return Some(value.trim().trim_matches('`').to_string());
    }
    if let Some(start) = line.find('`')
        && let Some(end) = line[start + 1..].find('`')
    {
        let candidate = line[start + 1..start + 1 + end].trim();
        if !candidate.is_empty()
            && candidate
                .chars()
                .all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_')
        {
            return Some(candidate.to_string());
        }
    }
    for token in line
        .split(|ch: char| ch.is_whitespace() || ch == ':' || ch == ',' || ch == '(' || ch == ')')
    {
        let candidate = token.trim_matches('`').trim();
        if candidate.len() >= 2
            && candidate
                .chars()
                .all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_')
            && candidate.chars().any(|ch| ch.is_ascii_alphabetic())
        {
            return Some(candidate.to_string());
        }
    }
    None
}

fn proof_runtime_status_word(
    verdict: DoctorVerdict,
    phase: &str,
    timed_out: bool,
    interrupted: bool,
    cleanup_failed: bool,
) -> &'static str {
    if cleanup_failed {
        return "BLOCKED";
    }
    if interrupted {
        return "INTERRUPTED";
    }
    if timed_out {
        return "TIMEOUT";
    }
    match verdict {
        DoctorVerdict::Ready => "READY",
        DoctorVerdict::Risky => "READY",
        DoctorVerdict::NotReady => {
            if phase == "preconditions" {
                "NOT READY"
            } else {
                "BLOCKED"
            }
        }
        DoctorVerdict::PolicyBlocked | DoctorVerdict::AgentBlocked => "BLOCKED",
    }
}

fn proof_runtime_phase_label(phase: &str) -> &str {
    phase
}

fn proof_runtime_command_for_repo(
    command: &str,
    workflow: Option<&str>,
    extra: Option<&str>,
    contract_path: &Path,
) -> String {
    let mut full = command.to_string();
    if let Some(workflow) = workflow {
        full.push_str(" --workflow ");
        full.push_str(workflow);
    }
    if let Some(extra) = extra {
        full.push(' ');
        full.push_str(extra);
    }
    let repo_root = contract_working_dir(contract_path);
    let repo_display = compact_repo_path(repo_root);
    format!("{full} {repo_display}")
}

fn proof_runtime_up_exit_primary_blocker(
    summary: &DoctorSummary,
    up_process_failure: Option<&str>,
    up_log_artifact: &str,
) -> Option<DoctorPrimaryBlocker> {
    let process_failure = up_process_failure?;
    let primary = summary.primary_blocker.as_ref()?;
    if !(primary.summary.starts_with("Surface readiness failed:")
        || primary.summary.starts_with("Surface readiness timed out:"))
    {
        return None;
    }

    Some(DoctorPrimaryBlocker {
        code: None,
        severity: FindingSeverity::Error,
        summary: String::from("Run task exited before readiness"),
        why: process_failure.to_string(),
        next: format!("inspect {} and rerun `ota proof runtime`", up_log_artifact),
        provenance: primary.provenance.clone(),
        provenance_key: primary.provenance_key.clone(),
    })
}

fn render_proof_runtime_text(
    path: &str,
    workflow: Option<&str>,
    contract_path: &Path,
    phase: &str,
    status: &str,
    summary: &DoctorSummary,
    up_process_failure: Option<&str>,
    topology_artifact: &str,
    doctor_artifact: &str,
    up_log_artifact: &str,
    workflow_env_artifacts: &[EnvRenderedArtifactEntry],
    likely_cause: Option<&str>,
    cleanup_error: Option<&str>,
    cleanup_next: Option<&str>,
) -> String {
    let mut stdout = format_command_header("PROOF", path);
    stdout.push_str(&format!(
        "\n\n{} {}",
        paint_key("Workflow:"),
        workflow.unwrap_or("default task path")
    ));
    stdout.push_str(&format!(
        "\n{} {}",
        paint_key("Mode:"),
        paint_mode_value("runtime-proof")
    ));

    if status == "READY" {
        stdout.push_str(&format!(
            "\n\n{} {}",
            info_bullet(),
            paint_section_title("Steps")
        ));
        for step in [
            "validate contract".to_string(),
            "capture execution topology".to_string(),
            format!(
                "run {}",
                paint_backticked_code(&proof_runtime_command_for_repo(
                    "ota up",
                    workflow,
                    Some("--stream"),
                    contract_path,
                ))
            ),
            format!(
                "wait for {} to report ready",
                paint_backticked_code(&proof_runtime_command_for_repo(
                    "ota doctor",
                    workflow,
                    Some("--json"),
                    contract_path,
                ))
            ),
            "capture proof artifacts".to_string(),
            "clean up runtime".to_string(),
        ] {
            stdout.push_str(&format!("\n  {} {}", next_bullet(), step));
        }
        stdout.push_str(&format!("\n\n{}", render_status_line(status)));
    } else {
        stdout.push_str(&format!("\n\n{}", render_status_line(status)));
        stdout.push_str(&format!("\n{} {phase}", paint_key("Phase:")));
        stdout.push('\n');
        if let Some(cleanup_error) = cleanup_error {
            stdout.push_str(&format!(
                "\n{}  {}\n{} {}\n{} {}",
                render_severity(FindingSeverity::Error),
                render_finding_summary_with_count(
                    FindingSeverity::Error,
                    "Runtime cleanup failed",
                    1,
                ),
                finding_detail_key(FindingSeverity::Error, "Why:"),
                cleanup_error,
                finding_detail_key(FindingSeverity::Error, "Next:"),
                render_backticked_text(
                    cleanup_next.unwrap_or(
                        "run `ota clean`, inspect the remaining runtime state, then rerun proof"
                    ),
                    None,
                )
            ));
        } else if let Some(primary) = summary.primary_blocker.as_ref() {
            stdout.push_str(&format!(
                "\n{}  {}\n{} {}\n{} {}",
                render_severity(primary.severity),
                render_finding_summary_with_count(primary.severity, &primary.summary, 1,),
                finding_detail_key(primary.severity, "Why:"),
                render_backticked_text(&primary.why, None),
                finding_detail_key(primary.severity, "Next:"),
                render_backticked_text(&primary.next, None)
            ));
        } else if let Some(process_failure) = up_process_failure {
            stdout.push_str(&format!(
                "\n{}  {}\n{} {}\n{} {}",
                render_severity(FindingSeverity::Error),
                render_finding_summary_with_count(
                    FindingSeverity::Error,
                    "Up process exited unexpectedly",
                    1,
                ),
                finding_detail_key(FindingSeverity::Error, "Why:"),
                render_backticked_text(process_failure, None),
                finding_detail_key(FindingSeverity::Error, "Next:"),
                render_backticked_text(
                    &format!("inspect {} and rerun `ota proof runtime`", up_log_artifact),
                    None,
                )
            ));
        }
        if let Some(likely_cause) = likely_cause {
            stdout.push_str(&format!(
                "\n{} {}",
                finding_detail_key(FindingSeverity::Error, "Likely cause:"),
                render_backticked_text(likely_cause, None),
            ));
        }
    }

    stdout.push_str(&format!(
        "\n\n{} {}",
        info_bullet(),
        paint_section_title("Artifacts")
    ));
    stdout.push_str(&format!(
        "\n  {} {} {}",
        next_bullet(),
        paint_key("Topology:"),
        paint_backticked_code(topology_artifact)
    ));
    stdout.push_str(&format!(
        "\n  {} {} {}",
        next_bullet(),
        paint_key("Doctor:"),
        paint_backticked_code(doctor_artifact)
    ));
    stdout.push_str(&format!(
        "\n  {} {} {}",
        next_bullet(),
        paint_key("Up log:"),
        paint_backticked_code(up_log_artifact)
    ));
    if !workflow_env_artifacts.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Workflow Env Artifacts")
        ));
        for artifact in workflow_env_artifacts {
            stdout.push_str(&render_env_rendered_artifact_text(artifact));
        }
    }

    if status == "READY" {
        stdout.push_str(&format!("\n\n{}", paint_next_key()));
        stdout.push_str(&format!(
            "\n  {} inspect {} for the canonical readiness verdict",
            next_bullet(),
            paint_backticked_code("doctor.json")
        ));
        stdout.push_str(&format!(
            "\n  {} inspect {} when startup behavior needs review",
            next_bullet(),
            paint_backticked_code("up.log")
        ));
    }

    stdout
}

fn render_up_preview_text(
    path: &str,
    summary: &DoctorSummary,
    contract_identity: &ContractIdentity,
    execution: &UpPreviewExecution,
    plan: &UpPreviewPlan,
) -> String {
    let mut stdout = format!(
        "{}\n\n{}\n\n{}",
        format_command_header("UP PREVIEW", path),
        render_preview_readiness_status(summary.verdict),
        format_mode_line("dry-run (no write)")
    );

    stdout.push_str(&format!("\n\n{}\n", paint_section_title("Execution")));
    stdout.push_str(&detail_list_row(&paint_key("Backend:"), &execution.backend));
    if let Some(context) = execution.context.as_deref() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Context:"),
            &paint_backticked_code(context),
        ));
    }
    if let Some(lifecycle) = execution.lifecycle.as_deref() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(&paint_key("Lifecycle:"), lifecycle));
    }
    if let Some(image) = execution.image.as_deref() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Image:"),
            &paint_backticked_code(image),
        ));
    }
    if let Some(target) = execution.target.as_deref() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Target:"),
            &paint_backticked_code(target),
        ));
    }
    if let Some(task) = execution.task.as_deref() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Task:"),
            &paint_backticked_code(task),
        ));
    }

    let project = contract_identity
        .project
        .project_type
        .as_deref()
        .map(|project_type| format!("{} ({project_type})", contract_identity.project.name))
        .unwrap_or_else(|| contract_identity.project.name.clone());
    stdout.push_str(&format!("\n\n{}\n", paint_section_title("Contract")));
    stdout.push_str(&detail_list_row(&paint_key("Project:"), &project));
    stdout.push('\n');
    stdout.push_str(&detail_list_row(
        &paint_key("Version:"),
        &contract_identity.version.to_string(),
    ));
    let metadata = [
        contract_identity
            .metadata
            .owner
            .as_ref()
            .map(|value| format!("owner={value}")),
        contract_identity
            .metadata
            .team
            .as_ref()
            .map(|value| format!("team={value}")),
        contract_identity
            .metadata
            .repo_class
            .as_ref()
            .map(|value| format!("repo_class={value}")),
    ]
    .into_iter()
    .flatten()
    .collect::<Vec<_>>();
    if !metadata.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Metadata:"),
            &metadata.join(", "),
        ));
    }
    let mut execution_identity = Vec::new();
    if let Some(preferred) = contract_identity.execution.preferred.as_deref() {
        execution_identity.push(format!("preferred={preferred}"));
    }
    if let Some(lifecycle) = contract_identity.execution.lifecycle.as_deref() {
        execution_identity.push(format!("lifecycle={lifecycle}"));
    }
    if !contract_identity.execution.supported.is_empty() {
        execution_identity.push(format!(
            "supported={}",
            contract_identity.execution.supported.join(", ")
        ));
    }
    if let Some(image) = contract_identity.execution.image.as_deref() {
        execution_identity.push(format!("image={image}"));
    }
    if !execution_identity.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Execution:"),
            &execution_identity.join(", "),
        ));
    }
    let mut count_parts = vec![
        format!("runtimes={}", contract_identity.counts.runtimes),
        format!("tools={}", contract_identity.counts.tools),
        format!("env={}", contract_identity.counts.env),
        format!("services={}", contract_identity.counts.services),
        format!("checks={}", contract_identity.counts.checks),
        format!("tasks={}", contract_identity.counts.tasks),
    ];
    if let Some(repos) = contract_identity.counts.repos {
        count_parts.push(format!("repos={repos}"));
    }
    if let Some(policies) = contract_identity.counts.policies {
        count_parts.push(format!("policies={policies}"));
    }
    stdout.push('\n');
    stdout.push_str(&detail_list_row(
        &paint_key("Counts:"),
        &count_parts.join(", "),
    ));

    stdout.push_str(&format!("\n\n{}", paint_section_title("Plan")));
    if plan.actions.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_item("none"));
    } else {
        for action in &plan.actions {
            append_wrapped_bullet_text(
                &mut stdout,
                detail_arrow(),
                action,
                " ",
                84,
                render_backticked_preview_value,
            );
        }
    }

    if !plan.skipped.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Skipped")));
        for skipped in &plan.skipped {
            append_wrapped_bullet_text(
                &mut stdout,
                detail_arrow(),
                skipped,
                " ",
                84,
                render_backticked_preview_value,
            );
        }
    }

    if let Some(primary_finding) = summary.primary_blocker.as_ref() {
        stdout.push_str("\n\n");
        stdout.push_str(&render_primary_finding_text_with_next_rewriter(
            primary_finding.severity,
            &primary_finding.summary,
            &primary_finding.why,
            &primary_finding.next,
            primary_finding.provenance.clone(),
            doctor_mode_from_backend(Some(execution.backend.as_str())),
            lifecycle_from_display_value(execution.lifecycle.as_deref()),
            None,
            rewrite_up_preview_next_command,
        ));
    }

    stdout.push_str(&format!("\n\n{}", paint_section_title("Dry run only")));
    for line in [
        "no provisioning executed",
        "no services started",
        "no repo files changed",
    ] {
        stdout.push('\n');
        stdout.push_str(&detail_list_item(line));
    }

    stdout
}

fn render_compact_contract_identity(contract_identity: &ContractIdentity) -> String {
    let mut parts = vec![
        contract_identity
            .project
            .project_type
            .as_deref()
            .map(|project_type| format!("{} ({project_type})", contract_identity.project.name))
            .unwrap_or_else(|| contract_identity.project.name.clone()),
    ];
    if let Some(preferred) = contract_identity.execution.preferred.as_deref() {
        parts.push(format!("preferred={preferred}"));
    }
    if let Some(lifecycle) = contract_identity.execution.lifecycle.as_deref() {
        parts.push(format!("lifecycle={lifecycle}"));
    }
    if let Some(image) = contract_identity.execution.image.as_deref() {
        parts.push(format!("image={image}"));
    }
    if let Some(repos) = contract_identity.counts.repos {
        parts.push(format!("repos={repos}"));
    } else {
        parts.push(format!("tasks={}", contract_identity.counts.tasks));
    }
    parts.join(", ")
}

fn render_backticked_preview_value(value: &str) -> String {
    render_backticked_text(value, None)
}

fn phase_output_text(stdout: &str, stderr: &str) -> Option<String> {
    let stdout = stdout.trim_end();
    let stderr = stderr.trim_end();

    match (stdout.is_empty(), stderr.is_empty()) {
        (true, true) => None,
        (false, true) => Some(stdout.to_string()),
        (true, false) => Some(stderr.to_string()),
        (false, false) => Some(format!("{stdout}\n{stderr}")),
    }
}

fn render_up_section_from_parts(
    path: &str,
    contract_path: Option<&Path>,
    status: &str,
    phase: &str,
    report: &DoctorReport,
    backend: Option<&str>,
    context: Option<&str>,
    service: Option<&str>,
    service_command: Option<&str>,
    task: Option<&str>,
    task_command: Option<&str>,
    stderr: Option<&str>,
    exit_code: Option<i32>,
) -> String {
    let doctor_mode = doctor_mode_from_backend(backend);
    let mut stdout = format!(
        "{}\n\n{}\n{} {phase}",
        format_command_header("UP", path),
        render_status_line(status),
        paint_key("Phase:")
    );
    if let Some(backend) = backend {
        stdout.push_str(&format!("\n{} {backend}", paint_key("Backend:")));
    }
    if let Some(context) = context {
        stdout.push_str(&format!("\n{} {context}", paint_key("Context:")));
    }
    if let Some(service) = service {
        stdout.push_str(&format!("\n{} {service}", paint_key("Service:")));
    }
    if let Some(service_command) = service_command {
        stdout.push_str(&format!(
            "\n{} {service_command}",
            paint_key("Service command:")
        ));
    }

    if let Some(task) = task {
        stdout.push_str(&format!("\n{} {task}", paint_key("Task:")));
    }
    if let Some(task_command) = task_command {
        stdout.push_str(&format!("\n{} {task_command}", paint_key("Command:")));
    }
    if let Some(exit_code) = exit_code {
        stdout.push_str(&format!("\n{} {exit_code}", paint_key("Exit code:")));
        if phase == "services" {
            stdout.push_str(&format!(
                "\n{} inspect the `Service command:` line and `Service output:`, then fix the reported issue",
                finding_detail_key(FindingSeverity::Error, "Next:"),
            ));
        } else if phase == "setup" {
            stdout.push_str(&format!(
                "\n{} inspect the backend output first; if the backend is healthy, inspect the command and task output next",
                finding_detail_key(FindingSeverity::Error, "Next:")
            ));
        }
    }

    let should_render_phase_output = status != "READY" || exit_code.unwrap_or(0) != 0;
    if should_render_phase_output
        && let Some(stderr) = stderr.and_then(|stderr| {
            let stderr = stderr.trim_end();
            if stderr.is_empty() {
                None
            } else {
                Some(stderr)
            }
        })
    {
        let output_label = if phase == "setup" {
            setup_failure_output_label(stderr)
        } else if phase == "services" {
            "Service output:"
        } else {
            "Task output:"
        };
        stdout.push_str(&format!("\n{} {}", paint_key(output_label), stderr));
    }

    for group in group_doctor_findings(report.findings.iter()) {
        if group.findings.len() == 1 {
            let finding = group.findings[0];
            stdout.push_str("\n\n");
            let rewritten_next = rewrite_doctor_mode_command(&finding.next, doctor_mode, None);
            let rewritten_next =
                if should_prepend_up_execution_plan_for_finding(status, phase, finding, backend) {
                    prepend_up_execution_plan_next_step(
                        &rewritten_next,
                        contract_path,
                        member_from_display_contract_target(path),
                        backend,
                    )
                } else {
                    rewritten_next
                };
            if render_depends_on_boundary_doctor_finding(
                &mut stdout,
                finding.severity,
                &finding.summary,
                &finding.why,
                &rewritten_next,
                contract_path,
            ) {
                continue;
            }
            let why = render_backticked_text(&finding.why, contract_path);
            let next = render_backticked_text(&rewritten_next, contract_path);
            stdout.push_str(&format!(
                "{}  {}\n{} {}\n{} {}",
                render_severity(finding.severity),
                render_finding_summary_with_count(
                    finding.severity,
                    &finding.summary,
                    single_finding_display_count(&finding.summary, &finding.why),
                ),
                finding_detail_key(finding.severity, "Why:"),
                why,
                finding_detail_key(finding.severity, "Next:"),
                next
            ));
            continue;
        }

        stdout.push_str(&render_grouped_doctor_findings(
            &group,
            contract_path,
            doctor_mode,
        ));
    }

    stdout
}

fn prepend_up_execution_plan_next_step(
    next: &str,
    contract_path: Option<&Path>,
    member: Option<&str>,
    backend: Option<&str>,
) -> String {
    let Some(contract_path) = contract_path else {
        return next.to_string();
    };
    let backend = match backend {
        Some("container") => Backend::Container,
        Some("remote") => Backend::Remote,
        _ => return next.to_string(),
    };
    if next.contains("ota execution plan") {
        return next.to_string();
    }
    let command = repo_execution_plan_command(contract_path, member, backend);
    format!(
        "run `{command}` to inspect the selected execution path before changing execution settings; {next}"
    )
}

fn should_prepend_up_execution_plan_for_finding(
    status: &str,
    phase: &str,
    finding: &Finding,
    backend: Option<&str>,
) -> bool {
    if !matches!(backend, Some("container" | "remote")) {
        return false;
    }
    if finding.next.contains("ota execution plan") {
        return false;
    }
    if status == "PROVISION FAILED" {
        return true;
    }
    if phase != "preconditions" {
        return false;
    }
    let summary = finding.summary.as_str();
    summary == "Container execution is not configured"
        || summary == "Container execution lifecycle is not configured"
        || summary.starts_with("Missing container execution backend CLI")
        || summary == "Remote execution is not configured"
        || summary == "Remote execution target is not configured"
}

fn normalized_up_receipt(
    member: Option<&str>,
    status: &str,
    phase: &str,
    findings: &[Finding],
    stderr: Option<&str>,
    receipt: &ExecutionReceipt,
) -> ExecutionReceipt {
    let mut normalized = receipt.clone();
    normalized.next = normalized_up_receipt_next(member, status, phase, findings, stderr, receipt);
    normalized
}

fn normalized_up_receipt_next(
    member: Option<&str>,
    status: &str,
    phase: &str,
    findings: &[Finding],
    stderr: Option<&str>,
    receipt: &ExecutionReceipt,
) -> Option<String> {
    let backend = receipt.backend.as_deref();
    let cause = primary_up_failure_cause(status, phase, findings, backend, stderr, None, None);
    if matches!(cause, Some(UpFailureCause::BackendStartup)) {
        let Some(contract_path) = Some(Path::new(receipt.contract.as_str())) else {
            return receipt.next.clone();
        };
        let backend = match backend {
            Some("container") => Backend::Container,
            Some("remote") => Backend::Remote,
            _ => return receipt.next.clone(),
        };
        let command = repo_execution_plan_command(contract_path, member, backend);
        let mut next_steps = vec![format!(
            "run `{command}` to inspect the selected execution path before changing execution settings"
        )];
        if stderr
            .map(|text| {
                let lowered = text.to_ascii_lowercase();
                lowered.contains("network") && lowered.contains("not found")
            })
            .unwrap_or(false)
        {
            next_steps.push(String::from(
                "repair the missing compose/runtime network attachment, then rerun `ota up`",
            ));
        } else {
            next_steps.push(String::from(
                "repair the container backend startup state, then rerun `ota up`",
            ));
        }
        next_steps.push(String::from(
            "verify the container runtime and required compose attachments are healthy",
        ));
        return Some(next_steps.join("; "));
    }

    let Some(primary) = findings
        .iter()
        .find(|finding| finding.severity == FindingSeverity::Error)
        .or_else(|| findings.first())
    else {
        return receipt.next.clone();
    };

    let current_next = receipt
        .next
        .as_deref()
        .unwrap_or(primary.next.as_str())
        .to_string();

    if should_prepend_up_execution_plan_for_finding(status, phase, primary, backend) {
        return Some(prepend_up_execution_plan_next_step(
            &current_next,
            Some(Path::new(receipt.contract.as_str())),
            member,
            backend,
        ));
    }

    if status == "READY" && primary.severity == FindingSeverity::Info {
        let next_steps = finding_next_steps(&current_next);
        if let Some(first_step) = next_steps.first() {
            return Some(first_step.clone());
        }
    }

    Some(current_next)
}

fn doctor_mode_from_backend(backend: Option<&str>) -> Option<DoctorMode> {
    match backend.map(|backend| backend.trim()) {
        Some("container") => Some(DoctorMode::Container),
        Some("remote") => Some(DoctorMode::Remote),
        Some("native") => Some(DoctorMode::Native),
        _ => None,
    }
}

fn lifecycle_from_display_value(lifecycle: Option<&str>) -> Option<Lifecycle> {
    match lifecycle.map(str::trim) {
        Some("persistent") => Some(Lifecycle::Persistent),
        Some("ephemeral") => Some(Lifecycle::Ephemeral),
        _ => None,
    }
}

fn setup_failure_output_label(stderr: &str) -> &'static str {
    let stderr = stderr.trim_start();
    let lower = stderr.to_ascii_lowercase();
    if lower.contains("bind for ") && lower.contains("port is already allocated") {
        return "Host publication error:";
    }
    if stderr.starts_with("container backend `")
        || stderr.starts_with("backend provider `")
        || stderr.starts_with("remote provider `")
        || stderr.starts_with("remote backend `")
    {
        "Backend error:"
    } else {
        "Task output:"
    }
}

fn render_execution_receipt_text(receipt: &ExecutionReceipt) -> String {
    let mut stdout = String::from("\n\n");
    if !receipt.steps.is_empty() {
        stdout.push_str(&paint_section_title("Steps"));
        for step in &receipt.steps {
            if step.order > 1 {
                stdout.push_str("\n\n");
            } else {
                stdout.push('\n');
            }
            let detail_indent = "   ";
            stdout.push_str(&format!(
                " {}. {}  {}",
                step.order,
                render_execution_receipt_status(&step.status),
                paint(&step.label, "1")
            ));
            if let Some(detail) = step.detail.as_deref() {
                stdout.push_str(&format!(
                    "\n{}{} {}",
                    detail_indent,
                    paint_key("Detail:"),
                    detail
                ));
            }
            if let Some(exit_code) = step.exit_code {
                stdout.push_str(&format!(
                    "\n{}{} {exit_code}",
                    detail_indent,
                    paint_key("Exit code:")
                ));
            }
        }
        stdout.push_str("\n\n");
    }

    if let Some(identity) = receipt.contract_identity.as_ref() {
        stdout.push_str(&render_contract_identity_text(identity));
        stdout.push_str("\n\n");
    }

    stdout.push_str(&paint_section_title("Summary"));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Errors:"),
        receipt.summary.error_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Warnings:"),
        receipt.summary.warn_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Info:"),
        receipt.summary.info_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Steps:"),
        receipt.summary.step_count
    ));
    if !receipt.env_sources.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Env Sources")));
        for source in &receipt.env_sources {
            stdout.push_str(&format!(
                "\n{} {} ({})",
                paint_key(&source.name),
                source.value,
                source.source
            ));
        }
    }

    if !receipt.workflow_env_artifacts.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Workflow Env Artifacts")
        ));
        for artifact in &receipt.workflow_env_artifacts {
            stdout.push_str(&render_env_rendered_artifact_text(artifact));
        }
    }

    if !receipt.native_prerequisites.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Native Prerequisites")
        ));
        for prerequisite in &receipt.native_prerequisites {
            stdout.push_str(&format!(
                "\n{} {} ({})",
                paint_key(&prerequisite.name),
                if prerequisite.required {
                    "required"
                } else {
                    "optional"
                },
                prerequisite.platform
            ));
            if let Some(check) = prerequisite.check.as_deref() {
                stdout.push_str(&format!("\n  {} {check}", paint_key("Check:")));
            }
            if let Some(activation) = prerequisite.activation.as_ref() {
                let mut activation_detail = match activation.kind.as_str() {
                    "visual_studio_dev_shell" => String::from("Visual Studio Developer Shell"),
                    "command" => String::from("command activation"),
                    other => other.replace('_', " "),
                };
                if let Some(arch) = activation.arch.as_deref() {
                    activation_detail.push_str(&format!(" ({arch})"));
                }
                if let Some(shell) = activation.shell.as_deref() {
                    activation_detail.push_str(&format!(" via {shell}"));
                }
                if activation.applied {
                    activation_detail.push_str("; applied");
                }
                stdout.push_str(&format!(
                    "\n  {} {activation_detail}",
                    paint_key("Activation:")
                ));
                if let Some(run) = activation.run.as_deref() {
                    stdout.push_str(&format!(
                        "\n  {} {}",
                        paint_key("Command:"),
                        paint_code(run)
                    ));
                }
            }
            for item in &prerequisite.provisioning {
                stdout.push_str(&format!("\n  {} {item}", paint_key("Provision:")));
            }
            if let Some(note) = prerequisite.note.as_deref() {
                stdout.push_str(&format!("\n  {} {note}", paint_key("Note:")));
            }
        }
    }

    if !receipt.toolchains.is_empty() {
        stdout.push_str("\n\n");
        stdout.push_str(&render_toolchain_summary_text(&receipt.toolchains));
    }

    if let Some(runtime) = receipt.runtime.as_ref() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Runtime")));
        append_runtime_listener_lines(&mut stdout, runtime, "");
    }

    if !receipt.host_service_cleanup.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Host Service Cleanup")
        ));
        for cleanup in &receipt.host_service_cleanup {
            stdout.push_str(&format!(
                "\n{} {} ({}, {})",
                paint_key(&cleanup.service),
                cleanup.status,
                cleanup.action,
                cleanup.trigger
            ));
            if let Some(detail) = cleanup.detail.as_deref() {
                stdout.push_str(&format!("\n  {} {detail}", paint_key("Detail:")));
            }
        }
    }

    if !receipt.workloads.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Workloads")));
        for (task_name, runtime) in &receipt.workloads {
            stdout.push_str(&format!("\n{}", paint_key(task_name)));
            append_runtime_listener_lines(&mut stdout, runtime, "  ");
        }
    }

    if let Some(logs) = receipt.logs.as_ref() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Logs")));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Dir:"),
            paint_code(&logs.dir)
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Stdout:"),
            paint_code(&logs.stdout)
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Stderr:"),
            paint_code(&logs.stderr)
        ));
    }

    if !receipt.policy.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Policy")));
        for line in &receipt.policy {
            stdout.push_str(&format!("\n{}", line));
        }
    }

    if !receipt.blocked.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Blocked")));
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Items:"),
            receipt.blocked.join(", ")
        ));
    }

    if let Some(execution_conflict) = execution_receipt_conflict(&receipt.blocked) {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Execution Conflict")
        ));
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Reasons:"),
            execution_conflict
                .reasons
                .iter()
                .map(|reason| format!("`{reason}`"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }

    stdout.push('\n');

    stdout
}

fn render_contract_identity_text(identity: &ContractIdentity) -> String {
    let project = identity
        .project
        .project_type
        .as_deref()
        .map(|project_type| format!("{} ({project_type})", identity.project.name))
        .unwrap_or_else(|| identity.project.name.clone());
    let mut stdout = String::new();
    stdout.push_str(&paint_section_title("Contract"));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Project:"),
        project
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Version:"),
        identity.version
    ));
    let metadata = [
        identity
            .metadata
            .owner
            .as_ref()
            .map(|value| format!("owner={value}")),
        identity
            .metadata
            .team
            .as_ref()
            .map(|value| format!("team={value}")),
        identity
            .metadata
            .repo_class
            .as_ref()
            .map(|value| format!("repo_class={value}")),
    ]
    .into_iter()
    .flatten()
    .collect::<Vec<_>>();
    if !metadata.is_empty() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Metadata:"),
            metadata.join(", ")
        ));
    }
    let mut execution = Vec::new();
    if let Some(preferred) = identity.execution.preferred.as_deref() {
        execution.push(format!("preferred={preferred}"));
    }
    if let Some(lifecycle) = identity.execution.lifecycle.as_deref() {
        execution.push(format!("lifecycle={lifecycle}"));
    }
    if !identity.execution.supported.is_empty() {
        execution.push(format!(
            "supported={}",
            identity.execution.supported.join(", ")
        ));
    }
    if let Some(image) = identity.execution.image.as_deref() {
        execution.push(format!("image={image}"));
    }
    if !execution.is_empty() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Execution:"),
            execution.join(", ")
        ));
    }
    let mut count_parts = vec![
        format!("runtimes={}", identity.counts.runtimes),
        format!("tools={}", identity.counts.tools),
        format!("env={}", identity.counts.env),
        format!("services={}", identity.counts.services),
        format!("checks={}", identity.counts.checks),
        format!("tasks={}", identity.counts.tasks),
    ];
    if let Some(repos) = identity.counts.repos {
        count_parts.push(format!("repos={repos}"));
    }
    if let Some(policies) = identity.counts.policies {
        count_parts.push(format!("policies={policies}"));
    }
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Counts:"),
        count_parts.join(", ")
    ));
    stdout
}

fn render_up_json(
    path: &str,
    member: Option<&str>,
    status: &str,
    phase: &str,
    cause: Option<&str>,
    report: DoctorReport,
    ready: bool,
    stderr: Option<&str>,
    service: Option<&str>,
    task: Option<&str>,
    exit_code: Option<i32>,
    receipt: &ExecutionReceipt,
) -> CommandOutput {
    let receipt = normalized_up_receipt(member, status, phase, &report.findings, stderr, receipt);
    CommandOutput {
        stdout: to_json(&UpStatus {
            ok: ready,
            path,
            status,
            phase,
            cause,
            findings: &report.findings,
            receipt,
            stderr,
            service,
            task,
            exit_code,
        }),
        stderr: None,
        exit_code: exit_code.unwrap_or(if ready { 0 } else { 1 }),
    }
}

fn render_workspace_tasks_text(path: &str, repos: &[WorkspaceRepoTasksReport]) -> CommandOutput {
    let mut stdout = format_command_header("WORKSPACE TASKS", path);
    stdout.push_str(&format!("\n\n{}\n", paint_section_title("Overview")));
    stdout.push_str(&format!(
        "\n {}  {} {}",
        summary_bullet(),
        paint_key("Use:"),
        "inventory of declared workspace tasks by repo"
    ));

    for repo in repos {
        stdout.push_str(&format!(
            "\n\n{} {} [{}] ({})",
            list_bullet(),
            paint(&repo.name, "1"),
            if repo.required {
                "required"
            } else {
                "optional"
            },
            if repo.acquired {
                "acquired"
            } else {
                "not acquired"
            }
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Path:"),
            compact_repo_path(Path::new(&repo.path))
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Contract:"),
            compact_contract_path(Path::new(&repo.contract_path))
        ));
        if !repo.depends_on.is_empty() {
            stdout.push_str(&format!(
                "\n{} {}",
                paint_key("Depends on:"),
                repo.depends_on.join(", ")
            ));
        }

        if !repo.acquired {
            stdout.push_str(&format!("\n{} repo not acquired", paint_key("Tasks:")));
            continue;
        }

        if repo.tasks.is_empty() {
            stdout.push_str(&format!("\n{} none", paint_key("Tasks:")));
            continue;
        }

        for task in &repo.tasks {
            stdout.push_str(&format!(
                "\n{} {} ({})",
                list_bullet(),
                task.name,
                task.kind
            ));
            if let Some(repo_task) = task.repo_task.as_deref() {
                stdout.push_str(&format!(" repo_task={repo_task}"));
            }
            if !task.depends_on.is_empty() {
                stdout.push_str(&format!(" depends_on={}", task.depends_on.join(",")));
            }
            if !task.requires_services.is_empty() {
                stdout.push_str(&format!(
                    " requires_services={}",
                    task.requires_services.join(",")
                ));
            }
            if !task.effects.is_empty() {
                stdout.push_str(&format!(
                    " effects={}",
                    render_task_effects_text(&task.effects)
                ));
            }
            if !task.after_success.is_empty() {
                stdout.push_str(&format!(" after_success={}", task.after_success.join(",")));
            }
            if !task.after_failure.is_empty() {
                stdout.push_str(&format!(" after_failure={}", task.after_failure.join(",")));
            }
            if !task.after_always.is_empty() {
                stdout.push_str(&format!(" after_always={}", task.after_always.join(",")));
            }
            if let Some(description) = task.description.as_deref() {
                stdout.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Description:"),
                    description
                ));
            }
            if let Some(launch) = task.launch.as_ref() {
                stdout.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Launch:"),
                    render_workspace_task_launch_text(launch)
                ));
            }
            if let Some(prepare) = task.prepare.as_ref() {
                stdout.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Prepare:"),
                    render_workspace_task_prepare_text(prepare)
                ));
            }
            if let Some(aggregate) = task.aggregate.as_ref() {
                stdout.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Aggregate:"),
                    render_task_aggregate_text(aggregate)
                ));
            }
        }
    }

    append_markdown_table(
        &mut stdout,
        "Repos",
        &[
            "Repo",
            "Required",
            "Acquired",
            "Path",
            "Contract",
            "Depends On",
        ],
        repos.iter().map(|repo| {
            vec![
                repo.name.clone(),
                if repo.required {
                    String::from("required")
                } else {
                    String::from("optional")
                },
                if repo.acquired {
                    String::from("acquired")
                } else {
                    String::from("not acquired")
                },
                compact_repo_path(Path::new(&repo.path)),
                compact_contract_path(Path::new(&repo.contract_path)),
                if repo.depends_on.is_empty() {
                    String::from("-")
                } else {
                    repo.depends_on.join(", ")
                },
            ]
        }),
    );

    let task_rows = repos.iter().flat_map(|repo| {
        repo.tasks.iter().map(|task| {
            vec![
                repo.name.clone(),
                task.name.clone(),
                task.kind.clone(),
                task.repo_task.clone().unwrap_or_else(|| String::from("-")),
                if task.depends_on.is_empty() {
                    String::from("-")
                } else {
                    task.depends_on.join(",")
                },
                if task.requires_services.is_empty() {
                    String::from("-")
                } else {
                    task.requires_services.join(",")
                },
                [
                    task.repo_task
                        .as_ref()
                        .map(|repo_task| format!("repo={repo_task}")),
                    if task.after_success.is_empty() {
                        None
                    } else {
                        Some(format!("success={}", task.after_success.join(",")))
                    },
                    if task.after_failure.is_empty() {
                        None
                    } else {
                        Some(format!("failure={}", task.after_failure.join(",")))
                    },
                    if task.after_always.is_empty() {
                        None
                    } else {
                        Some(format!("always={}", task.after_always.join(",")))
                    },
                ]
                .into_iter()
                .flatten()
                .collect::<Vec<_>>()
                .join(" "),
                render_task_effects_text(&task.effects),
                task.run
                    .clone()
                    .or(task.script.clone())
                    .or(task.launch.as_ref().map(render_workspace_task_launch_text))
                    .or(task
                        .prepare
                        .as_ref()
                        .map(render_workspace_task_prepare_text))
                    .or(task.aggregate.as_ref().map(render_task_aggregate_text))
                    .unwrap_or_else(|| String::from("-")),
                format!(
                    "`ota run {} {}`",
                    task.name,
                    compact_repo_path(Path::new(&repo.path))
                ),
            ]
        })
    });
    append_markdown_table(
        &mut stdout,
        "Tasks",
        &[
            "Repo",
            "Task",
            "Kind",
            "Binding",
            "Depends On",
            "Requires Services",
            "Hooks",
            "Effects",
            "Command",
            "Use",
        ],
        task_rows,
    );

    CommandOutput::success(stdout)
}

fn render_workspace_list_text(path: &str, repos: &[WorkspaceRepoListReport]) -> CommandOutput {
    let mut stdout = format_command_header("WORKSPACE LIST", path);

    if repos.is_empty() {
        stdout.push_str(&format!("\n\n{} none", info_bullet()));
        return CommandOutput::success(stdout);
    }

    if concise_mode() {
        for repo in repos {
            let mut line = format!(
                "{} {} [{}] ({})",
                list_bullet(),
                paint(&repo.name, "1"),
                if repo.required {
                    "required"
                } else {
                    "optional"
                },
                if repo.acquired {
                    paint("ACQUIRED", "1;38;2;192;192;192")
                } else {
                    paint("NOT ACQUIRED", "1;93")
                }
            );
            if !repo.contract_present {
                line.push_str(&format!(
                    " {}",
                    paint("(contract: missing)", "1;38;2;255;235;59")
                ));
            }
            if !repo.depends_on.is_empty() {
                line.push_str(&format!(" depends_on={}", repo.depends_on.join(",")));
            }
            stdout.push_str(&format!("\n\n{line}"));
            stdout.push_str(&format!(
                "\n  {} {}",
                paint_key("Status:"),
                render_status_word(&repo.status)
            ));
        }
        return CommandOutput::success(stdout);
    }

    for repo in repos {
        stdout.push_str(&format!(
            "\n\n{} {} [{}] ({})",
            list_bullet(),
            paint(&repo.name, "1"),
            if repo.required {
                "required"
            } else {
                "optional"
            },
            if repo.acquired {
                paint("ACQUIRED", "1;38;2;192;192;192")
            } else {
                paint("NOT ACQUIRED", "1;93")
            }
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Status:"),
            render_status_word(&repo.status)
        ));
        stdout.push_str(&format!(
            "\n{} {}",
            paint_key("Path:"),
            compact_repo_path(Path::new(&repo.path))
        ));
        if repo.contract_present {
            stdout.push_str(&format!(
                "\n{} {}",
                paint_key("Contract:"),
                compact_contract_path(Path::new(&repo.contract_path))
            ));
        } else {
            stdout.push_str(&format!(
                "\n{} {} (run {})",
                paint_key("Contract:"),
                paint("missing", "1;38;2;255;235;59"),
                paint_code(&format!(
                    "`ota init {}`",
                    compact_repo_path(Path::new(&repo.path))
                ))
            ));
        }
        if repo.depends_on.is_empty() {
            stdout.push_str(&format!("\n{} -", paint_key("Depends On:")));
        } else {
            stdout.push_str(&format!(
                "\n{} {}",
                paint_key("Depends On:"),
                repo.depends_on.join(", ")
            ));
        }
        if let Some(execution) = repo.execution.as_ref() {
            stdout.push_str(&render_workspace_execution_text(execution));
        }
    }

    CommandOutput::success(stdout)
}

fn render_workspace_execution_text(execution: &WorkspaceExecutionSummary) -> String {
    let mut lines = vec![String::new(), paint_section_title("Execution")];

    if let Some(preferred) = execution.preferred.as_deref() {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Preferred:"),
            paint_backticked_code(preferred)
        ));
    }
    if !execution.supported.is_empty() {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Supported:"),
            render_inline_code_list(&execution.supported)
        ));
    }
    if let Some(lifecycle) = execution.lifecycle.as_deref() {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Lifecycle:"),
            paint_backticked_code(lifecycle)
        ));
    }
    if let Some(backends) = execution.backends.as_ref() {
        if let Some(container) = backends.container.as_ref() {
            lines.push(format!(
                " {}  {} {}",
                summary_bullet(),
                paint_key("Container:"),
                paint_backticked_code(&container.image)
            ));
        }
        if let Some(remote) = backends.remote.as_ref() {
            let mut details = vec![format!(
                "{} {}",
                paint_key("provider"),
                paint_backticked_code(&remote.provider)
            )];
            if let Some(target) = remote.target.as_deref() {
                details.push(format!(
                    "{} {}",
                    paint_key("target"),
                    paint_backticked_code(target)
                ));
            }
            if let Some(cwd) = remote.cwd.as_deref() {
                details.push(format!(
                    "{} {}",
                    paint_key("cwd"),
                    paint_backticked_code(cwd)
                ));
            }
            lines.push(format!(
                " {}  {} {}",
                summary_bullet(),
                paint_key("Remote:"),
                details.join(" ")
            ));
        }
    }
    if !execution.env.is_empty() {
        lines.push(format!(
            " {}  {} workspace policy > org policy > process > declared env sources > contract default > required missing",
            summary_bullet(),
            paint_key("Env precedence:")
        ));
        for item in &execution.env {
            let mut details = Vec::new();
            if let Some(source) = item.source.as_deref() {
                details.push(source.to_string());
            } else if item.default.is_some() {
                details.push(String::from("contract default"));
            } else {
                details.push(String::from("missing"));
            }
            if item.required {
                details.push(String::from("required"));
            }
            if let Some(default) = item.default.as_deref() {
                details.push(format!("default={default}"));
            }
            if !item.allowed.is_empty() {
                details.push(format!("allowed={}", item.allowed.join(", ")));
            }
            lines.push(format!(
                " {}  {} {} ({})",
                summary_bullet(),
                paint_key("Env:"),
                paint_backticked_code(&item.name),
                details.join(", ")
            ));
        }
    }

    lines.join("\n")
}

fn append_output_block(buffer: &mut String, label: &str, contents: Option<&str>) {
    let Some(contents) = contents.map(str::trim_end) else {
        return;
    };
    if contents.is_empty() {
        return;
    }

    buffer.push_str(&format!("\n  {} ", paint_key(&format!("{label}:"))));
    let Some(excerpt) = run_output_excerpt(contents, "", 14) else {
        return;
    };
    if excerpt.omitted_before > 0 || excerpt.omitted_after > 0 {
        buffer.push_str(&format!(
            "\n    {} {}",
            summary_bullet(),
            stylize_inline_text(&output_excerpt_notice(&excerpt))
        ));
    }
    for line in excerpt.lines {
        buffer.push_str(&format!(
            "\n    {} {}",
            summary_bullet(),
            stylize_inline_text(&line)
        ));
    }
}

fn append_markdown_table(
    output: &mut String,
    title: &str,
    headers: &[&str],
    rows: impl IntoIterator<Item = Vec<String>>,
) {
    let rows = rows.into_iter().collect::<Vec<_>>();

    output.push_str(&format!("\n\n{}:", paint_section_title(title)));

    if rows.is_empty() {
        output.push_str(&format!("\n{} none", list_bullet()));
        return;
    }

    for (idx, row) in rows.into_iter().enumerate() {
        if idx == 0 {
            output.push('\n');
        }
        output.push('\n');
        let first_header = headers.first().copied().unwrap_or("Item");
        let compact_repo_row = first_header == "Repo";
        output.push_str(&format!(
            "{}{}",
            list_bullet(),
            if compact_repo_row { " " } else { "  " }
        ));
        if compact_repo_row {
            output.push_str(&paint(
                &render_table_cell(row.first().map_or("-", String::as_str)),
                "1",
            ));
        } else {
            output.push_str(&paint_key(first_header));
            output.push_str(": ");
            output.push_str(&paint(
                &render_table_cell(row.first().map_or("-", String::as_str)),
                "1",
            ));
        }

        for (idx, header) in headers.iter().enumerate().skip(1) {
            let value = row.get(idx).map_or("-", String::as_str);
            output.push_str(if compact_repo_row { "\n" } else { "\n  " });
            output.push_str(&paint_key(header));
            output.push_str(": ");
            output.push_str(&render_table_cell(value));
        }

        output.push('\n');
    }
}

fn severity_color(severity: FindingSeverity) -> &'static str {
    match severity {
        FindingSeverity::Error => "1;31",
        FindingSeverity::Warn => "1;33",
        FindingSeverity::Info => "1;36",
    }
}

fn render_severity(severity: FindingSeverity) -> String {
    if plain_mode() {
        return match severity {
            FindingSeverity::Error => String::from("ERROR"),
            FindingSeverity::Warn => String::from("WARN"),
            FindingSeverity::Info => String::from("INFO"),
        };
    }

    let color = severity_color(severity);
    format!(
        "{} {}",
        paint("◉", color),
        paint(
            match severity {
                FindingSeverity::Error => "ERROR",
                FindingSeverity::Warn => "WARN",
                FindingSeverity::Info => "INFO",
            },
            color
        )
    )
}

fn render_finding_summary(severity: FindingSeverity, summary: &str) -> String {
    let _ = severity;
    paint(summary, "1")
}

fn render_finding_summary_with_count(
    severity: FindingSeverity,
    summary: &str,
    count: usize,
) -> String {
    format!(
        "{} {}",
        render_finding_summary(severity, summary),
        paint_group_meta(&format!("({count})"))
    )
}

fn render_valid_status() -> String {
    if plain_mode() {
        String::from("VALID")
    } else {
        format!(
            "{} {}",
            primary_success_marker(),
            paint("VALID", "1;38;2;0;255;120")
        )
    }
}

fn render_resolved_status() -> String {
    if plain_mode() {
        String::from("RESOLVED")
    } else {
        format!(
            "{} {}",
            primary_success_marker(),
            paint("RESOLVED", "1;38;2;0;255;120")
        )
    }
}

fn render_named_status(status: &str, marker: String, color: &str) -> String {
    if plain_mode() {
        status.to_string()
    } else {
        format!("{marker} {}", paint(status, color))
    }
}

fn render_readiness_status(ready: bool) -> String {
    if ready {
        render_named_status("READY", primary_success_marker(), "1;38;2;0;255;120")
    } else {
        render_named_status("NOT READY", primary_warn_marker(), "1;38;2;255;235;59")
    }
}

fn render_status_line(status: &str) -> String {
    match status.trim() {
        "READY" => render_readiness_status(true),
        "NOT READY" => render_readiness_status(false),
        "VALID" => render_valid_status(),
        "RESOLVED" => render_resolved_status(),
        "MERGED" | "REWRITTEN" | "REVIEWED" | "CONFIRMED" | "ALREADY REVIEWED" => {
            render_named_status(status.trim(), primary_success_marker(), "1;38;2;0;255;120")
        }
        "NO CHANGES" | "PREVIEW" => {
            render_named_status(status.trim(), primary_info_marker(), "1;38;2;102;245;255")
        }
        "BLOCKED" | "UNRESOLVED" | "WARN" | "REVIEW REQUIRED" => {
            render_named_status(status.trim(), primary_warn_marker(), "1;38;2;255;235;59")
        }
        value if value.contains("INVALID") || value.contains("UNREADABLE") => {
            render_named_status(value, primary_error_marker(), "1;38;2;255;122;122")
        }
        value if value.contains("FAILED") => render_failed_status_label(value),
        other => other.to_string(),
    }
}

fn render_status_word(status: &str) -> String {
    let trimmed = status.trim();
    if plain_mode() {
        return trimmed.to_string();
    }
    match trimmed {
        "READY" => paint("READY", "1;38;2;0;255;120"),
        "NOT READY" => paint("NOT READY", "1;38;2;255;235;59"),
        "VALID" => paint("VALID", "1;38;2;0;255;120"),
        "RESOLVED" => paint("RESOLVED", "1;38;2;0;255;120"),
        "MERGED" | "REWRITTEN" => paint(trimmed, "1;38;2;0;255;120"),
        "NO CHANGES" => paint(trimmed, "1;38;2;102;245;255"),
        "BLOCKED" | "UNRESOLVED" | "WARN" => paint(trimmed, "1;38;2;255;235;59"),
        "INVALID CONTRACT" | "UNREADABLE CONTRACT" | "MISSING CONTRACT" => {
            paint(trimmed, "1;38;2;255;122;122")
        }
        value if value.contains("FAILED") => render_failed_status_label(value),
        other => other.to_string(),
    }
}

fn render_completion_status_word(status: &str) -> String {
    let trimmed = status.trim();
    if plain_mode() {
        return trimmed.to_string();
    }
    match trimmed {
        "installed" | "updated" | "already configured" | "present" | "removed" => {
            paint(trimmed, "1;38;2;0;255;120")
        }
        "needs update" | "missing" | "not configured" => paint(trimmed, "1;38;2;255;235;59"),
        other => paint(other, "1;37"),
    }
}

pub(crate) fn render_completion_success_text(
    shell: &str,
    file: &str,
    status: Option<&str>,
    hook: Option<&str>,
    binary: Option<&str>,
    completion_file: Option<&str>,
    next: &str,
) -> String {
    let overview_status = match (status.map(str::trim), hook.map(str::trim)) {
        (Some("removed"), _) => "RESOLVED",
        (Some("missing" | "needs update" | "not configured"), _)
        | (_, Some("missing" | "needs update" | "not configured")) => "WARN",
        _ => "READY",
    };

    let mut lines = vec![
        format_command_header("COMPLETION", shell),
        String::new(),
        render_status_line(overview_status),
        String::new(),
        paint_section_title("Overview"),
    ];
    if let Some(binary) = binary {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Binary:"),
            paint_code(binary)
        ));
    }
    lines.push(format!(
        " {}  {} {}",
        summary_bullet(),
        paint_key("File:"),
        paint_code(file)
    ));
    if let Some(completion_file) = completion_file {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Completion file:"),
            paint_code(completion_file)
        ));
    }
    if let Some(status) = status {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Status:"),
            render_completion_status_word(status)
        ));
    }
    if let Some(hook) = hook {
        lines.push(format!(
            " {}  {} {}",
            summary_bullet(),
            paint_key("Hook:"),
            render_completion_status_word(hook)
        ));
    }
    lines.push(format!(
        " {}  {} {}",
        summary_bullet(),
        paint_key("Shell:"),
        paint(shell, "1")
    ));
    lines.push(format_next_timeline(&[next.to_string()]));
    lines.join("\n")
}

