fn execution_receipt_summary(
    findings: &[Finding],
    step_count: usize,
    repo_count: Option<usize>,
    ready_count: Option<usize>,
    not_ready_count: Option<usize>,
) -> ExecutionReceiptSummary {
    let error_count = findings
        .iter()
        .filter(|finding| finding.severity == FindingSeverity::Error)
        .count();
    let warn_count = findings
        .iter()
        .filter(|finding| finding.severity == FindingSeverity::Warn)
        .count();
    let info_count = findings
        .iter()
        .filter(|finding| finding.severity == FindingSeverity::Info)
        .count();

    ExecutionReceiptSummary {
        error_count,
        warn_count,
        info_count,
        step_count,
        repo_count,
        ready_count,
        not_ready_count,
    }
}

fn native_prerequisite_provisioning_lines(
    platform: &crate::schema::NativePrerequisitePlatformSpec,
) -> Vec<String> {
    let mut lines = Vec::new();
    lines.extend(native_prerequisite_manual_preparation_lines(platform));
    lines.extend(native_prerequisite_package_preparation_lines(platform));
    lines
}

fn native_prerequisite_manual_preparation_lines(
    platform: &crate::schema::NativePrerequisitePlatformSpec,
) -> Vec<String> {
    let mut lines = Vec::new();
    if let Some(command) = platform
        .install
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        lines.push(format!("run `{command}`"));
    }
    if platform.xcode_clt {
        lines.push(String::from("install Xcode Command Line Tools"));
    }
    if let Some(visual_studio) = platform.visual_studio.as_ref() {
        if visual_studio.components.is_empty() {
            lines.push(String::from("install Visual Studio Build Tools"));
        } else {
            lines.push(format!(
                "install Visual Studio Build Tools with components: `{}`",
                visual_studio.components.join(" ")
            ));
        }
    } else if platform.visual_studio_build_tools {
        lines.push(String::from("install Visual Studio Build Tools"));
    }
    lines
}

fn native_prerequisite_package_preparation_lines(
    platform: &crate::schema::NativePrerequisitePlatformSpec,
) -> Vec<String> {
    let mut lines = Vec::new();
    if !platform.apt.is_empty() {
        lines.push(format!(
            "install apt packages: `{}`",
            platform.apt.join(" ")
        ));
    }
    if !platform.brew.is_empty() {
        lines.push(format!(
            "install Homebrew packages: `{}`",
            platform.brew.join(" ")
        ));
    }
    if !platform.winget.is_empty() {
        lines.push(format!(
            "install winget packages: `{}`",
            platform.winget.join(" ")
        ));
    }
    if !platform.choco.is_empty() {
        lines.push(format!(
            "install Chocolatey packages: `{}`",
            platform.choco.join(" ")
        ));
    }
    if !platform.scoop.is_empty() {
        lines.push(format!(
            "install Scoop packages: `{}`",
            platform.scoop.join(" ")
        ));
    }
    lines
}

fn native_prerequisite_activation_kind_label(
    activation: &crate::schema::NativePrerequisiteActivationSpec,
) -> &'static str {
    match activation.kind {
        crate::schema::NativePrerequisiteActivationKind::VisualStudioDevShell => {
            "visual_studio_dev_shell"
        }
        crate::schema::NativePrerequisiteActivationKind::Command => "command",
    }
}

fn native_prerequisite_activation_shell_label(
    shell: crate::schema::NativePrerequisiteActivationShell,
) -> &'static str {
    match shell {
        crate::schema::NativePrerequisiteActivationShell::Sh => "sh",
        crate::schema::NativePrerequisiteActivationShell::Bash => "bash",
        crate::schema::NativePrerequisiteActivationShell::Zsh => "zsh",
        crate::schema::NativePrerequisiteActivationShell::Pwsh => "pwsh",
        crate::schema::NativePrerequisiteActivationShell::Cmd => "cmd",
    }
}

fn receipt_native_prerequisites(
    contract: &Contract,
    task: Option<&str>,
    backend: Backend,
    current_os: &str,
    activation_applied: bool,
) -> Vec<crate::output::ExecutionReceiptNativePrerequisite> {
    if backend != Backend::Native {
        return Vec::new();
    }
    let Some(task_name) = task else {
        return Vec::new();
    };
    let Some(task_spec) = contract.tasks.get(task_name) else {
        return Vec::new();
    };
    let mut prerequisites = Vec::new();
    let mut seen = BTreeSet::new();
    let context_name = task_spec.context_for_backend(contract.execution.as_ref(), backend);
    for name in task_spec.scoped_native_requirements_for_execution(backend, context_name) {
        if !seen.insert(name.clone()) {
            continue;
        }
        let Some(prerequisite) = contract.native_prerequisites.get(name.as_str()) else {
            continue;
        };
        let Some(platform) = prerequisite.platform_for_os(current_os) else {
            continue;
        };
        let requires = native_prerequisite_receipt_requires(platform, current_os);
        prerequisites.push(crate::output::ExecutionReceiptNativePrerequisite {
            name: name.clone(),
            required: prerequisite.required,
            platform: current_os.to_string(),
            check: prerequisite.check_for_os(current_os).map(str::to_string),
            activation: platform.activation.as_ref().map(|activation| {
                crate::output::ExecutionReceiptNativeActivation {
                    kind: native_prerequisite_activation_kind_label(activation).to_string(),
                    applied: activation_applied,
                    arch: activation.arch.clone(),
                    shell: activation
                        .shell
                        .map(native_prerequisite_activation_shell_label)
                        .map(str::to_string),
                    run: activation.run.clone(),
                }
            }),
            requires,
            provisioning: native_prerequisite_provisioning_lines(platform),
            note: platform
                .note
                .as_deref()
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_string),
        });
    }
    prerequisites
}

fn native_prerequisite_receipt_requires(
    platform: &crate::schema::NativePrerequisitePlatformSpec,
    current_os: &str,
) -> Option<crate::output::ExecutionReceiptNativeRequires> {
    let requires = &platform.requires;
    if requires.runtimes.is_empty()
        && requires.tools.is_empty()
        && requires.toolchains.is_empty()
        && requires.env.is_empty()
        && requires.checks.is_empty()
    {
        return None;
    }
    Some(crate::output::ExecutionReceiptNativeRequires {
        runtimes: requires
            .runtimes
            .iter()
            .map(|(name, requirement)| {
                (
                    name.clone(),
                    requirement.version_for_os(current_os).to_string(),
                )
            })
            .collect(),
        tools: requires
            .tools
            .iter()
            .map(|(name, requirement)| {
                (
                    name.clone(),
                    requirement.version_for_os(current_os).to_string(),
                )
            })
            .collect(),
        toolchains: requires.toolchains.clone(),
        env: requires.env.clone(),
        checks: requires.checks.clone(),
        source: String::from("native_prerequisite.platform.requires"),
    })
}

fn execution_receipt_step(
    order: usize,
    label: impl Into<String>,
    status: impl Into<String>,
    detail: Option<String>,
    exit_code: Option<i32>,
) -> ExecutionReceiptStep {
    ExecutionReceiptStep {
        order,
        label: label.into(),
        status: status.into(),
        detail,
        exit_code,
        target_resolutions: Vec::new(),
        backend_fulfillment: None,
        shared_local_backend: None,
    }
}

fn execution_summary_status_for_step(step: &ExecutionReceiptStep) -> &'static str {
    match step.status.trim() {
        "READY" => "success",
        "INTERRUPTED" => "interrupted",
        "PREVIEW" => "preview",
        "SKIPPED" | "NOT ACQUIRED" => "skipped",
        "NOT READY" => match step.label.trim() {
            "preconditions" | "provisioning" | "validation" | "dependencies" => "blocked",
            _ => "failed",
        },
        "BLOCKED" | "WARN" | "MISSING" | "MISSING CONTRACT" | "UNRESOLVED" | "INVALID CONTRACT" => {
            "blocked"
        }
        value if value.contains("FAILED") => "failed",
        _ => "failed",
    }
}

fn aggregate_execution_summary_status(
    ok: bool,
    steps: &[ExecutionReceiptStep],
    blocked: &[String],
) -> String {
    if steps.is_empty() {
        return if ok {
            String::from("success")
        } else if !blocked.is_empty() {
            String::from("blocked")
        } else {
            String::from("failed")
        };
    }

    let mapped_statuses: Vec<&'static str> = steps
        .iter()
        .map(execution_summary_status_for_step)
        .collect();

    if mapped_statuses.iter().all(|status| *status == "preview") {
        return String::from("preview");
    }

    if mapped_statuses.iter().all(|status| *status == "skipped") {
        return String::from("skipped");
    }

    if ok {
        return String::from("success");
    }

    if mapped_statuses
        .iter()
        .any(|status| *status == "interrupted")
    {
        return String::from("interrupted");
    }

    if mapped_statuses.iter().any(|status| *status == "failed") {
        return String::from("failed");
    }

    if !blocked.is_empty() || mapped_statuses.iter().any(|status| *status == "blocked") {
        return String::from("blocked");
    }

    if mapped_statuses.iter().any(|status| *status == "skipped") {
        return String::from("skipped");
    }

    String::from("failed")
}

fn doctor_mode_execution_overrides(
    mode: DoctorMode,
    lifecycle: Option<Lifecycle>,
) -> ExecutionOverrides {
    ExecutionOverrides {
        backend: Some(backend_for_doctor_mode(mode)),
        lifecycle: lifecycle.or(match mode {
            DoctorMode::Container => Some(Lifecycle::Ephemeral),
            DoctorMode::Native | DoctorMode::Remote => None,
        }),
        host_port: None,
        memory: None,
        skip_deps: false,
    }
}

fn backend_for_doctor_mode(mode: DoctorMode) -> Backend {
    match mode {
        DoctorMode::Native => Backend::Native,
        DoctorMode::Container => Backend::Container,
        DoctorMode::Remote => Backend::Remote,
    }
}

fn doctor_mode_from_execution_overrides(backend: Option<Backend>) -> Option<DoctorMode> {
    backend.map(|backend| match backend {
        Backend::Native => DoctorMode::Native,
        Backend::Container => DoctorMode::Container,
        Backend::Remote => DoctorMode::Remote,
    })
}

fn doctor_mode_for_contract(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> DoctorMode {
    if let Some(task_name) = selected_up_primary_task_name(contract, workflow_name) {
        return match effective_task_execution(contract, task_name, overrides).backend {
            Backend::Native => DoctorMode::Native,
            Backend::Container => DoctorMode::Container,
            Backend::Remote => DoctorMode::Native,
        };
    }

    match effective_execution(contract, overrides).0 {
        Backend::Native => DoctorMode::Native,
        Backend::Container => DoctorMode::Container,
        Backend::Remote => DoctorMode::Native,
    }
}

fn doctor_selected_command(
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> Option<String> {
    let mode = doctor_mode?;
    let mut command = match mode {
        DoctorMode::Native => String::from("ota doctor"),
        DoctorMode::Container => String::from("ota doctor --mode container"),
        DoctorMode::Remote => String::from("ota doctor --mode remote"),
    };
    if let Some(lifecycle) = doctor_lifecycle {
        command.push_str(" --lifecycle ");
        command.push_str(match lifecycle {
            Lifecycle::Persistent => "persistent",
            Lifecycle::Ephemeral => "ephemeral",
        });
    }
    Some(command)
}

fn up_preview_selected_command(
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> String {
    let mut command = match doctor_mode.unwrap_or(DoctorMode::Native) {
        DoctorMode::Native => String::from("ota up --dry-run"),
        DoctorMode::Container => String::from("ota up --dry-run --mode container"),
        DoctorMode::Remote => String::from("ota up --dry-run --mode remote"),
    };
    if let Some(lifecycle) = doctor_lifecycle {
        command.push_str(" --lifecycle ");
        command.push_str(match lifecycle {
            Lifecycle::Persistent => "persistent",
            Lifecycle::Ephemeral => "ephemeral",
        });
    }
    command
}

fn repo_readiness_receipt(
    contract_path: &Path,
    contract: &Contract,
    mode: DoctorMode,
    lifecycle: Option<Lifecycle>,
    workflow_name: Option<&str>,
    report: &DoctorReport,
) -> ExecutionReceipt {
    let context = doctor_report_execution_context(contract, contract_path, mode, lifecycle, report);
    let mut receipt = repo_execution_receipt(
        contract_path,
        contract,
        context,
        if report.ok { "READY" } else { "NOT READY" },
        "readiness",
        workflow_name,
        None,
        None,
        &report.findings,
        None,
        report
            .findings
            .iter()
            .find(|finding| finding.severity == FindingSeverity::Error)
            .or_else(|| report.findings.first())
            .map(|finding| rewrite_doctor_mode_command(&finding.next, Some(mode), lifecycle)),
    );
    receipt.native_prerequisites = selected_up_receipt_native_prerequisites(
        contract,
        doctor_mode_execution_overrides(mode, lifecycle),
        workflow_name,
        None,
    );
    receipt.blocked = report
        .findings
        .iter()
        .filter(|finding| finding.severity == FindingSeverity::Error)
        .map(|finding| finding.summary.clone())
        .collect();
    receipt
}

fn repo_execution_receipt(
    path: &Path,
    contract: &Contract,
    context: PhaseExecutionContext,
    status: &str,
    phase: &str,
    workflow_name: Option<&str>,
    service: Option<&str>,
    task: Option<&str>,
    findings: &[Finding],
    exit_code: Option<i32>,
    next: Option<String>,
) -> ExecutionReceipt {
    repo_execution_receipt_with_overrides(
        path,
        contract,
        context,
        status,
        phase,
        workflow_name,
        service,
        task,
        findings,
        exit_code,
        next,
        None,
    )
}

fn repo_execution_receipt_with_overrides(
    path: &Path,
    contract: &Contract,
    context: PhaseExecutionContext,
    status: &str,
    phase: &str,
    workflow_name: Option<&str>,
    service: Option<&str>,
    task: Option<&str>,
    findings: &[Finding],
    exit_code: Option<i32>,
    next: Option<String>,
    execution_overrides: Option<ExecutionOverrides>,
) -> ExecutionReceipt {
    let execution_backend = phase_execution_backend(&context).unwrap_or(Backend::Native);
    let effective_task_env = task
        .and_then(|task_name| contract.tasks.get(task_name))
        .map(|task| task.env_for_backend(contract.execution.as_ref(), execution_backend));
    let env_details = task
        .map(|task_name| {
            resolve_task_env_details_for_task(
                contract,
                path,
                task_name,
                effective_task_env.as_ref(),
            )
        })
        .unwrap_or_else(|| resolve_task_env_details(contract, path, effective_task_env.as_ref()))
        .unwrap_or_default();
    let declared_sources = load_declared_env_sources(contract, path);
    let detail = service
        .map(|service| format!("service `{service}`"))
        .or_else(|| task.map(|task| format!("task `{task}`")));
    let mut steps = Vec::new();
    steps.push(execution_receipt_step(
        1,
        phase.to_string(),
        status.to_string(),
        detail,
        exit_code,
    ));
    let ok = status == "READY" && exit_code.unwrap_or(0) == 0;
    let receipt_status = aggregate_execution_summary_status(ok, &steps, &[]);
    let native_prerequisites = receipt_native_prerequisites(
        contract,
        task,
        execution_backend,
        current_requirement_platform(),
        phase != "preview" && phase != "readiness",
    );
    let toolchains = task
        .map(|task_name| {
            selected_task_toolchain_summaries(contract, task_name, ExecutionOverrides::default())
        })
        .unwrap_or_else(|| fallback_toolchain_summaries_for_backend(contract, execution_backend));
    let toolchain_names = toolchain_summary_names(&toolchains);

    ExecutionReceipt {
        ok,
        path: path.display().to_string(),
        scope: String::from("repo"),
        contract: path.display().to_string(),
        contract_identity: Some(repo_contract_identity(contract)),
        contract_snapshot_hash: None,
        contract_snapshot_ref: None,
        assumption_set_hash: None,
        workspace: None,
        backend: context.backend,
        context: context.context,
        lifecycle: context.lifecycle,
        image: context.image,
        container_memory_bytes: context.container_memory_bytes,
        target: context.target,
        provider: context.provider,
        cwd: context.cwd,
        acquired: Vec::new(),
        env: env_details
            .iter()
            .map(|(name, value)| (name.clone(), receipt_env_value(value)))
            .collect(),
        env_sources: env_details
            .iter()
            .map(|(name, value)| receipt_env_source_entry(name, value, &declared_sources))
            .collect(),
        workflow_env_artifacts: selected_workflow_env_profile_rendered_artifact_entries(
            contract,
            path,
            workflow_name,
        ),
        native_prerequisites,
        toolchains,
        runtime: None,
        logs: None,
        service_termination: None,
        host_service_cleanup: Vec::new(),
        backend_fulfillment: None,
        workloads: BTreeMap::new(),
        policy: execution_policy_lines_for_toolchain_names(
            contract,
            path,
            execution_backend,
            &toolchain_names,
        ),
        dependency_steps: planned_dependency_steps_for_task(contract, task, execution_overrides),
        steps,
        status: Some(receipt_status),
        failed_task: None,
        failed_dependency: None,
        failure_origin: None,
        blocked: Vec::new(),
        summary: execution_receipt_summary(findings, 1, None, None, None),
        next,
    }
}

fn phase_execution_backend(context: &PhaseExecutionContext) -> Option<Backend> {
    match context.backend.as_deref() {
        Some("native") => Some(Backend::Native),
        Some("container") => Some(Backend::Container),
        Some("remote") => Some(Backend::Remote),
        _ => None,
    }
}

fn matching_phase_execution_context_name(
    contract: &Contract,
    backend: Backend,
    lifecycle: Option<Lifecycle>,
) -> Option<String> {
    crate::execution::matching_declared_execution_context_name(
        contract.execution.as_ref(),
        backend,
        lifecycle,
    )
    .map(str::to_string)
}

fn execution_context_container_backend<'a>(
    contract: &'a Contract,
    context_name: Option<&str>,
) -> Option<&'a ContainerBackend> {
    context_name
        .and_then(|name| named_execution_context(contract, name))
        .and_then(|(_, context)| context.container.as_ref())
}

fn execution_context_remote_backend<'a>(
    contract: &'a Contract,
    context_name: Option<&str>,
) -> Option<&'a crate::schema::RemoteBackend> {
    context_name
        .and_then(|name| named_execution_context(contract, name))
        .and_then(|(_, context)| context.remote.as_ref())
}

fn phase_execution_image(
    contract: &Contract,
    backend: Backend,
    context_name: Option<&str>,
) -> Option<String> {
    if backend != Backend::Container {
        return None;
    }
    execution_context_container_backend(contract, context_name)
        .map(|container| container.image.clone())
        .or_else(|| execution_image(contract, backend))
}

fn phase_execution_target(
    contract: &Contract,
    path: &Path,
    backend: Backend,
    lifecycle: Option<Lifecycle>,
    context_name: Option<&str>,
) -> Option<String> {
    match backend {
        Backend::Native => None,
        Backend::Remote => execution_context_remote_backend(contract, context_name)
            .and_then(|remote| remote.target.clone())
            .or_else(|| execution_target(contract, path, backend, lifecycle)),
        Backend::Container => {
            let container = execution_context_container_backend(contract, context_name);
            match lifecycle {
                Some(Lifecycle::Persistent) => container
                    .map(|container| {
                        let engine = selected_container_engine_from_backend(Some(container))
                            .unwrap_or_else(|| {
                                container_engine_candidates_from_backend(Some(container))
                                    .into_iter()
                                    .next()
                                    .unwrap_or_else(|| String::from("docker"))
                            });
                        persistent_container_name(
                            path.parent().unwrap_or(path),
                            &container.image,
                            &engine,
                        )
                    })
                    .or_else(|| execution_target(contract, path, backend, lifecycle)),
                Some(Lifecycle::Ephemeral) | None => container
                    .map(|container| {
                        let engine = selected_container_engine_from_backend(Some(container))
                            .unwrap_or_else(|| {
                                container_engine_candidates_from_backend(Some(container))
                                    .into_iter()
                                    .next()
                                    .unwrap_or_else(|| String::from("docker"))
                            });
                        ephemeral_container_name(
                            path.parent().unwrap_or(path),
                            &container.image,
                            &engine,
                        )
                    })
                    .or_else(|| ephemeral_container_target(contract, path)),
            }
        }
    }
}

fn phase_execution_provider(contract: &Contract, context_name: Option<&str>) -> Option<String> {
    execution_context_remote_backend(contract, context_name).map(|remote| remote.provider.clone())
}

fn phase_execution_cwd(contract: &Contract, context_name: Option<&str>) -> Option<String> {
    execution_context_remote_backend(contract, context_name).and_then(|remote| remote.cwd.clone())
}

fn effective_phase_container_backend<'a>(
    contract: &'a Contract,
    backend: Backend,
    context_name: Option<&str>,
) -> Option<&'a ContainerBackend> {
    if backend != Backend::Container {
        return None;
    }
    execution_context_container_backend(contract, context_name).or_else(|| {
        contract
            .execution
            .as_ref()
            .and_then(|execution| execution.backends.as_ref())
            .and_then(|backends| backends.container.as_ref())
    })
}

fn native_phase_execution_context() -> PhaseExecutionContext {
    PhaseExecutionContext {
        backend: Some(String::from("native")),
        ..PhaseExecutionContext::default()
    }
}

fn selected_phase_execution_context(
    contract: &Contract,
    path: &Path,
    overrides: ExecutionOverrides,
) -> PhaseExecutionContext {
    let (backend, lifecycle) = effective_execution(contract, overrides);
    let context = matching_phase_execution_context_name(contract, backend, lifecycle);
    PhaseExecutionContext {
        backend: Some(format_backend(backend).to_string()),
        context: context.clone(),
        lifecycle: lifecycle.map(format_lifecycle).map(str::to_string),
        image: phase_execution_image(contract, backend, context.as_deref()),
        container_memory_bytes: receipt_container_memory_bytes(
            effective_phase_container_backend(contract, backend, context.as_deref()),
            overrides.memory,
        ),
        target: phase_execution_target(contract, path, backend, lifecycle, context.as_deref()),
        provider: phase_execution_provider(contract, context.as_deref()),
        cwd: phase_execution_cwd(contract, context.as_deref()),
    }
}

fn effective_task_execution_target(
    path: &Path,
    effective: crate::runner::EffectiveTaskExecution<'_>,
) -> Option<String> {
    match effective.backend {
        Backend::Remote => effective.remote.and_then(|remote| remote.target.clone()),
        Backend::Container if effective.lifecycle == Some(Lifecycle::Persistent) => {
            let container = effective.container?;
            let engine =
                selected_container_engine_from_backend(Some(container)).unwrap_or_else(|| {
                    container_engine_candidates_from_backend(Some(container))
                        .into_iter()
                        .next()
                        .unwrap_or_else(|| String::from("docker"))
                });
            Some(persistent_container_name(
                path.parent().unwrap_or(path),
                &container.image,
                &engine,
            ))
        }
        Backend::Container | Backend::Native => None,
    }
}

fn task_phase_execution_context(
    contract: &Contract,
    path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    target: Option<String>,
) -> PhaseExecutionContext {
    let effective = effective_task_execution(contract, task_name, overrides);
    let provider = effective.remote.map(|remote| remote.provider.clone());
    let cwd = effective.remote.and_then(|remote| remote.cwd.clone());
    let mut context = PhaseExecutionContext {
        backend: Some(format_backend(effective.backend).to_string()),
        context: reported_task_context_for_backend(contract, task_name, effective.backend)
            .map(str::to_string),
        lifecycle: effective
            .lifecycle
            .map(format_lifecycle)
            .map(str::to_string),
        image: effective
            .container
            .map(|container| container.image.clone())
            .filter(|_| matches!(effective.backend, Backend::Container)),
        container_memory_bytes: match effective.backend {
            Backend::Container => {
                receipt_container_memory_bytes(effective.container, overrides.memory)
            }
            Backend::Native | Backend::Remote => None,
        },
        target: effective_task_execution_target(path, effective),
        provider,
        cwd,
    };
    if target.is_some() {
        context.target = target;
    }
    context
}

fn doctor_phase_execution_context(
    contract: &Contract,
    path: &Path,
    mode: DoctorMode,
    lifecycle: Option<Lifecycle>,
) -> PhaseExecutionContext {
    selected_phase_execution_context(
        contract,
        path,
        doctor_mode_execution_overrides(mode, lifecycle),
    )
}

fn doctor_report_execution_context(
    contract: &Contract,
    path: &Path,
    mode: DoctorMode,
    lifecycle: Option<Lifecycle>,
    report: &DoctorReport,
) -> PhaseExecutionContext {
    let mut context = doctor_phase_execution_context(contract, path, mode, lifecycle);
    if mode == DoctorMode::Container && contract_container_host_bound_scope_note_present(report) {
        context.target = None;
    } else if mode == DoctorMode::Container && context.target.is_none() {
        context.target = report.execution_target.clone();
    }
    context
}

fn contract_container_host_bound_scope_note_present(report: &DoctorReport) -> bool {
    report
        .findings
        .iter()
        .any(|finding| finding.summary == "Container readiness does not include host-only checks")
}

fn provisioning_phase_execution_context(
    contract: &Contract,
    path: &Path,
    target: &ProvisioningExecutionTarget,
) -> PhaseExecutionContext {
    match target {
        ProvisioningExecutionTarget::Native => PhaseExecutionContext {
            context: matching_phase_execution_context_name(contract, Backend::Native, None),
            ..native_phase_execution_context()
        },
        ProvisioningExecutionTarget::Container {
            image, lifecycle, ..
        } => {
            let context = matching_phase_execution_context_name(
                contract,
                Backend::Container,
                Some(*lifecycle),
            );
            PhaseExecutionContext {
                backend: Some(String::from("container")),
                context: context.clone(),
                lifecycle: Some(format_lifecycle(*lifecycle).to_string()),
                image: Some(image.clone()),
                container_memory_bytes: receipt_container_memory_bytes(
                    effective_phase_container_backend(
                        contract,
                        Backend::Container,
                        context.as_deref(),
                    ),
                    None,
                ),
                target: phase_execution_target(
                    contract,
                    path,
                    Backend::Container,
                    Some(*lifecycle),
                    context.as_deref(),
                )
                .and_then(|target| {
                    if *lifecycle == Lifecycle::Persistent {
                        Some(target)
                    } else {
                        None
                    }
                }),
                provider: None,
                cwd: None,
            }
        }
        ProvisioningExecutionTarget::Remote { context_name, .. } => {
            let context = context_name
                .clone()
                .or_else(|| matching_phase_execution_context_name(contract, Backend::Remote, None));
            PhaseExecutionContext {
                backend: Some(String::from("remote")),
                context: context.clone(),
                target: phase_execution_target(
                    contract,
                    path,
                    Backend::Remote,
                    None,
                    context.as_deref(),
                ),
                provider: phase_execution_provider(contract, context.as_deref()),
                cwd: phase_execution_cwd(contract, context.as_deref()),
                ..PhaseExecutionContext::default()
            }
        }
    }
}

fn render_repo_receipt(
    text_path: &str,
    json_path: &str,
    contract_path: &Path,
    report: &RepoReceiptReport,
    format: OutputFormat,
) -> CommandOutput {
    match format {
        OutputFormat::Text => {
            let mut stdout = format!(
                "{}\n{}",
                format_command_header("RECEIPT", text_path),
                render_execution_receipt_text(&report.receipt)
            );
            if let Some(workflow) = report.workflow.as_deref() {
                stdout.push_str(&format!(
                    "\n{} {} {}",
                    summary_bullet(),
                    paint_key("Workflow:"),
                    workflow
                ));
            }
            if report.archive_path.is_some() || report.promoted_baseline.is_some() {
                stdout.push_str(&format!("\n\n{}", paint_section_title("Archive")));
                if let Some(archive_path) = report.archive_path.as_ref() {
                    stdout.push_str(&format!(
                        "\n {}  {} {}",
                        summary_bullet(),
                        paint_key("Archive:"),
                        compact_path(archive_path, ".")
                    ));
                }
                if let Some(promoted_baseline) = report.promoted_baseline.as_ref() {
                    stdout.push_str(&format!(
                        "\n {}  {} {}",
                        summary_bullet(),
                        paint_key("Baseline:"),
                        compact_path(Path::new(&promoted_baseline.path), ".")
                    ));
                    stdout.push_str(&format!(
                        "\n {}  {} {}",
                        summary_bullet(),
                        paint_key("Promoted:"),
                        &promoted_baseline.promoted_at
                    ));
                }
            }
            stdout.push('\n');

            CommandOutput {
                stdout,
                stderr: None,
                exit_code: if report.receipt.ok { 0 } else { 1 },
            }
        }
        OutputFormat::Json => CommandOutput {
            stdout: {
                let archive_path = report
                    .archive_path
                    .as_ref()
                    .map(|path| receipt_storage_path_display(path));
                let findings =
                    retarget_policy_review_followups_for_repo(&report.findings, contract_path);
                let payload = ReceiptSuccess {
                    ok: report.receipt.ok,
                    path: json_path,
                    mode: "receipt",
                    workflow: report.workflow.as_deref(),
                    summary: report.receipt.summary,
                    receipt: report.receipt.clone(),
                    archive_path: archive_path.as_deref(),
                    promoted_baseline: report.promoted_baseline.clone(),
                    findings: &findings,
                };
                to_json(&payload)
            },
            stderr: None,
            exit_code: if report.receipt.ok { 0 } else { 1 },
        },
    }
}

fn render_repo_receipt_snapshot(
    text_path: &str,
    json_path: &str,
    contract_path: &Path,
    workflow_name: Option<&str>,
    selection: &str,
    format: OutputFormat,
) -> CommandOutput {
    let root = contract_working_dir(contract_path);
    let report = match resolve_repo_receipt_snapshot(root, contract_path, workflow_name, selection)
    {
        Ok(report) => report,
        Err(error) => {
            return match format {
                OutputFormat::Text => CommandOutput::failure(error),
                OutputFormat::Json => CommandOutput {
                    stdout: to_json(&ValidateFailure {
                        summary: None,
                        ok: false,
                        path: json_path,
                        errors: vec![error],
                        error: None,
                        warnings: Vec::new(),
                        warning_details: Vec::new(),
                    }),
                    stderr: None,
                    exit_code: 1,
                },
            };
        }
    };

    match format {
        OutputFormat::Text => {
            let mut stdout = format_command_header("RECEIPT SNAPSHOT", text_path);
            stdout.push_str("\n\n");
            stdout.push_str(&paint_section_title("Overview"));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Source:"),
                report.source
            ));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Selection kind:"),
                report.selection_kind
            ));
            if let Some(workflow) = report.workflow.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Workflow:"),
                    workflow
                ));
            }
            if let Some(selection_path) = report.selection_path.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Selection:"),
                    compact_path(Path::new(selection_path), ".")
                ));
            }
            if let Some(archive_path) = report.archive_path.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Archive:"),
                    compact_path(Path::new(archive_path), ".")
                ));
            }
            if let Some(archived_at) = report.archived_at.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Archived:"),
                    archived_at
                ));
            }
            if let Some(promoted_at) = report.promoted_at.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Promoted:"),
                    promoted_at
                ));
            }
            if let Some(contract) = report.contract.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Contract:"),
                    compact_path(Path::new(contract), ".")
                ));
            }
            if let Some(contract_identity) = report.contract_identity.as_deref() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Identity:"),
                    contract_identity
                ));
            }
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Snapshot path:"),
                compact_path(&report.snapshot_path, ".")
            ));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Hash:"),
                report.snapshot_hash
            ));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Assumption set hash:"),
                report.assumption_set_hash
            ));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Assumptions:"),
                report.assumption_count
            ));

            let snapshot = serde_json::to_string_pretty(&report.snapshot)
                .unwrap_or_else(|_| String::from("{}"));
            stdout.push_str(&format!(
                "\n\n{}\n\n{}",
                paint_section_title("Snapshot"),
                snapshot
            ));
            stdout.push('\n');

            CommandOutput::success(stdout)
        }
        OutputFormat::Json => {
            let snapshot_path = receipt_storage_path_display(&report.snapshot_path);
            CommandOutput::success(to_json(&ReceiptSnapshotSuccess {
                ok: true,
                path: json_path,
                mode: "snapshot",
                source: &report.source,
                selection_kind: &report.selection_kind,
                workflow: report.workflow.as_deref(),
                selection_path: report.selection_path.as_deref(),
                archive_path: report.archive_path.as_deref(),
                archived_at: report.archived_at.as_deref(),
                promoted_at: report.promoted_at.as_deref(),
                snapshot_hash: &report.snapshot_hash,
                assumption_set_hash: &report.assumption_set_hash,
                snapshot_path: &snapshot_path,
                contract: ReceiptSnapshotContract {
                    contract: report.contract.as_deref(),
                    contract_identity: report.contract_identity.as_deref(),
                },
                summary: ReceiptSnapshotSummary {
                    input_count: 1,
                    assumption_count: report.assumption_count,
                },
                snapshot: report.snapshot,
            }))
        }
    }
}

fn render_repo_receipt_history(
    text_path: &str,
    json_path: &str,
    report: &RepoReceiptHistoryReport,
    format: OutputFormat,
) -> CommandOutput {
    match format {
        OutputFormat::Text => {
            let mut stdout = format_command_header("RECEIPT HISTORY", text_path);
            stdout.push_str("\n\n");
            stdout.push_str(&paint_section_title("Overview"));
            stdout.push_str(&format!(
                "\n {}  {} {}",
                summary_bullet(),
                paint_key("Archives:"),
                report.archives.len()
            ));
            if !report.invalid_archives.is_empty() {
                stdout.push_str(&format!(
                    "\n {}  {} {}",
                    summary_bullet(),
                    paint_key("Invalid:"),
                    report.invalid_archives.len()
                ));
            }

            if report.archives.is_empty() {
                stdout.push_str("\n\nno archived receipts");
            } else {
                for (index, archive) in report.archives.iter().enumerate() {
                    stdout.push_str(&format!(
                        "\n\n{}. {} {}",
                        index + 1,
                        render_execution_receipt_status(receipt_history_status_label(
                            archive.status.as_deref(),
                            archive.ok,
                        )),
                        archive.archived_at
                    ));
                    stdout.push_str(&format!(
                        "\n   {} {}",
                        paint_key("Contract:"),
                        compact_path(Path::new(&archive.contract), ".")
                    ));
                    if let Some(context) = archive.context.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Context:"), context));
                    }
                    if let Some(backend) = archive.backend.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Backend:"), backend));
                    }
                    if let Some(target) = archive.target.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Target:"), target));
                    }
                    if let Some(provider) = archive.provider.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Provider:"), provider));
                    }
                    if let Some(lifecycle) = archive.lifecycle.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Lifecycle:"), lifecycle));
                    }
                    if let Some(cwd) = archive.cwd.as_deref() {
                        stdout.push_str(&format!("\n   {} {}", paint_key("Cwd:"), cwd));
                    }
                    stdout.push_str(&format!(
                        "\n   {} errors={}, warnings={}, info={}",
                        paint_key("Summary:"),
                        archive.summary.error_count,
                        archive.summary.warn_count,
                        archive.summary.info_count
                    ));
                    stdout.push_str(&format!(
                        "\n   {} {}",
                        paint_key("Archive:"),
                        compact_path(Path::new(&archive.archive_path), ".")
                    ));
                }
            }
            if !report.invalid_archives.is_empty() {
                stdout.push_str("\n\n");
                stdout.push_str(&paint_section_title("Skipped Archives"));
                for archive in &report.invalid_archives {
                    stdout.push_str(&format!(
                        "\n{} {}",
                        list_bullet(),
                        compact_path(Path::new(&archive.archive_path), ".")
                    ));
                    stdout.push_str(&format!("\n  {} {}", paint_key("Why:"), archive.error));
                }
            }
            stdout.push('\n');

            CommandOutput {
                stdout,
                stderr: None,
                exit_code: 0,
            }
        }
        OutputFormat::Json => CommandOutput {
            stdout: to_json(&ReceiptHistorySuccess {
                ok: true,
                path: json_path,
                mode: "history",
                summary: ReceiptHistorySummary {
                    archive_count: report.archives.len(),
                    invalid_archive_count: report.invalid_archives.len(),
                },
                archives: &report.archives,
                invalid_archives: &report.invalid_archives,
            }),
            stderr: None,
            exit_code: 0,
        },
    }
}

fn receipt_history_status_label<'a>(status: Option<&'a str>, ok: bool) -> &'a str {
    match status.map(str::trim).filter(|value| !value.is_empty()) {
        Some("success") => "READY",
        Some("interrupted") => "INTERRUPTED",
        Some("blocked") => "BLOCKED",
        Some("preview") => "PREVIEW",
        Some("skipped") => "SKIPPED",
        Some("failed") => "FAILED",
        Some(other) => other,
        None => {
            if ok {
                "READY"
            } else {
                "NOT READY"
            }
        }
    }
}

fn workspace_env_sources(
    contract: &Contract,
    contract_path: &Path,
    task_name: Option<&str>,
    task_env: Option<&BTreeMap<String, String>>,
    policy_env: Option<&BTreeMap<String, String>>,
) -> Vec<ExecutionReceiptEnvSource> {
    let repo_policy = load_policy_env_overlay(contract_path).unwrap_or_default();
    let workspace_policy_env = policy_env.cloned().unwrap_or_default();
    let declared_sources = load_declared_env_sources(contract, contract_path);

    task_name
        .map(|task_name| {
            resolve_task_env_details_for_task_with_policy(
                contract,
                contract_path,
                task_name,
                task_env,
                policy_env,
            )
        })
        .unwrap_or_else(|| {
            resolve_task_env_details_with_policy(contract, contract_path, task_env, policy_env)
        })
        .unwrap_or_default()
        .into_iter()
        .map(|(name, value)| {
            let source = match &value.source {
                EnvResolutionSource::Process => String::from("process"),
                EnvResolutionSource::Default => String::from("default"),
                EnvResolutionSource::Task => String::from("task"),
                EnvResolutionSource::Policy(label) => {
                    if workspace_policy_env.contains_key(&name) {
                        String::from("workspace policy")
                    } else if repo_policy.values.contains_key(&name) {
                        if label.is_empty() {
                            repo_policy.label.clone()
                        } else {
                            label.to_string()
                        }
                    } else {
                        label.to_string()
                    }
                }
                EnvResolutionSource::Source(label) => label.clone(),
            };
            let (source_kind, source_path, source_status, source_label) =
                env_entry_source_metadata(source.as_str(), &declared_sources);
            ExecutionReceiptEnvSource {
                name,
                value: receipt_env_value(&value),
                source,
                source_kind,
                source_path,
                source_status,
                source_label,
            }
        })
        .collect()
}

fn workspace_up_receipt(
    workspace_path: &Path,
    contract_identity: &ContractIdentity,
    workspace_name: &str,
    repos: &[WorkspaceRepoUpReport],
) -> ExecutionReceipt {
    let mut findings = Vec::new();
    let mut steps = Vec::new();
    let mut blocked = Vec::new();
    let mut env_sources = Vec::new();
    let mut ready_count = 0usize;
    let mut not_ready_count = 0usize;

    for (index, repo) in repos.iter().enumerate() {
        if repo.ok {
            ready_count += 1;
        } else {
            not_ready_count += 1;
        }
        if repo.status == "BLOCKED" {
            blocked.push(repo.name.clone());
        }
        findings.extend(repo.findings.clone());
        env_sources.extend(repo.env_sources.clone());
        steps.push(execution_receipt_step(
            index + 1,
            repo.name.clone(),
            repo.status.clone(),
            Some(match repo.phase.as_str() {
                "services" => repo
                    .service
                    .as_deref()
                    .map(|service| format!("service `{service}`"))
                    .unwrap_or_else(|| repo.phase.clone()),
                "setup" => repo
                    .task
                    .as_deref()
                    .map(|task| format!("task `{task}`"))
                    .unwrap_or_else(|| repo.phase.clone()),
                other => other.to_string(),
            }),
            repo.exit_code,
        ));
    }

    let next = repos
        .iter()
        .flat_map(|repo| repo.findings.iter())
        .map(|finding| finding.next.clone())
        .find(|next| !next.trim().is_empty())
        .or_else(|| workspace_refresh_receipt_next(repos));
    let ok = repos.iter().all(|repo| repo.ok || !repo.required);
    let receipt_status = aggregate_execution_summary_status(ok, &steps, &blocked);

    ExecutionReceipt {
        ok,
        path: workspace_path.display().to_string(),
        scope: String::from("workspace"),
        contract: workspace_path.display().to_string(),
        contract_identity: Some(contract_identity.clone()),
        contract_snapshot_hash: None,
        contract_snapshot_ref: None,
        assumption_set_hash: None,
        workspace: Some(workspace_name.to_string()),
        backend: None,
        context: None,
        lifecycle: None,
        image: None,
        container_memory_bytes: None,
        target: None,
        provider: None,
        cwd: None,
        acquired: Vec::new(),
        env: env_sources
            .iter()
            .map(|source| (source.name.clone(), source.value.clone()))
            .collect(),
        env_sources,
        workflow_env_artifacts: Vec::new(),
        native_prerequisites: Vec::new(),
        toolchains: Vec::new(),
        runtime: None,
        logs: None,
        service_termination: None,
        host_service_cleanup: Vec::new(),
        backend_fulfillment: None,
        workloads: BTreeMap::new(),
        policy: Vec::new(),
        dependency_steps: Vec::new(),
        steps,
        status: Some(receipt_status),
        failed_task: None,
        failed_dependency: None,
        failure_origin: None,
        blocked,
        summary: execution_receipt_summary(
            &findings,
            repos.len(),
            Some(repos.len()),
            Some(ready_count),
            Some(not_ready_count),
        ),
        next,
    }
}

fn workspace_status_receipt(
    workspace_path: &Path,
    contract_identity: &ContractIdentity,
    workspace_name: &str,
    report: &WorkspaceStatusReport,
) -> ExecutionReceipt {
    let mut findings = Vec::new();
    let mut steps = Vec::new();
    let mut ready_count = 0usize;
    let mut not_ready_count = 0usize;

    for (index, repo) in report.repos.iter().enumerate() {
        if repo.ready {
            ready_count += 1;
        } else {
            not_ready_count += 1;
        }
        findings.extend(repo.findings.clone());
        steps.push(execution_receipt_step(
            index + 1,
            repo.name.clone(),
            repo.readiness_status.clone(),
            Some(format!("{} · {}", repo.readiness_status, repo.drift_status)),
            None,
        ));
    }

    let next = report.next.clone().or_else(|| {
        report
            .repos
            .iter()
            .flat_map(|repo| repo.findings.iter())
            .map(|finding| finding.next.clone())
            .find(|next| !next.trim().is_empty())
    });
    let ok = report.repos.iter().all(|repo| !repo.required || repo.ready);
    let receipt_status = aggregate_execution_summary_status(ok, &steps, &[]);

    ExecutionReceipt {
        ok,
        path: workspace_path.display().to_string(),
        scope: String::from("workspace"),
        contract: workspace_path.display().to_string(),
        contract_identity: Some(contract_identity.clone()),
        contract_snapshot_hash: None,
        contract_snapshot_ref: None,
        assumption_set_hash: None,
        workspace: Some(workspace_name.to_string()),
        backend: None,
        context: None,
        lifecycle: None,
        image: None,
        container_memory_bytes: None,
        target: None,
        provider: None,
        cwd: None,
        acquired: Vec::new(),
        env: BTreeMap::new(),
        env_sources: Vec::new(),
        workflow_env_artifacts: Vec::new(),
        native_prerequisites: Vec::new(),
        toolchains: Vec::new(),
        runtime: None,
        logs: None,
        service_termination: None,
        host_service_cleanup: Vec::new(),
        backend_fulfillment: None,
        workloads: BTreeMap::new(),
        policy: Vec::new(),
        dependency_steps: Vec::new(),
        steps,
        status: Some(receipt_status),
        failed_task: None,
        failed_dependency: None,
        failure_origin: None,
        blocked: Vec::new(),
        summary: execution_receipt_summary(
            &findings,
            report.repos.len(),
            Some(report.repos.len()),
            Some(ready_count),
            Some(not_ready_count),
        ),
        next,
    }
}

