fn workspace_progress_prefix(workspace_name: &str) -> String {
    let trimmed = workspace_name.trim();
    if trimmed.is_empty() {
        String::from("[workspace]")
    } else {
        format!("[{trimmed}]")
    }
}

fn workspace_progress_mode_for(
    format: OutputFormat,
    enabled_for_text: bool,
    stderr_is_terminal: bool,
    progress_json: bool,
) -> Option<WorkspaceProgressMode> {
    match format {
        OutputFormat::Text => enabled_for_text.then_some(WorkspaceProgressMode::Text),
        OutputFormat::Json => {
            if progress_json {
                Some(WorkspaceProgressMode::Json)
            } else if stderr_is_terminal {
                Some(WorkspaceProgressMode::Text)
            } else {
                None
            }
        }
    }
}

fn workspace_progress_mode(
    format: OutputFormat,
    enabled_for_text: bool,
    progress_json: bool,
) -> Option<WorkspaceProgressMode> {
    workspace_progress_mode_for(
        format,
        enabled_for_text,
        io::stderr().is_terminal(),
        progress_json,
    )
}

fn workspace_run_progress_tail(repo: &WorkspaceRepoRef, task: &str) -> String {
    let resolved = repo.resolve_workspace_task(task);
    if resolved == task {
        task.to_string()
    } else {
        format!("{task} -> {resolved}")
    }
}

fn workspace_progress_run_detail(repo: &WorkspaceRepoRef, task: &str) -> WorkspaceProgressDetail {
    WorkspaceProgressDetail {
        tail: Some(workspace_run_progress_tail(repo, task)),
        task: Some(task.to_string()),
        repo_task: Some(repo.resolve_workspace_task(task).to_string()),
        dependency: None,
    }
}

fn workspace_progress_dependency_detail(dependency: &str) -> WorkspaceProgressDetail {
    WorkspaceProgressDetail {
        tail: Some(format!("({dependency})")),
        task: None,
        repo_task: None,
        dependency: Some(dependency.to_string()),
    }
}

fn workspace_progress_report_detail(report: &WorkspaceRepoRunReport) -> WorkspaceProgressDetail {
    let tail = match report.repo_task.as_deref() {
        Some(repo_task) if repo_task != report.task => {
            Some(format!("{} -> {}", report.task, repo_task))
        }
        _ => Some(report.task.clone()),
    };
    WorkspaceProgressDetail {
        tail,
        task: Some(report.task.clone()),
        repo_task: Some(
            report
                .repo_task
                .clone()
                .unwrap_or_else(|| report.task.clone()),
        ),
        dependency: None,
    }
}

fn workspace_progress_blocked_run_detail(
    report: &WorkspaceRepoRunReport,
    dependency: &str,
) -> WorkspaceProgressDetail {
    let mut detail = workspace_progress_report_detail(report);
    detail.dependency = Some(dependency.to_string());
    detail.tail = match detail.tail.take() {
        Some(tail) if !tail.trim().is_empty() => Some(format!("{tail} ({dependency})")),
        _ => Some(format!("({dependency})")),
    };
    detail
}

fn workspace_progress_status_detail(report: &WorkspaceRepoStatusReport) -> WorkspaceProgressDetail {
    WorkspaceProgressDetail {
        tail: Some(report.drift_status.clone()),
        task: None,
        repo_task: None,
        dependency: None,
    }
}

fn workspace_progress_diff_detail(report: &WorkspaceRepoDiffReport) -> WorkspaceProgressDetail {
    WorkspaceProgressDetail {
        tail: Some(report.drift_kind.clone()),
        task: None,
        repo_task: None,
        dependency: None,
    }
}

fn workspace_progress_line(
    workspace_name: &str,
    status: &str,
    repo_name: &str,
    detail: Option<&WorkspaceProgressDetail>,
) -> String {
    let tail = detail.and_then(|detail| detail.tail.as_deref());
    if plain_mode() {
        return match tail {
            Some(tail) if !tail.trim().is_empty() => format!(
                "{} {} {} {}",
                workspace_progress_prefix(workspace_name),
                status.trim(),
                repo_name,
                tail
            ),
            _ => format!(
                "{} {} {}",
                workspace_progress_prefix(workspace_name),
                status.trim(),
                repo_name
            ),
        };
    }

    let prefix = paint(&workspace_progress_prefix(workspace_name), "1;36");
    let status = workspace_progress_status(status);
    let repo = paint(repo_name, "1;37");

    match tail {
        Some(tail) if !tail.trim().is_empty() => {
            format!("{prefix} {status} {repo} {}", paint(tail, "1;37"))
        }
        _ => format!("{prefix} {status} {repo}"),
    }
}

fn workspace_progress_status(status: &str) -> String {
    match status.trim() {
        "RUN" => paint("RUN", "1;36"),
        "READY" => paint("READY", "1;38;2;0;255;120"),
        "NOT READY" => paint("NOT READY", "1;38;2;255;235;59"),
        "BLOCKED" => paint("BLOCKED", "1;38;2;255;235;59"),
        "ACQUIRE" => paint("ACQUIRE", "1;35"),
        value if value.contains("FAILED") => paint(value, "1;31"),
        value => paint(value, "1;37"),
    }
}

fn render_failed_status_label(value: &str) -> String {
    if plain_mode() {
        return value.to_string();
    }
    format!("{} {}", primary_error_marker(), paint(value, "1;31"))
}

fn task_command_preview(task: &TaskSpec) -> Option<String> {
    let execution = task.resolved_execution(current_os())?;
    Some(execution.preview())
}

fn emit_workspace_progress_line(
    mode: WorkspaceProgressMode,
    command: &str,
    workspace_name: &str,
    status: &str,
    repo_name: &str,
    detail: Option<&WorkspaceProgressDetail>,
) {
    if matches!(mode, WorkspaceProgressMode::Text) && io::stderr().is_terminal() {
        let mut stderr = io::stderr();
        let _ = write!(stderr, "\r\x1b[2K\r");
        let _ = stderr.flush();
    }
    match mode {
        WorkspaceProgressMode::Text => eprintln!(
            "{}",
            workspace_progress_line(workspace_name, status, repo_name, detail)
        ),
        WorkspaceProgressMode::Json => eprintln!(
            "{}",
            workspace_progress_json_line(command, workspace_name, status, repo_name, detail)
        ),
    }
}

fn workspace_progress_json_line(
    command: &str,
    workspace_name: &str,
    status: &str,
    repo_name: &str,
    detail: Option<&WorkspaceProgressDetail>,
) -> String {
    to_json_compact(&WorkspaceProgressEvent {
        event: "workspace_progress",
        command,
        workspace: workspace_name,
        status,
        repo: repo_name,
        tail: detail.and_then(|detail| detail.tail.as_deref()),
        task: detail.and_then(|detail| detail.task.as_deref()),
        repo_task: detail.and_then(|detail| detail.repo_task.as_deref()),
        dependency: detail.and_then(|detail| detail.dependency.as_deref()),
    })
}

fn run_workspace_repo_up(
    repo: WorkspaceRepoRef,
    mode: RepoExecutionMode,
    workspace_path: &Path,
) -> WorkspaceRepoUpReport {
    let repo_name = repo.name.clone();
    let contract_path_display = repo.contract_path.display().to_string();
    let path_display = repo.path.display().to_string();
    match acquire_workspace_repo(&repo, mode) {
        Ok(acquisition) if acquisition.exit_code != 0 => {
            return WorkspaceRepoUpReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                workflow: repo.workflow.clone(),
                required: repo.required,
                ok: !repo.required,
                status: if repo.required {
                    "ACQUIRE FAILED"
                } else {
                    "WARN"
                }
                .to_string(),
                phase: "acquisition".to_string(),
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo acquisition failed: {}", repo_name),
                    why: match repo.source_url.as_deref() {
                        Some(source_url) => format!(
                            "workspace repo `{}` could not be cloned from `{}`",
                            repo_name, source_url
                        ),
                        None => format!("workspace repo `{}` could not be acquired", repo_name),
                    },
                    next: String::from(
                        "inspect the `Source:` and `Acquire output:` lines, then fix source access and credentials before rerunning `ota workspace up`",
                    ),
                }],
                service: None,
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                service_command: None,
                task: None,
                task_command: None,
                exit_code: Some(acquisition.exit_code),
                stdout: match mode {
                    RepoExecutionMode::Capture => {
                        (!acquisition.stdout.is_empty()).then_some(acquisition.stdout)
                    }
                    RepoExecutionMode::Stream => None,
                },
                stderr: match mode {
                    RepoExecutionMode::Capture => {
                        (!acquisition.stderr.is_empty()).then_some(acquisition.stderr)
                    }
                    RepoExecutionMode::Stream => None,
                },
                env_sources: Vec::new(),
                next: None,
                next_steps: Vec::new(),
            };
        }
        Ok(_) => {}
        Err(error) => {
            return WorkspaceRepoUpReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                workflow: repo.workflow.clone(),
                required: repo.required,
                ok: !repo.required,
                status: if repo.required {
                    "ACQUIRE FAILED"
                } else {
                    "WARN"
                }
                .to_string(),
                phase: "acquisition".to_string(),
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo acquisition failed: {}", repo_name),
                    why: error,
                    next: String::from(
                        "inspect the `Source:` line and acquisition output, then fix source access and credentials before rerunning `ota workspace up`",
                    ),
                }],
                service: None,
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                service_command: None,
                task: None,
                task_command: None,
                exit_code: None,
                stdout: None,
                stderr: None,
                env_sources: Vec::new(),
                next: None,
                next_steps: Vec::new(),
            };
        }
    }

    match load_and_validate_target(&repo.contract_path, None) {
        Ok(target) => {
            let env_sources = target
                .contract
                .selected_setup_task_name_for(repo.workflow.as_deref())
                .and_then(|task_name| target.contract.tasks.get(task_name))
                .map(|task| {
                    workspace_env_sources(
                        &target.contract,
                        &target.contract_path,
                        target
                            .contract
                            .selected_setup_task_name_for(repo.workflow.as_deref()),
                        Some(&task.env),
                        Some(&repo.policy_env),
                    )
                })
                .unwrap_or_default();

            match execute_repo_up(
                &target.contract,
                &target.contract_path,
                ExecutionOverrides::default(),
                repo.workflow.as_deref(),
                Some(&repo.policy_env),
                false,
                mode,
            ) {
                Ok(result) => WorkspaceRepoUpReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    workflow: repo.workflow.clone(),
                    required: repo.required,
                    ok: if repo.required { result.ok } else { true },
                    status: if repo.required || result.ok {
                        result.status.to_string()
                    } else {
                        String::from("WARN")
                    },
                    phase: result.phase.to_string(),
                    findings: adjust_workspace_up_findings(result.report.findings, repo.required),
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    service: result.service,
                    service_command: result.service_command,
                    task: result.task,
                    task_command: result.task_command,
                    exit_code: result.exit_code,
                    stdout: match mode {
                        RepoExecutionMode::Capture => {
                            (!result.stdout.is_empty()).then_some(result.stdout)
                        }
                        RepoExecutionMode::Stream => None,
                    },
                    stderr: match mode {
                        RepoExecutionMode::Capture => {
                            (!result.stderr.is_empty()).then_some(result.stderr)
                        }
                        RepoExecutionMode::Stream => None,
                    },
                    env_sources: env_sources.clone(),
                    next: None,
                    next_steps: Vec::new(),
                },
                Err(error) => WorkspaceRepoUpReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    workflow: repo.workflow.clone(),
                    required: repo.required,
                    ok: !repo.required,
                    status: if repo.required { "FAILED" } else { "WARN" }.to_string(),
                    phase: "setup".to_string(),
                    findings: vec![Finding {
                        identity: None,
                        severity: if repo.required {
                            FindingSeverity::Error
                        } else {
                            FindingSeverity::Warn
                        },
                        summary: format!("Repo up failed: {}", repo_name),
                        why: error,
                        next: workspace_repo_validate_then_rerun_next(
                            &repo.contract_path,
                            &command_for_workspace("ota workspace up", workspace_path),
                        ),
                    }],
                    service: None,
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    service_command: None,
                    task: None,
                    task_command: None,
                    exit_code: None,
                    stdout: None,
                    stderr: None,
                    env_sources,
                    next: None,
                    next_steps: Vec::new(),
                },
            }
        }
        Err(error) => WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow,
            required: repo.required,
            ok: !repo.required,
            status: if repo.required { "NOT READY" } else { "WARN" }.to_string(),
            phase: "validation".to_string(),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo contract failed validation: {}", repo_name),
                why: render_contract_problem(&error),
                next: workspace_repo_validate_then_rerun_next(
                    &repo.contract_path,
                    &command_for_workspace("ota workspace up", workspace_path),
                ),
            }],
            service: None,
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            service_command: None,
            task: None,
            task_command: None,
            exit_code: None,
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        },
    }
}

fn blocked_workspace_repo_up(repo: WorkspaceRepoRef, dependency: String) -> WorkspaceRepoUpReport {
    WorkspaceRepoUpReport {
        name: repo.name,
        path: repo.path.display().to_string(),
        contract_path: repo.contract_path.display().to_string(),
        workflow: repo.workflow,
        required: repo.required,
        ok: !repo.required,
        status: String::from("BLOCKED"),
        phase: String::from("dependencies"),
        findings: vec![Finding {
            identity: None,
            severity: if repo.required {
                FindingSeverity::Error
            } else {
                FindingSeverity::Warn
            },
            summary: format!("Blocked by failed dependency: {dependency}"),
            why: format!("workspace repo depends on `{dependency}`, which did not become ready"),
            next: format!("repair `{dependency}` first, then rerun `ota workspace up`"),
        }],
        service: None,
        source_url: None,
        source_ref: None,
        service_command: None,
        task: None,
        task_command: None,
        exit_code: None,
        stdout: None,
        stderr: None,
        env_sources: Vec::new(),
        next: None,
        next_steps: Vec::new(),
    }
}

fn workspace_repo_git_output(args: &[&str], cwd: &Path) -> Result<String, String> {
    let output = run_git_command(args, Some(cwd), RepoExecutionMode::Capture).map_err(|error| {
        format!(
            "failed to start git command for `{}`: {}",
            cwd.display(),
            error
        )
    })?;
    if output.exit_code != 0 {
        return Err(format!(
            "git command `{}` failed with exit code {}",
            args.join(" "),
            output.exit_code
        ));
    }

    Ok(output.stdout.trim().to_string())
}

fn run_workspace_repo_diff(repo: WorkspaceRepoRef) -> WorkspaceRepoDiffReport {
    let repo_name = repo.name.clone();
    let path_display = repo.path.display().to_string();
    let contract_path_display = repo.contract_path.display().to_string();

    if !repo.present || !repo.path.is_dir() {
        return WorkspaceRepoDiffReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            required: repo.required,
            acquired: false,
            status: String::from("MISSING"),
            drift_kind: String::from("missing_repo"),
            target_source: None,
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            branch: None,
            head: None,
            target_ref: None,
            ahead: None,
            behind: None,
            dirty: false,
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo missing: {}", repo_name),
                why: format!(
                    "workspace repo `{}` is not present at `{}` yet",
                    repo_name,
                    repo.path.display()
                ),
                next: match repo.source_url.as_deref() {
                    Some(source_url) => format!(
                        "run `ota workspace up` to acquire `{}` from `{}`",
                        repo_name, source_url
                    ),
                    None => format!(
                        "create `{}` and rerun `ota workspace diff`",
                        repo.path.display()
                    ),
                },
            }],
            next: None,
            next_steps: Vec::new(),
        };
    }

    if !repo.contract_path.is_file() {
        return WorkspaceRepoDiffReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            required: repo.required,
            acquired: true,
            status: String::from("MISSING CONTRACT"),
            drift_kind: String::from("missing_contract"),
            target_source: None,
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            branch: None,
            head: None,
            target_ref: None,
            ahead: None,
            behind: None,
            dirty: false,
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo contract missing: {}", repo_name),
                why: format!(
                    "workspace repo `{}` does not have a readable ota.yaml at `{}`",
                    repo_name,
                    repo.contract_path.display()
                ),
                next: format!(
                    "restore `{}` and rerun `ota workspace diff`",
                    repo.contract_path.display()
                ),
            }],
            next: None,
            next_steps: Vec::new(),
        };
    }

    let branch = workspace_repo_git_output(&["branch", "--show-current"], &repo.path)
        .ok()
        .and_then(|value| (!value.is_empty()).then_some(value));
    let head = match workspace_repo_git_output(&["rev-parse", "HEAD"], &repo.path) {
        Ok(value) => Some(value),
        Err(error) => {
            return WorkspaceRepoDiffReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                required: repo.required,
                acquired: true,
                status: String::from("UNRESOLVED"),
                drift_kind: String::from("comparison_unresolved"),
                target_source: None,
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                branch,
                head: None,
                target_ref: None,
                ahead: None,
                behind: None,
                dirty: false,
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo comparison unavailable: {}", repo_name),
                    why: format!(
                        "workspace repo `{}` could not resolve its local HEAD: {}",
                        repo_name, error
                    ),
                    next: String::from(
                        "fix the local git repository state, then rerun `ota workspace diff`",
                    ),
                }],
                next: None,
                next_steps: Vec::new(),
            };
        }
    };

    let dirty = workspace_repo_git_output(&["status", "--porcelain"], &repo.path)
        .ok()
        .map(|value| !value.is_empty())
        .unwrap_or(true);
    let target_ref = repo
        .source_ref
        .clone()
        .or_else(|| workspace_repo_upstream_branch(&repo.path));

    if target_ref.is_none() {
        return WorkspaceRepoDiffReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            required: repo.required,
            acquired: true,
            status: String::from("UNRESOLVED"),
            drift_kind: String::from("target_unavailable"),
            target_source: None,
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            branch,
            head,
            target_ref: None,
            ahead: None,
            behind: None,
            dirty,
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo comparison target unavailable: {}", repo_name),
                why: format!(
                    "workspace repo `{}` does not have a declared source ref or upstream branch to compare against",
                    repo_name
                ),
                next: String::from(
                    "declare `source.ref` or configure an upstream branch, then rerun `ota workspace diff`",
                ),
            }],
            next: None,
            next_steps: Vec::new(),
        };
    }

    let comparison = match workspace_repo_git_output(
        &[
            "rev-list",
            "--left-right",
            "--count",
            &format!("HEAD...{}", target_ref.as_deref().unwrap()),
        ],
        &repo.path,
    ) {
        Ok(value) => value,
        Err(error) => {
            return WorkspaceRepoDiffReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                required: repo.required,
                acquired: true,
                status: String::from("UNRESOLVED"),
                drift_kind: String::from("comparison_unresolved"),
                target_source: workspace_repo_target_source(repo.source_ref.is_some(), true)
                    .map(String::from),
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                branch,
                head,
                target_ref,
                ahead: None,
                behind: None,
                dirty,
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo comparison unavailable: {}", repo_name),
                    why: format!(
                        "workspace repo `{}` could not compare HEAD against its target ref: {}",
                        repo_name, error
                    ),
                    next: String::from(
                        "fix the local git repository state, then rerun `ota workspace diff`",
                    ),
                }],
                next: None,
                next_steps: Vec::new(),
            };
        }
    };
    let mut parts = comparison.split_whitespace();
    let ahead = parts.next().and_then(|value| value.parse::<usize>().ok());
    let behind = parts.next().and_then(|value| value.parse::<usize>().ok());

    let status = if dirty {
        "DIRTY"
    } else if ahead.unwrap_or(0) != 0 || behind.unwrap_or(0) != 0 {
        "DIFFERENT"
    } else {
        "MATCH"
    };

    let findings = if status == "MATCH" {
        Vec::new()
    } else {
        let target_label = workspace_repo_target_label(
            target_ref.as_deref().unwrap_or("declared target"),
            repo.source_ref.is_some(),
        );
        vec![Finding {
            identity: None,
            severity: if repo.required {
                FindingSeverity::Warn
            } else {
                FindingSeverity::Info
            },
            summary: format!("Repo drift detected: {}", repo_name),
            why: if dirty {
                format!(
                    "workspace repo `{}` has uncommitted changes and differs from {}",
                    repo_name, target_label
                )
            } else {
                format!(
                    "workspace repo `{}` is {} commit(s) ahead and {} commit(s) behind of {}",
                    repo_name,
                    ahead.unwrap_or(0),
                    behind.unwrap_or(0),
                    target_label
                )
            },
            next: workspace_repo_drift_next(repo.source_ref.is_some()),
        }]
    };

    WorkspaceRepoDiffReport {
        name: repo.name,
        path: path_display,
        contract_path: contract_path_display,
        required: repo.required,
        acquired: true,
        status: status.to_string(),
        drift_kind: String::from(workspace_repo_drift_kind(&status, target_ref.is_some())),
        target_source: workspace_repo_target_source(
            repo.source_ref.is_some(),
            target_ref.is_some(),
        )
        .map(String::from),
        source_url: repo.source_url.clone(),
        source_ref: repo.source_ref.clone(),
        branch,
        head,
        target_ref,
        ahead,
        behind,
        dirty,
        findings,
        next: None,
        next_steps: Vec::new(),
    }
}

fn run_workspace_repo_status(
    repo: WorkspaceRepoRef,
    workspace_path: &Path,
) -> WorkspaceRepoStatusReport {
    let diff = run_workspace_repo_diff(repo.clone());
    let doctor = diagnose_workspace_repo(repo.clone(), workspace_path);
    let readiness_status = if !repo.present {
        String::from("NOT ACQUIRED")
    } else if doctor.ok {
        String::from("READY")
    } else {
        String::from("NOT READY")
    };
    let findings = if doctor.findings.is_empty() {
        diff.findings.clone()
    } else {
        doctor.findings.clone()
    };

    WorkspaceRepoStatusReport {
        name: repo.name,
        path: diff.path,
        contract_path: diff.contract_path,
        workflow: repo.workflow,
        required: diff.required,
        acquired: repo.present,
        ready: doctor.ok,
        readiness_status,
        drift_status: diff.status,
        drift_kind: diff.drift_kind,
        target_source: diff.target_source,
        source_url: diff.source_url,
        source_ref: diff.source_ref,
        branch: diff.branch,
        head: diff.head,
        target_ref: diff.target_ref,
        ahead: diff.ahead,
        behind: diff.behind,
        dirty: diff.dirty,
        findings,
        next: None,
        next_steps: Vec::new(),
    }
}

fn run_workspace_repo_execution_plan(
    repo: WorkspaceRepoRef,
    overrides: ExecutionOverrides,
    workspace_path: &Path,
) -> WorkspaceRepoExecutionPlanReport {
    let path_display = repo.path.display().to_string();
    let contract_path_display = repo.contract_path.display().to_string();
    let repo_name = repo.name.clone();

    if !repo.present {
        return WorkspaceRepoExecutionPlanReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            task: None,
            required: repo.required,
            acquired: false,
            status: String::from("NOT ACQUIRED"),
            contract_identity: None,
            declared_execution: None,
            resolved: None,
            error: Some(format!(
                "workspace repo `{}` has not been acquired into `{}` yet",
                repo_name,
                repo.path.display()
            )),
            next: Some(match repo.source_url.as_deref() {
                Some(source_url) => format!(
                    "run `ota workspace up` to acquire `{}` from `{}`",
                    repo_name, source_url
                ),
                None => format!(
                    "create `{}` and rerun `ota workspace execution plan`",
                    repo.path.display()
                ),
            }),
        };
    }

    if !repo.contract_path.is_file() {
        return WorkspaceRepoExecutionPlanReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display.clone(),
            workflow: repo.workflow.clone(),
            task: None,
            required: repo.required,
            acquired: true,
            status: String::from("MISSING CONTRACT"),
            contract_identity: None,
            declared_execution: None,
            resolved: None,
            error: Some(format!(
                "workspace repo `{}` does not contain a readable contract at `{}`",
                repo_name, contract_path_display
            )),
            next: Some(format!(
                "create `{}` and rerun `ota workspace execution plan`",
                contract_path_display
            )),
        };
    }

    match load_contract(&repo.contract_path) {
        Ok(contract) => {
            let contract_identity = repo_contract_identity(&contract);
            let declared_execution = WorkspaceExecutionSummary::from_contract_with_policy(
                &contract,
                &repo.contract_path,
                Some(&repo.policy_env),
            );

            if let Err(errors) = validate_contract_with_path(&contract, Some(&repo.contract_path)) {
                let error = errors
                    .errors()
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
                    .join("; ");
                return WorkspaceRepoExecutionPlanReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display.clone(),
                    workflow: repo.workflow.clone(),
                    task: None,
                    required: repo.required,
                    acquired: true,
                    status: String::from("INVALID CONTRACT"),
                    contract_identity: Some(contract_identity),
                    declared_execution,
                    resolved: None,
                    error: Some(format!(
                        "repo contract `{}` is invalid: {}",
                        contract_path_display, error
                    )),
                    next: Some(workspace_repo_validate_then_rerun_next(
                        &repo.contract_path,
                        &command_for_workspace("ota workspace execution plan", workspace_path),
                    )),
                };
            }

            if let Some(workflow_name) = repo.workflow.as_deref()
                && !selected_workflow_selector_is_valid(&contract, workflow_name)
            {
                return WorkspaceRepoExecutionPlanReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display.clone(),
                    workflow: repo.workflow.clone(),
                    task: None,
                    required: repo.required,
                    acquired: true,
                    status: String::from("INVALID WORKFLOW"),
                    contract_identity: Some(contract_identity),
                    declared_execution,
                    resolved: None,
                    error: Some(format!(
                        "workspace repo `{}` workflow `{}` is not declared in `{}`",
                        repo_name, workflow_name, contract_path_display
                    )),
                    next: Some(format!(
                        "repair `repos.{repo_name}.workflow` in the workspace contract or add the workflow to `{}` before rerunning `ota workspace execution plan`",
                        contract_path_display
                    )),
                };
            }

            let effective_workflow = contract
                .selected_workflow(repo.workflow.as_deref())
                .map(|(name, _)| name.to_string());
            let selected_task =
                selected_execution_plan_task_name(&contract, repo.workflow.as_deref())
                    .map(str::to_string);
            let report_workflow = repo
                .workflow
                .clone()
                .or_else(|| selected_task.as_ref().and(effective_workflow.clone()));

            match resolve_execution_plan(
                &contract,
                &repo.contract_path,
                overrides,
                repo.workflow.as_deref(),
            ) {
                Ok(resolved) => WorkspaceRepoExecutionPlanReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    workflow: report_workflow.clone(),
                    task: selected_task,
                    required: repo.required,
                    acquired: true,
                    status: String::from("RESOLVED"),
                    contract_identity: Some(contract_identity),
                    declared_execution,
                    resolved: Some(resolved),
                    error: None,
                    next: None,
                },
                Err(error) => WorkspaceRepoExecutionPlanReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display.clone(),
                    workflow: report_workflow,
                    task: selected_task,
                    required: repo.required,
                    acquired: true,
                    status: String::from("UNRESOLVED"),
                    contract_identity: Some(contract_identity),
                    declared_execution,
                    resolved: None,
                    error: Some(execution_plan_error(&error)),
                    next: Some(format!(
                        "repair `{}` so the selected execution mode is runnable, then rerun `ota workspace execution plan`",
                        contract_path_display
                    )),
                },
            }
        }
        Err(error) => WorkspaceRepoExecutionPlanReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display.clone(),
            workflow: repo.workflow,
            task: None,
            required: repo.required,
            acquired: true,
            status: String::from("UNREADABLE CONTRACT"),
            contract_identity: None,
            declared_execution: None,
            resolved: None,
            error: Some(format!(
                "workspace repo contract `{}` could not be loaded: {}",
                contract_path_display, error
            )),
            next: Some(workspace_repo_validate_then_rerun_next(
                &repo.contract_path,
                &command_for_workspace("ota workspace execution plan", workspace_path),
            )),
        },
    }
}

fn blocked_workspace_repo_refresh(
    repo: WorkspaceRepoRef,
    dependency: String,
) -> WorkspaceRepoUpReport {
    WorkspaceRepoUpReport {
        name: repo.name,
        path: repo.path.display().to_string(),
        contract_path: repo.contract_path.display().to_string(),
        workflow: repo.workflow,
        required: repo.required,
        ok: !repo.required,
        status: String::from("BLOCKED"),
        phase: String::from("dependencies"),
        findings: vec![Finding {
            identity: None,
            severity: if repo.required {
                FindingSeverity::Error
            } else {
                FindingSeverity::Warn
            },
            summary: format!("Blocked by failed dependency: {dependency}"),
            why: format!("workspace repo depends on `{dependency}`, which did not become ready"),
            next: format!("repair `{dependency}` first, then rerun `ota workspace refresh`"),
        }],
        service: None,
        source_url: None,
        source_ref: None,
        service_command: None,
        task: None,
        task_command: None,
        exit_code: None,
        stdout: None,
        stderr: None,
        env_sources: Vec::new(),
        next: None,
        next_steps: Vec::new(),
    }
}

fn blocked_workspace_repo_run(
    repo: WorkspaceRepoRef,
    task: &str,
    dependency: String,
) -> WorkspaceRepoRunReport {
    let repo_name = repo.name.clone();
    let requested_task = task.to_string();
    let resolved_task = repo.resolve_workspace_task(task).to_string();
    let resolved_task_field = (resolved_task != requested_task).then(|| resolved_task.clone());
    WorkspaceRepoRunReport {
        name: repo.name,
        path: repo.path.display().to_string(),
        contract_path: repo.contract_path.display().to_string(),
        required: repo.required,
        ok: !repo.required,
        status: if repo.required { "BLOCKED" } else { "WARN" }.to_string(),
        task: requested_task.clone(),
        repo_task: resolved_task_field,
        findings: vec![Finding {
            identity: None,
            severity: if repo.required {
                FindingSeverity::Error
            } else {
                FindingSeverity::Warn
            },
            summary: format!("Blocked by failed dependency: {dependency}"),
            why: format!(
                "workspace repo `{}` depends on `{dependency}`, which did not complete successfully",
                repo_name
            ),
            next: format!(
                "repair `{dependency}` first, then rerun `ota workspace run {requested_task}`"
            ),
        }],
        source_url: None,
        source_ref: None,
        task_command: None,
        exit_code: None,
        stdout: None,
        stderr: None,
        env_sources: Vec::new(),
        next: None,
        next_steps: Vec::new(),
    }
}

fn refresh_ref_override<'a>(
    repo_ref: Option<&'a str>,
    refresh_ref: Option<&'a str>,
) -> Option<&'a str> {
    refresh_ref
        .filter(|value| !value.trim().is_empty())
        .or_else(|| repo_ref.filter(|value| !value.trim().is_empty()))
}

fn workspace_repo_upstream_branch(repo_path: &Path) -> Option<String> {
    workspace_repo_git_output(
        &["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"],
        repo_path,
    )
    .ok()
    .and_then(|value| (!value.is_empty()).then_some(value))
}

fn workspace_repo_drift_kind(status: &str, target_ref_present: bool) -> &'static str {
    match status {
        "MATCH" => "match",
        "DIRTY" => "local_dirty",
        "DIFFERENT" => "commit_divergence",
        "MISSING" => "missing_repo",
        "MISSING CONTRACT" => "missing_contract",
        "UNRESOLVED" if !target_ref_present => "target_unavailable",
        "UNRESOLVED" => "comparison_unresolved",
        _ => "comparison_unresolved",
    }
}

fn workspace_repo_target_source(
    source_ref_present: bool,
    target_ref_present: bool,
) -> Option<&'static str> {
    if !target_ref_present {
        return None;
    }

    if source_ref_present {
        Some("declared_ref")
    } else {
        Some("upstream_branch")
    }
}

fn workspace_repo_target_label(target_ref: &str, source_ref_present: bool) -> String {
    if source_ref_present {
        format!("declared source ref `{target_ref}`")
    } else {
        format!("upstream branch `{target_ref}`")
    }
}

fn workspace_repo_drift_next(source_ref_present: bool) -> String {
    if source_ref_present {
        String::from(
            "run `ota workspace refresh` to reconcile the repo, or `ota workspace refresh --dry-run` to preview the sync",
        )
    } else {
        String::from(
            "run `ota workspace refresh --dry-run` to preview the sync against the repo upstream branch; run `ota workspace refresh` when you are ready to reconcile the repo; declare `source.ref` if the workspace should own the target explicitly",
        )
    }
}

fn workspace_refresh_command(effective_ref: Option<&str>, force: bool, prune: bool) -> String {
    if force {
        let mut command = String::from("git fetch --force");
        if prune {
            command.push_str(" --prune");
        }
        if let Some(ref_name) = effective_ref {
            command.push_str(" origin ");
            command.push_str(ref_name);
        }
        command.push_str(" && git reset --hard FETCH_HEAD");
        return command;
    }

    let mut command = String::from("git pull --ff-only");
    if prune {
        command.push_str(" --prune");
    }
    if let Some(ref_name) = effective_ref {
        command.push_str(" origin ");
        command.push_str(ref_name);
    }
    command
}

fn workspace_refresh_target_error(stderr: &str) -> bool {
    let stderr = stderr.to_ascii_lowercase();
    stderr.contains("couldn't find remote ref")
        || stderr.contains("couldn't find remote branch")
        || stderr.contains("no such ref was fetched")
        || stderr.contains("invalid refspec")
}

fn workspace_refresh_source_access_error(stderr: &str) -> bool {
    let stderr = stderr.to_ascii_lowercase();
    stderr.contains("authentication failed")
        || stderr.contains("permission denied")
        || stderr.contains("could not read from remote repository")
        || stderr.contains("repository not found")
        || stderr.contains("does not appear to be a git repository")
        || stderr.contains("no such file or directory")
        || stderr.contains("could not resolve host")
        || stderr.contains("connection timed out")
        || stderr.contains("connection refused")
}

fn workspace_refresh_failure_finding(
    repo_name: &str,
    source_ref: Option<&str>,
    stderr: Option<&str>,
) -> Finding {
    let stderr = stderr.unwrap_or_default();

    if workspace_refresh_target_error(stderr) {
        let target = source_ref.unwrap_or("<target>");
        return Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: format!("Refresh target unavailable: {repo_name}"),
            why: format!(
                "workspace repo `{repo_name}` could not refresh from `{target}` because the selected target does not exist on the remote"
            ),
            next: String::from(
                "fix `source.ref`, confirm the remote branch or tag exists, or rerun `ota workspace refresh --dry-run --ref <branch|tag|sha>` before applying `ota workspace refresh`",
            ),
        };
    }

    if workspace_refresh_source_access_error(stderr) {
        return Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: format!("Repo refresh failed: {repo_name}"),
            why: format!(
                "workspace repo `{repo_name}` could not reach or authenticate to its declared source during refresh"
            ),
            next: String::from(
                "inspect the `Source:` and `Refresh command:` lines, then fix source access or credentials before rerunning `ota workspace refresh`",
            ),
        };
    }

    Finding {
        identity: None,
        severity: FindingSeverity::Error,
        summary: format!("Repo refresh failed: {repo_name}"),
        why: format!("workspace repo `{repo_name}` could not complete its refresh command cleanly"),
        next: String::from(
            "inspect the `Refresh command:` line and refresh output, then fix branch tracking or local git state before rerunning `ota workspace refresh`",
        ),
    }
}

fn run_workspace_repo_refresh_command(
    repo: &WorkspaceRepoRef,
    effective_ref: Option<&str>,
    options: &WorkspaceRefreshOptions,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, String> {
    if options.force {
        let fetch_args = {
            let mut args = vec!["fetch", "--force"];
            if options.prune {
                args.push("--prune");
            }
            if let Some(ref_name) = effective_ref {
                args.push("origin");
                args.push(ref_name);
            }
            args
        };
        let fetch = run_git_command(&fetch_args, Some(&repo.path), mode).map_err(|error| {
            format!(
                "failed to start forced git fetch for `{}`: {}",
                repo.name, error
            )
        })?;
        let mut stdout = fetch.stdout;
        let mut stderr = fetch.stderr;
        if fetch.exit_code != 0 {
            return Ok(CommandRunResult {
                exit_code: fetch.exit_code,
                executed_tasks: Vec::new(),
                stdout,
                stderr,
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            });
        }

        let reset = run_git_command(&["reset", "--hard", "FETCH_HEAD"], Some(&repo.path), mode)
            .map_err(|error| {
                format!("failed to start hard reset for `{}`: {}", repo.name, error)
            })?;
        stdout.push_str(&reset.stdout);
        stderr.push_str(&reset.stderr);
        return Ok(CommandRunResult {
            exit_code: reset.exit_code,
            executed_tasks: Vec::new(),
            stdout,
            stderr,
            target: None,
            runtime: None,
            service_termination: None,
            fulfilled_toolchains: Vec::new(),
            host_service_cleanup: Vec::new(),
        });
    }

    let pull_args = {
        let mut args = vec!["pull", "--ff-only"];
        if options.prune {
            args.push("--prune");
        }
        if let Some(ref_name) = effective_ref {
            args.push("origin");
            args.push(ref_name);
        }
        args
    };

    run_git_command(&pull_args, Some(&repo.path), mode)
        .map_err(|error| format!("failed to start git refresh for `{}`: {}", repo.name, error))
}

fn run_workspace_repo_refresh(
    repo: WorkspaceRepoRef,
    options: &WorkspaceRefreshOptions,
    mode: RepoExecutionMode,
) -> WorkspaceRepoUpReport {
    let repo_name = repo.name.clone();
    let contract_path_display = repo.contract_path.display().to_string();
    let path_display = repo.path.display().to_string();

    if !repo.present || !repo.path.is_dir() {
        return WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            required: repo.required,
            ok: !repo.required,
            status: String::from("NOT ACQUIRED"),
            phase: String::from("refresh"),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo not acquired: {}", repo_name),
                why: format!(
                    "workspace repo `{}` has not been acquired into `{}` yet",
                    repo_name,
                    repo.path.display()
                ),
                next: match repo.source_url.as_deref() {
                    Some(source_url) => format!(
                        "run `ota workspace up` to acquire `{}` from `{}`",
                        repo_name, source_url
                    ),
                    None => format!(
                        "create `{}` and rerun `ota workspace refresh`",
                        repo.path.display()
                    ),
                },
            }],
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            service: None,
            service_command: None,
            task: None,
            task_command: None,
            exit_code: None,
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        };
    }

    if repo.source_url.is_none() {
        return WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            required: repo.required,
            ok: true,
            status: String::from("SKIPPED"),
            phase: String::from("refresh"),
            findings: Vec::new(),
            source_url: None,
            source_ref: None,
            service: None,
            service_command: None,
            task: None,
            task_command: None,
            exit_code: None,
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        };
    }

    let effective_ref =
        refresh_ref_override(repo.source_ref.as_deref(), options.git_ref.as_deref());
    let upstream_ref = if effective_ref.is_none() {
        workspace_repo_upstream_branch(&repo.path)
    } else {
        None
    };
    if effective_ref.is_none() && upstream_ref.is_none() {
        return WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            required: repo.required,
            ok: !repo.required,
            status: if repo.required {
                String::from("REFRESH FAILED")
            } else {
                String::from("WARN")
            },
            phase: String::from("refresh"),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Refresh target unavailable: {}", repo_name),
                why: format!(
                    "workspace repo `{}` does not declare `source.ref`, has no `--ref` override, and does not have an upstream branch to refresh from",
                    repo_name
                ),
                next: String::from(
                    "declare `source.ref`, configure an upstream branch, or rerun `ota workspace refresh --dry-run --ref <branch|tag|sha>` before applying `ota workspace refresh`",
                ),
            }],
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            service: None,
            service_command: None,
            task: None,
            task_command: None,
            exit_code: Some(1),
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        };
    }
    let refresh_command = workspace_refresh_command(effective_ref, options.force, options.prune);

    if options.dry_run {
        return WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            required: repo.required,
            ok: true,
            status: String::from("PREVIEW"),
            phase: String::from("refresh"),
            findings: Vec::new(),
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            service: None,
            service_command: None,
            task: None,
            task_command: Some(refresh_command),
            exit_code: None,
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        };
    }

    let refresh = match run_workspace_repo_refresh_command(&repo, effective_ref, options, mode) {
        Ok(result) => result,
        Err(error) => {
            return WorkspaceRepoUpReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                workflow: repo.workflow.clone(),
                required: repo.required,
                ok: !repo.required,
                status: if repo.required {
                    String::from("REFRESH FAILED")
                } else {
                    String::from("WARN")
                },
                phase: String::from("refresh"),
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo refresh failed: {}", repo_name),
                    why: format!(
                        "workspace repo `{}` could not start its refresh command: {}",
                        repo_name, error
                    ),
                    next: String::from(
                        "inspect the `Refresh command:` line and refresh output, then fix branch tracking or source access before rerunning `ota workspace refresh`",
                    ),
                }],
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                service: None,
                service_command: None,
                task: None,
                task_command: Some(refresh_command),
                exit_code: Some(1),
                stdout: None,
                stderr: None,
                env_sources: Vec::new(),
                next: None,
                next_steps: Vec::new(),
            };
        }
    };

    if refresh.exit_code != 0 {
        let finding = workspace_refresh_failure_finding(
            &repo_name,
            effective_ref.or(repo.source_ref.as_deref()),
            Some(&refresh.stderr),
        );
        return WorkspaceRepoUpReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display,
            workflow: repo.workflow.clone(),
            required: repo.required,
            ok: !repo.required,
            status: if repo.required {
                String::from("REFRESH FAILED")
            } else {
                String::from("WARN")
            },
            phase: String::from("refresh"),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    finding.severity
                } else if finding.severity == FindingSeverity::Error {
                    FindingSeverity::Warn
                } else {
                    finding.severity
                },
                ..finding
            }],
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            service: None,
            service_command: None,
            task: None,
            task_command: Some(refresh_command),
            exit_code: Some(refresh.exit_code),
            stdout: match mode {
                RepoExecutionMode::Capture => {
                    (!refresh.stdout.is_empty()).then_some(refresh.stdout)
                }
                RepoExecutionMode::Stream => None,
            },
            stderr: match mode {
                RepoExecutionMode::Capture => {
                    (!refresh.stderr.is_empty()).then_some(refresh.stderr)
                }
                RepoExecutionMode::Stream => None,
            },
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        };
    }

    WorkspaceRepoUpReport {
        name: repo.name,
        path: path_display,
        contract_path: contract_path_display,
        workflow: repo.workflow,
        required: repo.required,
        ok: true,
        status: String::from("READY"),
        phase: String::from("refresh"),
        findings: Vec::new(),
        source_url: repo.source_url.clone(),
        source_ref: repo.source_ref.clone(),
        service: None,
        service_command: None,
        task: None,
        task_command: Some(refresh_command),
        exit_code: None,
        stdout: match mode {
            RepoExecutionMode::Capture => (!refresh.stdout.is_empty()).then_some(refresh.stdout),
            RepoExecutionMode::Stream => None,
        },
        stderr: match mode {
            RepoExecutionMode::Capture => (!refresh.stderr.is_empty()).then_some(refresh.stderr),
            RepoExecutionMode::Stream => None,
        },
        env_sources: Vec::new(),
        next: None,
        next_steps: Vec::new(),
    }
}

fn run_workspace_repo_task(
    repo: WorkspaceRepoRef,
    task: &str,
    task_args: &[String],
    mode: RepoExecutionMode,
    workspace_path: &Path,
) -> WorkspaceRepoRunReport {
    let repo_name = repo.name.clone();
    let contract_path_display = repo.contract_path.display().to_string();
    let path_display = repo.path.display().to_string();
    let requested_task = task.to_string();
    let resolved_task = repo.resolve_workspace_task(task).to_string();
    let resolved_task_field = (resolved_task != requested_task).then(|| resolved_task.clone());

    match acquire_workspace_repo(&repo, mode) {
        Ok(acquisition) if acquisition.exit_code != 0 => {
            return WorkspaceRepoRunReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                required: repo.required,
                ok: !repo.required,
                status: if repo.required {
                    "ACQUIRE FAILED"
                } else {
                    "WARN"
                }
                .to_string(),
                task: requested_task.clone(),
                repo_task: resolved_task_field.clone(),
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo acquisition failed: {}", repo_name),
                    why: match repo.source_url.as_deref() {
                        Some(source_url) => format!(
                            "workspace repo `{}` could not be cloned from `{}`",
                            repo_name, source_url
                        ),
                        None => format!("workspace repo `{}` could not be acquired", repo_name),
                    },
                    next: format!(
                        "inspect the `Source:` and `Acquire output:` lines, then fix source access and credentials before rerunning `ota workspace run {}`",
                        requested_task
                    ),
                }],
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                task_command: None,
                exit_code: Some(acquisition.exit_code),
                stdout: match mode {
                    RepoExecutionMode::Capture => Some(acquisition.stdout),
                    RepoExecutionMode::Stream => None,
                },
                stderr: match mode {
                    RepoExecutionMode::Capture => Some(acquisition.stderr),
                    RepoExecutionMode::Stream => None,
                },
                env_sources: Vec::new(),
                next: None,
                next_steps: Vec::new(),
            };
        }
        Ok(_) => {}
        Err(error) => {
            return WorkspaceRepoRunReport {
                name: repo.name,
                path: path_display,
                contract_path: contract_path_display,
                required: repo.required,
                ok: !repo.required,
                status: if repo.required {
                    "ACQUIRE FAILED"
                } else {
                    "WARN"
                }
                .to_string(),
                task: requested_task.clone(),
                repo_task: resolved_task_field.clone(),
                findings: vec![Finding {
                    identity: None,
                    severity: if repo.required {
                        FindingSeverity::Error
                    } else {
                        FindingSeverity::Warn
                    },
                    summary: format!("Repo acquisition failed: {}", repo_name),
                    why: format!(
                        "workspace repo `{}` could not be acquired: {}",
                        repo_name, error
                    ),
                    next: format!(
                        "inspect the `Source:` line and acquisition output, then fix source access and credentials before rerunning `ota workspace run {}`",
                        requested_task
                    ),
                }],
                source_url: repo.source_url.clone(),
                source_ref: repo.source_ref.clone(),
                task_command: None,
                exit_code: Some(1),
                stdout: None,
                stderr: None,
                env_sources: Vec::new(),
                next: None,
                next_steps: Vec::new(),
            };
        }
    }

    match load_contract(&repo.contract_path) {
        Ok(contract) => {
            let task_command = contract
                .tasks
                .get(&resolved_task)
                .and_then(task_command_preview);
            if let Err(error) = validate_contract_with_path(&contract, Some(&repo.contract_path)) {
                return WorkspaceRepoRunReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display.clone(),
                    required: repo.required,
                    ok: !repo.required,
                    status: if repo.required {
                        "INVALID CONTRACT"
                    } else {
                        "WARN"
                    }
                    .to_string(),
                    task: requested_task.clone(),
                    repo_task: resolved_task_field.clone(),
                    findings: error
                        .errors()
                        .iter()
                        .map(|validation_error| Finding {
                            identity: None,
                            severity: if repo.required {
                                FindingSeverity::Error
                            } else {
                                FindingSeverity::Warn
                            },
                            summary: format!("Invalid repo contract: {}", repo_name),
                            why: format!(
                                "repo contract `{}` is invalid: {}",
                                contract_path_display, validation_error
                            ),
                            next: workspace_repo_validate_then_rerun_next(
                                &repo.contract_path,
                                &command_for_workspace(
                                    &format!("ota workspace run {}", requested_task),
                                    workspace_path,
                                ),
                            ),
                        })
                        .collect(),
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    task_command,
                    exit_code: Some(1),
                    stdout: None,
                    stderr: None,
                    env_sources: Vec::new(),
                    next: None,
                    next_steps: Vec::new(),
                };
            }

            let env_sources = contract
                .tasks
                .get(&resolved_task)
                .map(|task_spec| {
                    workspace_env_sources(
                        &contract,
                        &repo.contract_path,
                        Some(&resolved_task),
                        Some(&task_spec.env),
                        Some(&repo.policy_env),
                    )
                })
                .unwrap_or_default();
            let run_result = match mode {
                RepoExecutionMode::Capture => {
                    run_task_captured_with_args_with_overrides_with_policy(
                        &contract,
                        &repo.contract_path,
                        &resolved_task,
                        task_args,
                        ExecutionOverrides::default(),
                        Some(&repo.policy_env),
                    )
                    .map(|result| CommandRunResult {
                        exit_code: result.exit_code,
                        executed_tasks: Vec::new(),
                        stdout: result.stdout,
                        stderr: result.stderr,
                        target: result.target,
                        runtime: result.runtime,
                        service_termination: result.service_termination,
                        fulfilled_toolchains: result.fulfilled_toolchains,
                        host_service_cleanup: result.host_service_cleanup,
                    })
                }
                RepoExecutionMode::Stream => {
                    run_task_with_progress_and_args_and_overrides_with_policy(
                        &contract,
                        &repo.contract_path,
                        &resolved_task,
                        false,
                        task_args,
                        ExecutionOverrides::default(),
                        false,
                        None,
                        Some(&repo.policy_env),
                    )
                    .map(|result| CommandRunResult {
                        exit_code: result.exit_code,
                        executed_tasks: Vec::new(),
                        stdout: String::new(),
                        stderr: String::new(),
                        target: result.target,
                        runtime: result.runtime,
                        service_termination: result.service_termination,
                        fulfilled_toolchains: result.fulfilled_toolchains,
                        host_service_cleanup: result.host_service_cleanup,
                    })
                }
            };

            match run_result {
                Ok(result) if result.exit_code == 0 => WorkspaceRepoRunReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    required: repo.required,
                    ok: true,
                    status: String::from("READY"),
                    task: requested_task.clone(),
                    repo_task: resolved_task_field.clone(),
                    findings: Vec::new(),
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    task_command: task_command.clone(),
                    exit_code: None,
                    stdout: match mode {
                        RepoExecutionMode::Capture => Some(result.stdout),
                        RepoExecutionMode::Stream => None,
                    },
                    stderr: match mode {
                        RepoExecutionMode::Capture => Some(result.stderr),
                        RepoExecutionMode::Stream => None,
                    },
                    env_sources: env_sources.clone(),
                    next: None,
                    next_steps: Vec::new(),
                },
                Ok(result) => WorkspaceRepoRunReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    required: repo.required,
                    ok: !repo.required,
                    status: if repo.required { "TASK FAILED" } else { "WARN" }.to_string(),
                    task: requested_task.clone(),
                    repo_task: resolved_task_field.clone(),
                    findings: vec![Finding {
                        identity: None,
                        severity: if repo.required {
                            FindingSeverity::Error
                        } else {
                            FindingSeverity::Warn
                        },
                        summary: format!("Task failed: {}", resolved_task),
                        why: format!(
                            "workspace repo `{}` task `{}` exited with code {}",
                            repo_name, resolved_task, result.exit_code
                        ),
                        next: format!(
                            "inspect repo `{}` task `{}` output and repair the failure",
                            repo_name, resolved_task
                        ),
                    }],
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    task_command: task_command.clone(),
                    exit_code: Some(result.exit_code),
                    stdout: match mode {
                        RepoExecutionMode::Capture => Some(result.stdout),
                        RepoExecutionMode::Stream => None,
                    },
                    stderr: match mode {
                        RepoExecutionMode::Capture => Some(result.stderr),
                        RepoExecutionMode::Stream => None,
                    },
                    env_sources: env_sources.clone(),
                    next: None,
                    next_steps: Vec::new(),
                },
                Err(error) => WorkspaceRepoRunReport {
                    name: repo.name,
                    path: path_display,
                    contract_path: contract_path_display,
                    required: repo.required,
                    ok: !repo.required,
                    status: if repo.required { "TASK FAILED" } else { "WARN" }.to_string(),
                    task: requested_task.clone(),
                    repo_task: resolved_task_field.clone(),
                    findings: vec![Finding {
                        identity: None,
                        severity: if repo.required {
                            FindingSeverity::Error
                        } else {
                            FindingSeverity::Warn
                        },
                        summary: format!("Task execution failed: {}", resolved_task),
                        why: format!(
                            "workspace repo `{}` task `{}` could not be executed: {}",
                            repo_name,
                            resolved_task,
                            render_run_error(error)
                        ),
                        next: format!(
                            "repair repo `{}` task `{}` and rerun `ota workspace run {}`",
                            repo_name, resolved_task, requested_task
                        ),
                    }],
                    source_url: repo.source_url.clone(),
                    source_ref: repo.source_ref.clone(),
                    task_command,
                    exit_code: Some(1),
                    stdout: None,
                    stderr: None,
                    env_sources,
                    next: None,
                    next_steps: Vec::new(),
                },
            }
        }
        Err(error) => WorkspaceRepoRunReport {
            name: repo.name,
            path: path_display,
            contract_path: contract_path_display.clone(),
            required: repo.required,
            ok: !repo.required,
            status: if repo.required {
                "INVALID CONTRACT"
            } else {
                "WARN"
            }
            .to_string(),
            task: requested_task.clone(),
            repo_task: resolved_task_field,
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Unreadable repo contract: {}", repo_name),
                why: format!(
                    "workspace repo `{}` contract `{}` could not be loaded: {}",
                    repo_name, contract_path_display, error
                ),
                next: workspace_repo_validate_then_rerun_next(
                    &repo.contract_path,
                    &command_for_workspace(
                        &format!("ota workspace run {}", requested_task),
                        workspace_path,
                    ),
                ),
            }],
            source_url: repo.source_url.clone(),
            source_ref: repo.source_ref.clone(),
            task_command: None,
            exit_code: Some(1),
            stdout: None,
            stderr: None,
            env_sources: Vec::new(),
            next: None,
            next_steps: Vec::new(),
        },
    }
}

fn adjust_workspace_up_findings(mut findings: Vec<Finding>, required: bool) -> Vec<Finding> {
    if required {
        return findings;
    }
    for finding in &mut findings {
        if finding.severity == FindingSeverity::Error {
            finding.severity = FindingSeverity::Warn;
        }
    }
    findings
}

fn load_and_check_workspace(
    path: &Path,
    jobs: usize,
    progress_mode: Option<WorkspaceProgressMode>,
) -> Result<crate::workspace::WorkspaceDoctorReport, WorkspaceProblem> {
    let workspace = load_workspace_contract(path).map_err(WorkspaceProblem::Load)?;
    let workspace_name = workspace.workspace.name.clone();
    let repo_refs =
        ordered_workspace_repo_refs(path, &workspace).map_err(WorkspaceProblem::Validation)?;

    let mut repos = BTreeMap::new();
    let mut completed = BTreeSet::new();
    let mut ok = true;
    let mut pending = repo_refs.into_iter().enumerate().collect::<Vec<_>>();

    while !pending.is_empty() {
        let ready = pending
            .iter()
            .enumerate()
            .filter(|(_, (_, repo))| {
                repo.depends_on
                    .iter()
                    .all(|dependency| completed.contains(dependency))
            })
            .map(|(pending_index, _)| pending_index)
            .take(jobs)
            .collect::<Vec<_>>();

        debug_assert!(
            !ready.is_empty(),
            "validated workspace repos should remain schedulable"
        );

        let mut batch = Vec::new();
        for pending_index in ready.into_iter().rev() {
            batch.push(pending.remove(pending_index));
        }
        batch.reverse();

        let (tx, rx) = mpsc::channel();
        let handles = batch
            .into_iter()
            .map(|(order, repo)| {
                let tx = tx.clone();
                let workspace_path = path.to_path_buf();
                thread::spawn(move || {
                    let report = check_workspace_repo(repo, &workspace_path);
                    let _ = tx.send((order, report));
                })
            })
            .collect::<Vec<_>>();
        drop(tx);

        for _ in 0..handles.len() {
            let (order, report) = rx
                .recv()
                .expect("workspace check worker should send a report");
            if let Some(progress_mode) = progress_mode {
                let status = if report.ok { "READY" } else { "NOT READY" };
                emit_workspace_progress_line(
                    progress_mode,
                    "workspace.check",
                    &workspace_name,
                    status,
                    &report.name,
                    None,
                );
            }
            if report.required && !report.ok {
                ok = false;
            }
            completed.insert(report.name.clone());
            repos.insert(order, report);
        }

        for handle in handles {
            handle
                .join()
                .expect("workspace check thread should not panic");
        }
    }

    Ok(crate::workspace::WorkspaceDoctorReport {
        ok,
        repos: repos.into_values().collect(),
    })
}

fn check_workspace_repo(
    repo: WorkspaceRepoRef,
    workspace_path: &Path,
) -> crate::workspace::WorkspaceRepoDoctorReport {
    let repo_name = repo.name.clone();
    let contract_path_display = repo.contract_path.display().to_string();

    if !repo.present {
        return crate::workspace::WorkspaceRepoDoctorReport {
            name: repo.name,
            path: repo.path.display().to_string(),
            contract_path: contract_path_display,
            workflow: repo.workflow,
            required: repo.required,
            ok: !repo.required,
            agent_verdict: DoctorVerdict::NotReady,
            primary_blocker: None,
            execution: None,
            provisioning: None,
            adapter_bootstrap: None,
            extensions: BTreeMap::new(),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Repo not acquired: {}", repo_name),
                why: format!(
                    "workspace repo `{}` has not been acquired into `{}` yet",
                    repo_name,
                    repo.path.display()
                ),
                next: match repo.source_url.as_deref() {
                    Some(source_url) => format!(
                        "run `ota workspace up` to acquire `{}` from `{}`",
                        repo_name, source_url
                    ),
                    None => {
                        format!(
                            "create `{}` and rerun `ota workspace check`",
                            repo.path.display()
                        )
                    }
                },
            }],
        };
    }

    match load_contract(&repo.contract_path) {
        Ok(contract) => {
            if let Err(error) = validate_contract_with_path(&contract, Some(&repo.contract_path)) {
                return crate::workspace::WorkspaceRepoDoctorReport {
                    name: repo.name,
                    path: repo.path.display().to_string(),
                    contract_path: contract_path_display.clone(),
                    workflow: repo.workflow.clone(),
                    required: repo.required,
                    ok: !repo.required,
                    agent_verdict: crate::workspace::agent_verdict_from_agent(
                        contract.agent.as_ref(),
                    ),
                    primary_blocker: None,
                    execution: WorkspaceExecutionSummary::from_contract_with_policy(
                        &contract,
                        &repo.contract_path,
                        Some(&repo.policy_env),
                    ),
                    provisioning: None,
                    adapter_bootstrap: None,
                    extensions: contract.extensions.clone(),
                    findings: error
                        .errors()
                        .iter()
                        .map(|validation_error| Finding {
                            identity: None,
                            severity: if repo.required {
                                FindingSeverity::Error
                            } else {
                                FindingSeverity::Warn
                            },
                            summary: format!("Invalid repo contract: {}", repo_name),
                            why: format!(
                                "repo contract `{}` is invalid: {}",
                                contract_path_display, validation_error
                            ),
                            next: workspace_repo_validate_then_rerun_next(
                                &repo.contract_path,
                                &command_for_workspace("ota workspace check", workspace_path),
                            ),
                        })
                        .collect(),
                };
            }

            let report = diagnose_checks_only_for_workflow(
                &contract,
                &repo.contract_path,
                repo.workflow.as_deref(),
            );
            let findings = adjust_workspace_up_findings(report.findings, repo.required);

            crate::workspace::WorkspaceRepoDoctorReport {
                name: repo.name,
                path: repo.path.display().to_string(),
                contract_path: contract_path_display,
                workflow: repo.workflow,
                required: repo.required,
                ok: !findings
                    .iter()
                    .any(|finding| finding.severity == FindingSeverity::Error),
                agent_verdict: crate::workspace::agent_verdict_from_agent(contract.agent.as_ref()),
                primary_blocker: None,
                execution: WorkspaceExecutionSummary::from_contract_with_policy(
                    &contract,
                    &repo.contract_path,
                    Some(&repo.policy_env),
                ),
                provisioning: None,
                adapter_bootstrap: None,
                extensions: contract.extensions.clone(),
                findings,
            }
        }
        Err(error) => crate::workspace::WorkspaceRepoDoctorReport {
            name: repo.name,
            path: repo.path.display().to_string(),
            contract_path: contract_path_display.clone(),
            workflow: repo.workflow,
            required: repo.required,
            ok: !repo.required,
            agent_verdict: DoctorVerdict::NotReady,
            primary_blocker: None,
            execution: None,
            provisioning: None,
            adapter_bootstrap: None,
            extensions: BTreeMap::new(),
            findings: vec![Finding {
                identity: None,
                severity: if repo.required {
                    FindingSeverity::Error
                } else {
                    FindingSeverity::Warn
                },
                summary: format!("Unreadable repo contract: {}", repo_name),
                why: format!(
                    "workspace repo `{}` contract `{}` could not be loaded: {}",
                    repo_name, contract_path_display, error
                ),
                next: workspace_repo_validate_then_rerun_next(
                    &repo.contract_path,
                    &command_for_workspace("ota workspace check", workspace_path),
                ),
            }],
        },
    }
}

fn render_contract_problem(error: &ContractProblem) -> String {
    match error {
        ContractProblem::Load(error) => error.to_string(),
        ContractProblem::Validation(error) => error.to_string(),
    }
}

fn service_start_order_for(contract: &Contract, selected: &BTreeSet<String>) -> Vec<String> {
    let mut order = Vec::new();
    let mut visited = BTreeSet::new();
    for name in selected.clone() {
        visit_service_start_order(contract, name.as_str(), selected, &mut visited, &mut order);
    }
    order
}

fn required_service_closure(contract: &Contract) -> BTreeSet<String> {
    let mut selected = BTreeSet::new();
    for (name, service) in &contract.services {
        if service.required {
            collect_service_dependencies(contract, name, &mut selected);
        }
    }
    selected
}

fn selected_up_setup_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    contract
        .selected_setup_task_name_for(workflow_name)
        .filter(|name| contract.tasks.contains_key(*name))
}

fn selected_up_prepare_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    contract
        .selected_prepare_task_name_for(workflow_name)
        .filter(|name| contract.tasks.contains_key(*name))
}

fn selected_up_prepare_action<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a crate::schema::TaskActionSpec> {
    contract.selected_prepare_action_for(workflow_name)
}

fn selected_execution_plan_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    let (_, workflow) = contract.selected_workflow(workflow_name)?;
    workflow
        .run
        .as_ref()
        .map(|phase| phase.task.as_str())
        .filter(|task| !task.trim().is_empty())
        .filter(|name| contract.tasks.contains_key(*name))
        .or_else(|| {
            workflow
                .setup
                .as_ref()
                .map(|phase| phase.task.as_str())
                .filter(|task| !task.trim().is_empty())
                .filter(|name| contract.tasks.contains_key(*name))
        })
}

fn selected_up_run_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    contract
        .selected_run_task_name_for(workflow_name)
        .filter(|name| contract.tasks.contains_key(*name))
}

fn selected_up_attach_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    contract
        .selected_attach_task_name_for(workflow_name)
        .filter(|name| contract.tasks.contains_key(*name))
}

fn selected_up_primary_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    selected_up_setup_task_name(contract, workflow_name)
        .or_else(|| selected_up_run_task_name(contract, workflow_name))
}

fn selected_workflow_instance_prerequisite_selectors(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> Vec<String> {
    contract.selected_workflow_instance_prerequisite_selectors(workflow_name)
}

fn selected_up_activation_task_name<'a>(
    contract: &'a Contract,
    workflow_name: Option<&str>,
) -> Option<&'a str> {
    let setup_task = selected_up_setup_task_name(contract, workflow_name);
    selected_up_run_task_name(contract, workflow_name).filter(|task_name| {
        Some(*task_name) != setup_task
            && contract
                .tasks
                .get(*task_name)
                .is_some_and(TaskSpec::has_any_service_runtime)
    })
}

fn task_required_service_closure(contract: &Contract, task_name: &str) -> BTreeSet<String> {
    let mut selected = BTreeSet::new();
    let Some(task) = contract.tasks.get(task_name) else {
        return selected;
    };
    for service_name in &task.requires_services {
        collect_service_dependencies(contract, service_name, &mut selected);
    }
    selected
}

fn selected_workflow_required_service_closure(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> BTreeSet<String> {
    if let Some((_, workflow)) = contract.selected_workflow(workflow_name) {
        let mut selected = BTreeSet::new();
        let services = &workflow.services;
        for service_name in &services.required {
            collect_service_dependencies(contract, service_name, &mut selected);
        }
        selected
    } else {
        required_service_closure(contract)
    }
}

fn up_pre_setup_service_closure(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> BTreeSet<String> {
    selected_up_setup_task_name(contract, workflow_name)
        .map(|task_name| task_required_service_closure(contract, task_name))
        .unwrap_or_default()
}

fn remaining_up_required_service_closure(
    contract: &Contract,
    workflow_name: Option<&str>,
    already_selected: &BTreeSet<String>,
) -> BTreeSet<String> {
    selected_workflow_required_service_closure(contract, workflow_name)
        .into_iter()
        .filter(|service_name| !already_selected.contains(service_name))
        .collect()
}

fn collect_service_dependencies(contract: &Contract, name: &str, selected: &mut BTreeSet<String>) {
    if !selected.insert(name.to_string()) {
        return;
    }

    let Some(service) = contract.services.get(name) else {
        return;
    };

    for dependency in &service.depends_on {
        collect_service_dependencies(contract, dependency, selected);
    }
}

fn visit_service_start_order(
    contract: &Contract,
    name: &str,
    selected: &BTreeSet<String>,
    visited: &mut BTreeSet<String>,
    order: &mut Vec<String>,
) {
    if !visited.insert(name.to_string()) {
        return;
    }

    if let Some(service) = contract.services.get(name) {
        for dependency in &service.depends_on {
            if selected.contains(dependency) {
                visit_service_start_order(contract, dependency, selected, visited, order);
            }
        }
    }

    order.push(name.to_string());
}

fn run_shell_command(
    command: &str,
    working_dir: &Path,
    mode: RepoExecutionMode,
    loader_label: &str,
) -> Result<CommandRunResult, String> {
    match mode {
        RepoExecutionMode::Stream => {
            let mut process = shell_command(command);
            process.current_dir(working_dir);
            run_streaming_command_with_loader(&mut process, loader_label)
                .map(|exit_code| CommandRunResult {
                    exit_code,
                    executed_tasks: Vec::new(),
                    stdout: String::new(),
                    stderr: String::new(),
                    target: None,
                    runtime: None,
                    service_termination: None,
                    fulfilled_toolchains: Vec::new(),
                    host_service_cleanup: Vec::new(),
                })
                .map_err(|error| format!("failed to execute `{command}`: {error}"))
        }
        RepoExecutionMode::Capture => shell_command(command)
            .current_dir(working_dir)
            .stdin(std::process::Stdio::inherit())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .and_then(|child| child.wait_with_output())
            .map(|output| CommandRunResult {
                exit_code: output.status.code().unwrap_or(1),
                executed_tasks: Vec::new(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            })
            .map_err(|error| format!("failed to execute `{command}`: {error}")),
    }
}

fn finalize_debug(
    mut output: CommandOutput,
    debug: bool,
    debug_lines: Vec<String>,
) -> CommandOutput {
    if !looks_like_json(&output.stdout) {
        output.stdout = stylize_inline_code(&output.stdout);
    }
    if let Some(stderr) = output.stderr.as_ref() {
        if !looks_like_json(stderr) {
            output.stderr = Some(stylize_inline_code(stderr));
        }
    }

    if !debug {
        return output;
    }

    output.with_stderr(Some(debug_lines.join("\n")))
}

#[cfg(unix)]
fn shell_command(command: &str) -> Command {
    let mut shell = Command::new("sh");
    shell
        .arg("-c")
        .arg(signal_forwarding_shell_script(command.to_string()));
    shell
}

#[cfg(windows)]
fn shell_command(command: &str) -> Command {
    if looks_like_powershell_script(command) {
        return powershell_shell_command(command);
    }
    if looks_like_posix_script(command)
        && let Some(bash) = bash_executable()
    {
        let mut shell = Command::new(bash);
        shell.arg("-lc").arg(command);
        return shell;
    }
    let mut shell = Command::new("cmd");
    shell.arg("/C").arg(command);
    shell
}

#[cfg(any(windows, test))]
fn looks_like_posix_script(command: &str) -> bool {
    let command = command.trim();
    if command.is_empty() || looks_like_powershell_script(command) {
        return false;
    }

    const POSIX_MARKERS: [&str; 8] = [
        "command -v ",
        "; then",
        " fi",
        "&& ",
        " || ",
        "<<'PY'",
        "sh -lc ",
        "bash -lc ",
    ];

    if command.starts_with("cmd ") || command.starts_with("cmd/") {
        return false;
    }

    command.starts_with("./")
        || command.starts_with("../")
        || command.contains("&&")
        || command.contains("||")
        || command.contains('\n')
        || command.contains("export ")
        || command.contains("printf '")
        || command.contains("printf \"")
        || POSIX_MARKERS.iter().any(|marker| command.contains(marker))
        || contains_posix_env_reference(command)
}

#[cfg(any(windows, test))]
fn looks_like_powershell_script(command: &str) -> bool {
    let command = command.trim_start();
    command.starts_with("powershell ")
        || command.starts_with("pwsh ")
        || command.contains("$LASTEXITCODE")
        || command.contains("$env:")
        || command.contains("Join-Path ")
        || command.contains("Test-Path ")
        || command.contains("Add-Content ")
        || command.contains("Set-Content ")
        || command.contains("Get-ChildItem ")
        || command.contains("New-Item ")
        || command.contains("Write-Host ")
        || command.contains("Write-Error ")
        || command.contains("throw ")
}

#[cfg(any(windows, test))]
fn contains_posix_env_reference(command: &str) -> bool {
    let bytes = command.as_bytes();
    bytes.windows(2).any(|window| {
        window[0] == b'$'
            && (window[1] == b'{' || window[1] == b'_' || window[1].is_ascii_alphabetic())
    })
}

#[cfg(windows)]
fn powershell_shell_command(command: &str) -> Command {
    let executable = if has_pwsh() { "pwsh" } else { "powershell" };
    let mut shell = Command::new(executable);
    shell.args(["-NoProfile", "-NonInteractive", "-Command", command]);
    shell
}

#[cfg(windows)]
fn has_bash() -> bool {
    bash_executable().is_some()
}

#[cfg(windows)]
fn bash_executable() -> Option<PathBuf> {
    static BASH: OnceLock<Option<PathBuf>> = OnceLock::new();
    BASH.get_or_init(find_bash_executable).clone()
}

#[cfg(windows)]
fn find_bash_executable() -> Option<PathBuf> {
    let mut candidates = env::var_os("PATH")
        .map(|paths| {
            env::split_paths(&paths)
                .flat_map(|dir| [dir.join("bash.exe"), dir.join("bash")])
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    for key in ["ProgramW6432", "ProgramFiles", "ProgramFiles(x86)"] {
        if let Some(base) = env::var_os(key) {
            let base = PathBuf::from(base);
            candidates.push(base.join("Git").join("bin").join("bash.exe"));
            candidates.push(base.join("Git").join("usr").join("bin").join("bash.exe"));
        }
    }

    candidates.into_iter().find(|candidate| {
        candidate.is_file()
            && Command::new(candidate)
                .arg("--version")
                .status()
                .map(|status| status.success())
                .unwrap_or(false)
    })
}

#[cfg(windows)]
fn has_pwsh() -> bool {
    static HAS_PWSH: OnceLock<bool> = OnceLock::new();
    *HAS_PWSH.get_or_init(|| {
        Command::new("pwsh")
            .args(["-NoProfile", "-NonInteractive", "-Command", "exit 0"])
            .status()
            .map(|status| status.success())
            .unwrap_or(false)
    })
}

fn shell_single_quote(command: &str) -> String {
    let escaped = command.replace('\'', r"'\''");
    format!("'{}'", escaped)
}

#[cfg(unix)]
fn signal_forwarding_shell_script(command: String) -> String {
    format!("trap 'kill 0' INT TERM; {command}")
}

#[cfg(windows)]
#[allow(dead_code)]
fn signal_forwarding_shell_script(command: String) -> String {
    command
}

fn to_json<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_string_pretty(value).expect("serializing CLI output should not fail")
}

fn to_json_compact<T: serde::Serialize>(value: &T) -> String {
    serde_json::to_string(value).expect("serializing CLI output should not fail")
}

fn to_json_value(value: JsonValue) -> String {
    serde_json::to_string_pretty(&value).expect("serializing CLI output should not fail")
}

fn looks_like_json(value: &str) -> bool {
    let trimmed = value.trim();
    (!trimmed.is_empty()) && serde_json::from_str::<JsonValue>(trimmed).is_ok()
}

fn stylize_inline_code(value: &str) -> String {
    let mut output = String::with_capacity(value.len());
    let mut rest = value;

    loop {
        let Some(start) = rest.find('`') else {
            output.push_str(rest);
            break;
        };
        output.push_str(&rest[..start]);
        let after_start = &rest[start + 1..];
        let Some(end) = after_start.find('`') else {
            output.push_str(&rest[start..]);
            break;
        };
        let code = &after_start[..end];
        output.push('`');
        output.push_str(&paint_code(code));
        output.push('`');
        rest = &after_start[end + 1..];
    }

    output
}

fn stylize_yaml_preview(value: &str) -> String {
    if plain_mode() {
        return value.to_string();
    }

    let mut out = String::with_capacity(value.len() + 16);
    for (idx, line) in value.lines().enumerate() {
        if idx > 0 {
            out.push('\n');
        }
        let trimmed = line.trim_start();
        if trimmed.is_empty() {
            continue;
        }

        let styled = if trimmed.ends_with(':') {
            paint(line, "1;38;2;155;240;195")
        } else if trimmed.contains(": ") {
            paint(line, "1;37")
        } else {
            paint(line, "37")
        };
        out.push_str(&styled);
    }
    out
}

struct LoadedContractTarget {
    contract: crate::schema::Contract,
    contract_path: PathBuf,
}

fn load_and_validate_target(
    path: &Path,
    member: Option<&str>,
) -> Result<LoadedContractTarget, ContractProblem> {
    let (contract, contract_path) = match member {
        Some(member) => load_contract_for_member(path, member).map_err(ContractProblem::Load)?,
        None => load_contract_auto(path).map_err(ContractProblem::Load)?,
    };
    validate_contract_with_path(&contract, Some(&contract_path))
        .map_err(ContractProblem::Validation)?;
    Ok(LoadedContractTarget {
        contract,
        contract_path,
    })
}

fn load_and_validate_workspace(path: &Path) -> Result<(), WorkspaceProblem> {
    let workspace = load_workspace_contract(path).map_err(WorkspaceProblem::Load)?;
    validate_workspace_contract(path, &workspace).map_err(WorkspaceProblem::Validation)?;
    Ok(())
}

fn load_and_diagnose_workspace(
    path: &Path,
    jobs: usize,
) -> Result<crate::workspace::WorkspaceDoctorReport, WorkspaceProblem> {
    let workspace = load_workspace_contract(path).map_err(WorkspaceProblem::Load)?;
    diagnose_workspace_contract_with_jobs(path, &workspace, jobs)
        .map_err(WorkspaceProblem::Validation)
}

fn load_and_diagnose_workspace_streaming(
    path: &Path,
    jobs: usize,
    progress_mode: Option<WorkspaceProgressMode>,
) -> Result<crate::workspace::WorkspaceDoctorReport, WorkspaceProblem> {
    let workspace = load_workspace_contract(path).map_err(WorkspaceProblem::Load)?;
    let workspace_name = workspace.workspace.name.clone();
    let repo_refs =
        ordered_workspace_repo_refs(path, &workspace).map_err(WorkspaceProblem::Validation)?;

    let mut repos = BTreeMap::new();
    let mut ok = true;
    let mut completed = BTreeSet::new();
    let mut pending = repo_refs.into_iter().enumerate().collect::<Vec<_>>();

    while !pending.is_empty() {
        let ready = pending
            .iter()
            .enumerate()
            .filter(|(_, (_, repo))| {
                repo.depends_on
                    .iter()
                    .all(|dependency| completed.contains(dependency))
            })
            .map(|(pending_index, _)| pending_index)
            .take(jobs)
            .collect::<Vec<_>>();

        debug_assert!(
            !ready.is_empty(),
            "validated workspace repos should remain schedulable"
        );

        let (tx, rx) = mpsc::channel();
        let mut handles = Vec::new();
        for pending_index in ready.into_iter().rev() {
            let (order, repo) = pending.remove(pending_index);
            let tx = tx.clone();
            let workspace_path = path.to_path_buf();
            handles.push(thread::spawn(move || {
                let report = crate::workspace::diagnose_workspace_repo(repo, &workspace_path);
                let _ = tx.send((order, report));
            }));
        }
        drop(tx);

        for _ in 0..handles.len() {
            let (order, report) = rx
                .recv()
                .expect("workspace doctor worker should send a report");
            if let Some(progress_mode) = progress_mode {
                let status = if report.ok { "READY" } else { "NOT READY" };
                emit_workspace_progress_line(
                    progress_mode,
                    "workspace.doctor",
                    &workspace_name,
                    status,
                    &report.name,
                    None,
                );
            }
            if report.required && !report.ok {
                ok = false;
            }
            completed.insert(report.name.clone());
            repos.insert(order, report);
        }

        for handle in handles {
            handle
                .join()
                .expect("workspace doctor thread should not panic");
        }
    }

    Ok(crate::workspace::WorkspaceDoctorReport {
        ok,
        repos: repos.into_values().collect(),
    })
}

fn render_run_error(error: RunError) -> String {
    error.to_string()
}

const NO_ACTIVE_POLICY_PROVISIONING_DETAILS: &str =
    "no active org policy pack is available to select approved provisioning sources";

fn up_backend_fulfillment_blocked_result(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    task_name: &str,
    task_command: Option<String>,
    stdout: String,
    stderr: String,
    error: &RunError,
) -> Option<RepoUpResult> {
    let fallback_finding = fallback_backend_fulfillment_missing_requirement_finding(error)?;
    let doctor_mode = up_doctor_mode(contract, overrides, workflow_name);
    let mut report = diagnose_preconditions_with_mode_for_workflow_with_overrides(
        contract,
        resolved_path,
        doctor_mode,
        workflow_name,
        overrides,
    );
    prepend_finding_if_missing(&mut report.findings, fallback_finding);
    report.ok = false;

    let receipt = repo_execution_receipt(
        resolved_path,
        contract,
        doctor_report_execution_context(
            contract,
            resolved_path,
            doctor_mode,
            overrides.lifecycle,
            &report,
        ),
        "BLOCKED",
        "provisioning",
        workflow_name,
        None,
        Some(task_name),
        &report.findings,
        None,
        report.findings.first().map(|finding| finding.next.clone()),
    );

    Some(RepoUpResult {
        ok: false,
        status: "BLOCKED",
        phase: "provisioning",
        report,
        preview: None,
        receipt,
        service: None,
        service_command: None,
        task: Some(task_name.to_string()),
        task_command,
        exit_code: None,
        stdout,
        stderr,
    })
}

fn fallback_backend_fulfillment_missing_requirement_finding(error: &RunError) -> Option<Finding> {
    let evidence = match error {
        RunError::BackendFulfillmentFailed {
            details, evidence, ..
        } if details == NO_ACTIVE_POLICY_PROVISIONING_DETAILS => evidence,
        _ => return None,
    };

    let Some(primary_gap) = evidence.missing.first() else {
        return Some(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Backend prerequisites are missing"),
            why: String::from(
                "the selected run path requires prerequisites that are not currently available in this execution context",
            ),
            next: String::from("install the missing prerequisites and rerun `ota up`"),
        });
    };

    if let Some((kind, name, required, details)) = parse_backend_requirement_gap(primary_gap) {
        if kind == "tool" {
            let why = if details.contains("not available") {
                format!(
                    "`{name}` is required by the selected run path, but {details} on this execution context"
                )
            } else {
                format!(
                    "`{name}` is required by the selected run path (`{required}`), but {details}"
                )
            };
            return Some(Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: format!("Tool probe failed: {name}"),
                why,
                next: format!(
                    "install `{name}` on the selected execution context and rerun `ota up`"
                ),
            });
        }

        if kind == "runtime" {
            if details.contains("not available") {
                return Some(Finding {
                    identity: None,
                    severity: FindingSeverity::Error,
                    summary: format!("Runtime probe failed: {name}"),
                    why: format!(
                        "`{name}` is required by the selected run path, but {details} on this execution context"
                    ),
                    next: format!(
                        "install `{name}` on the selected execution context and rerun `ota up`"
                    ),
                });
            }
            return Some(Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: format!("Version mismatch for runtime: {name}"),
                why: format!(
                    "`{name}` is required by the selected run path (`{required}`), but {details}"
                ),
                next: format!(
                    "install `{name}` on the selected execution context and rerun `ota up`"
                ),
            });
        }
    }

    Some(Finding {
        identity: None,
        severity: FindingSeverity::Error,
        summary: String::from("Backend prerequisites are missing"),
        why: format!(
            "the selected run path is missing required prerequisites: {}",
            evidence.missing.join("; ")
        ),
        next: String::from("install the missing prerequisites and rerun `ota up`"),
    })
}

fn parse_backend_requirement_gap(line: &str) -> Option<(String, String, String, String)> {
    let (kind, rest) = line.split_once(" `")?;
    let (name, rest) = rest.split_once("` requires `")?;
    let (required, details) = rest.split_once("` (")?;
    let details = details.strip_suffix(')')?;
    Some((
        kind.trim().to_ascii_lowercase(),
        name.to_string(),
        required.to_string(),
        details.to_string(),
    ))
}

fn render_up_run_error(
    contract_path: &Path,
    overrides: ExecutionOverrides,
    error: RunError,
) -> String {
    match error {
        RunError::HostPublicationConflict {
            task,
            listener,
            address,
            port,
        } => {
            let is_auto_projection = load_contract(contract_path)
                .ok()
                .and_then(|contract| {
                    let task_backend = effective_task_execution(
                        &contract,
                        task.as_str(),
                        ExecutionOverrides::default(),
                    )
                    .backend;
                    contract
                        .tasks
                        .get(task.as_str())
                        .and_then(|task_spec| task_spec.service_runtime_for_backend(task_backend))
                        .and_then(|runtime| runtime.listeners.get(listener.as_str()))
                        .and_then(|listener_spec| listener_spec.project.host.as_ref())
                        .map(|host| host.port.mode == TaskRuntimeHostPortMode::Auto)
                })
                .unwrap_or(false);
            let where_value = display_contract_target(&compact_contract_path(contract_path), None);
            let mut next_steps = vec![format!(
                "stop the process or container using host port `{port}`"
            )];
            if is_auto_projection {
                next_steps.push(String::from(
                    "rerun `ota up` so ota can reserve a new host port",
                ));
            } else {
                next_steps.push(format!(
                    "change `tasks.{task}.runtime.listeners.{listener}.project.host.port.mode` to `auto`"
                ));
            }
            next_steps.push(String::from("rerun `ota up`"));
            render_field_error_with_tail(
                "UP",
                &where_value,
                &format!("tasks.{task}.runtime.listeners.{listener}.project.host.port"),
                "Host publication failed",
                &[
                    format!("host port `{port}` on `{address}` is already allocated"),
                    format!(
                        "task `{task}` listener `{listener}` requested a published host endpoint"
                    ),
                ],
                &next_steps,
                None,
                None,
            )
        }
        RunError::NativeListenerBindConflict {
            task,
            listener,
            address,
            port,
        } => {
            let where_value = display_contract_target(&compact_contract_path(contract_path), None);
            let loaded_contract = load_contract(contract_path).ok();
            let compose_engine = loaded_contract.as_ref().and_then(|contract| {
                native_structured_compose_engine_for_task(contract, task.as_str(), overrides)
            });
            let mut why_lines = vec![
                format!("task `{task}` listener `{listener}` needs `{address}:{port}`"),
                format!("port `{port}` is already in use on the host"),
            ];
            let mut next_steps = vec![format!("stop the process already using `{address}:{port}`")];
            if let Some(engine) = compose_engine {
                why_lines.push(format!(
                    "task `{task}` publishes this listener through native `{}` compose",
                    engine.as_str()
                ));
                match (
                    engine,
                    loaded_contract.as_ref().and_then(|contract| {
                        native_compose_publication_owner_for_listener(
                            contract,
                            task.as_str(),
                            listener.as_str(),
                        )
                    }),
                ) {
                    (crate::schema::ComposeCliEngine::Docker, Some(service)) => {
                        why_lines.push(format!(
                            "listener `{listener}` declares native compose publication ownership through service `{service}`"
                        ));
                        next_steps.push(String::from(
                            "or rerun with `--host-port <free-port>` to remap this native compose publication",
                        ));
                    }
                    (crate::schema::ComposeCliEngine::Docker, None) => {
                        why_lines.push(String::from(
                            "native compose host-port remap requires `project.publication.compose.service`",
                        ));
                        next_steps.push(format!(
                            "or set `tasks.{task}.runtime.listeners.{listener}.project.publication.compose.service` to the owning compose service name",
                        ));
                    }
                    _ => {
                        why_lines.push(String::from(
                            "native compose host-port remap currently supports `docker compose` only",
                        ));
                        next_steps.push(String::from(
                            "or change the underlying Compose publication truth for this service to use a different host port",
                        ));
                    }
                }
            } else {
                why_lines.push(String::from(
                    "this usually means another local workload is still running",
                ));
                next_steps.push(format!(
                    "or change `tasks.{task}.runtime.listeners.{listener}.bind.port`",
                ));
            }
            render_field_error_with_tail(
                "UP",
                &where_value,
                &format!("tasks.{task}.runtime.listeners.{listener}.bind.port"),
                "Listener bind conflict",
                &why_lines,
                &[next_steps, vec![String::from("rerun `ota up`")]].concat(),
                None,
                None,
            )
        }
        RunError::RuntimeListenerResolutionFailed {
            task,
            listener,
            kind,
        } => {
            let where_value = display_contract_target(&compact_contract_path(contract_path), None);
            let runtime_listener_resolution =
                runtime_listener_resolution_text(&task, &listener, &kind, "ota up");
            render_field_error_with_tail(
                "UP",
                &where_value,
                &runtime_listener_resolution.field,
                &runtime_listener_resolution.summary,
                &runtime_listener_resolution.why_lines,
                &runtime_listener_resolution.next_steps,
                None,
                None,
            )
        }
        RunError::ToolchainFulfillmentFailed {
            task,
            toolchain,
            details,
        } => {
            let where_value = display_contract_target(&compact_contract_path(contract_path), None);
            let contract = match load_contract(contract_path) {
                Ok(contract) => contract,
                Err(_) => {
                    return render_run_error(RunError::ToolchainFulfillmentFailed {
                        task,
                        toolchain,
                        details,
                    });
                }
            };
            let target_os =
                selected_toolchain_target_os_for_task(&contract, task.as_str(), overrides);
            let summary = resolved_toolchain_fulfillment_attempt_summary(
                &contract,
                toolchain.as_str(),
                target_os,
            );
            let provider = summary.provider_label.as_str();
            render_field_error_with_tail(
                "UP",
                &where_value,
                &format!("toolchains.{toolchain}"),
                "Toolchain fulfillment failed",
                &[
                    format!("task `{task}` selected toolchain `{toolchain}`"),
                    summary.allowance_clause,
                    format!(
                        "{}; provisioning attempt failed: {details}",
                        summary.requirement_clause
                    ),
                ],
                &[
                    format!(
                        "repair `{provider}` or adjust `toolchains.{toolchain}` for task `{task}`"
                    ),
                    String::from("rerun `ota up`"),
                ],
                None,
                None,
            )
        }
        _ => render_run_error(error),
    }
}

fn render_field_error_with_tail(
    command: &str,
    where_value: &str,
    field: &str,
    summary: &str,
    why_lines: &[String],
    next_steps: &[String],
    receipt_text: Option<&str>,
    summary_block: Option<&str>,
) -> String {
    let mut output =
        structured_field_error_text(command, where_value, field, summary, why_lines, next_steps);
    if let Some(receipt_text) = receipt_text
        && !receipt_text.trim().is_empty()
    {
        output.push('\n');
        output.push_str(receipt_text);
    }
    if let Some(summary_block) = summary_block {
        output.push('\n');
        output.push_str(summary_block);
    }
    output
}

fn render_confidence(confidence: Confidence) -> String {
    match confidence {
        Confidence::High => paint("high", "1;38;2;0;255;120"),
        Confidence::Medium => paint("medium", "1;38;2;255;235;59"),
        Confidence::Low => paint("low", "1;31"),
    }
}

fn init_mode(inferences: &[Inference]) -> &'static str {
    if inferences.is_empty()
        || inferences
            .iter()
            .all(|inference| inference.source == "directory-name")
    {
        "blank"
    } else {
        "detected"
    }
}

fn excluded_write_inferences(report: &DetectReport) -> impl Iterator<Item = &Inference> {
    report
        .inferences
        .iter()
        .filter(|inference| inference.confidence != Confidence::High)
}

fn render_detect_write_blocked_error(report: &DetectReport) -> String {
    let excluded = excluded_write_inferences(report).collect::<Vec<_>>();
    let low_confidence = excluded
        .iter()
        .copied()
        .filter(|inference| inference.confidence == Confidence::Low)
        .collect::<Vec<_>>();
    let eligible = excluded
        .iter()
        .copied()
        .filter(|inference| inference.confidence != Confidence::Low)
        .collect::<Vec<_>>();

    let mut why_lines = vec![String::from(
        "detected fields are not sufficient to write a valid contract automatically",
    )];
    if !low_confidence.is_empty() {
        why_lines.push(format!(
            "{} {}",
            join_detect_inference_fields(&low_confidence),
            if low_confidence.len() == 1 {
                "is still low confidence"
            } else {
                "are still low confidence"
            }
        ));
    }

    let detect_dry_run = command_for_repo("ota detect --dry-run", &report.root);
    let detect_contract = command_for_repo("ota detect --contract", &report.root);
    let init_dry_run = command_for_repo("ota init --dry-run", &report.root);
    let detect_write = command_for_repo("ota detect --write", &report.root);
    let mut next_steps = vec![
        format!("run `{detect_dry_run}` to review medium and low confidence fields"),
        format!("run `{detect_contract}` to inspect the exact detected contract text"),
        format!("run `{init_dry_run}` to compare the conservative starter path"),
    ];
    if !low_confidence.is_empty() {
        next_steps.push(format!(
            "confirm or add {}, then rerun `{detect_write}`",
            join_detect_inference_fields(&low_confidence),
        ));
    }
    if !eligible.is_empty() {
        let mut inferred_fields = String::from("eligible inferred fields:");
        for inference in eligible {
            inferred_fields.push_str(&format!(
                "\n    • `{} = {}`",
                inference.field, inference.value
            ));
        }
        next_steps.push(inferred_fields);
    }

    let mut output = format!(
        "{}  {}",
        render_severity(FindingSeverity::Error),
        paint("Detect write blocked", "1;37")
    );
    output.push_str(&format!(
        "\n{} {}",
        paint_key("Where:"),
        paint_code("ota detect")
    ));
    append_error_detail_section(&mut output, "Why:", &why_lines, None);
    append_error_detail_section(&mut output, "Next:", &next_steps, None);
    output
}

fn join_detect_inference_fields(inferences: &[&Inference]) -> String {
    inferences
        .iter()
        .map(|inference| paint_code(&format!("`{}`", inference.field)))
        .collect::<Vec<_>>()
        .join(", ")
}

fn render_inference_section<'a>(
    output: &mut String,
    title: &str,
    inferences: impl IntoIterator<Item = &'a Inference>,
) {
    let rows = inferences.into_iter().collect::<Vec<_>>();
    output.push_str(&format!("\n\n{}:", paint_section_title(title)));
    if rows.is_empty() {
        output.push_str(&format!("\n{}  none", info_bullet()));
        return;
    }

    for (index, inference) in rows.into_iter().enumerate() {
        if index > 0 {
            output.push('\n');
        }
        output.push_str(&format!(
            "\n{} {} {}",
            info_bullet(),
            paint_key("Field:"),
            inference.field
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Type:"),
            inference.field_type
        ));
        output.push_str(&format!("\n  {} {}", paint_key("Value:"), inference.value));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source:"),
            inference.source
        ));
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Signal:"),
            inference.signal
        ));
        if let Some(agent_safe) = inference.agent_safe {
            output.push_str(&format!("\n  {} {}", paint_key("Agent Safe:"), agent_safe));
        }
        if let Some(agent_signal) = inference.agent_signal {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Agent Signal:"),
                agent_signal
            ));
        }
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Confidence:"),
            render_confidence(inference.confidence)
        ));
    }
}

fn render_table_cell(value: &str) -> String {
    value.replace('\n', " ").replace('|', "¦")
}

enum ContractProblem {
    Load(LoadContractError),
    Validation(ValidationErrors),
}

enum WorkspaceProblem {
    Load(crate::workspace::LoadWorkspaceError),
    Validation(WorkspaceValidationErrors),
}

#[derive(Debug, thiserror::Error)]
enum ResolveContractError {
    #[error("failed to read the current directory: {message}")]
    CurrentDirectory { message: String },
    #[error("no `ota.yaml` found from `{start}` upward")]
    NotFound { start: String },
    #[error("explicit contract path from {origin} does not point to a file: `{path}`")]
    MissingExplicitFile { origin: &'static str, path: String },
    #[error("explicit repo path does not contain `ota.yaml`: `{path}`")]
    MissingExplicitDirectory { path: String },
    #[error(
        "contract path does not exist: `{path}`\n\nNext:\n  » run `ota init` to create a starter contract\n  » run `ota detect --dry-run` to preview inferred fields\n  » run `ota detect --write` to write a detected contract"
    )]
    MissingExplicitPath { path: String },
}

#[derive(Debug, thiserror::Error)]
enum ResolveWorkspaceError {
    #[error("failed to read the current directory: {message}")]
    CurrentDirectory { message: String },
    #[error("{message}")]
    NotFound { message: String },
    #[error("explicit workspace path from {origin} does not point to a file: `{path}`")]
    MissingExplicitFile { origin: &'static str, path: String },
    #[error("explicit workspace path does not contain `ota.workspace.yaml`: `{path}`")]
    MissingExplicitDirectory { path: String },
    #[error(
        "workspace path does not exist: `{path}`\n\nNext:\n  » run `ota workspace init` to create a starter workspace"
    )]
    MissingExplicitPath { path: String },
}
